n.NVIC_IRQChannel = USART1_IRQn;                       //    中断向量（名字见启动文件）
n.NVIC_IRQChannelPreemptionPriority = 2;               //    抢占优先级（数值越小越高）
n.NVIC_IRQChannelSubPriority = 0;                      //    子优先级
n.NVIC_IRQChannelCmd = ENABLE;
NVIC_Init(&n);
// ③ 写中断函数：void USART1_IRQHandler(void) { …判标志 → 处理 → 清标志… }

