g.GPIO_Mode  = GPIO_Mode_OUT;              //   输出模式
g.GPIO_OType = GPIO_OType_PP;              //   推挽
g.GPIO_Speed = GPIO_Speed_100MHz;          //   高速
g.GPIO_PuPd  = GPIO_PuPd_NOPULL;           //   无上下拉
GPIO_Init(GPIOF, &g);                      // 3 生效：PF9/PF10 变输出
// 之后：GPIO_SetBits(GPIOF, GPIO_Pin_9) 就能点灯

GPIO_InitTypeDef g;
GPIO_StructInit(&g);
g.GPIO_Pin = GPIO_Pin_1;
