/* 场景：读按键，PA0 配 GPIO_Mode_IN + GPIO_PuPd_UP，按下接地为低电平 */
if (GPIO_ReadInputDataBit(GPIOA, GPIO_Pin_0) == 0)
{
    /* 按键按下 */
}
// 只读一个引脚用本函数；要一次读整个端口 16 个脚用 GPIO_ReadInputData(GPIOA)

/* 场景：PF9 接 LED，点亮 / 熄灭 / 闪烁 */
// 先按 GPIO_Init 卡把 PF9 配成 GPIO_Mode_OUT + GPIO_OType_PP
GPIO_SetBits(GPIOF, GPIO_Pin_9);                // 输出高：点亮
GPIO_ResetBits(GPIOF, GPIO_Pin_9);              // 输出低：熄灭
GPIO_ToggleBits(GPIOF, GPIO_Pin_9);             // 翻转：闪烁
GPIO_SetBits(GPIOF, GPIO_Pin_9 | GPIO_Pin_10);  // 位或：一次置高多个引脚

/* 场景：熄灭 LED / 拉低片选等（输出 0） */
GPIO_ResetBits(GPIOF, GPIO_Pin_9);                 // PF9 变低（LED 灭）
GPIO_ResetBits(GPIOB, GPIO_Pin_12 | GPIO_Pin_13);  // 位或：一次拉低多个引脚

/* 场景：LED 闪烁（主循环里每 500ms 翻转一次） */
while (1)
{
    GPIO_ToggleBits(GPIOF, GPIO_Pin_9);   // PF9 电平取反
    Delay_ms(500);
}

