/* 场景：发一个字符串（每个字节等 TXE 空再送） */
void usart_send_string(USART_TypeDef* USARTx, const char* s)
{
    while (*s)
    {
        while (USART_GetFlagStatus(USARTx, USART_FLAG_TXE) == RESET) { }  // 等发送寄存器空
        USART_SendData(USARTx, *s++);
    }
    while (USART_GetFlagStatus(USARTx, USART_FLAG_TC) == RESET) { }       // 等整帧发完
}

usart_send_string(USART1, "Hello");

/* 场景：轮询收一个字节（连续收请配中断或 DMA，见 USART_ITConfig 卡） */
while (USART_GetFlagStatus(USART1, USART_FLAG_RXNE) == RESET) { }  // 等数据到达
uint8_t ch = USART_ReceiveData(USART1) & 0xFF;                     // 读走数据（RXNE 自动清）

/* 场景：串口收中断（每收到一字节进 USART1_IRQHandler） */
USART_ITConfig(USART1, USART_IT_RXNE, ENABLE);   // 1 开“接收非空”中断源
NVIC_InitTypeDef n;                              // 2 NVIC 使能串口中断
n.NVIC_IRQChannel = USART1_IRQn;
n.NVIC_IRQChannelPreemptionPriority = 2;
n.NVIC_IRQChannelSubPriority = 0;
n.NVIC_IRQChannelCmd = ENABLE;
NVIC_Init(&n);
// 3 中断函数：
void USART1_IRQHandler(void)
{
    if (USART_GetITStatus(USART1, USART_IT_RXNE) == SET)
    {
        uint8_t ch = USART_ReceiveData(USART1);   // 读走数据（标志自动清）
    }
}

/* 两大常用等待（轮询用法） */
while (USART_GetFlagStatus(USART1, USART_FLAG_TXE) == RESET) { }   // 等发送寄存器空 → 才能送下一字节
USART_SendData(USART1, 'A');
while (USART_GetFlagStatus(USART1, USART_FLAG_RXNE) == RESET) { }  // 等收到数据 → 才能读
uint8_t ch = USART_ReceiveData(USART1);
/* 标志含义：TXE 发送寄存器空 / TC 整帧发完 / RXNE 收到数据 / IDLE 总线空闲 / ORE 溢出 */

void USART1_IRQHandler(void)
{
    if (USART_GetITStatus(USART1, USART_IT_RXNE) == SET)
    {
        uint8_t ch = USART_ReceiveData(USART1);
    }
}

