/* 场景：串口 DMA 收不定长数据（IDLE 中断里算收了多少字节） */
void USART1_IRQHandler(void)
{
    if (USART_GetITStatus(USART1, USART_IT_IDLE) == SET)
    {
        (void)USART1->SR; (void)USART1->DR;   // 清 IDLE 标志（读 SR 再读 DR）
        uint16_t left = DMA_GetCurrDataCounter(DMA2_Stream5);
        uint16_t received = 64 - left;        // 64 = DMA_BufferSize
        /* 现在 rx_buf[0..received-1] 就是收到的数据 */
    }
}

/* 目标：TIM2 产生 1ms 更新中断（APB1 时钟 84MHz） */
RCC_APB1PeriphClockCmd(RCC_APB1Periph_TIM2, ENABLE);   // 1 开时钟
TIM_TimeBaseInitTypeDef t;                             // 2 配时基
t.TIM_Prescaler = 83;      // 84MHz/(83+1) = 1MHz
t.TIM_Period = 999;        // 1MHz/(999+1) = 1kHz → 1ms
t.TIM_ClockDivision = TIM_CKD_DIV1;
t.TIM_CounterMode = TIM_CounterMode_Up;
t.TIM_RepetitionCounter = 0;
TIM_TimeBaseInit(TIM2, &t);
TIM_ITConfig(TIM2, TIM_IT_Update, ENABLE);             // 3 开更新中断（再接 NVIC_Init）
TIM_Cmd(TIM2, ENABLE);                                 // 4 启动
// 中断函数 TIM2_IRQHandler 里：判 TIM_GetITStatus → 干任务 → TIM_ClearITPendingBit

/* 完整流程：PWM 引脚复用 + 时基 + 通道配置（TIM3_CH1=PA6 示例，按原理图改引脚） */
RCC_AHB1PeriphClockCmd(RCC_AHB1Periph_GPIOA, ENABLE);     // 1. 引脚时钟
RCC_APB1PeriphClockCmd(RCC_APB1Periph_TIM3, ENABLE);      //    定时器时钟
GPIO_PinAFConfig(GPIOA, GPIO_PinSource6, GPIO_AF_TIM3);   // 2. PA6 复用给 TIM3_CH1
GPIO_InitTypeDef g;
g.GPIO_Pin  = GPIO_Pin_6;
g.GPIO_Mode = GPIO_Mode_AF;
g.GPIO_OType = GPIO_OType_PP;
g.GPIO_Speed = GPIO_Speed_100MHz;
g.GPIO_PuPd = GPIO_PuPd_NOPULL;
GPIO_Init(GPIOA, &g);
// 3. 时基（如 1kHz PWM：TIM_Prescaler=83、TIM_Period=999，见 TIM_TimeBaseInit 卡）
TIM_OCInitTypeDef o;                                     // 4. 通道参数（本函数）
o.TIM_OCMode = TIM_OCMode_PWM1;
o.TIM_OutputState = TIM_OutputState_Enable;
o.TIM_OCPolarity = TIM_OCPolarity_High;
o.TIM_Pulse = 500;
TIM_OC1Init(TIM3, &o);
TIM_OC1PreloadConfig(TIM3, TIM_OCPreload_Enable);
TIM_Cmd(TIM3, ENABLE);                                    // 5. 启动输出
// 改占空比：TIM_SetCompare1(TIM3, 值)

/* 场景：启动 1ms 中断定时器（完整四步） */
// 1 RCC_APB1PeriphClockCmd(RCC_APB1Periph_TIM2, ENABLE);      // 开时钟
// 2 TIM_TimeBaseInit(TIM2, &t);                                // 配时基（见 TIM_TimeBaseInit 卡）
// 3 TIM_ITConfig(TIM2, TIM_IT_Update, ENABLE); + NVIC_Init      // 开中断
TIM_Cmd(TIM2, ENABLE);                                         // 4 启动：开始计数进中断
// 停止：TIM_Cmd(TIM2, DISABLE);

if (TIM_GetITStatus(TIM2, TIM_IT_Update) != RESET)
{
    TIM_ClearITPendingBit(TIM2, TIM_IT_Update);
}

/* 场景：TIM3 的通道 1 输出 PWM 调亮度（初始化见 TIM_OC1Init 卡，Period=999） */
TIM_SetCompare1(TIM3, 250);   // ≈25% 占空比（暗）
TIM_SetCompare1(TIM3, 500);   // ≈50%
TIM_SetCompare1(TIM3, 999);   // ≈100%（最亮）
// 呼吸灯：主循环里随时间缓慢增减比较值（Delay_ms 控制变化速度）

/* 场景：TIM2_ETR(PA0) 数外部脉冲（完整顺序） */
RCC_AHB1PeriphClockCmd(RCC_AHB1Periph_GPIOA, ENABLE);   // 1. 引脚时钟
RCC_APB1PeriphClockCmd(RCC_APB1Periph_TIM2, ENABLE);   //    定时器时钟
GPIO_PinAFConfig(GPIOA, GPIO_PinSource0, GPIO_AF_TIM2); // 2. PA0 复用为 TIM2_ETR
GPIO_InitTypeDef g;
g.GPIO_Pin  = GPIO_Pin_0;
g.GPIO_Mode = GPIO_Mode_AF;
g.GPIO_OType = GPIO_OType_PP;
g.GPIO_Speed = GPIO_Speed_100MHz;
g.GPIO_PuPd = GPIO_PuPd_NOPULL;
GPIO_Init(GPIOA, &g);
TIM_TimeBaseInitTypeDef t;                              // 3. 时基（预分频=0：一个脉冲计 1）
t.TIM_Prescaler = 0;
t.TIM_Period = 65535;
t.TIM_CounterMode = TIM_CounterMode_Up;
t.TIM_ClockDivision = TIM_CKD_DIV1;
t.TIM_RepetitionCounter = 0;
TIM_TimeBaseInit(TIM2, &t);
TIM_ETRClockMode2Config(TIM2, TIM_ExtTRGPSC_OFF, TIM_ExtTRGPolarity_NonInverted, 0x00);  // 4. ETR 外部时钟（本函数）
TIM_Cmd(TIM2, ENABLE);                                  // 5. 启动：外部脉冲开始计数
// 读脉冲数：TIM_GetCounter(TIM2)

/* 场景：TIM2_CH1(PA0) 输入捕获测脉宽（完整顺序） */
RCC_APB1PeriphClockCmd(RCC_APB1Periph_TIM2, ENABLE);   // 1. 开时钟
// 2. 配时基：TIM_TimeBaseInit(TIM2, &t)（预分频定分辨率，如 1MHz→1us 一格）
RCC_AHB1PeriphClockCmd(RCC_AHB1Periph_GPIOA, ENABLE);  // 3. 引脚时钟
GPIO_PinAFConfig(GPIOA, GPIO_PinSource0, GPIO_AF_TIM2); //    PA0 复用 TIM2_CH1
GPIO_InitTypeDef g;
g.GPIO_Pin  = GPIO_Pin_0;
g.GPIO_Mode = GPIO_Mode_AF;
g.GPIO_OType = GPIO_OType_PP;
g.GPIO_Speed = GPIO_Speed_100MHz;
g.GPIO_PuPd = GPIO_PuPd_NOPULL;
GPIO_Init(GPIOA, &g);
TIM_ICInitTypeDef ic;                                  // 4. 捕获配置（本函数）
ic.TIM_Channel = TIM_Channel_1;
ic.TIM_ICPolarity = TIM_ICPolarity_Rising;
ic.TIM_ICSelection = TIM_ICSelection_DirectTI;
ic.TIM_ICPrescaler = TIM_ICPSC_DIV1;
ic.TIM_ICFilter = 0x0;
TIM_ICInit(TIM2, &ic);
TIM_Cmd(TIM2, ENABLE);                                 // 5. 启动
// 读捕获值：TIM_GetCapture1(TIM2)（配 TIM_IT_CC1 中断可自动记时间差）

/* 场景：PA0 按键下降沿中断（完整顺序） */
RCC_APB2PeriphClockCmd(RCC_APB2Periph_SYSCFG, ENABLE);  // 1 开 SYSCFG（映射用）
RCC_AHB1PeriphClockCmd(RCC_AHB1Periph_GPIOA, ENABLE);   // 2 开 GPIO 时钟
