uint32_t pulses = TIM_GetCounter(TIM2);

/* PWM 标准做法：预装载都打开，运行时改值才平滑 */
TIM_ARRPreloadConfig(TIM3, ENABLE);                   // 改 Period 平滑生效
TIM_OC1PreloadConfig(TIM3, TIM_OCPreload_Enable);    // 改占空比平滑生效
TIM_Cmd(TIM3, ENABLE);

/* 轮询等一轮定时结束（不占中断，但会阻塞） */
while (TIM_GetFlagStatus(TIM2, TIM_FLAG_Update) == RESET) { }
