/* 场景：CAN1 发标准帧 0x123，数据 11 22 33 44 */
CanTxMsg t;
t.StdId = 0x123;
t.IDE   = CAN_Id_Standard;
t.RTR   = CAN_RTR_Data;
t.DLC   = 4;
t.Data[0] = 0x11; t.Data[1] = 0x22; t.Data[2] = 0x33; t.Data[3] = 0x44;
uint8_t mb = CAN_Transmit(CAN1, &t);
if (mb == CAN_TxStatus_NoMailBox) { /* 邮箱满，稍后重试 */ }
// 等发送完成：while (CAN_TransmitStatus(CAN1, mb) == CAN_TxStatus_Pending) { }

/* 场景：轮询收 CAN 报文 */
if (CAN_MessagePending(CAN1, CAN_FIFO0) > 0)
{
    CanRxMsg r;
    CAN_Receive(CAN1, CAN_FIFO0, &r);
    CAN_FIFORelease(CAN1, CAN_FIFO0);      // 必须释放
    /* 用 r.StdId / r.DLC / r.Data[] */
}

uint8_t mb = CAN_Transmit(CAN1, &t);
while (CAN_TransmitStatus(CAN1, mb) == CAN_TxStatus_Pending) { }
if (CAN_TransmitStatus(CAN1, mb) == CAN_TxStatus_Failed) { /* 发送失败 */ }

