SYS_SPI_Init(SYS_SPI_1, 1000000U, SYS_SPI_MODE_0);   // 先 1MHz 稳一点
// 片选自己控制（每个从机一根 CS）：
GPIO_ResetBits(GPIOB, GPIO_Pin_14);                  // W25QXX 的 CS 拉低
/* … 用 SYS_SPI_Transfer 收发 … */
GPIO_SetBits(GPIOB, GPIO_Pin_14);                    // 收工拉高

/* 用 0x9F 读 W25QXX 的 JEDEC ID（3 字节）：先发命令，再读 3 字节 */
uint8_t cmd = 0x9F, id[3];
SYS_SPI_Transfer(SYS_SPI_1, &cmd, 0, 1);            // 只发命令、不收
SYS_SPI_Transfer(SYS_SPI_1, 0, id, 3);              // 只收 3 字节（内部发 0xFF）
// 本板 GD25Q128 应得到 id = {0xC8, 0x40, 0x18}

/* 读 SPI Flash 状态寄存器：命令 0x05，然后收 1 字节 */
GPIO_ResetBits(GPIOB, GPIO_Pin_14);
SYS_SPI_TransferByte(SYS_SPI_1, 0x05);
uint8_t sr = SYS_SPI_TransferByte(SYS_SPI_1, 0xFF);
GPIO_SetBits(GPIOB, GPIO_Pin_14);
// sr 的 bit0 = WIP（1 表示芯片还在忙，写/擦期间必须等它变 0）

