                 TIM_OCMode_Timing, 1000U, 500U, OnTick1ms);

/* 每 1ms 进一次回调（T=1ms → cycle_hz=1000；ccr 决定在计数的哪个位置匹配） */
static volatile uint32_t g_ticks = 0;
static void OnTick1ms(void) { g_ticks++; }

SYS_TIM_OcInitIT(SYS_TIM_3, 1, 0, 0, 0,
                 TIM_OCMode_Timing, 1000U, 500U, OnTick1ms);
// 之后 g_ticks 每毫秒 +1，主循环读它即可（不用轮询 GPIO）

