{
    /* ---- 1. 开时钟（三个都要开） ---- */
    RCC_AHB1PeriphClockCmd(RCC_AHB1Periph_GPIOA | RCC_AHB1Periph_DMA2, ENABLE);
    RCC_APB2PeriphClockCmd(RCC_APB2Periph_USART1, ENABLE);

    /* ---- 2. PA9=TX / PA10=RX 复用 ---- */
    GPIO_InitTypeDef g;
    GPIO_PinAFConfig(GPIOA, GPIO_PinSource9,  GPIO_AF_USART1);
    GPIO_PinAFConfig(GPIOA, GPIO_PinSource10, GPIO_AF_USART1);
    g.GPIO_Pin   = GPIO_Pin_9 | GPIO_Pin_10;
    g.GPIO_Mode  = GPIO_Mode_AF;            /* 复用模式 */
    g.GPIO_OType = GPIO_OType_PP;
    g.GPIO_Speed = GPIO_Speed_50MHz;
    g.GPIO_PuPd  = GPIO_PuPd_UP;            /* RX 建议上拉 */
    GPIO_Init(GPIOA, &g);

    /* ---- 3. 串口参数 115200-8-N-1 ---- */
    USART_InitTypeDef u;
    u.USART_BaudRate            = 115200;
    u.USART_WordLength          = USART_WordLength_8b;
    u.USART_StopBits            = USART_StopBits_1;
    u.USART_Parity              = USART_Parity_No;
    u.USART_Mode                = USART_Mode_Rx | USART_Mode_Tx;
    u.USART_HardwareFlowControl = USART_HardwareFlowControl_None;
    USART_Init(USART1, &u);

    /* ---- 4. DMA 接收配置（USART1_RX = DMA2_Stream5 通道4） ---- */
    DMA_InitTypeDef d;
    DMA_DeInit(DMA2_Stream5);
    while (DMA_GetCmdStatus(DMA2_Stream5) != DISABLE) { }   /* 等它真的停了 */
    d.DMA_Channel            = DMA_Channel_4;               /* 外设固定映射，不能乱填 */
    d.DMA_PeripheralBaseAddr = (uint32_t)&USART1->DR;       /* 外设端：串口数据寄存器 */
    d.DMA_Memory0BaseAddr    = (uint32_t)rxBuf;             /* 内存端：接收缓冲区 */
    d.DMA_DIR                = DMA_DIR_PeripheralToMemory;  /* 外设 → 内存（收） */
    d.DMA_BufferSize         = RX_BUF_SIZE;
    d.DMA_PeripheralInc      = DMA_PeripheralInc_Disable;   /* 外设地址固定 */
    d.DMA_MemoryInc          = DMA_MemoryInc_Enable;        /* 内存地址递增 */
    d.DMA_PeripheralDataSize = DMA_PeripheralDataSize_Byte;
    d.DMA_MemoryDataSize     = DMA_MemoryDataSize_Byte;
    d.DMA_Mode               = DMA_Mode_Normal;             /* 收完一帧要手动重启 */
    d.DMA_Priority           = DMA_Priority_High;
    d.DMA_FIFOMode           = DMA_FIFOMode_Disable;
    DMA_Init(DMA2_Stream5, &d);

    /* ---- 5. 开空闲中断（一帧结束后触发） ---- */
    USART_ITConfig(USART1, USART_IT_IDLE, ENABLE);

    /* ---- 6. 使能：外设端 + DMA 端 + 内核端 ---- */
    USART_DMACmd(USART1, USART_DMAReq_Rx, ENABLE);
    DMA_Cmd(DMA2_Stream5, ENABLE);
    USART_Cmd(USART1, ENABLE);
    NVIC_EnableIRQ(USART1_IRQn);
}

/* ---- 7. 中断服务：只做最少的事 ---- */
void USART1_IRQHandler(void)
{
    if (USART_GetITStatus(USART1, USART_IT_IDLE) != RESET)
    {
        /* 清 IDLE 标志：必须先读 SR 再读 DR，少一步标志清不掉 */
        volatile uint32_t tmp;
        tmp = USART1->SR;
        tmp = USART1->DR;
        (void)tmp;

        /* 算本帧长度 = 总长 - DMA 剩余未搬数 */
        rxLen = RX_BUF_SIZE - DMA_GetCurrDataCounter(DMA2_Stream5);
        rxReady = 1;

        /* 重启 DMA，准备收下一帧 */
        DMA_Cmd(DMA2_Stream5, DISABLE);
        DMA_SetCurrDataCounter(DMA2_Stream5, RX_BUF_SIZE);
        DMA_Cmd(DMA2_Stream5, ENABLE);
    }
}

/* ---- 主循环里处理 ---- */
int main(void)
{
    USART1_DMA_IDLE_Init();
    while (1)
    {
        if (rxReady)
        {
            rxReady = 0;
            /* 此时 rxBuf[0..rxLen-1] 里就是完整一帧，交给协议解析 */
        }
    }
}

/* ============ FreeRTOS 版：中断里只释放信号量 ============
 * 架构文档要的就是这个形态：ISR 里只调 osSemaphoreRelease 等价物，
 * 解析放任务里做（中断里绝不能做耗时的事）。
 *
 * static SemaphoreHandle_t rxSem;
 *
 * 初始化里加：
 *   NVIC_PriorityGroupConfig(NVIC_PriorityGroup_4);   // FreeRTOS 必须 Group_4
 *   rxSem = xSemaphoreCreateBinary();
 *   NVIC_SetPriority(USART1_IRQn, 5);                 // ≥5 才能调 FromISR
 *   NVIC_EnableIRQ(USART1_IRQn);
 *
 * 中断里（替换上面的 rxReady = 1; 之后）：
 *   BaseType_t hpw = pdFALSE;
 *   xSemaphoreGiveFromISR(rxSem, &hpw);
 *   portYIELD_FROM_ISR(hpw);
 *
 * 接收任务里：
 *   void CommRxTask(void *arg)
 *   {
 *       for (;;)
 *       {
 *           if (xSemaphoreTake(rxSem, portMAX_DELAY) == pdTRUE)
 *           {
 *               // 这里慢慢解析 rxBuf[0..rxLen-1]
 *           }
 *       }
 *   }
 */

/* ---- 方式一：printf 重定向（最常用） ---- */
#include <stdio.h>

int fputc(int ch, FILE *f)
{
    while (USART_GetFlagStatus(USART1, USART_FLAG_TXE) == RESET) { }
    USART_SendData(USART1, (uint8_t)ch);
    return ch;
}
/* 之后直接 printf("温度=%d\r\n", temp); */

/* ---- 方式二：自己写发送函数（不依赖 printf，省 Flash） ---- */
void uart_send_buf(USART_TypeDef* USARTx, const uint8_t* buf, uint16_t len)
{
    uint16_t i;
    for (i = 0; i < len; i++)
    {
        while (USART_GetFlagStatus(USARTx, USART_FLAG_TXE) == RESET) { }
        USART_SendData(USARTx, buf[i]);
    }
    while (USART_GetFlagStatus(USARTx, USART_FLAG_TC) == RESET) { }  /* 等整帧发完 */
}

/* ---- 方式三：发字符串 ---- */
void uart_send_str(USART_TypeDef* USARTx, const char* s)
{
    while (*s)
    {
        while (USART_GetFlagStatus(USARTx, USART_FLAG_TXE) == RESET) { }
        USART_SendData(USARTx, (uint8_t)*s++);
    }
}

