/* ============ 方式一：裸机手搓（理解时序用） ============ */
static void i2c1_init(void)
{
    RCC_AHB1PeriphClockCmd(RCC_AHB1Periph_GPIOB, ENABLE);
    RCC_APB1PeriphClockCmd(RCC_APB1Periph_I2C1, ENABLE);

    GPIO_PinAFConfig(GPIOB, GPIO_PinSource8, GPIO_AF_I2C1);
    GPIO_PinAFConfig(GPIOB, GPIO_PinSource9, GPIO_AF_I2C1);
    GPIO_InitTypeDef g;
    g.GPIO_Pin   = GPIO_Pin_8 | GPIO_Pin_9;
    g.GPIO_Mode  = GPIO_Mode_AF;
    g.GPIO_OType = GPIO_OType_OD;     /* 开漏：I2C 硬性要求 */
    g.GPIO_Speed = GPIO_Speed_50MHz;
    g.GPIO_PuPd  = GPIO_PuPd_UP;      /* 上拉 */
    GPIO_Init(GPIOB, &g);

    I2C_InitTypeDef i;
    i.I2C_ClockSpeed          = 400000;                  /* 100k 更稳，400k 更快 */
    i.I2C_Mode                = I2C_Mode_I2C;
    i.I2C_DutyCycle           = I2C_DutyCycle_2;
    i.I2C_OwnAddress1         = 0x00;
    i.I2C_Ack                 = I2C_Ack_Enable;
    i.I2C_AcknowledgedAddress = I2C_AcknowledgedAddress_7bit;
    I2C_Init(I2C1, &i);
    I2C_Cmd(I2C1, ENABLE);
}

/* ---- 写一个寄存器（8 位寄存器地址） ---- */
uint8_t i2c_write_reg(uint8_t devAddr7, uint8_t reg, uint8_t val)
{
    while (I2C_GetFlagStatus(I2C1, I2C_FLAG_BUSY)) { }
    I2C_GenerateSTART(I2C1, ENABLE);
    while (!I2C_CheckEvent(I2C1, I2C_EVENT_MASTER_MODE_SELECT)) { }

    I2C_Send7bitAddress(I2C1, devAddr7 << 1, I2C_Direction_Transmitter);
    while (!I2C_CheckEvent(I2C1, I2C_EVENT_MASTER_TRANSMITTER_MODE_SELECTED)) { }

    I2C_SendData(I2C1, reg);
    while (!I2C_CheckEvent(I2C1, I2C_EVENT_MASTER_BYTE_TRANSMITTING)) { }

    I2C_SendData(I2C1, val);
    while (!I2C_CheckEvent(I2C1, I2C_EVENT_MASTER_BYTE_TRANSMITTED)) { }

    I2C_GenerateSTOP(I2C1, ENABLE);
    return 0;
}

/* ---- 读 N 个寄存器（读时序，传感器最常用） ---- */
uint8_t i2c_read_regs(uint8_t devAddr7, uint8_t reg, uint8_t* buf, uint16_t len)
{
    /* 第 1 段：写要读哪个寄存器 */
    while (I2C_GetFlagStatus(I2C1, I2C_FLAG_BUSY)) { }
    I2C_GenerateSTART(I2C1, ENABLE);
    while (!I2C_CheckEvent(I2C1, I2C_EVENT_MASTER_MODE_SELECT)) { }
    I2C_Send7bitAddress(I2C1, devAddr7 << 1, I2C_Direction_Transmitter);
    while (!I2C_CheckEvent(I2C1, I2C_EVENT_MASTER_TRANSMITTER_MODE_SELECTED)) { }
    I2C_SendData(I2C1, reg);
    while (!I2C_CheckEvent(I2C1, I2C_EVENT_MASTER_BYTE_TRANSMITTED)) { }

    /* 第 2 段：重启，改成读 */
    I2C_GenerateSTART(I2C1, ENABLE);
    while (!I2C_CheckEvent(I2C1, I2C_EVENT_MASTER_MODE_SELECT)) { }
    I2C_Send7bitAddress(I2C1, devAddr7 << 1, I2C_Direction_Receiver);
    while (!I2C_CheckEvent(I2C1, I2C_EVENT_MASTER_RECEIVER_MODE_SELECTED)) { }

    /* 逐个字节读；最后一个字节之前必须先 NACK，让从机停止发送 */
    while (len)
    {
        if (len == 1)
        {
            I2C_AcknowledgeConfig(I2C1, DISABLE);           /* 最后一个：NACK */
            I2C_GenerateSTOP(I2C1, ENABLE);                 /* 先安排 STOP */
        }
        while (!I2C_CheckEvent(I2C1, I2C_EVENT_MASTER_BYTE_RECEIVED)) { }
        *buf++ = I2C_ReceiveData(I2C1);
        len--;
    }
    I2C_AcknowledgeConfig(I2C1, ENABLE);                     /* 恢复 ACK 给下次用 */
    return 0;
}

/* ============ 方式二：直接用本工程的封装（推荐） ============
 * FWLIB\inc\sys_i2c.h 里已有：
 *   SYS_I2C_Init()                     初始化
 *   SYS_I2C_IsDeviceReady(addr)        探测设备在不在（调试第一步）
 *   SYS_I2C_WriteReg16(addr, reg, val) 写寄存器
 *   SYS_I2C_ReadReg16(addr, reg, buf, len)  读寄存器
 *   SYS_I2C_Scan()                     扫描总线上所有设备
 *
 * 建议每个新传感器上手第一步都先 SYS_I2C_Scan()，
 * 确认地址对得上再写驱动，能省掉一大半“读不出数据”的排查时间。
 */

/* ============ 2 个通道 + DMA 循环，数组自动刷新 ============ */
#define ADC_CH_NUM   2
static volatile uint16_t adcDmaBuf[ADC_CH_NUM];   /* DMA 直接往这里写 */

void adc_dma_circular_init(void)
{
    /* ---- 1. 开时钟 ---- */
    RCC_AHB1PeriphClockCmd(RCC_AHB1Periph_GPIOA | RCC_AHB1Periph_DMA2, ENABLE);
    RCC_APB2PeriphClockCmd(RCC_APB2Periph_ADC1, ENABLE);

    /* ---- 2. 模拟输入引脚（示例 PA0 = ADC_Channel_0；本工程 MQ-135 接 PF7 = ADC3_IN5） ---- */
    GPIO_InitTypeDef g;
    g.GPIO_Pin  = GPIO_Pin_0;
    g.GPIO_Mode = GPIO_Mode_AN;        /* 模拟模式，不是 IN */
    g.GPIO_PuPd = GPIO_PuPd_NOPULL;
    GPIO_Init(GPIOA, &g);

    /* ---- 3. ADC 公共配置（必须最先做，时钟不能超 36MHz） ---- */
    ADC_CommonInitTypeDef c;
    c.ADC_Mode             = ADC_Mode_Independent;
    c.ADC_Prescaler        = ADC_Prescaler_Div4;      /* 84MHz/4 = 21MHz */
    c.ADC_DMAAccessMode    = ADC_DMAAccessMode_Disabled;
    c.ADC_TwoSamplingDelay = ADC_TwoSamplingDelay_5Cycles;
    ADC_CommonInit(&c);

    /* ---- 4. ADC 本体 ---- */
    ADC_InitTypeDef a;
    a.ADC_Resolution           = ADC_Resolution_12b;
    a.ADC_ScanConvMode         = ENABLE;              /* 多通道要开扫描 */
    a.ADC_ContinuousConvMode   = ENABLE;              /* 连续转换：后台一直采 */
    a.ADC_ExternalTrigConvEdge = ADC_ExternalTrigConvEdge_None;
    a.ADC_ExternalTrigConv     = ADC_ExternalTrigConv_T1_CC1;  /* 不用外部触发，随便填 */
    a.ADC_DataAlign            = ADC_DataAlign_Right;
    a.ADC_NbrOfConversion      = ADC_CH_NUM;
    ADC_Init(ADC1, &a);

    /* ---- 5. 排通道序列（顺序 = 在数组里的下标） ---- */
    ADC_RegularChannelConfig(ADC1, ADC_Channel_0, 1, ADC_SampleTime_480Cycles);
    ADC_RegularChannelConfig(ADC1, ADC_Channel_1, 2, ADC_SampleTime_480Cycles);

    /* ---- 6. ADC 的 DMA 请求（ADC1 = DMA2_Stream0 通道0） ---- */
    ADC_DMACmd(ADC1, ENABLE);

    DMA_InitTypeDef d;
    DMA_DeInit(DMA2_Stream0);
    while (DMA_GetCmdStatus(DMA2_Stream0) != DISABLE) { }
    d.DMA_Channel            = DMA_Channel_0;
    d.DMA_PeripheralBaseAddr = (uint32_t)&ADC1->DR;
    d.DMA_Memory0BaseAddr    = (uint32_t)adcDmaBuf;
    d.DMA_DIR                = DMA_DIR_PeripheralToMemory;
    d.DMA_BufferSize         = ADC_CH_NUM;
    d.DMA_PeripheralInc      = DMA_PeripheralInc_Disable;
    d.DMA_MemoryInc          = DMA_MemoryInc_Enable;
    d.DMA_PeripheralDataSize = DMA_PeripheralDataSize_HalfWord;
    d.DMA_MemoryDataSize     = DMA_MemoryDataSize_HalfWord;
    d.DMA_Mode               = DMA_Mode_Circular;      /* 循环：数组自己一直刷新 */
    d.DMA_Priority           = DMA_Priority_High;
    d.DMA_FIFOMode           = DMA_FIFOMode_Disable;
    DMA_Init(DMA2_Stream0, &d);
    DMA_Cmd(DMA2_Stream0, ENABLE);

    /* ---- 7. 使能并启动（连续模式只需启动一次） ---- */
    ADC_Cmd(ADC1, ENABLE);
    ADC_SoftwareStartConv(ADC1);
}

/* ---- 任务里直接读数组，不用等 ---- */
uint16_t mq135_raw(void)
{
    return adcDmaBuf[0];       /* 0~4095，DMA 已经在后台更新 */
}

/* 12 位原始值 → 电压(mV)：V = raw * 3300 / 4095 */
uint32_t adc_to_mv(uint16_t raw)
{
    return (uint32_t)raw * 3300 / 4095;
}

/* 想要更稳：多次采样求平均（SYS_ADC_ReadAvg 已实现类似功能） */
uint16_t adc_avg(uint8_t ch, uint8_t times)
{
    uint32_t sum = 0;
    uint8_t i;
    for (i = 0; i < times; i++) { sum += adcDmaBuf[ch]; }
    return (uint16_t)(sum / times);
}

/* ============ TIM3_CH1(PC6) 输出 1kHz PWM ============ */
void pwm_init(void)
{
    /* ---- 1. 开时钟 ---- */
    RCC_AHB1PeriphClockCmd(RCC_AHB1Periph_GPIOC, ENABLE);
    RCC_APB1PeriphClockCmd(RCC_APB1Periph_TIM3, ENABLE);   /* TIM3 在 APB1 */

    /* ---- 2. 引脚复用为 TIM3_CH1 ---- */
    GPIO_PinAFConfig(GPIOC, GPIO_PinSource6, GPIO_AF_TIM3);
    GPIO_InitTypeDef g;
    g.GPIO_Pin   = GPIO_Pin_6;
    g.GPIO_Mode  = GPIO_Mode_AF;
    g.GPIO_OType = GPIO_OType_PP;
    g.GPIO_Speed = GPIO_Speed_100MHz;
    g.GPIO_PuPd  = GPIO_PuPd_NOPULL;
    GPIO_Init(GPIOC, &g);

    /* ---- 3. 时基：84MHz/(83+1)/(999+1) = 1kHz ---- */
    TIM_TimeBaseInitTypeDef t;
    t.TIM_Prescaler     = 83;
    t.TIM_Period        = 999;
    t.TIM_CounterMode   = TIM_CounterMode_Up;
    t.TIM_ClockDivision = TIM_CKD_DIV1;
    t.TIM_RepetitionCounter = 0;
    TIM_TimeBaseInit(TIM3, &t);

    /* ---- 4. 通道 1 输出比较 ---- */
    TIM_OCInitTypeDef o;
    o.TIM_OCMode      = TIM_OCMode_PWM1;
    o.TIM_OutputState = TIM_OutputState_Enable;
    o.TIM_Pulse       = 500;                       /* 初值 50% 占空比 */
    o.TIM_OCPolarity  = TIM_OCPolarity_High;
    TIM_OC1Init(TIM3, &o);

    /* ---- 5. 预装载（运行时改值才平滑） ---- */
    TIM_OC1PreloadConfig(TIM3, TIM_OCPreload_Enable);
    TIM_ARRPreloadConfig(TIM3, ENABLE);

    /* ---- 6. 启动 ---- */
    TIM_Cmd(TIM3, ENABLE);
    /* 普通定时器到这就出波形了。
     * 若换成 TIM1/TIM8（高级定时器），必须再加：
     *   TIM_CtrlPWMOutputs(TIM1, ENABLE);   // 不加则引脚永远没波形
     */
}

/* ---- 运行时调占空比（呼吸灯 / 调速） ---- */
void pwm_set_duty(uint32_t pulse)   /* pulse: 0 ~ 999 */
{
    TIM_SetCompare1(TIM3, pulse);
}

