/* ============ TIM2_CH1(PA0) 输入捕获测高电平脉宽 ============ */
static volatile uint32_t capVal1 = 0, capVal2 = 0;
static volatile uint8_t  capEdge = 0;      /* 0=等上升沿 1=等下降沿 */
static volatile uint32_t pulseUs = 0;      /* 结果：脉宽(us) */

void ic_init(void)
{
    /* ---- 1. 开时钟 ---- */
    RCC_AHB1PeriphClockCmd(RCC_AHB1Periph_GPIOA, ENABLE);
    RCC_APB1PeriphClockCmd(RCC_APB1Periph_TIM2, ENABLE);

    /* ---- 2. PA0 复用为 TIM2_CH1 ---- */
    GPIO_PinAFConfig(GPIOA, GPIO_PinSource0, GPIO_AF_TIM2);
    GPIO_InitTypeDef g;
    g.GPIO_Pin   = GPIO_Pin_0;
    g.GPIO_Mode  = GPIO_Mode_AF;
    g.GPIO_OType = GPIO_OType_PP;
    g.GPIO_Speed = GPIO_Speed_100MHz;
    g.GPIO_PuPd  = GPIO_PuPd_DOWN;        /* 空闲低电平，等上升沿 */
    GPIO_Init(GPIOA, &g);

    /* ---- 3. 时基：1MHz → 1 格 = 1us ---- */
    TIM_TimeBaseInitTypeDef t;
    t.TIM_Prescaler     = 83;             /* 84MHz/(83+1) = 1MHz */
    t.TIM_Period        = 65535;          /* 最大量程 65.5ms */
    t.TIM_CounterMode   = TIM_CounterMode_Up;
    t.TIM_ClockDivision = TIM_CKD_DIV1;
    t.TIM_RepetitionCounter = 0;
    TIM_TimeBaseInit(TIM2, &t);

    /* ---- 4. 捕获通道 ---- */
    TIM_ICInitTypeDef ic;
    ic.TIM_Channel     = TIM_Channel_1;
    ic.TIM_ICPolarity  = TIM_ICPolarity_Rising;    /* 先捕上升沿 */
    ic.TIM_ICSelection = TIM_ICSelection_DirectTI;
    ic.TIM_ICPrescaler = TIM_ICPSC_DIV1;           /* 每个边沿都捕 */
    ic.TIM_ICFilter    = 0x0;                      /* 信号毛刺多就调大，如 0x3 */
    TIM_ICInit(TIM2, &ic);

    /* ---- 5. 捕获中断 ---- */
    TIM_ITConfig(TIM2, TIM_IT_CC1, ENABLE);
    NVIC_EnableIRQ(TIM2_IRQn);

    /* ---- 6. 启动 ---- */
    TIM_Cmd(TIM2, ENABLE);
}

/* ---- 中断里算脉宽 ---- */
void TIM2_IRQHandler(void)
{
    if (TIM_GetITStatus(TIM2, TIM_IT_CC1) != RESET)
    {
        TIM_ClearITPendingBit(TIM2, TIM_IT_CC1);

        if (capEdge == 0)                       /* 刚捕到上升沿 */
        {
            capVal1 = TIM_GetCapture1(TIM2);
            capEdge = 1;
            TIM_OC1PolarityConfig(TIM2, TIM_ICPolarity_Falling);   /* 改成等下降沿 */
        }
        else                                    /* 捕到下降沿 */
        {
            capVal2 = TIM_GetCapture1(TIM2);
            pulseUs = capVal2 - capVal1;        /* 1 格 = 1us，所以差值就是微秒 */
            capEdge = 0;
            TIM_OC1PolarityConfig(TIM2, TIM_ICPolarity_Rising);    /* 改回等上升沿 */
        }
    }
}

/* 读结果：pulseUs 就是高电平微秒数。
 * 频率 = 1000000 / 周期us；占空比 = 高电平us / 周期us。
 * 超过 65.5ms 的脉宽会溢出，需要额外在 TIM_IT_Update 里累加溢出次数。 */

/* ============ PA0 按键：下降沿中断（带上简单的软件消抖） ============ */
static volatile uint8_t keyFlag = 0;      /* 中断里只置标志 */

void key_exti_init(void)
{
    /* ---- 1. 开时钟（SYSCFG 必须开） ---- */
    RCC_APB2PeriphClockCmd(RCC_APB2Periph_SYSCFG, ENABLE);
    RCC_AHB1PeriphClockCmd(RCC_AHB1Periph_GPIOA, ENABLE);

    /* ---- 2. PA0 上拉输入（按下接地） ---- */
    GPIO_InitTypeDef g;
    g.GPIO_Pin  = GPIO_Pin_0;
    g.GPIO_Mode = GPIO_Mode_IN;
    g.GPIO_PuPd = GPIO_PuPd_UP;
    GPIO_Init(GPIOA, &g);

    /* ---- 3. 把 PA0 映射到 EXTI0 线（漏这步中断不触发） ---- */
    SYSCFG_EXTILineConfig(EXTI_PortSourceGPIOA, EXTI_PinSource0);

    /* ---- 4. 配 EXTI ---- */
    EXTI_InitTypeDef e;
    e.EXTI_Line    = EXTI_Line0;
    e.EXTI_Mode    = EXTI_Mode_Interrupt;
    e.EXTI_Trigger = EXTI_Trigger_Falling;    /* 按下接地：下降沿 */
    e.EXTI_LineCmd = ENABLE;
    EXTI_Init(&e);

    /* ---- 5. 开 NVIC ---- */
    NVIC_EnableIRQ(EXTI0_IRQn);
}

/* ---- 6. 中断函数：快进快出 ---- */
void EXTI0_IRQHandler(void)
{
    if (EXTI_GetITStatus(EXTI_Line0) != RESET)
    {
        EXTI_ClearITPendingBit(EXTI_Line0);   /* 必须清，否则反复进 */
        keyFlag = 1;                          /* 中断里只置标志 */
    }
}

/* ---- 主循环 / 任务里做真正的处理（含消抖） ---- */
void key_poll(void)
{
    if (keyFlag)
    {
        keyFlag = 0;
        delay_ms(20);                                        /* 消抖 */
        if (GPIO_ReadInputDataBit(GPIOA, GPIO_Pin_0) == 0)   /* 仍是低：真按下 */
        {
            /* 按键处理 */
        }
    }
}

/* FreeRTOS 里：中断里要通知任务就用二值信号量/任务通知：
 *     BaseType_t hpw = pdFALSE;
 *     xSemaphoreGiveFromISR(keySem, &hpw);
 *     portYIELD_FROM_ISR(hpw);
 *   并且 NVIC 优先级必须 ≥ 5（configLIBRARY_MAX_SYSCALL_INTERRUPT_PRIORITY）。
 */

/* ============ FreeRTOS 骨架：3 个任务 + 2 个队列 + 1 个互斥量 ============ */
#include "FreeRTOS.h"
#include "task.h"
#include "queue.h"
#include "semphr.h"
#include "stm32f4xx.h"

/* ---- 数据结构：队列里传的东西 ---- */
typedef struct {
    int16_t  temp_x10;      /* 温度 x10 */
    uint16_t humi_x10;      /* 湿度 x10 */
    uint16_t press_x10;     /* 气压 x10 */
    uint16_t lux;           /* 光照 */
    uint16_t tvoc;          /* CCS811 */
    uint16_t mq135;         /* ADC 原始值 */
} SensorData_t;

/* ---- 全局通信对象 ---- */
static QueueHandle_t     qRaw;        /* Queue1: 采集 → 处理 */
static QueueHandle_t     qTx;         /* Queue2: 处理 → 通信 */
static SemaphoreHandle_t i2cMutex;    /* 保护 I2C1 总线 */
static SemaphoreHandle_t wdgHeartbeat;/* 心跳喂狗用 */

/* ================= 任务 1：采集（优先级 3） ================= */
static void SensorTask(void *arg)
{
    SensorData_t d;
    TickType_t   last = xTaskGetTickCount();

    for (;;)
    {
        /* 严格周期唤醒：比 vTaskDelay 更准（不受任务执行时间影响） */
        vTaskDelayUntil(&last, pdMS_TO_TICKS(100));   /* 10Hz 采集 */

        /* 4 个传感器共用 I2C1 → 用互斥量保护 */
        if (xSemaphoreTake(i2cMutex, pdMS_TO_TICKS(50)) == pdTRUE)
        {
            /* d.temp_x10  = sht30_read_temp_x10();  */
            /* d.humi_x10  = sht30_read_humi_x10();  */
            /* d.press_x10 = bmp280_read_press_x10();*/
            /* d.lux       = bh1750_read_lux();      */
            /* d.tvoc      = ccs811_read_tvoc();     */
            xSemaphoreGive(i2cMutex);                 /* 无论成败都要释放 */
        }
        d.mq135 = 0;   /* adcDmaBuf[0]，DMA 后台刷新，不用加锁 */

        xQueueSend(qRaw, &d, 0);      /* 入队给处理任务；满了就丢（不阻塞采集） */
    }
}

/* ================= 任务 2：处理（优先级 3） ================= */
static void ProcessTask(void *arg)
{
    SensorData_t d;
    for (;;)
    {
        /* 阻塞等队列；没数据时让出 CPU（portMAX_DELAY = 永久等待） */
        if (xQueueReceive(qRaw, &d, portMAX_DELAY) == pdTRUE)
        {
            /* 滤波：中值 / 滑动平均（可参考 kalman.c / sys_filter.c） */
            /* 阈值判断 → 超标就报警（BEEP_On / 置告警位） */
            /* 打包后交给通信任务 */
            xQueueSend(qTx, &d, 0);
        }
    }
}

/* ================= 任务 3：通信（优先级 4） ================= */
static void CommTask(void *arg)
{
    SensorData_t d;
    uint8_t frame[20];
    for (;;)
    {
        if (xQueueReceive(qTx, &d, portMAX_DELAY) == pdTRUE)
        {
            /* 组帧：帧头 0xAA55 + 命令 + 长度 + 12 字节数据 + CRC16 + 帧尾 0x55AA */
            /* frame_build(frame, &d);  见“⑨ 帧组包与 CRC16 校验”流程卡 */
            /* LoRa 发送：uart_send_buf(USART2, frame, 20); */
        }
    }
}

/* ================= 任务 4：监控喂狗（优先级 5，最高） ================= */
static void MonitorTask(void *arg)
{
    for (;;)
    {
        vTaskDelay(pdMS_TO_TICKS(1000));
        /* 心跳法：所有任务都报到才喂狗（单任务卡死也能被发现） */
        /* if (all_heartbeats_ok()) { IWDG_ReloadCounter(); } */
        xSemaphoreGive(wdgHeartbeat);   /* 示例：给心跳信号量 */
    }
}

/* ================= main ================= */
int main(void)
{
    /* FreeRTOS 必须 Group_4，且要在任何中断使能之前设好 */
    NVIC_PriorityGroupConfig(NVIC_PriorityGroup_4);

    /* 硬件初始化（串口 / I2C / ADC+DMA / 定时器 / 看门狗初始化） */
    /* usart_dma_idle_init(); i2c1_init(); adc_dma_circular_init(); ... */

    /* 创建通信对象 */
    qRaw         = xQueueCreate(8, sizeof(SensorData_t));
    qTx          = xQueueCreate(8, sizeof(SensorData_t));
    i2cMutex     = xSemaphoreCreateMutex();
    wdgHeartbeat = xSemaphoreCreateBinary();

    /* 创建任务：深度单位是「字」（128 字 = 512 字节） */
    xTaskCreate(SensorTask,  "Sensor",  128, NULL, 3, NULL);
    xTaskCreate(ProcessTask, "Process", 128, NULL, 3, NULL);
    xTaskCreate(CommTask,    "Comm",    192, NULL, 4, NULL);
    xTaskCreate(MonitorTask, "Monitor", 128, NULL, 5, NULL);

    vTaskStartScheduler();      /* 启动后不返回 */

    for (;;) { }                /* 正常不会走到这里（堆不够才会） */
}

/* 三个常见问题：
 *  1) 任务里忘了阻塞（没 vTaskDelay / 没等队列）→ 同优先级其他任务饿死，看门狗复位
 *  2) 中断里调了非 FromISR 版本（如 xQueueSend）→ 偶发死机
 *  3) 会调 FreeRTOS API 的中断优先级填了 < 5 → configASSERT 卡死
 */

/* ============ 20 字节帧：组包 + CRC16-MODBUS + 解包 ============ */
#include <stdint.h>
#include <string.h>

#define FRAME_HEAD0   0xAA
#define FRAME_HEAD1   0x55
#define FRAME_TAIL0   0x55
#define FRAME_TAIL1   0xAA
#define FRAME_CMD_ENV 0x01
#define FRAME_DATA_LEN 12
#define FRAME_TOTAL_LEN (2 + 1 + 1 + FRAME_DATA_LEN + 2 + 2)   /* = 20 */

/* ---- CRC16-MODBUS（逐位法，最通用） ---- */
uint16_t crc16_modbus(const uint8_t *buf, uint16_t len)
{
    uint16_t crc = 0xFFFF;
    uint16_t i;
    uint8_t  j;

    for (i = 0; i < len; i++)
    {
        crc ^= buf[i];
        for (j = 0; j < 8; j++)
        {
            if (crc & 0x0001) { crc = (crc >> 1) ^ 0xA001; }
            else              { crc = (crc >> 1); }
        }
    }
    return crc;
}

/* ---- 组帧：dat 指向 12 字节数据段 ---- */
uint16_t frame_build(uint8_t *out, uint8_t cmd, const uint8_t *dat)
{
    uint16_t idx = 0;
    uint16_t crc;

    out[idx++] = FRAME_HEAD0;          /* 帧头 0xAA 0x55 */
    out[idx++] = FRAME_HEAD1;
    out[idx++] = cmd;                  /* 命令 */
    out[idx++] = FRAME_DATA_LEN;       /* 长度 = 12 */

    memcpy(&out[idx], dat, FRAME_DATA_LEN);   /* 数据段 */
    idx += FRAME_DATA_LEN;

    /* CRC 范围 = 命令 + 长度 + 数据段 = out[2..15]，共 14 字节 */
    crc = crc16_modbus(&out[2], 2 + FRAME_DATA_LEN);
    out[idx++] = (uint8_t)(crc & 0xFF);       /* 低字节在前 */
    out[idx++] = (uint8_t)(crc >> 8);

    out[idx++] = FRAME_TAIL0;          /* 帧尾 0x55 0xAA */
    out[idx++] = FRAME_TAIL1;

    return idx;                        /* 20 */
}

/* ---- 把传感器数据填成 12 字节数据段 ---- */
void frame_fill_payload(uint8_t *p,
                        int16_t temp_x10, uint16_t humi_x10, uint16_t press_x10,
                        uint16_t lux, uint16_t tvoc, uint16_t mq135)
{
    /* 大端：高字节在前 */
    p[0] = (uint8_t)(temp_x10  >> 8);  p[1] = (uint8_t)temp_x10;
    p[2] = (uint8_t)(humi_x10  >> 8);  p[3] = (uint8_t)humi_x10;
    p[4] = (uint8_t)(press_x10 >> 8);  p[5] = (uint8_t)press_x10;
    p[6] = (uint8_t)(lux       >> 8);  p[7] = (uint8_t)lux;
    p[8] = (uint8_t)(tvoc      >> 8);  p[9] = (uint8_t)tvoc;
    p[10]= (uint8_t)(mq135     >> 8);  p[11]= (uint8_t)mq135;
}

/* ================= 解帧：状态机逐字节扫描 ================= */
typedef enum { ST_HEAD0 = 0, ST_HEAD1, ST_CMD, ST_LEN, ST_DATA, ST_CRC0, ST_CRC1, ST_TAIL0, ST_TAIL1 } ParseState_t;

static ParseState_t st = ST_HEAD0;
static uint8_t  frameBuf[FRAME_TOTAL_LEN];
static uint16_t frameIdx = 0;
static uint8_t  payLen = 0;
static uint32_t crcRx = 0;

/* 每收到一个字节喂一次；返回 1 表示解出一帧完整好帧 */
uint8_t frame_parse_byte(uint8_t b)
{
    switch (st)
    {
        case ST_HEAD0:
            if (b == FRAME_HEAD0) { frameBuf[0] = b; frameIdx = 1; st = ST_HEAD1; }
            break;
        case ST_HEAD1:
            if (b == FRAME_HEAD1) { frameBuf[1] = b; frameIdx = 2; st = ST_CMD; }
            else { st = (b == FRAME_HEAD0) ? ST_HEAD1 : ST_HEAD0; }   /* 重新找帧头 */
            break;
        case ST_CMD:
            frameBuf[frameIdx++] = b; st = ST_LEN;
            break;
        case ST_LEN:
            frameBuf[frameIdx++] = b;
            payLen = b;
            if (payLen > FRAME_DATA_LEN) { st = ST_HEAD0; break; }    /* 长度不合法：丢弃 */
            st = ST_DATA;
            break;
        case ST_DATA:
            frameBuf[frameIdx++] = b;
            if (frameIdx >= 4 + payLen) { st = ST_CRC0; }
            break;
        case ST_CRC0:
            frameBuf[frameIdx++] = b; crcRx  = b; st = ST_CRC1;
            break;
        case ST_CRC1:
            frameBuf[frameIdx++] = b; crcRx |= ((uint32_t)b << 8); st = ST_TAIL0;
            break;
        case ST_TAIL0:
            frameBuf[frameIdx++] = b;
            st = (b == FRAME_TAIL0) ? ST_TAIL1 : ST_HEAD0;
            break;
        case ST_TAIL1:
            frameBuf[frameIdx++] = b;
            st = ST_HEAD0;                                            /* 无论对错都回到起点 */
            if (b == FRAME_TAIL1)
            {
                /* 校验 CRC：范围 = 命令 + 长度 + 数据段 */
                uint16_t crcCalc = crc16_modbus(&frameBuf[2], 2 + payLen);
                if (crcCalc == crcRx) { return 1; }                   /* 好帧 */
            }
            break;
        default:
            st = ST_HEAD0;
            break;
    }
    return 0;
}

/* ---- 解出好帧后取数据（有符号） ---- */
void frame_get_data(const uint8_t *f, int16_t *temp_x10, uint16_t *humi_x10,
                    uint16_t *press_x10, uint16_t *lux, uint16_t *tvoc, uint16_t *mq135)
{
    const uint8_t *p = &f[4];      /* 数据段从第 4 字节开始 */
    *temp_x10  = (int16_t)(((uint16_t)p[0]  << 8) | p[1]);
    *humi_x10  = (uint16_t)(((uint16_t)p[2] << 8) | p[3]);
    *press_x10 = (uint16_t)(((uint16_t)p[4] << 8) | p[5]);
    *lux       = (uint16_t)(((uint16_t)p[6] << 8) | p[7]);
    *tvoc      = (uint16_t)(((uint16_t)p[8] << 8) | p[9]);
    *mq135     = (uint16_t)(((uint16_t)p[10] << 8) | p[11]);
}

/* 温度换算：temp_x10 = 253 → 25.3℃
 *   float t = temp_x10 / 10.0f;
 * 负温示例：-5.0℃ → temp_x10 = -50 → 0xFFCE
 *
 * 工程里 FWLIB\src\modbus.c 已有 CRC16-MODBUS 现成实现，可直接复用（保持一致）。
 */

/* ============ E22 LoRa：AT 配置 + 透传发送 ============ */
/* 假设 LoRa 接在 USART2（PA2=TX / PA3=RX） */

/* ---- 1. 串口初始化（同 ① 的第 1~3 步，换成 USART2） ---- */
void lora_uart_init(void)
{
    RCC_AHB1PeriphClockCmd(RCC_AHB1Periph_GPIOA, ENABLE);
    RCC_APB1PeriphClockCmd(RCC_APB1Periph_USART2, ENABLE);   /* USART2 在 APB1 */

    GPIO_PinAFConfig(GPIOA, GPIO_PinSource2, GPIO_AF_USART2);
    GPIO_PinAFConfig(GPIOA, GPIO_PinSource3, GPIO_AF_USART2);
    GPIO_InitTypeDef g;
    g.GPIO_Pin   = GPIO_Pin_2 | GPIO_Pin_3;
    g.GPIO_Mode  = GPIO_Mode_AF;
    g.GPIO_OType = GPIO_OType_PP;
    g.GPIO_Speed = GPIO_Speed_50MHz;
    g.GPIO_PuPd  = GPIO_PuPd_UP;
    GPIO_Init(GPIOA, &g);

    USART_InitTypeDef u;
    u.USART_BaudRate            = 9600;      /* 必须与模块配置的波特率一致 */
    u.USART_WordLength          = USART_WordLength_8b;
    u.USART_StopBits            = USART_StopBits_1;
    u.USART_Parity              = USART_Parity_No;
    u.USART_Mode                = USART_Mode_Rx | USART_Mode_Tx;
    u.USART_HardwareFlowControl = USART_HardwareFlowControl_None;
    USART_Init(USART2, &u);
    USART_Cmd(USART2, ENABLE);

    /* 要收整包 → 中断接收 + 环形缓冲 + 字节间隔切帧；不要再对该串口配 DMA */
}

