/* ---- 4. 发一条 AT 指令（配置模式下，以 \r\n 结尾） ---- */
void lora_at(const char *cmd)
{
    uart_send_str(USART2, cmd);
    uart_send_str(USART2, "\r\n");
    delay_ms(100);               /* 给模块应答时间；严格做法是等串口回包 */
}

/* 常用 AT 指令（具体以 E22 手册为准，不同固件略有差异）：
 *   AT              测试通信
 *   AT+RESET        模块复位
 *   AT+ADDR         查 / 设模块地址（两端的地址与信道要配对）
 *   AT+NETID        查 / 设网络 ID（两端必须一致）
 *   AT+REG0         查寄存器配置（信道 / 空中速率 / 发射功率都在这一串里）
 *   AT+UART=9600,8,1,NON   设串口：9600 / 8 数据位 / 1 停止位 / 无校验（最后写 NON，不是 0）
 */

/* ---- 5. 透传发送（模块自动无线发出） ---- */
void lora_send_frame(const uint8_t *frame, uint16_t len)
{
    /* 严谨做法：先等 AUX 变高（模块空闲）再发，避免丢包 */
    /* while (GPIO_ReadInputDataBit(GPIOx, AUX_PIN) == 0) { } */
    uart_send_buf(USART2, frame, len);
}

/* ---- 6. 接收：模块收到无线数据会从串口吐出来 ----
 *   直接用 ① 卡的 DMA + 空闲中断，收到一整包后交给 ⑨ 卡的
 *   frame_parse_byte() 逐字节解帧即可。
 */

/* 三个常见问题：
 *  1) TX/RX 没交叉接 → 完全没反应
 *  2) 3.3V 供电电流不足 → 能收不能发，或发几次就重启
 *  3) 两个模块的频率/信道/地址/空中速率任一项不一致 → 收不到
 */

/* ============ 方式一：用本工程现成驱动（强烈推荐） ============ */
/* Project_2 的 FWLIB\inc\esp8266.h 提供：
 *   ESP8266_Init()          初始化
 *   ESP8266_TestAT()        自测 AT
 *   ESP8266_SetMode()       设置模式
 *   ESP8266_JoinAP()        连 WiFi
 *   ESP8266_GetIP()         查 IP
 *   ESP8266_ConnectTCP()    建 TCP
 *   ESP8266_SendCmd()       发命令
 *   ESP8266_SendData()      发数据
 *   ESP8266_HasAsyncData() / ESP8266_GetRawRx()   收异步数据
 *
 * FWLIB\inc\mqtt.h 提供：
 *   MQTT_Connect() / MQTT_ConnectSimple()   连接
 *   MQTT_Publish() / MQTT_PublishInt() / MQTT_PublishFloat() / MQTT_PublishStr()
 *   MQTT_Ping() / MQTT_KeepAliveService()   保活
 *   MQTT_Poll() / MQTT_IsConnected()        收包与状态
 *
 * 典型调用顺序：
 *   ESP8266_Init();
 *   if (ESP8266_TestAT() == 0) { ... }        // AT 通不通
 *   ESP8266_SetMode(1);                       // Station
 *   ESP8266_JoinAP("WiFi名", "WiFi密码");
 *   ESP8266_ConnectTCP("bemfa.com", 1883);    // 巴法云 MQTT
 *   MQTT_Connect("私钥", "订阅主题");
 *   MQTT_Publish("主题", "数据");
 *   // 主循环 / 任务里定期：
 *   MQTT_Poll();
 *   MQTT_KeepAliveService();
 */

/* ============ 方式二：手搓 AT（理解原理/调试用） ============ */
/* 1. 测试 */
/*   发: AT                      收: OK                          */

/* 2. 设 Station 模式 */
/*   发: AT+CWMODE=1             收: OK                          */

/* 3. 连 WiFi（引号要转义） */
/*   发: AT+CWJAP="MyWiFi","12345678"                             */
/*   收: WIFI CONNECTED / WIFI GOT IP / OK                        */

/* 4. 连巴法云 MQTT（单连接模式） */
/*   发: AT+CIPMUX=0             收: OK                          */
/*   发: AT+CIPSTART="TCP","bemfa.com",1883                       */
/*   收: CONNECT / OK                                             */

/* 5. 发 MQTT CONNECT 报文（十六进制，需按 MQTT 协议拼） */
/*   发: AT+CIPSEND=<len>        收: >                           */
/*   然后发 <len> 字节的二进制 MQTT CONNECT 报文                  */
/*   收: SEND OK                                                  */

/* 6. 发布数据 */
/*   发: AT+CIPSEND=<len>        收: >                           */
/*   然后发 MQTT PUBLISH 报文字节                                  */

/* 7. 心跳保活（默认 keepalive 60s，要在这之前发） */
/*   发: MQTT PINGREQ 报文（2 字节：0xC0 0x00）                    */

/* 三个常见问题：
 *  1) 供电不足（用板子 3.3V）→ 连 WiFi 时反复重启
 *  2) 忘记发心跳 → 服务器约 1.5 倍 keepalive 后断开
 *  3) MQTT 主题名写错 → 连上了但巴法云收不到数据
 *
 * 建议：先用串口助手手动发 AT 指令走通一遍，再用代码实现。
 */

/* ============ IWDG 初始化 + 心跳喂狗 ============ */
#define TASK_NUM      4
static volatile uint8_t hbFlag[TASK_NUM] = {0};    /* 各任务心跳标志 */

void iwdg_init(void)
{
    /* 超时 ≈ 64 × (1250) / 32768 ≈ 2.44s */
    RCC_APB1PeriphClockCmd(RCC_APB1Periph_IWDG, ENABLE);
    IWDG_WriteAccessCmd(IWDG_WriteAccess_Enable);
    IWDG_SetPrescaler(IWDG_Prescaler_64);
    IWDG_SetReload(1250);
    IWDG_ReloadCounter();          /* 先喂一次 */
    IWDG_Enable();                 /* 启动后无法用软件关闭 */
}

/* ---- 各任务在自己循环里调用：报个到 ---- */
void hb_report(uint8_t id)
{
    if (id < TASK_NUM) { hbFlag[id] = 1; }
}

/* ---- 监控任务里：所有任务都到了才喂狗 ---- */
void monitor_task_body(void)
{
    uint8_t i;
    uint8_t allOk = 1;

    for (i = 0; i < TASK_NUM; i++)
    {
        if (hbFlag[i] == 0) { allOk = 0; }    /* 有一个没报到 → 不喂 */
    }

    if (allOk)
    {
        IWDG_ReloadCounter();                 /* 全部到齐才喂狗 */
        for (i = 0; i < TASK_NUM; i++) { hbFlag[i] = 0; }   /* 清标志，下轮重新报 */
    }
    /* 若有任务没报到 → 不喂狗 → 约 2.4s 后自动复位 */
}

