/* 用 IWDG 调试时的问题：
 *   在 Keil 里单步调试时，程序停住不喂狗 → 会被复位。
 *   调试阶段可以先不调 IWDG_Enable()，或临时把超时设长。
 *
 * 也可以直接用工程里现成的 sys_wdg（FWLIB\inc\sys_wdg.h），
 *   它已经实现了「心跳喂狗 + 看门狗初始化」，不用自己写。
 */

/* ============ SPI1 主机：初始化 + 收发一个字节（裸机版） ============ */
#include "stm32f4xx.h"

/* ---- 1. 开时钟：SPI1 在 APB2，引脚在 GPIOA（AHB1） ---- */
void SPI1_Master_Init(void)
{
    GPIO_InitTypeDef g;
    SPI_InitTypeDef  s;

    RCC_AHB1PeriphClockCmd(RCC_AHB1Periph_GPIOA, ENABLE);
    RCC_APB2PeriphClockCmd(RCC_APB2Periph_SPI1,  ENABLE);

    /* ---- 2. 引脚复用：SCK=PA5 MISO=PA6 MOSI=PA7 ---- */
    GPIO_PinAFConfig(GPIOA, GPIO_PinSource5, GPIO_AF_SPI1);
    GPIO_PinAFConfig(GPIOA, GPIO_PinSource6, GPIO_AF_SPI1);
    GPIO_PinAFConfig(GPIOA, GPIO_PinSource7, GPIO_AF_SPI1);

    g.GPIO_Pin   = GPIO_Pin_5 | GPIO_Pin_6 | GPIO_Pin_7;
    g.GPIO_Mode  = GPIO_Mode_AF;          /* 复用功能 */
    g.GPIO_OType = GPIO_OType_PP;         /* 推挽 */
    g.GPIO_Speed = GPIO_Speed_100MHz;     /* SPI 高速时必须 100MHz */
    g.GPIO_PuPd  = GPIO_PuPd_UP;
    GPIO_Init(GPIOA, &g);

    /* ---- CS 用软件管理：另配成普通推挽输出，空闲拉高 ---- */
    g.GPIO_Pin  = GPIO_Pin_4;
    g.GPIO_Mode = GPIO_Mode_OUT;
    g.GPIO_PuPd = GPIO_PuPd_UP;
    GPIO_Init(GPIOA, &g);
    GPIO_SetBits(GPIOA, GPIO_Pin_4);          /* CS 空闲高 */

    /* ---- 3. SPI 参数（模式 0：CPOL=0 / CPHA=1Edge） ---- */
    s.SPI_Direction         = SPI_Direction_2Lines_FullDuplex;
    s.SPI_Mode              = SPI_Mode_Master;
    s.SPI_DataSize          = SPI_DataSize_8b;
    s.SPI_CPOL              = SPI_CPOL_Low;    /* 空闲时 SCK = 低 */
    s.SPI_CPHA              = SPI_CPHA_1Edge;  /* 第 1 个边沿采样 */
    s.SPI_NSS               = SPI_NSS_Soft;    /* 软件 CS */
    s.SPI_BaudRatePrescaler = SPI_BaudRatePrescaler_8;   /* 84MHz/8 = 10.5MHz */
    s.SPI_FirstBit          = SPI_FirstBit_MSB;/* Flash 必须 MSB 在前 */
    s.SPI_CRCPolynomial     = 7;
    SPI_Init(SPI1, &s);

    /* ---- 4. 顺序不能反：先 Init 再 Cmd ---- */
    SPI_Cmd(SPI1, ENABLE);
}

/* ---- 5. 收发一个字节（SPI 是全双工：发一个必然收一个） ---- */
uint8_t SPI1_TransferByte(uint8_t tx)
{
    /* 等发送缓冲空 */
    while (SPI_I2S_GetFlagStatus(SPI1, SPI_I2S_FLAG_TXE) == RESET) { }
    SPI_I2S_SendData(SPI1, tx);
    /* 等接收缓冲非空 */
    while (SPI_I2S_GetFlagStatus(SPI1, SPI_I2S_FLAG_RXNE) == RESET) { }
    return (uint8_t)SPI_I2S_ReceiveData(SPI1);
}

/* ---- 6. 用法：读 Flash 的 JEDEC ID（命令 0x9F，应得 0xC84018=GD25Q128） ---- */
uint32_t Flash_ReadID(void)
{
    uint32_t id;
    GPIO_ResetBits(GPIOA, GPIO_Pin_4);        /* CS 拉低：开始 */
    (void)SPI1_TransferByte(0x9F);            /* 命令 */
    id  = (uint32_t)SPI1_TransferByte(0xFF) << 16;
    id |= (uint32_t)SPI1_TransferByte(0xFF) << 8;
    id |= (uint32_t)SPI1_TransferByte(0xFF);
    GPIO_SetBits(GPIOA, GPIO_Pin_4);          /* CS 拉高：结束 */
    return id;
}

/* 常见问题：
 * 1) 忘了 SPI_Cmd(ENABLE) → 两个 while 都死等，看起来像“程序卡死”
 * 2) CPOL/CPHA 填错 → 收回来全是 0xFF 或 0x00（时序采错位）
 * 3) 忘了拉低 CS → 从机根本不响应，读回全 0xFF
 * 4) 多从机共用 SPI 却没有各自独立的 CS → 两个器件同时驱动 MISO，数据互撞
 *
 * 本项目 FWLIB 里已经有现成驱动，直接用，别手搓：
 *     板2：SYS_SPI_Init / SYS_SPI_TransferByte / SYS_SPI_Transfer / SYS_SPI_Read
 *          W25QXX_Init / W25QXX_ReadID / W25QXX_Read / W25QXX_Write / W25QXX_EraseSector
 *     板1：sys_spi.c 同一套 API（SYS_SPI_*） *    SYS_SPI_TransferByte 内部自带超时（SYS_SPI_TIMEOUT），
 *      从机没接好时返回 0xFF 并累加 SYS_SPI_TimeoutCount()，不会死等。
 */

/* ============ 输出比较三种典型用法（对照着看就懂区别） ============ */
#include "stm32f4xx.h"

/* ------------------------------------------------------------------
 * 用法 A：纯定时，到点进中断，引脚完全不动
 *   适合：精确定时采样、软件计时器、任务调度节拍
 * ------------------------------------------------------------------ */
static volatile uint32_t g_tick_100us = 0;

void TIM_OC_Timing_Init(void)
{
    GPIO_InitTypeDef        g;
    TIM_TimeBaseInitTypeDef tb;
    TIM_OCInitTypeDef       oc;
    NVIC_InitTypeDef        ni;

    RCC_APB1PeriphClockCmd(RCC_APB1Periph_TIM3, ENABLE);

    /* 时基：84MHz/(83+1)=1MHz，计数 100 次 = 100µs */
    tb.TIM_Prescaler         = 84 - 1;
    tb.TIM_CounterMode       = TIM_CounterMode_Up;
    tb.TIM_Period            = 100 - 1;
    tb.TIM_ClockDivision     = TIM_CKD_DIV1;
    tb.TIM_RepetitionCounter = 0;
    TIM_TimeBaseInit(TIM3, &tb);

    /* 关键：OCMode = Timing，只置标志，不碰引脚 */
    oc.TIM_OCMode      = TIM_OCMode_Timing;
    oc.TIM_OutputState = TIM_OutputState_Disable;   /* 引脚输出关掉 */
    oc.TIM_Pulse       = 50;                        /* 计到 50 就触发（周期中点） */
    oc.TIM_OCPolarity  = TIM_OCPolarity_High;
    TIM_OC1Init(TIM3, &oc);

    /* 开通道 1 的比较中断 */
    TIM_ITConfig(TIM3, TIM_IT_CC1, ENABLE);

    ni.NVIC_IRQChannel                   = TIM3_IRQn;
    ni.NVIC_IRQChannelPreemptionPriority = 5;      /* FreeRTOS 下必须 ≥5 */
    ni.NVIC_IRQChannelSubPriority        = 0;
    ni.NVIC_IRQChannelCmd                = ENABLE;
    NVIC_Init(&ni);

    TIM_Cmd(TIM3, ENABLE);
}

/* TIM3 中断：通用定时器所有通道共用一个中断函数 */
void TIM3_IRQHandler(void)
{
    if (TIM_GetITStatus(TIM3, TIM_IT_CC1) != RESET)
    {
        TIM_ClearITPendingBit(TIM3, TIM_IT_CC1);   /* 必须清，否则反复进 */
        g_tick_100us++;
        /* 下一次比较点 = 当前 + 100（自动重装，形成等间隔中断） */
        TIM_SetCompare1(TIM3, (uint16_t)(TIM_GetCounter(TIM3) + 50));
    }
}

/* ------------------------------------------------------------------
 * 用法 B：单次精确脉冲，引脚输出一个宽度由 CCR 决定的高电平
 *   适合：超声触发、步进电机走一步、给传感器一个精确时钟
 * ------------------------------------------------------------------ */
void TIM_OC_OneShot_Init(void)      /* 例：TIM2_CH1 = PA0 */
{
    GPIO_InitTypeDef        g;
    TIM_TimeBaseInitTypeDef tb;
    TIM_OCInitTypeDef       oc;

    RCC_AHB1PeriphClockCmd(RCC_AHB1Periph_GPIOA, ENABLE);
    RCC_APB1PeriphClockCmd(RCC_APB1Periph_TIM2,  ENABLE);

    GPIO_PinAFConfig(GPIOA, GPIO_PinSource0, GPIO_AF_TIM2);
    g.GPIO_Pin   = GPIO_Pin_0;
    g.GPIO_Mode  = GPIO_Mode_AF;
    g.GPIO_OType = GPIO_OType_PP;
    g.GPIO_Speed = GPIO_Speed_100MHz;
    g.GPIO_PuPd  = GPIO_PuPd_UP;
    GPIO_Init(GPIOA, &g);

    /* 1MHz 计数：1 个 tick = 1µs */
    tb.TIM_Prescaler         = 84 - 1;
    tb.TIM_CounterMode       = TIM_CounterMode_Up;
    tb.TIM_Period            = 0xFFFF;
    tb.TIM_ClockDivision     = TIM_CKD_DIV1;
    tb.TIM_RepetitionCounter = 0;
    TIM_TimeBaseInit(TIM2, &tb);

    /* Active 模式：计到 CCR 时引脚变高（发脉冲起点） */
    oc.TIM_OCMode      = TIM_OCMode_Active;
    oc.TIM_OutputState = TIM_OutputState_Enable;
    oc.TIM_Pulse       = 10;              /* 10µs 后拉高 */
    oc.TIM_OCPolarity  = TIM_OCPolarity_High;
    TIM_OC1Init(TIM2, &oc);
    TIM_OC1PreloadConfig(TIM2, TIM_OCPreload_Disable);  /* 运行期改 CCR 立即生效 */

    TIM_Cmd(TIM2, ENABLE);
}

/* 发一个脉冲：先归零计数，再让它跑到 CCR+宽度 */
void Pulse_Once(uint16_t width_us)
{
    TIM_SetCounter(TIM2, 0);
    TIM_SetCompare1(TIM2, width_us);
    TIM_Cmd(TIM2, ENABLE);
    /* 等待这一轮跑完（裸机可忙等；RTOS 里请用事件/中断通知） */
    while (TIM_GetCounter(TIM2) < width_us) { }
    TIM_Cmd(TIM2, DISABLE);
    TIM_SetCounter(TIM2, 0);
    GPIO_ResetBits(GPIOA, GPIO_Pin_0);      /* 收尾拉低，保证下次从低开始 */
}

/* ------------------------------------------------------------------
 * 用法 C：运行期切换模式 + 强制输出（软件控制引脚电平）
 * ------------------------------------------------------------------ */
void OC_SwitchDemo(void)
{
    /* 运行期改模式：必须用 TIM_SelectOCxM（直接改结构体再 Init 是错的） */
    TIM_SelectOCxM(TIM2, TIM_Channel_1, TIM_OCMode_Toggle);
    TIM_CCxCmd(TIM2, TIM_Channel_1, TIM_CCx_Enable);

    /* 不看计数，立刻把引脚拉高/拉低（做“软件电平控制”） */
    TIM_ForcedOC1Config(TIM2, TIM_ForcedAction_Active);     /* 立刻高 */
    TIM_ForcedOC1Config(TIM2, TIM_ForcedAction_Inactive);   /* 立刻低 */
}

/* 常见问题：
 * 1) 把“输出比较”当成 PWM 用 → 以为引脚会自动出波形。
 *    只有 OutputState=Enable 且 OCMode 是 PWM/Active/Toggle 时引脚才动。
 * 2) 忘了 TIM_ClearITPendingBit → 中断里出不来，CPU 100% 占用。
 * 3) 通用定时器 TIM2~5 只有一个中断入口，多个通道要在同一个函数里分别判。
 * 4) 运行期改 OCMode：用 TIM_SelectOCxM，不要改结构体再 TIM_OCxInit。
 * 5) 高级定时器 TIM1/TIM8 还要 TIM_CtrlPWMOutputs (ENABLE)，否则引脚无输出。
 *
 * 本项目 FWLIB：sys_tim.c 已有 SYS_TIM_* 封装（含 PWM 通道与频率调整），
 *   但输出比较/单脉冲的封装还没做，要用 OC 就照本卡自己加，
 *    NVIC 优先级要 ≥5（FreeRTOS 红线），且中断函数名别和库里 __weak 的撞。
 */

/* ============ DAC 输出 0~3.3V 模拟电压 ============ */
#include "stm32f4xx.h"

void DAC1_Init(void)                      /* DAC1 -> PA4 */
{
    GPIO_InitTypeDef g;
    DAC_InitTypeDef  d;

    RCC_AHB1PeriphClockCmd(RCC_AHB1Periph_GPIOA, ENABLE);
    RCC_APB1PeriphClockCmd(RCC_APB1Periph_DAC,   ENABLE);

    /* 关键：DAC 引脚必须配成【模拟模式】，不是复用。
     *    若照 SPI/USART 的写法配成 GPIO_Mode_AF，引脚无输出。 */
    g.GPIO_Pin   = GPIO_Pin_4;
    g.GPIO_Mode  = GPIO_Mode_AN;          /* AN = analog，不是 AF */
    g.GPIO_OType = GPIO_OType_PP;         /* 模拟模式下这两项无意义 */
    g.GPIO_Speed = GPIO_Speed_100MHz;
    g.GPIO_PuPd  = GPIO_PuPd_NOPULL;      /* 模拟输入禁止上下拉 */
    GPIO_Init(GPIOA, &g);

    d.DAC_Trigger          = DAC_Trigger_None;          /* 软件触发 */
    d.DAC_WaveGeneration   = DAC_WaveGeneration_None;    /* 无波形发生器 */
    d.DAC_LFSRUnmask_TriangleAmplitude = DAC_LFSRUnmask_Bit0;
    d.DAC_OutputBuffer     = DAC_OutputBuffer_Enable;    /* 开缓冲，带载强 */
    DAC_Init(DAC_Channel_1, &d);

    DAC_Cmd(DAC_Channel_1, ENABLE);
    DAC_SetChannel1Data(DAC_Align_12b_R, 0);
}

/* ---- 按电压值输出（0.0 ~ 3.3V） ---- */
void DAC1_SetVoltage(float v)
{
    uint16_t val;

    if (v < 0.0f) { v = 0.0f; }
    if (v > 3.3f) { v = 3.3f; }

    val = (uint16_t)(v / 3.3f * 4095.0f + 0.5f);

    DAC_SetChannel1Data(DAC_Align_12b_R, val);

    /* 软件触发模式下必须再调这一句，否则输出不更新。
     *    现象：“我明明写了值，万用表量还是 0V”。 */
    DAC_SoftwareTriggerCmd(DAC_Channel_1, ENABLE);
}

/* ---- 按数字量输出（0 ~ 4095），不经过浮点，更快 ---- */
void DAC1_SetRaw(uint16_t val)
{
    if (val > 4095) { val = 4095; }
    DAC_SetChannel1Data(DAC_Align_12b_R, val);
    DAC_SoftwareTriggerCmd(DAC_Channel_1, ENABLE);
}

/* 常见问题：
 * 1) 引脚配成 GPIO_Mode_AF → 完全没有输出（必须是 GPIO_Mode_AN）
 * 2) 忘了 DAC_SoftwareTriggerCmd → 值写了但引脚不变
 * 3) 忘了 DAC_Cmd(ENABLE) → 同上
 * 4) 开了 OutputBuffer 却想要 0V → 最低只能到约 0.2V
 * 5) PA4 被 DAC 占用 → SPI1 的 NSS 就不能再用它（本项目 W25QXX 用软件 CS，正好避开）
 */

/* ============ CAN1 初始化 + 收发（500kbps，APB1=42MHz） ============ */
#include "stm32f4xx.h"

void CAN1_Init_500k(void)
{
    GPIO_InitTypeDef      g;
    CAN_InitTypeDef       c;
    CAN_FilterInitTypeDef cf;
    NVIC_InitTypeDef      ni;

    RCC_AHB1PeriphClockCmd(RCC_AHB1Periph_GPIOD, ENABLE);
    RCC_APB1PeriphClockCmd(RCC_APB1Periph_CAN1,  ENABLE);

    /* ---- 1. 引脚：PD0=RX / PD1=TX，复用推挽，速度至少 50MHz ---- */
    GPIO_PinAFConfig(GPIOD, GPIO_PinSource0, GPIO_AF_CAN1);
    GPIO_PinAFConfig(GPIOD, GPIO_PinSource1, GPIO_AF_CAN1);
    g.GPIO_Pin   = GPIO_Pin_0 | GPIO_Pin_1;
    g.GPIO_Mode  = GPIO_Mode_AF;
    g.GPIO_OType = GPIO_OType_PP;
    g.GPIO_Speed = GPIO_Speed_50MHz;
    g.GPIO_PuPd  = GPIO_PuPd_UP;
    GPIO_Init(GPIOD, &g);

    /* ---- 2. 位时序：42MHz / (1+5+6) / 7预分频 = 500kbps ---- */
    c.CAN_TTCM = DISABLE;                  /* 时间触发模式：不用 */
    c.CAN_ABOM = ENABLE;                   /* 自动总线恢复：必须开。 */
    c.CAN_AWUM = DISABLE;                  /* 自动唤醒 */
    c.CAN_NART = DISABLE;                  /* 关掉 = 发送失败自动重发（工业场合要的） */
    c.CAN_RFLM = DISABLE;                  /* 溢出时覆盖旧报文 */
    c.CAN_TXFP = DISABLE;                  /* 按标识符优先级发 */
    c.CAN_Mode = CAN_Mode_Normal;          /* 回环测试用 CAN_Mode_LoopBack */
    c.CAN_SJW  = CAN_SJW_1tq;
    c.CAN_BS1  = CAN_BS1_5tq;
    c.CAN_BS2  = CAN_BS2_6tq;
    c.CAN_Prescaler = 7;                   /* 42M / (1+5+6) / 7 = 500k */
    CAN_Init(CAN1, &c);

    /* ---- 3. 过滤器：不配它，FIFO 永远是空的。 ---- */
    cf.CAN_FilterNumber         = 0;
    cf.CAN_FilterMode           = CAN_FilterMode_IdMask;
    cf.CAN_FilterScale          = CAN_FilterScale_32bit;
    cf.CAN_FilterIdHigh         = 0x0000;   /* 全收：Id 与 Mask 都填 0 */
    cf.CAN_FilterIdLow          = 0x0000;
    cf.CAN_FilterMaskIdHigh     = 0x0000;
    cf.CAN_FilterMaskIdLow      = 0x0000;
    cf.CAN_FilterFIFOAssignment = CAN_Filter_FIFO0;
    cf.CAN_FilterActivation     = ENABLE;
    CAN_FilterInit(&cf);

    /* ---- 4. FIFO0 收到报文就中断 ---- */
    CAN_ITConfig(CAN1, CAN_IT_FMP0, ENABLE);

    ni.NVIC_IRQChannel                   = CAN1_RX0_IRQn;
    ni.NVIC_IRQChannelPreemptionPriority = 5;      /* FreeRTOS 红线 */
    ni.NVIC_IRQChannelSubPriority        = 0;
    ni.NVIC_IRQChannelCmd                = ENABLE;
    NVIC_Init(&ni);
}

/* ---- 5. 发一帧（8 字节以内） ---- */
uint8_t CAN1_Send(uint32_t std_id, const uint8_t *data, uint8_t len)
{
    CanTxMsg tx;
    uint8_t  i;

    if (len > 8) { len = 8; }              /* CAN 一帧最多 8 字节 */

    tx.StdId = std_id;
    tx.ExtId = 0;
    tx.IDE   = CAN_Id_Standard;
    tx.RTR   = CAN_RTR_Data;
    tx.DLC   = len;
    for (i = 0; i < 8; i++) { tx.Data[i] = (i < len) ? data[i] : 0; }

    if (CAN_Transmit(CAN1, &tx) == CAN_TxStatus_NoMailBox) { return 1; }

    i = 0;
    while (CAN_TransmitStatus(CAN1, 0) == CAN_TxStatus_Pending && i < 100) { i++; delay_ms(1); }

    return (CAN_TransmitStatus(CAN1, 0) == CAN_TxStatus_Ok) ? 0 : 2;
}

/* ---- 6. 中断里收 ---- */
static volatile uint32_t g_can_rx_cnt = 0;
static uint8_t           g_can_last[8];

void CAN1_RX0_IRQHandler(void)
{
    CanRxMsg rx;
    uint8_t  i;

    if (CAN_GetITStatus(CAN1, CAN_IT_FMP0) != RESET)   /* FMP0 = FIFO 有待处理报文 */
    {
        CAN_Receive(CAN1, CAN_FIFO0, &rx);
        for (i = 0; i < 8; i++) { g_can_last[i] = rx.Data[i]; }
        g_can_rx_cnt++;
        /* FMP0 在 CAN_Receive 后由硬件自动更新，无需手动清 */
    }
}

/* 常见问题（按出错频率排序）：
 * 1) 没调 CAN_FilterInit → FIFO 永远空、中断永不触发。
 *    现象：发送正常，但收不到任何报文。
 * 2) CAN_ABOM = DISABLE → 一次错误风暴进了 Bus-Off 就彻底静默。
 * 3) 波特率算错 → 其他节点全听不懂（ACK 错误 → 一直重发 → Bus-Off）。
 *    500kbps 时一位 = 2µs，可用示波器量。
 * 4) 终端电阻少了或多了 → 短距离能通、长距离时好时坏。
 * 5) CAN_Mode_LoopBack 自发自收永远成功，不能当“通了”的证据。
 *
 * 本项目 FWLIB（板2）：sys_can.c 有 SYS_CAN_Init / SYS_CAN_Transmit /
 *   SYS_CAN_InitIT(cb) / SYS_CAN_SetSilentMode / SYS_CAN_LoopbackTest，
 *   CAN1 引脚是 PA11/PA12（不是 PD0/PD1），波特率用枚举 SYS_CAN_500K。
 *   已知问题：SetSilentMode 与 LoopbackTest 内部会 CAN_DeInit + CAN_Init，
 *   过滤器配置和 CAN_ITConfig(FMP0) 会被一起清掉 → 调用后中断接收失效，
 *   必须重新 CAN_FilterInit + CAN_ITConfig。
 */

/* ============ RTC 闹钟 + 周期唤醒（中断驱动，主循环零轮询） ============ */
#include "stm32f4xx.h"

static volatile uint8_t  g_alarm_fired = 0;
static volatile uint32_t g_wakeup_cnt  = 0;

/* ------------------------------------------------------------------
 * 1. 每天固定时刻的闹钟（例：每天 08:30:00 触发）
 *    关键在 RTC_AlarmMask，屏蔽掉“日”，才会每天都响
 * ------------------------------------------------------------------ */
void RTC_AlarmDaily_Init(uint8_t hour, uint8_t min, uint8_t sec)
{
    RTC_AlarmTypeDef alarm;
    NVIC_InitTypeDef ni;
    EXTI_InitTypeDef ex;

    RTC_WriteProtectionCmd(DISABLE);              /* 改 RTC 寄存器前必须关写保护 */

    alarm.RTC_AlarmTime.RTC_H12     = RTC_H12_AMPM;      /* 用 24 小时制就不看它 */
    alarm.RTC_AlarmTime.RTC_Hours   = hour;
    alarm.RTC_AlarmTime.RTC_Minutes = min;
    alarm.RTC_AlarmTime.RTC_Seconds = sec;
    alarm.RTC_AlarmMask = RTC_AlarmMask_DateWeekDay;      /* 屏蔽日期 → 每天 */
    alarm.RTC_AlarmDateWeekDaySel = RTC_AlarmDateWeekDaySel_Date;
    alarm.RTC_AlarmDateWeekDay = 1;

    RTC_SetAlarm(RTC_Format_BIN, RTC_Alarm_A, &alarm);

    RTC_AlarmCmd(RTC_Alarm_A, ENABLE);            /* 写了值还不够，必须开开关 */

    RTC_ITConfig(RTC_IT_ALRA, ENABLE);            /* 中断使能 */

    RTC_ClearFlag(RTC_FLAG_ALRAF);                /* 清历史标志，防开机就进中断 */
    RTC_WriteProtectionCmd(ENABLE);               /* 恢复写保护 */

    ni.NVIC_IRQChannel                   = RTC_Alarm_IRQn;
    ni.NVIC_IRQChannelPreemptionPriority = 5;     /* FreeRTOS 红线 */
    ni.NVIC_IRQChannelSubPriority        = 0;
    ni.NVIC_IRQChannelCmd                = ENABLE;
    NVIC_Init(&ni);

    EXTI_ClearITPendingBit(EXTI_Line17);          /* 闹钟走 EXTI17，必须清+配 */
    ex.EXTI_Line    = EXTI_Line17;
    ex.EXTI_Mode    = EXTI_Mode_Interrupt;
    ex.EXTI_Trigger = EXTI_Trigger_Rising;
    ex.EXTI_LineCmd = ENABLE;
    EXTI_Init(&ex);
}

/* ------------------------------------------------------------------
 * 2. 周期唤醒（例：每 1 秒进一次中断）
 * ------------------------------------------------------------------ */
void RTC_WakeUp1s_Init(void)
{
    NVIC_InitTypeDef ni;
    EXTI_InitTypeDef ex;

    RTC_WriteProtectionCmd(DISABLE);

    /* 时钟源 RTCCLK/16：32768/16 = 2048Hz → 要 1 秒，计数值 = 2048 - 1 */
    RTC_WakeUpClockConfig(RTC_WakeUpClock_RTCCLK_Div16);
    RTC_SetWakeUpCounter(2047);

    RTC_ClearFlag(RTC_FLAG_WUTF);
    RTC_ITConfig(RTC_IT_WUT, ENABLE);

    RTC_WriteProtectionCmd(ENABLE);
    RTC_WakeUpCmd(ENABLE);                        /* 不使能就不计数 */

    ni.NVIC_IRQChannel                   = RTC_Alarm_IRQn;   /* 和闹钟共用向量 */
    ni.NVIC_IRQChannelPreemptionPriority = 5;
    ni.NVIC_IRQChannelSubPriority        = 0;
    ni.NVIC_IRQChannelCmd                = ENABLE;
    NVIC_Init(&ni);

    EXTI_ClearITPendingBit(EXTI_Line22);          /* 唤醒走 EXTI22 */
    ex.EXTI_Line    = EXTI_Line22;
    ex.EXTI_Mode    = EXTI_Mode_Interrupt;
    ex.EXTI_Trigger = EXTI_Trigger_Rising;
    ex.EXTI_LineCmd = ENABLE;
    EXTI_Init(&ex);
}

/* ------------------------------------------------------------------
 * 3. 共用中断：ALARM A / ALARM B / WAKEUP 三种标志都要判
 * ------------------------------------------------------------------ */
void RTC_Alarm_IRQHandler(void)
{
    if (RTC_GetITStatus(RTC_IT_ALRA) != RESET)
    {
        RTC_ClearITPendingBit(RTC_IT_ALRA);       /* 不清会反复进 */
        EXTI_ClearITPendingBit(EXTI_Line17);
        g_alarm_fired = 1;
    }
    if (RTC_GetITStatus(RTC_IT_ALRB) != RESET)
    {
        RTC_ClearITPendingBit(RTC_IT_ALRB);
        EXTI_ClearITPendingBit(EXTI_Line17);
    }
    if (RTC_GetITStatus(RTC_IT_WUT) != RESET)
    {
        RTC_ClearITPendingBit(RTC_IT_WUT);
        EXTI_ClearITPendingBit(EXTI_Line22);
        g_wakeup_cnt++;
    }
}

/* 常见问题：
 * 1) 只调 RTC_SetAlarm 没调 RTC_AlarmCmd(ENABLE) → 闹钟永远不响。
 * 2) RTC_AlarmMask 没屏蔽日期 → 会误认为“每天”，是“每月那一天”。
 * 3) 忘了配 EXTI_Line17/22 → RTC 中断到不了 NVIC。
 * 4) 改 RTC 寄存器没先 RTC_WriteProtectionCmd(DISABLE) → 写不进去，静默失败。
 * 5) 备份域掉电（VBAT 没接电池）后时间与闹钟全丢 → 本工程用 BKP_DR0 魔数判首次上电。
 *
 * 本项目 FWLIB 已有封装：板1 sys_rtc.h 的 SYS_RTC_SetAlarmDaily /
 *   SYS_RTC_SetAlarmCallback / SYS_RTC_WakeUp1sOn；
 *   板2 的 sys_rtc.c 带 SYS_RTC_IsBackupValid（备份域掉电检测）。
 */

/* ============================================================
 *  SPI Flash 断网缓存日志，分区 / 槽结构 / 原子提交 / 环形回绕
 *  平台：STM32F407 · GD25Q128 · SPI1 重映射 PB3/PB4/PB5 · CS = PB14
 * ============================================================ */
#include "stm32f4xx.h"
#include "w25qxx.h"

/* ---- ① 分区表：改这里就等于改整个存储布局 ---- */
#define ADDR_PARAM   0x000000UL      /* 参数区：1 扇区                    */
#define ADDR_LOG     0x001000UL      /* 日志区：16 扇区 = 64KB            */
#define ADDR_FONT    0x020000UL      /* 字库 / 图片区                     */

/* ---- ② 槽结构：32 字节一条，4KB 扇区正好 128 条 ---- */
#define SLOT_SIZE    32U
#define HDR_SIZE     12U
#define PAYLOAD      (SLOT_SIZE - HDR_SIZE)                        /* 20  */
#define LOG_SECTORS  16U
#define SLOTS_PER_SEC (W25QXX_SECTOR_SIZE / SLOT_SIZE)             /* 128 */
#define LOG_CAPACITY  ((uint16_t)(LOG_SECTORS * SLOTS_PER_SEC))    /* 2048 */
#define LOG_EMPTY    0xFFFFFFFFUL

/* 槽内 12 字节头（小端）：
 *   [0..4)   seq  序号，0xFFFFFFFF = 空槽（唯一有效性判据）
 *   [4..8)   ts   时间戳（秒）
 *   [8..10)  len  载荷长度
 *   [10..12) crc  CRC16-MODBUS，覆盖 ts + len + 载荷
 */

static uint16_t s_head;              /* 下一个要写的槽 */
static uint16_t s_count;             /* 当前有效条数   */
static uint32_t s_next_seq = 1UL;    /* 递增序号，跳过 0xFFFFFFFF */
static uint16_t s_lost;              /* 被挤掉 / 被擦掉的条数（必须上报） */

/* ---- CRC16-MODBUS：多项式 0xA001，初值 0xFFFF，末尾不异或 ---- */
static uint16_t log_crc16(const uint8_t *buf, uint16_t len)
{
    uint16_t crc = 0xFFFFU;
    uint16_t i;
    uint8_t  b;

    for (i = 0U; i < len; i++)
    {
        crc ^= (uint16_t)buf[i];
        for (b = 0U; b < 8U; b++)
        {
            if (crc & 0x0001U) { crc = (uint16_t)((crc >> 1) ^ 0xA001U); }
            else               { crc = (uint16_t)(crc >> 1); }
        }
    }
    return crc;
}

static uint32_t slot_addr(uint16_t index)
{
    return ADDR_LOG + (uint32_t)index * SLOT_SIZE;
}

/* 数一数某个扇区里还有几条「活着」的记录（seq != 0xFFFFFFFF） */
static uint16_t log_sector_live(uint16_t first)
{
    uint8_t  rec[SLOT_SIZE];
    uint32_t sq;
    uint16_t i, k = 0U;

    for (i = 0U; i < SLOTS_PER_SEC; i++)
    {
        if (W25QXX_Read(rec, slot_addr((uint16_t)(first + i)), SLOT_SIZE) != 0U) { continue; }
        sq = (uint32_t)rec[0] | ((uint32_t)rec[1] << 8) |
             ((uint32_t)rec[2] << 16) | ((uint32_t)rec[3] << 24);
        if (sq != LOG_EMPTY) { k++; }
    }
    return k;
}

/* ---- ③ 写一条：先写数据区，最后才写 seq ---- */
uint8_t log_write(uint32_t ts, const uint8_t *data, uint16_t len)
{
    uint8_t  rec[SLOT_SIZE];
    uint8_t  body[6U + PAYLOAD];
    uint16_t crc;
    uint16_t i;

    if (data == 0 || len == 0U || len > PAYLOAD) { return 1U; }

    for (i = 0U; i < SLOT_SIZE; i++) { rec[i] = 0xFFU; }

    rec[4] = (uint8_t)(ts);        rec[5] = (uint8_t)(ts >>  8);
    rec[6] = (uint8_t)(ts >> 16);  rec[7] = (uint8_t)(ts >> 24);
    rec[8] = (uint8_t)(len);       rec[9] = (uint8_t)(len >> 8);

    for (i = 0U; i < len; i++) { rec[HDR_SIZE + i] = data[i]; }

    /* CRC 只覆盖 ts + len + 载荷，seq 是最后写的，算进去就自相矛盾 */
    body[0] = rec[4]; body[1] = rec[5]; body[2] = rec[6]; body[3] = rec[7];
    body[4] = rec[8]; body[5] = rec[9];
    for (i = 0U; i < len; i++) { body[6U + i] = rec[HDR_SIZE + i]; }
    crc = log_crc16(body, (uint16_t)(6U + len));
    rec[10] = (uint8_t)(crc);      rec[11] = (uint8_t)(crc >> 8);

    /* ---- 该槽还是脏的：要腾地方 ---- */
    if (W25QXX_IsBlank(slot_addr(s_head), SLOT_SIZE) == 0U)
    {
        uint16_t first = (uint16_t)(s_head - (s_head % SLOTS_PER_SEC));
        uint16_t live  = log_sector_live(first);

        /* 擦除单位是 4KB = 128 条。这个扇区里还有 live 条没补传，
         *   一擦就全没了。这里选择如实记账而不是静默丢弃：
         *   更好的做法是先把 live 条读出来补传再擦（缓存区越大越走不到这条路）。 */
        if (live > 0U)
        {
            s_lost  = (uint16_t)(s_lost + live);
            s_count = (uint16_t)(s_count - live);
        }
        if (W25QXX_EraseSector(slot_addr(first)) != 0U) { return 4U; }
    }

    /* ---- 第一步：先写 [4..32)。此刻 seq 还是 0xFFFFFFFF，这条「不存在」 ---- */
    if (W25QXX_Write(&rec[4], slot_addr(s_head) + 4U, SLOT_SIZE - 4U) != 0U) { return 4U; }

    /* ---- 第二步：最后单独写 seq。[0..4) 落盘之前掉电 = 少一条，不会半条 ---- */
    rec[0] = (uint8_t)(s_next_seq);        rec[1] = (uint8_t)(s_next_seq >>  8);
    rec[2] = (uint8_t)(s_next_seq >> 16);  rec[3] = (uint8_t)(s_next_seq >> 24);
    if (W25QXX_Write(&rec[0], slot_addr(s_head), 4U) != 0U) { return 4U; }

    s_next_seq++;
    if (s_next_seq == LOG_EMPTY) { s_next_seq = 1UL; }   /* 主动跳过空槽标记 */

    s_head = (uint16_t)((s_head + 1U) % LOG_CAPACITY);
    if (s_count < LOG_CAPACITY) { s_count++; }
    else                        { s_lost++; }            /* 写满要记账 */

    return 0U;
}

/* ---- ④ 读第 index 条（index 0 = 最老） ---- */
uint8_t log_read(uint16_t index, uint32_t *ts, uint8_t *buf, uint16_t *len)
{
    uint8_t  rec[SLOT_SIZE];
    uint8_t  body[6U + PAYLOAD];
    uint32_t sq;
    uint16_t n, crc_saved, crc_calc, i;

    if (index >= s_count) { return 5U; }                 /* 5 = 这条是空的 */
    if (W25QXX_Read(rec, slot_addr(index), SLOT_SIZE) != 0U) { return 4U; }

    sq = (uint32_t)rec[0] | ((uint32_t)rec[1] << 8) |
         ((uint32_t)rec[2] << 16) | ((uint32_t)rec[3] << 24);

    /* 判空只看 seq。旧版靠一个「状态字 == VALID」，而那个状态字从来没被写进去，
     *   于是每条记录都被判成空槽，写入报成功、补传永远 0 条。 */
    if (sq == LOG_EMPTY) { return 5U; }

    n = (uint16_t)rec[8] | ((uint16_t)rec[9] << 8);
    if (n == 0U || n > PAYLOAD) { return 6U; }           /* 6 = 坏了 */

    body[0] = rec[4]; body[1] = rec[5]; body[2] = rec[6]; body[3] = rec[7];
    body[4] = rec[8]; body[5] = rec[9];
    for (i = 0U; i < n; i++) { body[6U + i] = rec[HDR_SIZE + i]; }

    crc_saved = (uint16_t)rec[10] | ((uint16_t)rec[11] << 8);
    crc_calc  = log_crc16(body, (uint16_t)(6U + n));
    if (crc_calc != crc_saved) { return 6U; }

    *ts = (uint32_t)rec[4] | ((uint32_t)rec[5] << 8) |
          ((uint32_t)rec[6] << 16) | ((uint32_t)rec[7] << 24);
    for (i = 0U; i < n; i++) { buf[i] = rec[HDR_SIZE + i]; }
    *len = n;
    return 0U;
}

/* ---- ⑤ 补传端：读到空槽要「跳过继续找」，不能就此收工 ---- */
uint16_t log_drain(void (*send)(uint32_t ts, const uint8_t *d, uint16_t n))
{
    uint8_t  buf[PAYLOAD];
    uint16_t len;
    uint32_t ts;
    uint16_t i, ok = 0U;

    for (i = 0U; i < LOG_CAPACITY; i++)
    {
        if (log_read(i, &ts, buf, &len) == 0U)
        {
            send(ts, buf, len);
            ok++;
        }
        /* 5（空槽）/ 6（损坏）都只是「这条跳过」，继续往后找 */
    }
    return ok;
}

/* ---- ⑥ 初始化：扫一遍恢复写指针，不额外磨损指针页 ---- */
uint8_t log_init(void)
{
    uint8_t  rec[SLOT_SIZE];
    uint32_t sq, max_seq = 0UL;
    uint16_t i;

    s_head = 0U; s_count = 0U; s_lost = 0U; s_next_seq = 1UL;

    for (i = 0U; i < LOG_CAPACITY; i++)
    {
        if (W25QXX_Read(rec, slot_addr(i), SLOT_SIZE) != 0U) { continue; }
        sq = (uint32_t)rec[0] | ((uint32_t)rec[1] << 8) |
             ((uint32_t)rec[2] << 16) | ((uint32_t)rec[3] << 24);
        if (sq == LOG_EMPTY) { s_head = i; break; }
        s_count++;
        if (sq > max_seq) { max_seq = sq; }
    }
    s_next_seq = max_seq + 1UL;
    if (s_next_seq == LOG_EMPTY) { s_next_seq = 1UL; }
    return 0U;
}

/* 常见问题：
 * 1) 判身份写死 JEDEC == 0xEF4018，板子上是 GD25Q128(0xC84018)，初始化永远失败。
 *    正确判据：只看容量字节，`(id & 0xFF) == 0x18`，并排除 0xFFFFFF / 0x000000。
 * 2) 另设一个「状态字」当有效性判据，却忘了在写入时给它赋值，全片缓存读不出来。
 * 3) 为腾一个槽去擦整个 4KB 扇区，连带毁掉同扇区 127 条没补传的记录，条数还在涨。
 * 4) 读取端一读到空槽就 return，环形缓冲里的积压永远补不完。
 * 5) 写完不算 WEL（0x06 写使能），命令被静默忽略，函数返回成功但读回还是 0xFF。
 * 6) 地址越界检查写成 `addr + len > SIZE`，无符号回绕导致检查失效。
 */

/* ============================================================
 *  LoRa E22-400T22S 点对点无线链路，初始化 / 发帧 / 收帧
 *  平台：STM32F407 · E22-400T22S（433MHz，透明传输）
 *  板1：USART3 PB10/PB11 + M0M1AUX = PB0/PB1/PB2
 *  板2：USART6 PC6/PC7   + M0M1AUX = PE5/PE6/PE7
 * ============================================================ */
#include "stm32f4xx.h"
#include "lora_e22.h"        /* 板级配置（串口号 / 三根控制脚 / 超时）都在这个头里 */

#include <string.h>

/* ---------------- ① 20 字节环境帧：字段偏移与长度集中在此 ---------------- */
#define FRAME_TOTAL   20U
#define FRAME_CMD_ENV 0x01U
#define FRAME_LEN_ENV 0x0CU      /* 数据段 12 字节 */
#define FRAME_CRC_OFF 16U

/*   [0][1]   0xAA 0x55   帧头
 *   [2]      命令字 0x01
 *   [3]      长度   0x0C
 *   [4..15]  数据段 12 字节（大端，高字节在前）
 *   [16][17] CRC16-MODBUS，低字节在前，范围 = [2..16) 共 14 字节
 *   [18][19] 0x55 0xAA   帧尾
 *
 *   帧尾 0x55AA 会和下一帧帧头 0xAA55 拼成 ...55 AA AA 55...，
 *     所以解析必须做“帧头 + 长度 + CRC”三重确认，不能见到 0xAA55
 *     就当帧头。这是透传模块上自定义帧最容易踩的问题。 */

static volatile uint32_t s_tx_ok, s_tx_fail;
static volatile uint32_t s_rx_ok, s_rx_bad;

/* ---------------- ② 初始化：先摆模式，再开串口 ---------------- */
uint8_t lora_link_init(void)
{
    uint8_t r;
    char    cfg[128];

    /* LORA_E22_Init() 内部顺序（源码 lora_e22.c 里逐条写的）：
     *   ① 把 M0/M1 推挽输出并置成透传(0,0)，必须在开串口之前，
     *      否则模块可能停在配置模式，把应用数据帧当 AT 指令吃掉；
     *   ② AUX 配成【输入上拉】（不接时读高，正好等价于“空闲”）；
     *   ③ SYS_USART_InitRxIT() 开中断接收 + 清环形缓冲；
     *   ④ 等模块就绪（上电后它自己要初始化射频，典型十几毫秒）。
     * 这里反复交代顺序，是因为“先开串口再摆模式”这个错很隐蔽：
     * 大部分时候也能跑，只在模块恰好停在配置模式时突然收不到数据。 */
    r = LORA_E22_Init();
    if (r != LORA_E22_OK) {
        /* 返回 1 = LORA_E22_ERR_AUX：AUX 一直低。
         * 按驱动头文件的故障表依次查：模块没上电 / M0M1 接错 /
         * AUX 被别的外设拉了 / 没共地。 */
        return r;
    }

    /* 开机把模块配置读出来打印一次，现场排障一眼看出
     *   “地址 / 网络ID / 信道”对不对。ReadConfig 内部依次问
     *   AT+VER / AT+ADDR / AT+NETID / AT+REG0，把多行折成一行。 */
    memset(cfg, 0, sizeof(cfg));
    r = LORA_E22_ReadConfig(cfg, sizeof(cfg));
    if (r == LORA_E22_OK) {
        printf("LoRa 模块配置 = %s\r\n", cfg);
    }

    /* 确认切模式这条通路是活的：能回 OK 就说明
     *   “切配置模式 + 串口收发 + 波特率”全通。
     *    SendAT 执行期间模块不能收发业务数据（它会切走模式），
     *   所以只在开机配置或人为改参数时调，绝不放进数据通路。 */
    r = LORA_E22_SendAT("AT");
    if (r != LORA_E22_OK) {
        return r;   /* 2 = ERR_NO_MODULE（没接 M0M1 / 波特率不符 / TXRX 反） */
    }

    /* 切回透传并确认 AUX 已空闲。
     *   SetMode 内部已经等了一次 AUX，这里再等一次是双保险：
     *   SetMode 的等待上限是 SYS_LORA_AUX_TIMEOUT_MS = 1000U，
     *   而“切回透传要重新初始化射频”，最坏可到 1s，卡在边界上时
     *   再等一轮能把偶发的“第一包丢”挡掉。 */
    r = LORA_E22_SetMode(LORA_E22_MODE_TRANSPARENT);
    if (r != LORA_E22_OK) {
        return r;
    }
    if (LORA_E22_WaitReady(1000U) == 0U) {
        return LORA_E22_ERR_AUX;    /* 等 1s 还是忙，多半 M0/M1/AUX 接错 */
    }
    if (LORA_E22_IsBusy() != 0U) {
        return LORA_E22_ERR_AUX;    /* 1 = 忙，此刻不能灌数据 */
    }

    return LORA_E22_OK;
}

/* ---------------- ③ 把一帧从空中发出去 ---------------- */
uint8_t lora_send_frame(const uint8_t *f, uint16_t n)
{
    uint8_t r;

    if (f == 0 || n != FRAME_TOTAL) {
        return LORA_E22_ERR_PARAM;
    }

    /* 应用层自检：对含 CRC 的整段再算一遍，结果应为 0。
     * 自洽才发，能挡掉“组帧时算错 CRC、对端全判坏帧”这种低级故障。
     * 本项目两板用的 CRC 实现不同名（板1 = SYS_MODBUS_Crc16，
     * 板2 = MODBUS_CRC16），但算法与初值一致 = CRC16-MODBUS。 */
    if (frame_crc16(&f[2], 16U) != 0U) {
        return LORA_E22_ERR_PARAM;
    }

    /* LORA_E22_Send 内部会先等 AUX 空闲（E22 的 UART 接收缓冲有限，
     * 灌太快会丢字节），再阻塞发完，最后等移位寄存器真正空掉才返回。
     * 驱动无锁，固定由 CommTask 一个任务调用，别多任务并发。
     * 它只可能返回 OK 或 ERR_PARAM，不会返回 ERR_NO_DATA。 */
    r = LORA_E22_Send(f, n);
    if (r == LORA_E22_OK) {
        s_tx_ok++;
    } else {
        s_tx_fail++;
    }
    return r;
}

/* ---------------- ④ 接收任务：必须周期性轮询 ---------------- */
/* E22 透传模式不吐“包开始/包结束”标记，驱动只能靠“字节间停顿”切帧：
 *   上一个字节到达后，串口缓冲空了、且间隔超过 SYS_LORA_FRAME_GAP_MS
 *   （10ms）就认为这一帧吐完了。所以 Recv 必须周期性调用，
 *   建议 10~50ms 一次。调用太稀会把两帧粘成一帧，这是透传的固有
 *   代价，不是驱动实现缺陷。
 *
 *   返回码处理是这张卡最容易被写错的地方：
 *     OK              收到完整一帧，out_len 有效
 *     ERR_NO_DATA(6)  暂时没有完整帧，不是错误，直接下轮再来，
 *                     不能打印、不能计数、更不能报警
 *     ERR_OVERFLOW(5) 这一帧比调用方缓冲长，**整帧已丢弃且状态已自动
 *                     复位**，这是真丢帧，该计数
 *     ERR_PARAM(4)    入参非法（空指针 / 零长度）
 */
void lora_rx_task_poll(void)
{
    uint8_t  buf[64];       /* ≥ 32 字节即可：20 字节帧 + 余量 */
    uint16_t n;
    uint8_t  r;

    n = 0U;
    r = LORA_E22_Recv(buf, (uint16_t)sizeof(buf), &n);

    if (r == LORA_E22_OK) {
        if (frame_parse(buf, n) != 0U) {
            s_rx_ok++;
            /* 交给队列：满了就丢，绝不阻塞接收，阻塞一次就会
             * 拉长两次 Recv 的间隔，把后面的帧粘在一起，连锁丢帧。 */
            (void)xQueueSend(s_q_frame, buf, 0);
        } else {
            s_rx_bad++;
        }
    } else if (r == LORA_E22_ERR_OVERFLOW) {
        s_rx_bad++;         /* 真丢帧，记账 */
    } else if (r == LORA_E22_ERR_NO_DATA) {
        /* 什么都不做。这一句注释的作用是防止后人“”在这里
         *   加一句打印或 s_rx_bad++：那会让接收任务每 20ms 刷一条
         *   假故障，真正的坏帧反而被淹没，监控数字也永远不准。 */
    } else {
        /* ERR_PARAM：入参写错了，属于代码 bug，静态就能发现 */
    }

    vTaskDelay(pdMS_TO_TICKS(20));   /* 20ms 远小于 2s 帧间隔，不会粘帧 */
}

/* 常见问题速查：
 * 1) 不接天线就上电发射 → 功率反射回功放，轻则距离骤减、重则烧模块
 * 2) M0/M1 悬空           → 模块随机进/不进配置模式，AT 有时通有时不通
 * 3) 切模式后立刻发指令    → 丢第一条，必须等 AUX（LORA_E22_WaitReady）
 * 4) 把 ERR_NO_DATA 当错误 → 日志刷爆、计数全假
 * 5) 两端 NETID/信道/地址 不一致 → Send 返回 OK 但对端永远收不到
 * 6) 没共地 / 去耦不够      → 发射瞬时 100~120mA 拉垮电压，模块复位
 * 7) 改完 AT 不复位        → 新参数没在透传模式下生效，改了像没改
 */

/* ============================================================
 *  ⑳ ESP8266 AT 联网 + MQTT 上报云端，联网 / 灌数据 / 组包 / 判活
 *  平台：STM32F407 · ESP8266（AT 固件）接 USART3 PB10/PB11 · 115200 8N1
 *  对应 FWLIB：esp8266.c + mqtt.c，底层走 sys_usart.c
 * ============================================================ */
#include "stm32f4xx.h"
#include "esp8266.h"
#include "mqtt.h"
#include "sys_usart.h"

#define WIFI_SSID   "lab-wifi-2.4g"      /* 只能 2.4GHz */
#define WIFI_PASS   "lab-pass"
#define SRV_HOST    "bemfa.com"         /* 巴法云；板2 自检时用 broker.emqx.io */
#define SRV_PORT    9501U               /* 巴法云 MQTT 明文端口（EMQX 用 1883） */

/* ---- ① AT 联网四步：每步都判返回值，超时与模块报错分开看 ----
 * 返回：0 = 通了；1 = 超时（查接线 / 供电 / 波特率）；2 = 模块回 ERROR（查命令拼写） */
static uint8_t net_up(void)
{
    uint8_t r;

    r = ESP8266_SendCmd("AT", "OK", 1000U);          /* 握手：模块在不在 */
    if (r != 0U) { return r; }

    r = ESP8266_SetMode(ESP8266_MODE_STA);            /* AT+CWMODE=1 站点模式 */
    if (r != 0U) { return r; }

    /* AT+CWJAP 是全程最慢的一步：模块要扫信道、做关联与四次握手，
     * 超时按 15s 给（ESP8266_JOIN_TIMEOUT_MS）。给 2s 会在信号弱时假失败 */
    r = ESP8266_JoinAP(WIFI_SSID, WIFI_PASS);
    if (r != 0U) { return r; }

    /* AT+CIPSTART 内部先发 AT+CIPMUX=0：单连接模式下 +IPD 不带连接号，
     * 下行解析简单得多；要同时连两个服务器才改成 1 */
    return ESP8266_ConnectTCP(SRV_HOST, SRV_PORT);
}

/* ---- ② 灌数据：等号后面的长度必须紧跟在等号后面；等不到 '>' 必须重同步 ---- */
static uint8_t at_send_raw(const uint8_t *buf, uint16_t len)
{
    char     cmd[24];
    char     tmp[8];
    uint16_t v = len;
    uint8_t  n = 0U;
    uint8_t  k = 0U;

    if (buf == 0 || len == 0U || len > 2048U) { return 1U; }   /* 单包上限 2048 */

    /* 长度转十进制（不用 sprintf，省 Flash） */
    while (v > 0U && n < 5U) { tmp[n++] = (char)('0' + (v % 10U)); v /= 10U; }

    cmd[0] = 'A'; cmd[1] = 'T'; cmd[2] = '+'; cmd[3] = 'C';
    cmd[4] = 'I'; cmd[5] = 'P'; cmd[6] = 'S'; cmd[7] = 'E';
    cmd[8] = 'N'; cmd[9] = 'D'; cmd[10] = '='; cmd[11] = 0;

    /* 长度必须从 "AT+CIPSEND=" 的末尾（下标 11）开始追加。
     * 原来这里写死 k = 10，正好把那个等号覆盖掉，实际发出去的是
     * "AT+CIPSEND100"（非法 AT 命令）→ 模块立即回 ERROR → 调用方在
     * 等 '>' 上白等 3 秒超时 → 客户端模式下所有 TCP 上行全失败：
     * MQTT 的 CONNECT / PUBLISH / SUBSCRIBE / PINGREQ 一条都发不出去。
     * 现在改用 strlen(cmd) 起算，以后长度位数变了也不会再错位。
     * 怎么发现：把 ESP8266_GetLastReply() 原样打到串口，ERROR 就写在里面。 */
    k = (uint8_t)strlen(cmd);
    while (n > 0U) { cmd[k++] = tmp[--n]; }
    cmd[k] = 0;

    if (ESP8266_SendCmd(cmd, ">", 3000U) != 0U) {
        /* 没等到 '>'：模块可能已经回过 '>' 而等待窗口错过了，此刻它处在
         * 数据接收模式，随后收到的任何字节都被当成载荷，之后每条 AT
         * 命令（连 AT+CIPCLOSE 和 MQTT 的报文）都会被吃掉，现象是
         * 「从某一刻起所有命令集体超时，复位一下又全好了」。
         * 逃逸办法（AT 手册）：先发 +++（不加 CRLF）退出数据模式，
         * 静默 20ms 以上，再发一条 AT 确认回到命令模式。
         * 不管超时原因是哪种这两步都安全：已在命令模式时 +++ 只回 ERROR。 */
        SYS_USART_SendString(ESP8266_USART, "+++");
        delay_ms_dwt(50U);
        (void)ESP8266_SendCmd("AT", "OK", 500U);
        return 1U;
    }

    /* 命中 '>' 才能灌字节；这里必须走原始写，不能再补回车换行 */
    SYS_USART_SendBuf(ESP8266_USART, buf, len);
    return ESP8266_SendCmd("", "SEND OK", 5000U);
}

/* ---- ③ 剩余长度：7 位变长编码，逐字节低位在前，最高位当续位 ---- */
static uint16_t mqtt_finalize(uint8_t *buf, uint16_t total)
{
    uint8_t  rl[4];
    uint8_t  rln = 0U;
    uint32_t body = (uint32_t)(total - 2U);    /* 去掉类型字节 + 1 字节占位 */
    uint32_t v = body;

    do {
        uint8_t b = (uint8_t)(v % 128U);
        v /= 128U;
        if (v > 0U) { b = (uint8_t)(b | 0x80U); }   /* 最高位 1 = 后面还有 */
        rl[rln++] = b;
    } while (v > 0U);

    if (rln > 1U) {
        /* 剩余长度占 2 字节时，正文整体右移 1 字节给多出来的长度字节腾地方 */
        memmove(&buf[1U + rln], &buf[2], (size_t)body);
    }
    memcpy(&buf[1], rl, (size_t)rln);
    return (uint16_t)(total - 1U + rln);       /* 真正的整包长度 */
}

/* ---- ④ 收下行：一个 +IPD 段里可能有多条报文，要循环取干净 ---- */
static void handle_downlink(const char *topic, const char *payload)
{
    (void)topic;
    (void)payload;      /* 本项目里按 # 分列解析后交给 app 层 */
}

static void net_poll_down(void)
{
    MqttMsg_t m;

    /* MQTT_Poll() 内部按剩余长度定报文结尾，游标只推进到本报文之后，
     * 所以这里必须 while 循环，直到它返回超时（没消息了）为止 */
    while (MQTT_Poll(&m) == MQTT_OK) {
        handle_downlink(m.topic, m.payload);
    }
}

/* ---- ⑤ 网络维护：先听、按半周期发心跳、超时判死 ---- */
void net_task_20ms(void)
{
    if (MQTT_IsConnected() == 0U) {
        /* 未连接：数据一律转 ⑱ 本地缓存；重连由外层每几秒试一次 */
        return;
    }

    net_poll_down();

    /* KeepAliveService 内部顺序很重要：
     *   ① mqtt_alive_check_rx()，看 AT 缓冲长度有没有变（PINGRESP /
     *      PUBLISH / SUBACK 都算「听到了」），变了就刷新 s_last_rx；
     *   ② 距上次发送超过半个心跳周期（30s）就发一条 PINGREQ；
     *   ③ 距上次收到任何字节超过 MQTT_ALIVE_TIMEOUT_S（120s）
     *      就清 s_connected 并返回 MQTT_ERR_ALIVE_TIMEOUT。
     * 第 ① 步必须在发心跳之前做，否则刚发完心跳就把「距上次接收」
     * 重置了，永远等不到超时，这正是只发 PINGREQ 不看 PINGRESP
     * 的老实现在 TCP 半开时 s_connected 永远为 1 的原因。 */
    if (MQTT_KeepAliveService() == MQTT_ERR_ALIVE_TIMEOUT) {
        return;     /* s_connected 已被清 0，从下一刻起走缓存补传 */
    }
}

/* ============================================================
 *  ㉑ Modbus RTU 从机 + RS485 半双工，应用层完整范例
 *  平台：STM32F407ZGT6 + SP3485(U7) 收发器
 *  板载默认接线：SYS_RS485_USART = SYS_USART_2(PA2/PA3)、DE = PG8
 *  PG8 同时是 NRF24L01 的 NRF_IRQ，两者不能同时使用；
 *  USART2 还要接 Qt 上位机，正式项目请换 UART4/UART5 并另选 DE 脚。
 *  对应 FWLIB：板2 modbus.c(513 行) / sys_rs485.c(194 行) / sys_usart.c
 * ============================================================ */
#include "stm32f4xx.h"
#include "modbus.h"
#include "sys_rs485.h"
#include "sys_usart.h"
#include "gpio_core.h"      /* DWT_GetUs / DWT_ElapsedUs / GPIO_OutInit */

/* ---- ① 从站参数：换地址/波特率只改这两行 ---- */
#define APP_SLAVE_ADDR   0x01U      /* 1~247；0 是广播地址，不能当从机地址 */
#define APP_BAUD         9600U      /* Modbus RTU 常规 8-N-1 */

/* ---- ② 四个数据区：先把地址表写在纸上，再落成数组 ----
 *   线圈/离散输入：一个元素 1 位，驱动负责打包成 Modbus 位流（低位在先）
 *   保持/输入寄存器：一个元素 1 个 16 位字，线上大端传送
 *   40001~40016 ↔ reg_hold[0..15]；30001~30008 ↔ reg_input[0..7] */
static uint16_t reg_hold[16];    /* 03 读 / 06 单写 / 10 多写 */
static uint16_t reg_input[8];    /* 04 只读，放采集值 */
static uint8_t  coil_bits[16];   /* 01 读 / 05 单写 / 0F 多写 */
static uint8_t  disc_bits[8];    /* 02 只读，放开关量输入 */
static volatile uint32_t tick_ms = 0U;
void SysTick_Handler(void) { tick_ms++; }

/* ---- ③ 上电先开 DWT 微秒计数器：3.5 字符的帧间隔全靠它量 ---- */
static void app_dwt_start(void)
{
    CoreDebug->DEMCR |= CoreDebug_DEMCR_TRCENA;
    DWT->CYCCNT = 0U;
    DWT->CTRL  |= DWT_CTRL_CYCCNTENA_Msk;
}

/* ---- ④ 自己算一遍帧间隔，跟上位机核对用 ----
 *   11 位/字符 × 3.5 = 38.5 位；9600 → 4010µs、115200 → 334µs
 *   库内 MODBUS_Init 会算同样的值并做 1000µs 下限兜底 */
static uint32_t app_gap_us(uint32_t baud)
{
    uint32_t gap = MODBUS_GAP_US(baud);   /* = 38500000UL / ((baud)) */
    if (gap < 1000U) { gap = 1000U; }     /* 高波特率防抖下限 */
    return gap;
}

/* ---- ⑤ 主站写入回调：在 MODBUS_Poll 上下文里执行，别长阻塞 ---- */
static void app_on_write(uint8_t func, uint16_t addr, uint16_t value)
{
    if (func == 0x06U || func == 0x10U)
    {
        if (addr < 16U) { reg_hold[addr] = value; }   /* 参数立刻生效 */
    }
    else if (func == 0x05U || func == 0x0FU)
    {
        if (addr < 16U) { coil_bits[addr] = (uint8_t)(value & 1U); }
    }
    else
    {
        /* 其它功能码不会走到这里；真实项目在这里存 Flash 要快进快出 */
    }
}

/* ---- ⑥ 把 32 位运行时间拆成两个输入寄存器（高字在前）---- */
static void app_set_u32(uint16_t *dst, uint32_t v)
{
    dst[0] = (uint16_t)(v >> 16);
    dst[1] = (uint16_t)(v & 0xFFFFU);
}

int main(void)
{
    uint32_t i;
    uint32_t t_log = 0U;

    app_dwt_start();                                   /* ③ 帧间隔计时 */
    SysTick_Config(SystemCoreClock / 1000U);
    SYS_USART_Init(SYS_USART_1, 115200U);              /* 调试口，USART1 要插跳线帽 */

    /* ---- ⑦ 协议层初始化：内部自动开好 RS485 物理层并算好帧间隔 ---- */
    MODBUS_Init(APP_SLAVE_ADDR, APP_BAUD);             /* 从站地址 + 波特率 */

    /* ---- ⑧ 绑定四个区：驱动直接读写这些数组，不做任何拷贝 ---- */
    for (i = 0U; i < 16U; i++) { reg_hold[i] = 0U; coil_bits[i] = 0U; }
    for (i = 0U; i < 8U; i++)  { reg_input[i] = 0U; disc_bits[i] = 0U; }
    MODBUS_BindHolding(reg_hold, 16U);   /* 0x03 / 0x06 / 0x10 */
    MODBUS_BindInput(reg_input, 8U);     /* 0x04 只读 */
    MODBUS_BindCoils(coil_bits, 16U);    /* 0x01 / 0x05 / 0x0F */
    MODBUS_BindDiscrete(disc_bits, 8U);  /* 0x02 只读 */
    MODBUS_SetWriteCallback(app_on_write);

    for (;;)
    {
        /* ---- ⑨ 刷新采集值：真实项目在这里读 ADC / 传感器 ---- */
        app_set_u32(reg_input, tick_ms);                  /* 运行时间 */
        disc_bits[0] = (uint8_t)(tick_ms & 1U);           /* 演示：跟着翻转 */

        /* ---- ⑩ 轮询：收字节 → 判 3.5 字符静默 → 校 CRC → 判地址
         *        → 执行 → 回帧。非阻塞，单次开销极小；
         *        中间不要塞长延时，否则一帧会被切成两帧 ---- */
        MODBUS_Poll();

        /* ---- ⑪ 每秒打印四个计数器：现场排错全靠它 ---- */
        if ((tick_ms - t_log) >= 1000U)
        {
            t_log = tick_ms;
            SYS_USART_Printf(SYS_USART_1,
                "[MB] gap=%luus Rx=%lu Tx=%lu Err=%lu Other=%lu\r\n",
                (unsigned long)app_gap_us(APP_BAUD),
                (unsigned long)MODBUS_GetRxFrames(),
                (unsigned long)MODBUS_GetTxFrames(),
                (unsigned long)MODBUS_GetErrFrames(),
                (unsigned long)MODBUS_GetOtherFrames());
        }
    }
}

/* ---- 判读四个计数器（反着查故障）----
 *   1) Rx 不涨             → 没收到完整帧：方向脚 / 接线 / 波特率 / 没共地
 *   2) Other 在涨 Err 不涨 → 地址过滤正确，总线上有别人的对话（正常现象）
 *   3) Err 在涨            → 收到了但过不了 CRC：干扰 / 不共地 / 缺终端电阻
 *   4) Tx 在涨但上位机超时 → 答了对方没认：A/B 接反、CRC 字节序搞反
 *   5) 串口助手发 01 03 00 00 00 02 C4 0B，应回 01 03 04 xx xx xx xx + CRC
 *
 *   如实说明：本套代码只在 Keil 下编译通过，没有在真实 RS485 总线上跑过一次。
 */

/* ============================================================
 *  sys_frame 自定义帧协议，组帧内置自检 + 逐字节解析
 *  线上格式：AA 55 | CMD | LEN | DATA(LEN) | CRC低 CRC高 | 55 AA
 *  整帧长度 = 8 + LEN，CRC 范围 = [2 .. 4+LEN) 共 LEN+2 字节
 *  平台：STM32F407 · 对应 FWLIB 的 sys_frame.c / sys_frame.h（两板同源）
 *  说明：本文件刻意不 include sys_frame.h，把关键逻辑摊开给看
 *        （工程里请直接用 SYS_FRAME_Build / SYS_FRAME_Verify / SYS_FRAME_Poll）
 * ============================================================ */
#include "stm32f4xx.h"

/* ---- ① 区块 1：协议常量（换协议只改这一段） ---- */
#define SYS_FRAME_HEAD_HI       0xAAU   /* 帧头第 1 字节（线上先发） */
#define SYS_FRAME_HEAD_LO       0x55U   /* 帧头第 2 字节             */
#define SYS_FRAME_TAIL_HI       0x55U   /* 帧尾第 1 字节             */
#define SYS_FRAME_TAIL_LO       0xAAU   /* 帧尾第 2 字节（与帧头反序）*/
#define SYS_FRAME_OVERHEAD      8U      /* 2 帧头 + CMD + LEN + 2 CRC + 2 帧尾 */
#define SYS_FRAME_MAX_PAYLOAD   64U     /* 数据段上限，同时是收帧缓冲大小 */

/* 环境数据帧：CMD 0x01，数据段 12 字节 = 6 个 uint16（大端） */
#define SYS_FRAME_CMD_ENV       0x01U
#define SYS_FRAME_ENV_LEN       0x0CU
#define SYS_FRAME_ENV_TEMP_OFF   0U     /* 温度 ℃ ×100（int16 补码） */
#define SYS_FRAME_ENV_HUMI_OFF   2U     /* 湿度 %RH ×100             */
#define SYS_FRAME_ENV_PRESS_OFF  4U     /* 气压 hPa ×10  不能 ×100 */
#define SYS_FRAME_ENV_LIGHT_OFF  6U     /* 光照 lx                   */
#define SYS_FRAME_ENV_TVOC_OFF   8U     /* TVOC ppb                  */
#define SYS_FRAME_ENV_MQ135_OFF 10U     /* MQ135 原始 ADC            */

/* ---- ② CRC16-MODBUS：初值 0xFFFF，反射多项式 0xA001，末尾不异或 ---- */
static uint16_t frame_crc16_update(uint16_t crc, uint8_t byte)
{
    uint8_t i;

    crc ^= (uint16_t)byte;
    for (i = 0U; i < 8U; i++)
    {
        if ((crc & 0x0001U) != 0U) { crc = (uint16_t)((crc >> 1) ^ 0xA001U); }
        else                       { crc = (uint16_t)(crc >> 1); }
    }
    return crc;
}

static uint16_t frame_crc16(const uint8_t *buf, uint16_t len)
{
    uint16_t crc = 0xFFFFU;
    uint16_t i;

    if (buf == 0) { return crc; }               /* 防野指针 */
    for (i = 0U; i < len; i++) { crc = frame_crc16_update(crc, buf[i]); }
    return crc;
}

/* 大端存取：环境帧所有多字节字段高字节在前 */
static void frame_put_u16_be(uint8_t *p, uint16_t v)
{
    p[0] = (uint8_t)(v >> 8);
    p[1] = (uint8_t)(v & 0xFFU);
}

static uint16_t frame_get_u16_be(const uint8_t *p)
{
    return (uint16_t)(((uint16_t)p[0] << 8) | (uint16_t)p[1]);
}

/* ---- ③ 组帧到缓冲区：返回整帧字节数，0 = 参数非法 ---- */
static uint16_t frame_build(uint8_t cmd, const uint8_t *payload, uint16_t len,
                            uint8_t *out, uint16_t cap)
{
    uint16_t crc;
    uint16_t i;

    if (out == 0)                                        { return 0U; }
    if (len > SYS_FRAME_MAX_PAYLOAD)                     { return 0U; }
    if ((payload == 0) && (len != 0U))                   { return 0U; }
    if (cap < (uint16_t)(len + SYS_FRAME_OVERHEAD))      { return 0U; }

    out[0] = SYS_FRAME_HEAD_HI;                  /* AA */
    out[1] = SYS_FRAME_HEAD_LO;                  /* 55 */
    out[2] = cmd;
    out[3] = (uint8_t)len;
    for (i = 0U; i < len; i++) { out[4U + i] = payload[i]; }

    /* CRC 覆盖 CMD + LEN + DATA：从 out[2] 起共 len + 2 字节
     *   不含帧头、不含 CRC 自身、不含帧尾，写错这里校验永远对不上 */
    crc = frame_crc16(&out[2], (uint16_t)(len + 2U));
    out[4U + len] = (uint8_t)(crc & 0xFFU);      /* 低字节在前 */
    out[5U + len] = (uint8_t)(crc >> 8);

    out[6U + len] = SYS_FRAME_TAIL_HI;           /* 55 */
    out[7U + len] = SYS_FRAME_TAIL_LO;           /* AA */
    return (uint16_t)(len + SYS_FRAME_OVERHEAD);
}

/* ---- ④ 环境帧：先拼 12 字节大端数据段，再套通用信封 ---- */
static uint16_t frame_build_env(uint8_t *out, uint16_t cap,
                                int16_t temp_x100, int16_t humi_x100,
                                int16_t press_x10, uint16_t light,
                                uint16_t tvoc, uint16_t mq135)
{
    uint8_t env[SYS_FRAME_ENV_LEN];

    if (out == 0) { return 0U; }

    frame_put_u16_be(&env[SYS_FRAME_ENV_TEMP_OFF],  (uint16_t)temp_x100);
    frame_put_u16_be(&env[SYS_FRAME_ENV_HUMI_OFF],  (uint16_t)humi_x100);
    frame_put_u16_be(&env[SYS_FRAME_ENV_PRESS_OFF], (uint16_t)press_x10);
    frame_put_u16_be(&env[SYS_FRAME_ENV_LIGHT_OFF], light);
    frame_put_u16_be(&env[SYS_FRAME_ENV_TVOC_OFF],  tvoc);
    frame_put_u16_be(&env[SYS_FRAME_ENV_MQ135_OFF], mq135);

    return frame_build(SYS_FRAME_CMD_ENV, env, SYS_FRAME_ENV_LEN, out, cap);
}

/* ---- ⑤ 校验一整帧：三重确认，返回 0 = OK ---- */
#define FRAME_OK        0U
#define FRAME_ERR_HEAD  1U
#define FRAME_ERR_TAIL  2U
#define FRAME_ERR_LEN   3U
#define FRAME_ERR_CRC   4U
#define FRAME_ERR_PARAM 5U

static uint8_t frame_verify(const uint8_t *buf, uint16_t len)
{
    uint16_t crc;
    uint16_t dlen;

    if (buf == 0)                 { return FRAME_ERR_PARAM; }
    if (len < SYS_FRAME_OVERHEAD) { return FRAME_ERR_PARAM; }

    /* 第一道：帧头必须连续两字节 AA 55（接缝处会凭空出现 AA 55，光看它不够） */
    if ((buf[0] != SYS_FRAME_HEAD_HI) || (buf[1] != SYS_FRAME_HEAD_LO))
    { return FRAME_ERR_HEAD; }

    /* 帧尾 55 AA */
    if ((buf[len - 2U] != SYS_FRAME_TAIL_HI) || (buf[len - 1U] != SYS_FRAME_TAIL_LO))
    { return FRAME_ERR_TAIL; }

    /* 第二道：长度字段与本次给的长度自洽（两帧粘接在这里被抓住） */
    dlen = (uint16_t)buf[3];
    if ((dlen + SYS_FRAME_OVERHEAD) != len) { return FRAME_ERR_LEN; }

    /* 第三道：重算 CRC16，与帧内两字节逐位比较 */
    crc = frame_crc16(&buf[2], (uint16_t)(dlen + 2U));
    if ((buf[4U + dlen] != (uint8_t)(crc & 0xFFU)) ||
        (buf[5U + dlen] != (uint8_t)(crc >> 8)))       { return FRAME_ERR_CRC; }

    return FRAME_OK;
}

/* ---- ⑥ 收帧状态机：九级，任一步失败就回找帧头 ---- */
enum {
    FX_ST_HEAD_HI = 0U, FX_ST_HEAD_LO, FX_ST_CMD, FX_ST_LEN, FX_ST_DATA,
    FX_ST_CRC_LO, FX_ST_CRC_HI, FX_ST_TAIL_HI, FX_ST_TAIL_LO
};

static struct {
    uint8_t  state;
    uint8_t  cmd;
    uint8_t  idx;
    uint8_t  dlen;
    uint8_t  data[SYS_FRAME_MAX_PAYLOAD];
    uint16_t crc;                       /* 边收边算 */
    uint8_t  rcrc_lo;                   /* 帧内带来的 CRC 低字节 */
    volatile uint8_t  ready;
    volatile uint8_t  rcmd;
    volatile uint16_t rlen;
    uint8_t  rbuf[SYS_FRAME_MAX_PAYLOAD];
    volatile uint16_t err;
} fx;

/* 失败后重启：若失败字节恰是 0xAA，直接当新帧头高字节（这就是帧同步） */
static void fx_restart(uint8_t byte)
{
    fx.crc = 0xFFFFU;
    fx.state = (byte == SYS_FRAME_HEAD_HI) ? FX_ST_HEAD_LO : FX_ST_HEAD_HI;
}

/* 喂一个字节；返回 1 = 刚好凑成一帧 */
static uint8_t frame_feed(uint8_t byte)
{
    uint8_t k;

    switch (fx.state)
    {
    case FX_ST_HEAD_HI:
        if (byte == SYS_FRAME_HEAD_HI) { fx.state = FX_ST_HEAD_LO; }
        return 0U;

    case FX_ST_HEAD_LO:
        if (byte == SYS_FRAME_HEAD_LO)      { fx.crc = 0xFFFFU; fx.state = FX_ST_CMD; }
        else if (byte != SYS_FRAME_HEAD_HI) { fx.state = FX_ST_HEAD_HI; }
        return 0U;                       /* byte == 0xAA：连着两个 AA，状态不动 */

    case FX_ST_CMD:
        fx.cmd = byte;  fx.crc = frame_crc16_update(fx.crc, byte);
        fx.state = FX_ST_LEN;  return 0U;

    case FX_ST_LEN:
        if (byte > SYS_FRAME_MAX_PAYLOAD) { fx.err++; fx_restart(byte); return 0U; }
        fx.dlen = byte; fx.crc = frame_crc16_update(fx.crc, byte); fx.idx = 0U;
        fx.state = (byte == 0U) ? FX_ST_CRC_LO : FX_ST_DATA;
        return 0U;                       /* LEN = 0 的 8 字节短帧直接进 CRC 态 */

    case FX_ST_DATA:
        fx.data[fx.idx] = byte; fx.idx++;
        fx.crc = frame_crc16_update(fx.crc, byte);
        if (fx.idx >= fx.dlen) { fx.state = FX_ST_CRC_LO; }
        return 0U;

    case FX_ST_CRC_LO:
        fx.rcrc_lo = byte; fx.state = FX_ST_CRC_HI; return 0U;

    case FX_ST_CRC_HI:
        if ((uint16_t)(((uint16_t)byte << 8) | fx.rcrc_lo) != fx.crc)
        { fx.err++; fx_restart(byte); return 0U; }
        fx.state = FX_ST_TAIL_HI; return 0U;

    case FX_ST_TAIL_HI:
        if (byte != SYS_FRAME_TAIL_HI) { fx.err++; fx_restart(byte); return 0U; }
        fx.state = FX_ST_TAIL_LO; return 0U;

    case FX_ST_TAIL_LO:
        if (byte != SYS_FRAME_TAIL_LO) { fx.err++; fx_restart(byte); return 0U; }
        fx.rcmd = fx.cmd; fx.rlen = fx.dlen;
        for (k = 0U; k < fx.dlen; k++) { fx.rbuf[k] = fx.data[k]; }
        fx.ready = 1U; fx.state = FX_ST_HEAD_HI;
        return 1U;                       /* 完整一帧，已存入就绪槽 */

    default:
        fx.state = FX_ST_HEAD_HI; return 0U;
    }
}

/* ---- ⑦ 自测：组一帧 → 整段重算应为 0 → 逐字节喂回去应解出原值 ---- */
uint8_t frame_selftest(void)
{
    uint8_t  f[20];
    uint16_t n;
    uint16_t i;
    int16_t  t, h, p;

    n = frame_build_env(f, sizeof(f), 2560, 6030, 10132, 320U, 15U, 812U);
    if (n != 20U)                       { return 1U; }
    if (frame_verify(f, n) != FRAME_OK) { return 2U; }

    /* 整帧重算 = 0 是 CRC16-MODBUS 的附带性质，联调时直接用 */
    if (frame_crc16(&f[2], 16U) != 0U)  { return 3U; }

    /* 逐字节喂状态机：应当恰好凑成 1 帧，且数据段能解回原值 */
    fx.state = FX_ST_HEAD_HI; fx.ready = 0U; fx.err = 0U;
    for (i = 0U; i < n; i++) { (void)frame_feed(f[i]); }
    if (fx.ready == 0U)                 { return 4U; }
    if (fx.rlen != SYS_FRAME_ENV_LEN)   { return 5U; }

    t = (int16_t)frame_get_u16_be(&fx.rbuf[SYS_FRAME_ENV_TEMP_OFF]);
    h = (int16_t)frame_get_u16_be(&fx.rbuf[SYS_FRAME_ENV_HUMI_OFF]);
    p = (int16_t)frame_get_u16_be(&fx.rbuf[SYS_FRAME_ENV_PRESS_OFF]);
    if (t != 2560) { return 6U; }
    if (h != 6030) { return 7U; }
    if (p != 10132) { return 8U; }      /* 1013.2 hPa，×10 后是 10132 */

    return 0U;                          /* 0 = 这份协议自洽 */
}

/* ============================================================
 *  SSD1306 OLED 显示（I2C），从开总线到整帧刷新的完整可用代码
 *  平台：STM32F407 · FreeRTOS · SSD1306 128x64 单色 OLED
 *  总线：SYS_I2C_1（SCL=PB8 / SDA=PB9），与 24C02、MPU6050 共用
 *  板级 API 两套（同一块屏）：
 *    板2  oled.c/.h（UTF-8）: OLED_*      , 像素坐标 + 反显标志 inv
 *    板1  sys_oled.c/.h（GBK）: SYS_OLED_*, 页号 page(0~7) + 列 x
 *  本例以板2 的 OLED_* 为准（板1 对照见下方注释）
 * ============================================================ */
#include "stm32f4xx.h"
#include "oled.h"           /* 板级配置：总线号 / 地址 / 分辨率都在这个头里 */
#include "sys_i2c.h"        /* I2C1 初始化、总线锁、器件探测 */
#include "FreeRTOS.h"
#include "task.h"

/* ---------------- ① 地址自检：先确认“总线上有人” ---------------- */
static uint8_t oled_selfcheck(void)
{
    uint8_t list[8];
    uint8_t n;

    /* SYS_I2C_Scan 逐个地址探测，返回扫到的器件个数并把地址填进 list。
     * 它比盲试地址快得多：扫一遍就知道屏在不在、是不是意外的 0x3D。 */
    n = SYS_I2C_Scan(OLED_I2C_ID, list, 8U);
    if (n == 0U) {
        return 0U;              /* 一个器件都没有：查供电、查 PB8/PB9 接线 */
    }

    /* IsDeviceReady 只回答“这个地址有没有人应答”。
     * 能寻址不等于写得进去，上拉不足 / 走线过长时，
     *   它能返回在线，但 OLED_Refresh 会一路失败。所以下面还要看错误计数。 */
    if (SYS_I2C_IsDeviceReady(OLED_I2C_ID, OLED_ADDR) != SYS_I2C_OK) {
        /* 默认 0x3C 没应答：模块背面 SA0 被上拉时地址是 0x3D，试一下 */
        if (SYS_I2C_IsDeviceReady(OLED_I2C_ID, 0x3DU) != SYS_I2C_OK) {
            return 0U;          /* 两个地址都没人：屏没插好 / 没供电 */
        }
        /* 走到这里说明屏在 0x3D：把 oled.h 里的 OLED_ADDR 改成 0x3D 再编 */
    }
    return 1U;
}

/* ---------------- ② 初始化：先开总线，再初始化屏 ---------------- */
static uint8_t oled_boot(void)
{
    /* 顺序不能反：驱动建在 sys_i2c 之上，总线没起来时所有事务都超时。
     * 400kHz 是 SSD1306 支持的速率，整屏 1024 字节约 23~25ms；
     * 留在 100kHz 就要 90ms 量级，刷屏发顿十有八九是这里没提速。 */
    SYS_I2C_Init(OLED_I2C_ID, 400000);

    /* OLED_Init() 内部按手册发完整上电序列，其中最关键的是
     * 0x8D,0x14 电荷泵开，漏了或参数写成 0x10，屏全黑，
     * 但地址照样扫得到、错误计数还是 0，最容易被误判成坏屏。
     * 它也把 0x20,0x00（页寻址模式）定下来，配合下面的逐页写。 */
    OLED_Init();

    if (oled_selfcheck() == 0U) {
        return 0U;
    }
    /* 初始化阶段（调度器未启动）加锁是空操作，本来就没有并发 */
    return 1U;
}

/* ---------------- ③ 拼一帧：所有绘制只改显存 ---------------- */
static void oled_draw_page(float temp_c, float humi_rh, uint32_t cnt)
{
    int32_t t100 = (int32_t)(temp_c * 10.0f);   /* 25.43 -> 254，定点交给 ShowFixed */
    int32_t h10  = (int32_t)(humi_rh * 10.0f);  /* 61.0  -> 610 */

    /* ClearBuffer 只清 RAM，屏上此刻没有任何变化；
     * 要清屏并立刻推上去就用 OLED_Clear()（它内部会再刷一次）。 */
    OLED_ClearBuffer();

    /* 8x16 点阵：一行 16 个字符、共 4 行。inv=0 黑底白字，inv=1 白底黑字 */
    OLED_ShowStringCenter(0, "NODE-2 COMM", 0);

    /* 定宽显示：位数变化时后面的内容不会被挤走，读数原地刷新不跳动。
     *   ShowFixed(x, y, val, frac, int_len, inv)：val 是放大后的整数。
     *   例：val=254, frac=1 -> 显示 25.4；int_len 是整数部分宽度。 */
    OLED_ShowString(0, 16, "T=", 0);
    OLED_ShowFixed(16, 16, t100, 1U, 3U, 0);
    OLED_ShowString(64, 16, "C", 0);

    OLED_ShowString(0, 32, "H=", 0);
    OLED_ShowFixed(16, 32, h10, 1U, 3U, 0);
    OLED_ShowString(64, 32, "%", 0);

    OLED_ShowNum(0, 48, cnt, 6U, 0);            /* 定宽 6 位无符号整数 */

    /* 图形接口同样只改 RAM：画框 + 进度条（permille 0~1000） */
    OLED_DrawRect(0, 0, 127, 63, 1);
    OLED_ShowProgress(8, 56, 112, 6, 700U);     /* 70% 进度条 */
}

/* ---------------- ④ 上屏：整帧一次性持锁 ---------------- */
static uint8_t oled_push(void)
{
    uint8_t fail;

    /* OLED_Refresh 内部就是：OLED_FRAME_LOCK() -> 8 页逐页写
     *   （每页 1 条定位命令 + 4 块 32 字节）-> OLED_FRAME_UNLOCK()。
     *   一帧共 40 次独立 I2C 事务，整段在同一个临界区里。
     *   为什么必须这样：I2C1 上还有 MPU6050(0x68) 和 24C02(0x50)，
     *   刷到一半被插进来就是“半屏新、半屏旧”的撕裂。
     *   代价：这 20ms 量级里别的器件要等，这是整帧不可插入的必然代价。
     *   返回：0 = 8 页全成功；>0 = 写失败的页数（1~8），据此降级。 */
    fail = OLED_Refresh();
    return fail;
}

/* ---------------- ⑤ 显示任务：接进 FreeRTOS 的最小示例 ---------------- */
/* 事实：两板 OLED 驱动都写好了，但全工程没有调用者，
 *   板2 OLED_Init 只在 oled.c:101 定义，板1 SYS_OLED_Init 只在
 *   sys_oled.c:259 定义，main.c 里没有接。屏不亮不是模块坏了，
 *   是没人叫它干活（可用 grep 搜 OLED_Init / SYS_OLED_Init 自己确认）。建任务：
 *     xTaskCreate(vOledTask, "oled", 256, 0, 3, 0);
 *   优先级放在采样任务之后（掉一帧没人受伤，丢一拍采样才要紧），
 *   栈 256 字足够：这里只有定点转换和 I2C 调用，没有深递归。 */
void vOledTask(void *pv)
{
    uint8_t  oled_ok;
    uint32_t cnt = 0U;
    float    temp = 25.4f;      /* 换成自己的传感器读数 */
    float    humi = 61.0f;

    (void)pv;

    oled_ok = oled_boot();

    for (;;) {
        if (oled_ok != 0U) {
            oled_draw_page(temp, humi, cnt);

            /* 上屏失败就降级：错误计数在涨说明“写不进去”
             *（接线 / 上拉 / 地址 / 总线被占），计数为 0 却仍不亮
             * 就是屏本身、供电或对比度的问题，一刀把故障切两半。 */
            if (oled_push() != 0U) {
                if (OLED_ErrCount() >= 10U) {
                    oled_ok = 0U;   /* 反复写不进去就别再刷，免得拖慢总线 */
                }
            }
            cnt++;
        }

        /* 100ms 一帧：人眼够顺，总线占用也低。
         *   绝不能塞进 1ms 定时器中断，一帧 20ms 以上会吃掉二十几个 tick，
         *   而且 sys_i2c 在中断上下文里会跳过加锁，等于没有互斥。 */
        vTaskDelay(pdMS_TO_TICKS(100));
    }
}

/* ---------------- ⑥ 主程序上电顺序（调度器启动之前） ---------------- */
void oled_app_start(void)
{
    /* 调度器还没跑，此时加锁是空操作；但先把总线拉起来，
     * 任务里第一帧就不用再等总线初始化。 */
    SYS_I2C_Init(OLED_I2C_ID, 400000);

    if (oled_boot() != 0U) {
        /* 上电先来一屏自检画面：四角点像素 + 一个方框 + 一行固定字符串。
         * 以后任何显示异常，只要自检画面对，就说明驱动没问题、错在内容。 */
        OLED_ClearBuffer();
        OLED_DrawPoint(0, 0, 1);
        OLED_DrawPoint(127, 0, 1);
        OLED_DrawPoint(0, 63, 1);
        OLED_DrawPoint(127, 63, 1);
        OLED_DrawRect(0, 0, 127, 63, 1);
        OLED_ShowStringCenter(28, "OLED READY", 0);
        (void)OLED_Refresh();
    }

    /* 建显示任务。屏只该有一个“主人”，两个任务同时刷会互相踩显存。
     * xTaskCreate(vOledTask, "oled", 256, 0, 3, 0); */
}

/* ---------------- ⑦ 板1（检测端）对照 ----------------
 *  同一块屏的另一套板级封装，函数名与形参不同，不可混用：
 *    SYS_I2C_Init(SYS_I2C_1, 400000);
 *    if (SYS_OLED_Init(SYS_I2C_1, SYS_OLED_I2C_ADDR) == 0U) { ... }
 *    SYS_OLED_Clear();                          // 清显存 + 立刻刷一次
 *    SYS_OLED_ShowString(0, 0, "DETECT NODE-1");   // 第一个参数是页号 0~7
 *    SYS_OLED_ShowFloat (2, 16, temp, 1);       // 保留 1 位小数
 *    SYS_OLED_ShowNum   (3, 32, (int32_t)cnt);  // 从 x 起按需占位
 *    SYS_OLED_SetPixel  (64, 32, 1);            // 像素坐标仍是 (x, y)
 *    if (SYS_OLED_Refresh() != 0U) { (void)SYS_OLED_ErrCount(); }
 *  两处最容易错的差异：
 *    ① 板1 的 ShowChar/ShowString/ShowNum/ShowFloat 第一个参数是页号 0~7，
 *       写成像素 y（比如 16）会被当成非法页，整行不显示；
 *    ② 板2 的同名函数多了 inv 参数（1 = 白底黑字反显），板1 没有反显入口；
 *       板1 的数字接口是从当前 x 按需占位，板2 的 ShowNum 带 len 定宽。
 *  两板驱动 .c 都整段持帧锁，缓冲与刷新语义一致，换板只改调用名。 */

/* ============================================================
 *  ㉔ DHT11 单总线温湿度，完整参考实现
 *  平台：STM32F407 · 168MHz · 数据脚 PG9（GPIOG / GPIO_Pin_9）
 *  依赖：delay.c 的 DWT 微秒延时、gpio_core.h 的引脚切换封装
 *  说明：按板1 的 sys_dht11.c 写；板2 是同算法、另一套 API 名
 * ============================================================ */
#include "stm32f4xx.h"
#include "delay.h"
#include "gpio_core.h"

#define DHT11_PORT            GPIOG
#define DHT11_PIN             GPIO_Pin_9
#define DHT11_START_LOW_MS    20U      /* 手册 ≥18ms，给 2ms 余量        */
#define DHT11_TIMEOUT_US      100U     /* 单段等待上限；手册最长 80us    */
#define DHT11_BIT_HIGH_US     45U      /* 位1≈70us / 位0≈26us，取中间    */
#define DHT11_RETRY           3U
#define DHT11_TIMEOUT_CYC     0xFFFFFFFFUL

static GPIO_TypeDef *s_port = 0;       /* 0 = 还没初始化                 */
static uint16_t      s_pin  = 0U;
static uint8_t       s_raw[5];         /* 最近一帧裸字节，排障用         */

/* 等某个电平，带超时。绝不能写成 while(引脚 != 电平) 的死等：
 * 器件没插时那根线永远是高，死等会把整个任务焊死在这里。 */
static uint32_t dht11_wait(uint8_t level, uint32_t timeout_us)
{
    uint32_t start = DWT->CYCCNT;
    uint32_t limit = timeout_us * (SystemCoreClock / 1000000U);

    while (GPIO_InRead(s_port, s_pin) != level)
    {
        if ((DWT->CYCCNT - start) > limit) { return DHT11_TIMEOUT_CYC; }
    }
    return (DWT->CYCCNT - start);      /* 返回这段电平占了多少个周期      */
}

/* 读一整帧：0 成功 / 1 无应答 / 2 校验和不对 */
static uint8_t dht11_read_frame(void)
{
    uint8_t  i, data[5] = {0, 0, 0, 0, 0};
    uint32_t irq, high, thresh;

    delay_us(1);                       /* 顺带确保 DWT 计时已使能         */

    /* ① 起始信号：拉低 ≥18ms 再松手（开漏写 1 = 释放总线），这段不关中断 */
    GPIO_OutInitOD(s_port, s_pin);
    GPIO_OutWrite(s_port, s_pin, 0U);
    delay_ms(DHT11_START_LOW_MS);
    GPIO_OutWrite(s_port, s_pin, 1U);

    /* ② 关中断窗口从这一刻开始：40 位约 4ms，被打断就整体错位 */
    irq = __get_PRIMASK();
    __disable_irq();

    GPIO_InInit(s_port, s_pin, GPIO_PuPd_UP);
    thresh = (SystemCoreClock / 1000000U) * DHT11_BIT_HIGH_US;

    /* ③ 三次等待：应答低起点 → 应答高起点 → 应答高结束（进入 bit0） */
    if (dht11_wait(0U, DHT11_TIMEOUT_US) == DHT11_TIMEOUT_CYC ||
        dht11_wait(1U, DHT11_TIMEOUT_US) == DHT11_TIMEOUT_CYC ||
        dht11_wait(0U, DHT11_TIMEOUT_US) == DHT11_TIMEOUT_CYC)
    {
        __set_PRIMASK(irq);
        GPIO_InInit(s_port, s_pin, GPIO_PuPd_UP);
        return 1U;                     /* 没插 / 没上拉 / 上电不足 1s     */
    }

    /* ④ 40 位：每位的 50us 低电平已被「等高」消费掉，只量高电平宽度 */
    for (i = 0U; i < 40U; i++)
    {
        if (dht11_wait(1U, DHT11_TIMEOUT_US) == DHT11_TIMEOUT_CYC) { break; }
        high = dht11_wait(0U, DHT11_TIMEOUT_US);

        data[i >> 3] = (uint8_t)(data[i >> 3] << 1);   /* 高位在前        */
        if (high > thresh) { data[i >> 3] |= 0x01U; }
    }

    __set_PRIMASK(irq);                /* ⑤ 先恢复中断，再做别的         */
    GPIO_InInit(s_port, s_pin, GPIO_PuPd_UP);          /* 空闲：输入+上拉 */

    for (i = 0U; i < 5U; i++) { s_raw[i] = data[i]; }

    /* ⑥ 校验和 = 前 4 字节之和的低 8 位；不对就整帧丢弃 */
    if ((uint8_t)(data[0] + data[1] + data[2] + data[3]) != data[4]) { return 2U; }
    return 0U;
}

void SYS_DHT11_Init(GPIO_TypeDef *port, uint16_t pin)
{
    s_port = port;
    s_pin  = pin;
    GPIO_InInit(port, pin, GPIO_PuPd_UP);  /* 空闲态就放开总线，别一直拉 */
}

/* 返回 0 成功 / -1 无响应 / -2 校验失败 */
int SYS_DHT11_Read(float *temp_c, float *humi_rh)
{
    uint8_t r;

    if (s_port == 0) { return -1; }

    r = dht11_read_frame();
    if (r == 1U) { return -1; }
    if (r == 2U) { return -2; }        /* 不用可疑值，直接报错给上层   */

    /* DHT11 小数位恒为 0，仍按 0.1 组合，将来换 DHT22 不用改调用方 */
    if (humi_rh != 0) { *humi_rh = (float)s_raw[0] + (float)s_raw[1] * 0.1f; }
    if (temp_c  != 0) { *temp_c  = (float)s_raw[2] + (float)s_raw[3] * 0.1f; }
    return 0;
}

/* 带重试：无应答重试没用（接线 / 上拉问题），只有校验失败才退避重试 */
int SYS_DHT11_ReadRetry(float *temp_c, float *humi_rh, uint8_t retries)
{
    uint8_t k;
    int     r = -1;

    for (k = 0U; k < retries; k++)
    {
        r = SYS_DHT11_Read(temp_c, humi_rh);
        if (r == 0)  { return 0; }
        if (r == -1) { break; }        /* 无应答：重试没有意义            */
        delay_ms(20);                  /* 只有校验失败才退避重试          */
    }
    return r;
}

/* ⑦ 用法：独立任务里每 2s 调一次 ReadRetry，成功就把温湿度通过队列
 * 交给处理任务，由处理任务按大端 ×100 填进 ㉒ 的 20 字节环境帧。 */

/* ============================================================
 *  ㉕ 一条 I2C 总线挂多个器件 + AT24C02 掉电保存参数
 *  平台：STM32F407 · 板2（数据通信端）
 *  总线：I2C1，SCL = PB8 / SDA = PB9，板上已有 4.7k 上拉
 *  器件：AT24C02(0x50) + MPU6050(0x68) + 外接 OLED(0x3C) / AHT10(0x38)
 *  依赖：sys_i2c.h + at24c02.h（本项目已有，本文件不改它们）
 * ============================================================ */
#include "stm32f4xx.h"
#include "sys_i2c.h"
#include "at24c02.h"
#include "modbus.h"      /* MODBUS_CRC16(buf, len)：多项式 0xA001，初值 0xFFFF */

#include <string.h>

/* ---------------- ① 总线上的器件清单（7 位地址） ---------------- */
#define BUS_EEPROM    SYS_I2C_ADDR_24C02      /* 0x50 板载 EEPROM */
#define BUS_MPU6050   SYS_I2C_ADDR_MPU6050    /* 0x68 板载六轴 AD0=0 */
#define BUS_OLED      SYS_I2C_ADDR_SSD1306    /* 0x3C 外接 OLED */
#define BUS_AHT10     SYS_I2C_ADDR_AHT10      /* 0x38 外接温湿度 */

/* ---------------- ② 参数区的“信封”布局（0x10 起，避开 MAGIC 区） ---------
 *   0x10  4 字节 MAGIC  “P25A”
 *   0x14  1 字节 版本    改了字段就得改它
 *   0x15  1 字节 长度    = sizeof(Param_t)，防止结构体变了还去读老数据
 *   0x16  2 字节 CRC16   覆盖 [0x10, 0x16) 共 6 字节
 *   0x18  N 字节 参数体
 * ============================================================ */
#define P25_MAGIC0     0x50U    /* 'P' */
#define P25_MAGIC1     0x32U    /* '2' */
#define P25_MAGIC2     0x35U    /* '5' */
#define P25_MAGIC3     0x41U    /* 'A' */
#define P25_VER        1U
#define P25_ADDR_HDR   0x10U
#define P25_ADDR_BODY  0x18U

/* 为什么参数体不放在 0x14：把定长头（MAGIC+版本+长度+CRC）与变长体分开，
 *   以后加字段只改 P25_VER 和结构体，头部布局不动，老固件的头依然能读。 */

typedef struct {
    uint16_t kp_x100;      /* PID Kp ×100：1.25 → 125 */
    uint16_t ki_x100;      /* PID Ki ×100 */
    uint16_t kd_x100;      /* PID Kd ×100 */
    uint16_t temp_alarm;   /* 报警阈值 ×10 摄氏度 */
    uint8_t  report_s;     /* 上报周期，秒 */
    uint8_t  reserved[3];  /* 补到 12 字节，与 8 字节页对齐更好拆 */
} Param_t;

static Param_t s_param;        /* 内存里的“当前生效参数” */
static uint8_t s_from_eeprom;  /* 1 = 来自 EEPROM，0 = 用的默认值 */

/* ---------------- ③ 扫一遍总线：把所有应答的 7 位地址列出来 ------------- */
void bus_scan_report(void)
{
    uint8_t found[16];
    uint8_t n;
    uint8_t i;

    /* 100000 = 100kHz。24C02 别跑 400k（头文件 AT24C02_I2C_SPEED 已定 100k） */
    SYS_I2C_Init(SYS_I2C_1, 100000UL);

    /* Scan 内部会自己加锁；返回 0 就是“整条总线没人应答” */
    n = SYS_I2C_Scan(SYS_I2C_1, found, 16U);
    printf("I2C1 上找到 %u 个器件：", (unsigned)n);
    for (i = 0U; i < n; i++) {
        printf("0x%02X ", (unsigned)found[i]);
    }
    printf("\r\n");

    /* 逐个点名：地址对不上时，这一段能立刻告诉“是谁不在” */
    if (SYS_I2C_IsDeviceReady(SYS_I2C_1, BUS_EEPROM) == SYS_I2C_OK) {
        printf("EEPROM  0x50 在线\r\n");
    } else {
        printf("EEPROM  0x50 不在线，查上拉/地址脚/供电\r\n");
    }
    if (SYS_I2C_IsDeviceReady(SYS_I2C_1, BUS_MPU6050) == SYS_I2C_OK) {
        uint8_t who = 0U;
        /* 通用姿势：先给寄存器号 0x75，再读回芯片 ID（应为 0x68） */
        SYS_I2C_ReadByte(SYS_I2C_1, BUS_MPU6050, 0x75U, &who);
        printf("MPU6050 在线，WHO_AM_I = 0x%02X\r\n", (unsigned)who);
    }
}

/* ---------------- ④ 参数组包：MAGIC + 版本 + 长度 + CRC16 ---------------- */
static uint16_t param_crc(const uint8_t *hdr)
{
    /* 自己按 8 位片算一遍：CRC16-MODBUS 是寄存器版，
     *   中断里想用就得换成这个查表/逐位版本，语义与 MODBUS_CRC16 一致 */
    uint16_t crc = 0xFFFFU;
    uint16_t k;
    uint8_t  b;

    for (k = 0U; k < 6U; k++) {
        crc ^= (uint16_t)hdr[k];
        for (b = 0U; b < 8U; b++) {
            if ((crc & 0x0001U) != 0U) {
                crc = (uint16_t)((crc >> 1) ^ 0xA001U);
            } else {
                crc = (uint16_t)(crc >> 1);
            }
        }
    }
    return crc;
}

static void param_build_header(uint8_t *hdr)
{
    hdr[0] = P25_MAGIC0;
    hdr[1] = P25_MAGIC1;
    hdr[2] = P25_MAGIC2;
    hdr[3] = P25_MAGIC3;
    hdr[4] = P25_VER;
    hdr[5] = (uint8_t)sizeof(Param_t);
}

/* 存：头 8 字节 + 体 12 字节，正好各占一页，天然不会跨页回卷 */
static uint8_t param_save(const Param_t *p)
{
    uint8_t  hdr[8];
    uint8_t  body[sizeof(Param_t)];
    uint16_t crc;

    param_build_header(hdr);
    memcpy(body, p, sizeof(Param_t));

    /* CRC 只覆盖定长头 6 字节（MAGIC + 版本 + 长度） */
    crc = param_crc(hdr);
    hdr[6] = (uint8_t)(crc & 0xFFU);        /* 低字节在前 */
    hdr[7] = (uint8_t)(crc >> 8);

    /* 两笔写必须整体成功或整体失败：外层再包一次锁（WriteBytes 内部
     * 各自已经加过锁，本项目是递归锁，同任务嵌套安全，不会自锁死） */
    SYS_I2C_Lock(SYS_I2C_1);
    if (AT24C02_WriteBytes(P25_ADDR_HDR, hdr, 8U) != 0U) {
        SYS_I2C_Unlock(SYS_I2C_1);
        return 1U;
    }
    if (AT24C02_WriteBytes(P25_ADDR_BODY, body, (uint16_t)sizeof(Param_t)) != 0U) {
        SYS_I2C_Unlock(SYS_I2C_1);
        return 1U;
    }
    SYS_I2C_Unlock(SYS_I2C_1);
    return 0U;
}

/* 读：三项校验全过才采用；任何一项不过都回落默认值 */
static uint8_t param_load(Param_t *out)
{
    uint8_t  hdr[8];
    uint16_t crc_now;
    uint16_t crc_stored;

    if (AT24C02_ReadBytes(P25_ADDR_HDR, hdr, 8U) != 0U) return 0U;

    /* ① MAGIC：新名字 AT24C02_IsMagicSet 语义是“魔数在不在”，正向好读。
     *    旧名 AT24C02_IsBlank 的语义与参数名相反，极易写反导致每次上电
     *    重灌默认参数、把用户设置冲掉，所以库里已经改名。 */
    if ((hdr[0] != P25_MAGIC0) || (hdr[1] != P25_MAGIC1) ||
        (hdr[2] != P25_MAGIC2) || (hdr[3] != P25_MAGIC3)) {
        return 0U;
    }
    /* ② 版本 + 长度：结构体改过就别读老数据 */
    if ((hdr[4] != P25_VER) || (hdr[5] != (uint8_t)sizeof(Param_t))) {
        return 0U;
    }
    /* ③ CRC16：内容坏了就整份丢掉，绝不让半个结构体进业务 */
    crc_stored = (uint16_t)(((uint16_t)hdr[7] << 8) | (uint16_t)hdr[6]);
    crc_now    = param_crc(hdr);
    if (crc_now != crc_stored) {
        return 0U;
    }
    if (AT24C02_ReadBytes(P25_ADDR_BODY, (uint8_t *)out, (uint16_t)sizeof(Param_t)) != 0U) {
        return 0U;
    }
    return 1U;
}

static void param_defaults(Param_t *p)
{
    p->kp_x100     = 125U;      /* 1.25 */
    p->ki_x100     = 30U;       /* 0.30 */
    p->kd_x100     = 5U;        /* 0.05 */
    p->temp_alarm  = 600U;      /* 60.0 摄氏度 */
    p->report_s    = 5U;        /* 每 5 秒上报一次 */
    p->reserved[0] = 0U;
    p->reserved[1] = 0U;
    p->reserved[2] = 0U;
}

/* ---------------- ⑤ 开机一条链：读→校验→否则默认+回写 ---------------- */
uint8_t param_init(void)
{
    /* AT24C02_Init 内部含约 10ms 等待（上电后 EEPROM 需要准备时间） */
    if (AT24C02_Init(0U) != 0U) {
        param_defaults(&s_param);
        s_from_eeprom = 0U;
        return 1U;                      /* 器件没应答，先用默认值跑 */
    }

    if (param_load(&s_param) != 0U) {
        s_from_eeprom = 1U;
        printf("参数从 EEPROM 读取成功\r\n");
    } else {
        /* 空片 / 版本不符 / CRC 不过，都走这里：用默认值并回写一次，
         * 这样下次上电就能读到一份合法的参数，而不是每次都回落。 */
        param_defaults(&s_param);
        s_from_eeprom = 0U;
        if (param_save(&s_param) != 0U) {
            printf("默认参数回写失败：查上拉/写周期/地址规划\r\n");
            return 2U;
        }
        printf("首次上电或参数损坏，已写入默认值\r\n");
    }
    printf("Kp=%u.%02u Ki=%u.%02u Kd=%u.%02u 阈值=%u.%u 上报=%us\r\n",
           (unsigned)(s_param.kp_x100 / 100U), (unsigned)(s_param.kp_x100 % 100U),
           (unsigned)(s_param.ki_x100 / 100U), (unsigned)(s_param.ki_x100 % 100U),
           (unsigned)(s_param.kd_x100 / 100U), (unsigned)(s_param.kd_x100 % 100U),
           (unsigned)(s_param.temp_alarm / 10U), (unsigned)(s_param.temp_alarm % 10U),
           (unsigned)s_param.report_s);
    return 0U;
}

/* ---------------- ⑥ 出错时怎么自救：先救总线，再重试一次 ---------------- */
int bus_read_with_recovery(uint8_t addr7, uint8_t reg, uint8_t *out)
{
    int err = SYS_I2C_ReadByte(SYS_I2C_1, addr7, reg, out);

    if (err == SYS_I2C_ERR_TIMEOUT) {
        /* 超时 = 总线被某个从机拉死了。BusReset 发 9 个时钟 + STOP，
         *   把从机的移位状态机踢回空闲，然后重新初始化本机 I2C。 */
        SYS_I2C_BusReset(SYS_I2C_1);
        err = SYS_I2C_ReadByte(SYS_I2C_1, addr7, reg, out);
    } else if (err == SYS_I2C_ERR_ADDR) {
        /* -3 无应答：另一种常见原因是“EEPROM 还在 5ms 写周期里”。
         *   多笔连续写之间一定要让驱动把写周期等完（at24c02.c 用
         *   IsDeviceReady 轮询 + delay_ms(5) 兜底做了这件事）。 */
        printf("0x%02X 无应答：%s\r\n", (unsigned)addr7, SYS_I2C_ErrStr(err));
    }
    return err;   /* 0 = OK；负值 = SYS_I2C_ERR_* */
}

/* ============================================================
 *  ㉖ FreeRTOS 双板闭环联调，总览骨架（板1 检测端 / 板2 数据通信端）
 * ------------------------------------------------------------
 *  这份骨架把「两板共用一个 main.c」的写法、启动顺序铁律、
 *  队列与任务的参数、各模块的锁与 ISR 边界、看门狗的心脏跳汇总，
 *  一次串成一份能直接看着改的完整例子。
 *
 *  两个 Keil 工程的 <Define> 都只写了
 *      USE_STDPERIPH_DRIVER, STM32F40_41xxx, HSE_VALUE=8000000
 *  没有注入 SYS_TEST_BOARD，所以两板各吃下面这个文件里的默认值：
 *      板1（STM32F407ZE, -O1）用 1，DHT11 采集 + LoRa 发送
 *      板2（STM32F407ZG, -O3）用 2，LoRa 接收 + W25QXX 断网缓存
 *  因此板1 里 (SYS_TEST_BOARD == 2) 的分支、板2 里 == 1 的分支
 *  都是死代码，根本不会被编译进去；板1 的 FWLIB 里没有 w25qxx.c
 *  也正是靠这个宏把整段剪掉才链得过。
 * ============================================================ */

#ifndef SYS_TEST_BOARD
#define SYS_TEST_BOARD      1       /* 板1 检测端；板2 的 main.c 这里写 2 */
#endif

#include "stm32f4xx.h"
#include "stdio.h"
#include "string.h"
#include "gpio_core.h"
#include "led.h"
#include "delay.h"
#include "sys_clock.h"
#include "sys_tick.h"
#include "sys_nvic.h"
#include "sys_usart.h"
#include "sys_wdg.h"
#include "sys_rtc.h"
#include "lora_e22.h"
#include "esp8266.h"
#include "mqtt.h"
#include "sys_i2c.h"
#include "FreeRTOS.h"
#include "task.h"
#include "queue.h"

#if (SYS_TEST_BOARD == 1)
    #define BOARD_NAME          "板1 检测端 (Project_1_检测端)"
    #include "sys_dht11.h"
    #include "sys_modbus.h"      /* 板1 的 CRC16 叫 SYS_MODBUS_Crc16 */
    #define HAS_DHT11           1
    #define APP_TASK_COUNT      3   /* Sensor / Process / Comm */
#else
    #define BOARD_NAME          "板2 数据通信端 (Project_2_数据通信端)"
    #include "w25qxx.h"
    #include "w25qxx_log.h"
    #include "modbus.h"          /* 板2 的 CRC16 叫 MODBUS_CRC16 */
    #define HAS_W25QXX          1
    #define APP_TASK_COUNT      2   /* LoraRx / Forward */
#endif

/* 调试口：两板都是 USART1(PA9/PA10) 走板载 CH340C；板2 还要插两枚跳线帽 */
#define DBG                 SYS_USART_1
#define DBG_BAUD            115200U

/* 看门狗超时：必须大于最慢任务的报到周期。
 * 监控任务 1s 一轮，取 4s 留够余量。
 * sys_wdg.h 的喂狗周期对照表：毫秒级轮询 1s 够用；整屏刷新 2s；
 * Flash 扇区擦除（128K 扇区可达约 1s）必须 ≥3s。 */
#define APP_WDG_TIMEOUT_MS  4000U

/* ---------------- 一、四个必须共享的全局量 ---------------- */

/* 队列句柄：采集任务写、处理任务读，靠队列本身同步，不用额外加锁 */
static QueueHandle_t s_q_sensor;        /* 板1 才有：DHT11 → 组帧 */
static QueueHandle_t s_q_frame;         /* 两板都有：20 字节整帧的中转站 */

/* ISR 与任务共享的计数：两板都是 -O1/-O3 优化，
 *   漏写 volatile 的后果不一样但都错：
 *     板2 是 -O3，编译器会把「循环里读一次就不再变」的变量
 *     提到循环外，ISR 改了任务也看不见，循环永不退出；
 *     板1 是 -O1，多半还能凑合跑，但换编译器 / 换优化档就炸。
 *   凡是「中断里写、任务里读」的变量，一律 volatile。 */
static volatile uint32_t s_tx_ok   = 0U;
static volatile uint32_t s_tx_fail = 0U;
static volatile uint32_t s_rx_ok   = 0U;
static volatile uint32_t s_rx_bad  = 0U;

/* ---------------- 二、20 字节环境数据帧（两板同一套协议） ---------------- */
/*
 *  [0][1]      0xAA 0x55   帧头（双字节，固定）
 *  [2]         0x01        命令：环境数据上报
 *  [3]         0x0C        数据段长度 = 12 字节
 *  [4..15]     数据段      六个字段，一律大端（高字节在前）
 *  [16][17]    CRC16       低字节在前，范围 = [2..15] 共 14 字节
 *  [18][19]    0x55 0xAA   帧尾（与帧头恰好相反）
 *
 * 帧尾 55 AA 和下一帧帧头 AA 55 首尾相连，线上是 ...55 AA AA 55...
 *   接缝处凭空多出一段 AA AA；一旦接收方从字节流中间接入、或路上丢了
 *   一个字节，「AA 55」这种两字节巧合还会大量出现在数据段里。
 *   所以解析必须三重确认：帧头 + 长度自洽 + CRC 完全相等。
 * 气压只能 ×10 不能 ×100：1013.25×100 = 101325 已经超 uint16。
 */
#define FRAME_CMD_ENV       0x01U
#define FRAME_LEN_ENV       0x0CU
#define FRAME_TOTAL         20U
#define FRAME_TEMP_OFF      4U
#define FRAME_HUMI_OFF      6U
#define FRAME_PRESS_OFF     8U
#define FRAME_LIGHT_OFF     10U
#define FRAME_TVOC_OFF      12U
#define FRAME_MQ135_OFF     14U
#define FRAME_CRC_OFF       16U

static void put_u16_be(uint8_t *p, uint16_t v)
{
    p[0] = (uint8_t)((v >> 8) & 0xFFU);
    p[1] = (uint8_t)(v & 0xFFU);
}

/* CRC 范围 = CMD + LEN + DATA，既不含帧头，也不含 CRC 自己与帧尾。
 * 附带性质：把 CRC 两字节也一起算进去结果为 0，
 * 所以「整帧重算 = 0」可以直接当校验通过的判据。
 * 两板的 CRC16 名字不同：板1 = SYS_MODBUS_Crc16，板2 = MODBUS_CRC16。 */
static uint16_t frame_crc16(const uint8_t *buf, uint16_t len)
{
#if (SYS_TEST_BOARD == 1)
    return SYS_MODBUS_Crc16(buf, len);
#else
    return MODBUS_CRC16(buf, len);
#endif
}

/* 组帧：DHT11 的浮点值统一放大成整型再大端填入 */
static void frame_build(uint8_t *f, float temp_c, float humi_rh,
                        float press_hpa, uint16_t light_lx,
                        uint16_t tvoc_ppb, uint16_t mq135_raw)
{
    uint16_t crc;

    memset(f, 0, FRAME_TOTAL);
    f[0] = 0xAAU;                       /* 帧头第 1 字节 */
    f[1] = 0x55U;                       /* 帧头第 2 字节 */
    f[2] = FRAME_CMD_ENV;
    f[3] = FRAME_LEN_ENV;

    put_u16_be(&f[FRAME_TEMP_OFF],  (uint16_t)(int16_t)(temp_c  * 100.0f));
    put_u16_be(&f[FRAME_HUMI_OFF],  (uint16_t)(humi_rh * 100.0f));
    put_u16_be(&f[FRAME_PRESS_OFF], (uint16_t)(press_hpa * 10.0f));
    put_u16_be(&f[FRAME_LIGHT_OFF], light_lx);
    put_u16_be(&f[FRAME_TVOC_OFF],  tvoc_ppb);
    put_u16_be(&f[FRAME_MQ135_OFF], mq135_raw);

    crc = frame_crc16(&f[2], 14U);      /* CMD + LEN + 12 字节数据段 */
    f[FRAME_CRC_OFF]      = (uint8_t)(crc & 0xFFU);   /* 低字节在前 */
    f[FRAME_CRC_OFF + 1U] = (uint8_t)((crc >> 8) & 0xFFU);
    f[18] = 0x55U;                      /* 帧尾第 1 字节 */
    f[19] = 0xAAU;                      /* 帧尾第 2 字节 */
}

/* 解帧：三重确认，任一不成立就当没收到这一帧 */
static uint8_t frame_parse(const uint8_t *f, uint16_t n,
                           int16_t *temp100, uint16_t *humi100)
{
    if (n != FRAME_TOTAL)                     return 0U;  /* 长度自洽 */
    if ((f[0] != 0xAAU) || (f[1] != 0x55U))   return 0U;  /* 帧头 */
    if ((f[18] != 0x55U) || (f[19] != 0xAAU)) return 0U;  /* 帧尾 */
    if (f[2] != FRAME_CMD_ENV)                return 0U;
    if (f[3] != FRAME_LEN_ENV)                return 0U;
    if (MODBUS_CRC16(&f[2], 16U) != 0U)       return 0U;  /* 整段重算 = 0 */

    *temp100 = (int16_t)(((uint16_t)f[FRAME_TEMP_OFF] << 8) |
                          (uint16_t)f[FRAME_TEMP_OFF + 1U]);
    *humi100 = (uint16_t)(((uint16_t)f[FRAME_HUMI_OFF] << 8) |
                           (uint16_t)f[FRAME_HUMI_OFF + 1U]);
    return 1U;
}

/* ---------------- 三、共享资源的锁：I2C 与 SPI1 ---------------- */
/*
 * I2C1 上挂了 OLED / MPU6050 / 24C02 三样东西，共用一条总线。
 * 谁都没加锁时会出现「OLED 刷一屏刷到一半，另一个任务把 MPU6050 的
 * 起始条件插进去」，现象是偶发花屏或某次读回全 0。库给了
 * SYS_I2C_Lock(bus) / SYS_I2C_Unlock(bus)，内部是递归互斥量，
 * 并且有五个守卫：总线号越界直接返回；__get_IPSR() != 0 时返回
 * （中断上下文里不能取会阻塞的互斥量）；调度器没跑起来时返回
 * （上电初始化阶段是单线程，加锁是空操作，这是刻意的不是漏加）；
 * 惰性建锁用临界区做 double-check；建锁失败也不卡死。
 * 刷整屏这种「要多次事务原子」的场景，就是递归锁的典型用法：
 *   SYS_I2C_Lock() → 多次读写 → SYS_I2C_Unlock()。
 * SPI1 上挂 W25QXX，而 sys_spi.c 里没有任何互斥，总线互斥得
 * 应用层自己做：谁用谁 SYS_SPI_* 之前先拿同一把锁。
 */
static void i2c_oled_full_refresh(void)
{
    SYS_I2C_Lock(SYS_I2C_1);
    /* 这里整段刷屏都不会被别的任务插进总线 */
    SYS_I2C_Unlock(SYS_I2C_1);
}

/* ---------------- 四、板1：三个任务 ---------------- */

#if (SYS_TEST_BOARD == 1)

typedef struct {
    float    temp_c;
    float    humi_rh;
    uint8_t  valid;     /* 0 = 本轮没读到，组帧任务直接跳过 */
    uint32_t tick;
} SensorMsg_t;

/* 采集任务：最慢、优先级最低。
 * DHT11 一次读要阻塞约 5ms（读期间还关中断），失败要等 2.2s 再试，
 * 连续 3 次失败才认输，这种任务绝不能和通信挤在一个任务里。 */
static void vTaskSensor(void *arg)
{
    SensorMsg_t m;
    int8_t      t = 0;
    uint8_t     h = 0;
    uint8_t     ok = 0U;
    uint8_t     i;

    (void)arg;
    SYS_DHT11_Init(SYS_DHT11_PORT, SYS_DHT11_PIN);

    for (;;) {
        for (i = 0U; i < 3U; i++) {
            if (SYS_DHT11_Read(&t, &h) == 0) { ok = 1U; break; }
            vTaskDelay(pdMS_TO_TICKS(2200));   /* DHT11 采样率只有 1Hz */
        }

        m.temp_c = (float)t;
        m.humi_rh = (float)h;
        m.valid  = ok;
        m.tick   = SYS_TICK_GetTick();

        /* 队列满时丢最旧的一帧，绝不让采集任务阻塞在发送上。
         *   宁可少一帧，也绝不能让采集停摆，这是实时性的底线。 */
        if (xQueueSend(s_q_sensor, &m, 0) != pdPASS) {
            SensorMsg_t old;
            (void)xQueueReceive(s_q_sensor, &old, 0);
            (void)xQueueSend(s_q_sensor, &m, 0);
        }

        LED_Toggle(0);
        SYS_WDG_Heartbeat(0U);              /* 心跳位 0：采集活着 */
        vTaskDelay(pdMS_TO_TICKS(2000));    /* 2 秒一帧 */
    }
}

/* 处理任务：把传感器读数组成 20 字节帧，交给发送任务。
 * 组帧 + CRC 是纯 CPU 活，几十微秒就完，但它和「发送」分开的理由是
 * 发送会阻塞（LoRa 模块忙、要等 AUX），不能让组帧跟着一起等。 */
static void vTaskProcess(void *arg)
{
    SensorMsg_t m;
    uint8_t     f[FRAME_TOTAL];
    int16_t     t100;
    uint16_t    h100;

    (void)arg;
    for (;;) {
        if (xQueueReceive(s_q_sensor, &m, portMAX_DELAY) != pdPASS) continue;

        if (m.valid == 0U) {
            SYS_USART_SendLine(DBG, "[处理] 本轮 DHT11 没读到，跳过组帧");
            continue;
        }

        frame_build(f, m.temp_c, m.humi_rh, 1013.2f, 320U, 15U, 400U);
        if (frame_parse(f, FRAME_TOTAL, &t100, &h100) != 0U) {
            (void)SYS_USART_Printf(DBG, "[处理] 反解校验 OK：T=%d.%02d H=%u.%02u",
                                   (int)(t100 / 100), (int)(t100 % 100),
                                   (unsigned)(h100 / 100U), (unsigned)(h100 % 100U));
        }

        if (xQueueSend(s_q_frame, f, 0) != pdPASS) {
            SYS_USART_SendLine(DBG, "[处理] 发送队列满，丢这一帧");
        }
        SYS_WDG_Heartbeat(1U);              /* 心跳位 1：处理活着 */
    }
}

/* 通信任务：优先级比采集高一级（4 > 3），因为它有硬实时成分
 * （LoRa 透传靠字节间停顿切帧，必须及时把数据灌出去）。
 * 但它仍然可以被更高级的监控任务打断，且它等队列 / 等模块时会让出
 * CPU，队列阻塞不是忙等，这正是「优先级高不会饿死低优先级」的前提。 */
static void vTaskComm(void *arg)
{
    uint8_t f[FRAME_TOTAL];

    (void)arg;
    for (;;) {
        if (xQueueReceive(s_q_frame, f, portMAX_DELAY) != pdPASS) continue;

        /* 发出前自检：把 CRC 两字节也算进去，结果必须是 0。
         *   组帧与 CRC 不自洽的 bug 在这一行就会被抓住，不用等下位机。 */
        if (frame_crc16(&f[2], 16U) == 0U) {
            SYS_USART_SendLine(DBG, "[发送] 帧自检 OK（整段 CRC = 0）");
        } else {
            SYS_USART_SendLine(DBG, "[发送] 帧自检失败，组帧与 CRC 不自洽");
        }

        if (LORA_E22_Send(f, FRAME_TOTAL) == 0) {
            s_tx_ok++;
        } else {
            s_tx_fail++;
            SYS_USART_SendLine(DBG, "[发送] LoRa 发失败，检查天线与 AUX");
        }

        LED_Toggle(1);
        SYS_WDG_Heartbeat(2U);              /* 心跳位 2：通信活着 */
    }
}

#endif /* SYS_TEST_BOARD == 1 */

/* ---------------- 五、板2：两个任务 + 断网落盘 ---------------- */

#if (SYS_TEST_BOARD == 2)

/* 接收任务：LoRa E22 透传模式不吐「包开始 / 包结束」标记，
 * 只能靠字节之间的停顿切帧，所以必须 10~50ms 就轮询一次；
 * 太稀会把两帧粘成一段，长度对不上就被 CRC 拦掉、白丢一帧。 */
static void vTaskLoraRx(void *arg)
{
    uint8_t  buf[64];
    uint16_t n = 0U;
    int16_t  t100;
    uint16_t h100;

    (void)arg;
    LORA_E22_Init();
    LORA_E22_SetMode(LORA_E22_MODE_TRANSPARENT);

    for (;;) {
        if (LORA_E22_Recv(buf, (uint16_t)sizeof(buf), &n) == 0) {
            if (frame_parse(buf, n, &t100, &h100) != 0U) {
                s_rx_ok++;
                if (xQueueSend(s_q_frame, buf, 0) != pdPASS) {
                    SYS_USART_SendLine(DBG, "[接收] 处理队列满，丢这一帧");
                }
            } else {
                s_rx_bad++;                 /* 坏帧单独计数，看链路质量 */
            }
        }

        LED_Toggle(0);
        SYS_WDG_Heartbeat(0U);
        vTaskDelay(pdMS_TO_TICKS(20));      /* 20ms 一轮，防止粘帧 */
    }
}

/* 转发任务：优先级 4，比接收高一级。
 * 联网时上报 MQTT；判活失败或上报失败就转 Flash 缓存。
 * W25QXX 的读写由「缓存任务写、补传任务读」两方共用，
 *   w25qxx_log.c 内部已经把锁做成三级降级：
 *     有 RTOS → vTaskSuspendAll() / xTaskResumeAll()（不关中断，
 *               只暂停任务切换，天然支持嵌套，也不破坏中断响应）；
 *     没 RTOS → taskENTER_CRITICAL()；
 *     都没有  → 空操作。
 *   锁内会调页编程与扇区擦除，erase 一次约 50ms，选
 *   vTaskSuspendAll 而不是临界区，正是为了避免关中断 50ms。
 *    vTaskSuspendAll 期间绝不能调 vTaskDelay 之类的阻塞 API。 */
static void vTaskForward(void *arg)
{
    uint8_t f[FRAME_TOTAL];
    SysRtc_t now;
    uint32_t ts;
    uint8_t  fail_streak = 0U;

    (void)arg;
    for (;;) {
        if (xQueueReceive(s_q_frame, f, portMAX_DELAY) != pdPASS) continue;

        SYS_RTC_GetTime(&now);
        ts = (uint32_t)now.hour * 10000U
           + (uint32_t)now.min  * 100U
           + (uint32_t)now.sec;             /* 简易序号：时分秒拼成一个数 */

        /* 判活失败也算通信失败，和上报失败走同一条落盘路径 */
        if ((fail_streak < 3U) && (MQTT_IsAlive() != 0U)) {
            if (MQTT_Publish("data/f407-002", f, FRAME_TOTAL, 0, 0) == 0) {
                fail_streak = 0U;
                SYS_USART_SendLine(DBG, "[转发] MQTT 上报成功");
                SYS_WDG_Heartbeat(1U);
                continue;
            }
            fail_streak++;
        }

        /* 断网 / 连续失败：写本板 SPI Flash 的环形日志区，先存下来 */
        if (W25QXX_LogWrite(ts, f, FRAME_TOTAL) == W25QXX_LOG_OK) {
            (void)SYS_USART_Printf(DBG, "[缓存] 已落盘，未上传 %u 条",
                                   (unsigned)W25QXX_LogCount());
        } else {
            SYS_USART_SendLine(DBG, "[缓存] 落盘失败，检查 W25QXX 与 SPI1");
        }

        SYS_WDG_Heartbeat(1U);
    }
}

/* 补传：网络恢复后从最旧一条开始读回来重发。
 * 读接口要求调用方缓冲是 PAYLOAD + 1 = 21 字节，末尾那个结束符是
 *   函数自己写的；写成 20 字节就会在 buf[20] 上越界写 1 字节。 */
static void backfill_cache(void)
{
    uint32_t count;
    uint32_t cap;
    uint16_t head;
    uint8_t  buf[W25QXX_LOG_PAYLOAD + 1U];
    uint32_t ts = 0U;
    uint16_t n  = 0U;

    W25QXX_LogStat(&count, &cap, &head);        /* 丢了多少条要另调 LogLost */
    while (MQTT_IsAlive() != 0U) {
        if (count == 0U) break;
        if (W25QXX_LogRead(0U, &ts, buf, &n) != W25QXX_LOG_OK) break;
        if (MQTT_Publish("data/f407-002", buf, n, 0, 0) != 0) break;
        count--;
    }
}

#endif /* SYS_TEST_BOARD == 2 */

/* ---------------- 六、ISR 与任务的边界 ---------------- */

/*
 * 串口接收中断里只做两件事：把字节搬进环形缓冲、置一个标志。
 * sys_usart.c 里 rx_buf / rx_head / rx_tail 全是 static volatile，
 * 因为 ISR 写、任务读；解析（找帧头、算 CRC）一律放在任务里。
 * 绝不能在 ISR 里做的事：
 *     I2C 读写（要等总线，且互斥量不能在中断上下文取）
 *     Flash 擦写（一次擦除几十毫秒到一秒）
 *     printf（串口发一个字符要等 TXE，会拖长中断时间）
 * 中断里能做的只有：搬运字节、置标志、必要时给信号量。
 */
static void app_uart_isr_skeleton(void)
{
    /* 真实实现在 sys_usart.c 的 usart_isr() 里：
     *   rx_buf[port][rx_head[port]] = 数据寄存器;
     *   rx_head[port] = (rx_head[port] + 1U) % SYS_USART_RX_BUF_SIZE;
     * 就这么两句，别的都交给任务。 */
}

/* ---------------- 七、监控任务：心跳汇总 + 统一喂狗 ---------------- */

/* 优先级 5 最高、1s 一轮。自己先报到位，再看是不是全员到齐：
 *   SYS_WDG_HeartbeatPoll() 非 0 → 所有任务都来过 → 它内部已经喂了狗；
 *   返回 0 → 有任务没报到 → 不喂狗 → 看门狗把整块板复位。
 * 这才是看门狗真正管用的用法；每个任务各自喂狗，会让一个卡死的
 * 任务被别的任务掩盖掉，看门狗形同虚设。 */
static void vTaskMonitor(void *arg)
{
    uint32_t t0;
    uint32_t t1;

    (void)arg;

    t0 = SYS_TICK_GetTick();
    vTaskDelay(pdMS_TO_TICKS(200));
    t1 = SYS_TICK_GetTick();
    SYS_TICK_Delay_ms(200U);            /* T1 修复后这里必须能返回 */

    (void)SYS_USART_Printf(DBG, "[监控] 调度器节拍验证：%u ms", (unsigned)(t1 - t0));

    for (;;) {
        vTaskDelay(pdMS_TO_TICKS(1000));
        SYS_WDG_Heartbeat((uint8_t)(APP_TASK_COUNT - 1U));

        if (SYS_WDG_HeartbeatPoll() == 0U) {
            (void)SYS_USART_Printf(DBG, "[监控] 有任务没报到：Pending = %08X",
                                   (unsigned)SYS_WDG_HeartbeatPending());
        }

#if (SYS_TEST_BOARD == 1)
        (void)SYS_USART_Printf(DBG, "[监控] tick=%u 发出 %u 帧 / 失败 %u 次",
                               (unsigned)SYS_TICK_GetTick(),
                               (unsigned)s_tx_ok, (unsigned)s_tx_fail);
#else
        (void)SYS_USART_Printf(DBG, "[监控] tick=%u 收到 %u 帧 / 坏帧 %u 个",
                               (unsigned)SYS_TICK_GetTick(),
                               (unsigned)s_rx_ok, (unsigned)s_rx_bad);
#endif
        LED_Toggle(3);
    }
}

/* ---------------- 八、main：先自检、再建任务、最后开狗启调度器 ---------------- */

int main(void)
{
    uint32_t t0;
    uint32_t t1;

    /* 第一句必须是它：把 NVIC 优先级分组设成 Group_4。
     *   分组错位会让中断抢占优先级被压缩到低位，越过 FreeRTOS 的
     *   BASEPRI 阈值、撕开内核临界区，偶发死机，最难查的一类。 */
    SYS_NVIC_Init();

    SYS_USART_Init(DBG, DBG_BAUD);
    SYS_USART_InitRxIT(DBG, DBG_BAUD);
    delay_ms_dwt(200);                  /* 等 CH340C 枚举 + 串口助手打开 */

    (void)SYS_USART_Printf(DBG, "#  %s  SPL + FreeRTOS 上板自检  #", BOARD_NAME);
    (void)SYS_USART_Printf(DBG, "#  编译时间 %s %s  #", __DATE__, __TIME__);

    LED_Init();
    LED_AllOn();
    delay_ms_dwt(200);
    LED_AllOff();

    /* ---------- 阶段一：阻塞式自检，调度器还没跑 ---------- */
    /* 这段时间里不能用 vTaskDelay，也不能用互斥量：
     * 没有调度器就没有「任务」概念，SYS_I2C_Lock 在此时是空操作。 */
    t0 = SYS_TICK_GetTick();
    delay_ms_dwt(50);
    t1 = SYS_TICK_GetTick();
    if ((t1 != t0) && ((t1 - t0) >= 40U) && ((t1 - t0) <= 60U)) {
        SYS_USART_SendLine(DBG, "[ OK ] 03 毫秒时基（T1 修复验证）");
    } else {
        SYS_USART_SendLine(DBG, "[FAIL] 03 毫秒时基：GetTick 不前进，检查 T1 修复");
    }

    if (SYS_WDG_HeartbeatPending() != 0U) {
        SYS_USART_SendLine(DBG, "[ OK ] 05 看门狗（W1 修复验证）");
    } else {
        SYS_USART_SendLine(DBG, "[FAIL] 05 看门狗：心跳位没置起来，检查 Heartbeat");
    }

#if (SYS_TEST_BOARD == 1)
    /* 板1 只有 DHT11 自检；板2 才有 Flash 身份与断网缓存日志 */
    SYS_USART_SendLine(DBG, "[ -- ] 08 DHT11 温湿度（D1 修复验证）");
#else
    if (W25QXX_Init(0U) == 0U) {
        uint32_t id = W25QXX_ReadID();
        if (((id >> 16) & 0xFFU) == 0xC8U) {
            SYS_USART_SendLine(DBG, "[ OK ] 06 Flash 身份：GigaDevice GD25Q128");
        } else {
            /* S4 修复点：旧代码只认 Winbond 的 0xEF4018，
             *   而本板是 GD25Q128(0xC84018)，Init 永远失败，
             *   调用方按示例直接 return，整个断网缓存模块被跳过。
             *   修复后只看容量字节 == 0x18。 */
            SYS_USART_SendLine(DBG, "[FAIL] 06 Flash 身份：不是 GD25Q128");
        }
    }
    W25QXX_LogInit();
    if (W25QXX_LogCount() > 0U) {
        SYS_USART_SendLine(DBG, "[ OK ] 07 断网缓存日志（S1/S2 修复验证）");
    } else {
        SYS_USART_SendLine(DBG, "[FAIL] 07 断网缓存日志：一条都读不出");
    }
#endif

    /* ---------- 阶段二：建队列 ---------- */
    SYS_USART_SendLine(DBG, "准备启动 FreeRTOS 调度器");
    (void)SYS_USART_Printf(DBG, "configTOTAL_HEAP_SIZE = %u 字节",
                           (unsigned)configTOTAL_HEAP_SIZE);

    s_q_frame = xQueueCreate(4, FRAME_TOTAL);
    if (s_q_frame == NULL) {
        SYS_USART_SendLine(DBG, "[FAIL] 帧队列创建失败（堆不够）");
        for (;;) { SYS_WDG_Feed(); LED_Toggle(0); delay_ms_dwt(500); }
    }

#if (SYS_TEST_BOARD == 1)
    s_q_sensor = xQueueCreate(4, sizeof(SensorMsg_t));
    if (s_q_sensor == NULL) {
        SYS_USART_SendLine(DBG, "[FAIL] 传感器队列创建失败（堆不够）");
        for (;;) { SYS_WDG_Feed(); LED_Toggle(0); delay_ms_dwt(500); }
    }
#endif

    /* ---------- 阶段三：建任务 ---------- */
    /* 栈参数单位是 word（4 字节）：512 = 2KB、256 = 1KB。
     * 局部大数组会爆任务栈，表现是随机 HardFault，最经典的问题。 */
#if (SYS_TEST_BOARD == 1)
    xTaskCreate(vTaskSensor,  "Sensor",  512, NULL, 3, NULL);
    xTaskCreate(vTaskProcess, "Process", 512, NULL, 3, NULL);
    xTaskCreate(vTaskComm,    "Comm",    512, NULL, 4, NULL);
#else
    xTaskCreate(vTaskLoraRx,  "LoraRx",  512, NULL, 3, NULL);
    xTaskCreate(vTaskForward, "Forward", 512, NULL, 4, NULL);
#endif
    xTaskCreate(vTaskMonitor, "Monitor", 256, NULL, 5, NULL);

    /* ---------- 阶段四：开看门狗，再启调度器 ---------- */
    /* 看门狗放在这里才开：前面 DHT11 / LoRa 自检要十几秒，
     * 提前开狗会在自检途中把板子咬复位，看起来像「程序跑不起来」。 */
    SYS_WDG_Init(APP_WDG_TIMEOUT_MS);
    (void)SYS_USART_Printf(DBG, "独立看门狗已启动，超时 %u ms",
                           (unsigned)APP_WDG_TIMEOUT_MS);

    vTaskStartScheduler();

    /* 正常永远到不了这里 */
    SYS_USART_SendLine(DBG, "[FAIL] 调度器没启动，几乎一定是堆不够");
    for (;;) { }
}

/* ============================================================
 *  上板自查三句话：
 *    1. 板1 单跑：01~05 + 08 + 09 全 OK，再看串口每 2 秒一行发出计数；
 *    2. 板2 单跑：01~09 全 OK，拔网线等 2 分钟看 MQTT 判活是否转 0；
 *    3. 两板同跑：板2 应持续打印 [接收]，每帧都落进 W25QXX 缓存，
 *      断电再上电 count 不减，掉电不丢才算闭环成立。
 * ============================================================ */

/* ============================================================
 *  ㉗ 数字滤波 + 卡尔曼 + PID 闭环，完整可用代码
 *  链路：ADC 采样 -> 限幅挡野值 -> 一阶低通降噪 -> 卡尔曼估计 -> PID -> PWM
 *  平台：STM32F407 · 板2 FWLIB · sys_filter.h / kalman.h / pid.h
 * ============================================================ */
#include "stm32f4xx.h"
#include "sys_filter.h"
#include "kalman.h"
#include "pid.h"
#include "sys_adc.h"
#include "sys_tim.h"
#include "sys_tick.h"
#include <stdio.h>

/* ---- ① 采样与执行器的量纲：全部集中在这里，别散落在函数里 ---- */
#define LOOP_ADC        ADC1
#define LOOP_ADC_CH     5U          /* 光电池通道                        */
#define LOOP_PWM_TIM    SYS_TIM_1
#define LOOP_PWM_CH     1U

#define RAW_STEP_MAX    200U        /* 限幅：一次最多允许变这么多 ADC 码 */
#define LPF_FC_HZ       20.0f       /* 截止频率：滤掉 50Hz 工频干扰       */
#define LPF_FS_HZ       1000.0f     /* 采样率：和下面的 PID 周期对应      */

/* ---- ② 三个对象一律 static：递推滤波器必须有记忆，别放栈上反复重建 ---- */
static FilterLpf_t s_lpf;
static Kalman_t    s_kf;
static Pid_t       s_pid;

static uint16_t s_prev_raw;         /* 限幅滤波要上次的值 */
static uint32_t s_bad_cnt;          /* 坏值计数：滤波器不替我们数 */
static uint32_t s_last_tick;

/* ---- ③ PID 输出（浮点控制量）换算成 PWM 千分比并钳位 ---- */
static uint16_t pid_out_to_permille(float out)
{
    float v = out;
    if (v < 0.0f)    { v = 0.0f; }        /* 单向执行器：负的输出没有意义 */
    if (v > 1000.0f) { v = 1000.0f; }
    return (uint16_t)(v + 0.5f);          /* 四舍五入 */
}

/* ---- ④ 一次完整的采样 -> 滤波 -> 估计 -> 控制 ---- */
static void loop_step(float target)
{
    uint16_t raw;
    float    z, y, out;
    float    dt = (float)SYS_TICK_Elapsed(s_last_tick) / 1000.0f;

    s_last_tick = SYS_TICK_GetTick();

    /* 4.1 采样。SYS_ADC_Read 是【两个】参数（adc, channel） */
    raw = SYS_ADC_Read(LOOP_ADC, LOOP_ADC_CH);

    /* 4.2 第一关：限幅。差得太多就说明是野值，保持上次值 */
    raw = FILTER_Limit(s_prev_raw, raw, RAW_STEP_MAX);
    s_prev_raw = raw;

    /* 4.3 第二关：一阶低通。坏值先自己判掉，别喂进去 */
    z = (float)raw;
    if (z != z) { s_bad_cnt++; return; }   /* z != z 是抓 NaN 最快的写法 */
    y = FILTER_LpfUpdate(&s_lpf, z);

    /* 4.4 第三关：卡尔曼。它自己算增益 K，比固定 alpha 的低通更懂“该信谁” */
    y = KALMAN_Update(&s_kf, y);

    /* 4.5 控制：位置式 PID，输出是绝对量，直接送执行器 */
    out = PID_Update(&s_pid, target, y, dt);
    SYS_TIM_PwmSetDuty(LOOP_PWM_TIM, LOOP_PWM_CH, pid_out_to_permille(out));
}

/* ---- ⑤ 初始化：顺序是“先对象、再限幅、最后限幅值”，别反 ---- */
void loop_init(float target)
{
    float p, i, d;

    /* 5.1 滤波器：按截止频率 + 采样率算精确 alpha */
    FILTER_LpfInit(&s_lpf, LPF_FC_HZ, LPF_FS_HZ);

    /* 5.2 卡尔曼：不想算平方就用“手感”说法，1 个单位的变化要跟上，8 个单位的乱跳要滤掉 */
    (void)KALMAN_AutoTune(&s_kf, 1.0f, 8.0f);
    (void)KALMAN_Reset(&s_kf, target);

    /* 5.3 PID：三系数 -> 输出限幅 -> 积分限幅（抗饱和）-> 微分先行 */
    PID_Init(&s_pid, 20.0f, 5.0f, 0.5f);
    PID_SetOutputLimit(&s_pid, 0.0f, 1000.0f);      /* 上电第一件事，必须设 */
    PID_SetIntegralLimit(&s_pid, -500.0f, 500.0f);  /* 取输出限幅的 50%~100%  */
    PID_SetDerivOnMeasurement(&s_pid, 1U);          /* 设定值突变不产生微分尖峰 */
    PID_SetSeparateThreshold(&s_pid, 200.0f);       /* 误差大于 200 时先不积分   */

    (void)PID_GetTerms(&s_pid, &p, &i, &d);         /* 确认能读出来 */
    s_last_tick = SYS_TICK_GetTick();
}

/* ---- ⑥ 固定周期跑：用 SYS_TICK_Every 保证 dt 稳定，dt 抖动会让 Ki/Kd 跑偏 ---- */
void loop_task(float target)
{
    uint32_t last = 0U;

    loop_init(target);

    for (;;)
    {
        if (SYS_TICK_Every(&last, 10U) != 0U)      /* 10ms 一次，dt 就是 0.01s */
        {
            loop_step(target);
        }
    }
}

/* ---- ⑦ 排错：把中间量全打出来，一眼看出是谁在捣乱 ---- */
void loop_dump(void)
{
    float p, i, d;

    PID_GetTerms(&s_pid, &p, &i, &d);
    printf("K=%.3f resid=%.2f  P=%.2f I=%.2f D=%.2f bad=%lu\r\n",
           KALMAN_GetGain(&s_kf), KALMAN_GetResid(&s_kf),
           p, i, d, (unsigned long)s_bad_cnt);
}

/* ============================================================
 *  ㉘ 板2 TFT 并口彩屏 ILI9481（FSMC NE4 + A6 当 RS）
 *  平台：STM32F407ZGT6 · FWLIB · lcd.h / lcd_font.h
 *  屏幕：320×480，命令 0x6C000000、数据 0x6C000080，背光 PB15
 * ============================================================ */
#include "stm32f4xx.h"
#include "sys_clock.h"
#include "sys_tick.h"
#include "lcd.h"
#include "lcd_font.h"

/* ---- ① 上电只做一次：初始化屏幕，再用 LCD_GetWidth/Height 确认方向 ---- */
void disp_boot(void)
{
    LCD_Init();                       /* 复位 + 读 ID + 写 LCD_MADCTL(0x48) + 清屏 */
    LCD_SetRotation(LCD_ROT_90);      /* 换成横屏；换完宽高互换 */
    LCD_Clear(LCD_COLOR_BLACK);
    LCD_BackLight(1);                 /* 背光最后点，避免看到上电雪花 */

    /* 用函数取尺寸，不要写死 320 / 480：换方向后这两个数会互换 */
    LCD_ShowString(8, 6, "TFT 320x480 on FSMC NE4", LCD_COLOR_CYAN, LCD_COLOR_BLACK, 1);
    LCD_ShowString(8, 26, "W x H = ", LCD_COLOR_WHITE, LCD_COLOR_BLACK, 1);
    LCD_ShowNum(8 + 8 * 8, 26, LCD_GetWidth(), 3, LCD_COLOR_YELLOW, LCD_COLOR_BLACK, 1);
    LCD_ShowChar(8 + 8 * 12, 26, 'x', LCD_COLOR_WHITE, LCD_COLOR_BLACK, 1);
    LCD_ShowNum(8 + 8 * 13, 26, LCD_GetHeight(), 3, LCD_COLOR_YELLOW, LCD_COLOR_BLACK, 1);
}

/* ---- ② 刷色块：先开窗再连续写，别用逐点 ---- */
void disp_block_test(void)
{
    uint16_t w = LCD_GetWidth();
    uint16_t h = LCD_GetHeight();

    /* 开窗口一次，驱动内部地址自增，整个矩形只需一次开窗 */
    LCD_SetWindow(0, h / 2, w - 1, h - 1);
    LCD_FillRect(0, h / 2, w - 1, h - 1, LCD_COLOR_BLUE);

    LCD_DrawRect(4, 4, 60, 60, LCD_COLOR_RED);
    LCD_DrawLine(0, 0, w - 1, h - 1, LCD_COLOR_GREEN);
    LCD_DrawCircle(w / 2, h / 2, 40, LCD_COLOR_YELLOW);
}

/* ---- ③ 显示一路传感器：整数用 ShowNum、定点用 ShowFixed ---- */
void disp_sensor(uint16_t lux, int32_t temp_c100)
{
    LCD_ShowString(8, 60, "LUX ", LCD_COLOR_WHITE, LCD_COLOR_BLACK, 1);
    LCD_ShowNum(8 + 8 * 4, 60, lux, 5, LCD_COLOR_GREEN, LCD_COLOR_BLACK, 1);

    /* 23.45 摄氏度：整数部分 2 位、小数 2 位；temp_c100 是摄氏度 ×100 */
    LCD_ShowString(8, 84, "TEMP ", LCD_COLOR_WHITE, LCD_COLOR_BLACK, 1);
    LCD_ShowFixed(8 + 8 * 5, 84, temp_c100, 2, 2, LCD_COLOR_ORANGE, LCD_COLOR_BLACK, 1);
}

/* ---- ④ 背光开关：唯一还能单独控制的屏幕引脚 ---- */
void disp_backlight(uint8_t on)
{
    LCD_BackLight(on ? 1 : 0);
}

int main(void)
{
    SYS_CLK_ToHighSpeed();
    SYS_TICK_Init();

    disp_boot();
    disp_block_test();

    while (1)
    {
        disp_sensor(1234, 2345);
        SYS_TICK_Delay_ms(1000);
    }
}

/* ============================================================
 *  ㉙ 板2 XPT2046 电阻触摸：读坐标 + 校准 + 事件
 *  平台：STM32F407ZGT6 · FWLIB · xpt2046.h · lcd.h
 *  接线：CS PC13 / CLK PB0 / DIN PF11 / DOUT PB2 / PEN PB1
 * ============================================================ */
#include "stm32f4xx.h"
#include "sys_tick.h"
#include "lcd.h"
#include "xpt2046.h"
#include "at24c02.h"

/* ---- ① 本示例自定义：一个极简的点四角校准辅助 ----
 * 它不采集硬件，只把调用方量到的四个角原始值交给驱动保存。
 * 真实产品要把提示用户点四个角做成界面交互。 */
static uint8_t touch_apply_corners(uint16_t raw_x_at_left,  uint16_t raw_x_at_right,
                                   uint16_t raw_y_at_top,   uint16_t raw_y_at_bottom)
{
    int32_t x_span = (int32_t)raw_x_at_right - (int32_t)raw_x_at_left;
    int32_t y_span = (int32_t)raw_y_at_bottom - (int32_t)raw_y_at_top;

    if (x_span < 0) { x_span = -x_span; }   /* 触摸板正装和反装都可能，取绝对值 */
    if (y_span < 0) { y_span = -y_span; }
    if (x_span < 200 || y_span < 200) { return 0; }   /* 跨度太小说明点错了，拒绝 */

    XPT2046_Calibrate(raw_x_at_left, raw_x_at_right, raw_y_at_top, raw_y_at_bottom,
                      0U, 0U, 0U);   /* swap_xy / invert_x / invert_y 全 0 = 正装 */
    return XPT2046_CalibSave();              /* 存到板上 AT24C02 的 0x80~0x89，掉电不丢 */
}

/* ---- ② 上电流程：能取回校准就用，取不回就用默认值兜底 ---- */
uint8_t touch_boot(void)
{
    /* 校准参数存在板上 AT24C02（0x50）的 0x80~0x89，必须先初始化它 */
    (void)AT24C02_Init(400000U);
    if (XPT2046_Init() == 0U) { return 0U; }   /* 软件时序自检，失败多半是接线 */

    if (XPT2046_IsCalibrated() != 0U)
    {
        if (XPT2046_CalibLoad() != 0U) { return 1U; }   /* 直接可用 */
    }

    XPT2046_CalibDefault();
    return 1U;   /* 真实产品在这里进校准界面，调用 touch_apply_corners 保存结果 */
}

/* ---- ③ 读一次触摸事件并画点 ---- */
void touch_poll_draw(void)
{
    uint16_t x = 0, y = 0;
    uint8_t  ev = XPT2046_GetEvent(&x, &y);

    if (ev == XPT2046_EVENT_DOWN)
    {
        /* x / y 已经是映射好的屏幕像素坐标，直接画 */
        LCD_DrawPoint(x, y, LCD_COLOR_RED);
        LCD_DrawPoint(x + 1, y, LCD_COLOR_RED);
        LCD_DrawPoint(x, y + 1, LCD_COLOR_RED);
    }
    else if (ev == XPT2046_EVENT_UP)
    {
        LCD_ShowString(8, 8, "touch up      ", LCD_COLOR_WHITE, LCD_COLOR_BLACK, 1);
    }
}

/* ---- ④ 想知道什么时候按下、什么时候松开 ---- */
uint8_t touch_wait_down_release(void)
{
    if (XPT2046_PenWaitDown(3000U) == 0U) { return 0U; }   /* 3 秒内没人碰 */
    return XPT2046_PenWaitUp(3000U);
}

int main(void)
{
    SYS_TICK_Init();
    LCD_Init();
    LCD_Clear(LCD_COLOR_BLACK);
    LCD_BackLight(1);

    touch_boot();

    while (1)
    {
        touch_poll_draw();
        SYS_TICK_Delay_ms(20);
    }
}

/* ============================================================
 *  ㉚ 板2 DS18B20 单总线温度
 *  平台：STM32F407ZGT6 · FWLIB · ds18b20.h · sys_usart.h · sys_tick.h
 *  接线：DQ = PG9（单总线，需要 4.7 kΩ 上拉到 3.3 V）
 * ============================================================ */
#include "stm32f4xx.h"
#include "sys_clock.h"
#include "sys_tick.h"
#include "sys_usart.h"
#include "ds18b20.h"

/* ---- ① 本示例自定义：原始值转摄氏百分之一度（纯整数，无浮点） ---- */
/* 12 位原始值 1 LSB = 0.0625℃ = 1/16℃，所以 ×100/16 正好是百分之一度 */
static int32_t ds18b20_raw_to_c100(int16_t raw)
{
    return ((int32_t)raw * 100) / 16;
}

/* ---- ② 按当前分辨率给出足够长的等待时间 ---- */
static void ds18b20_wait_convert(void)
{
    /* DS18B20_CONV_MS_12 = 800；留 100ms 余量，宁可多等 */
    SYS_TICK_Delay_ms(900);
}

/* ---- ③ 读一次温度，返回摄氏度 ×100 ---- */
uint8_t ds18b20_read_c100(int32_t *out_c100)
{
    int16_t raw = 0;

    if (DS18B20_IsPresent() == 0U)   { return 0U; }   /* 线掉了或者没插器件 */
    if (DS18B20_StartConvert() == 0U) { return 0U; }  /* 只发命令，数据还没好   */

    ds18b20_wait_convert();                           /* 12 位必须等 800ms 以上 */

    /* 只改分辨率不重新 Init：一次转换 100ms，代价是 0.5℃ 分辨率 */
    /* DS18B20_SetResolution(9); */

    if (DS18B20_ReadTempRaw(&raw) == 0U) { return 0U; }

    *out_c100 = ds18b20_raw_to_c100(raw);
    return 1U;
}

/* ---- ④ 想自己校验 CRC：读完整 9 字节暂存器 ---- */
uint8_t ds18b20_scratch_check(void)
{
    uint8_t sp[9];

    if (DS18B20_ReadScratch(sp) == 0U) { return 0U; }
    /* sp[0]=温度低字节 sp[1]=温度高字节 ... sp[8]=CRC8 */
    return (uint8_t)(sp[8] != 0U ? 1U : 0U);
}

int main(void)
{
    int32_t c100 = 0;

    SYS_CLK_ToHighSpeed();
    SYS_TICK_Init();
    SYS_USART_Init(SYS_USART_1, 115200U);

    DS18B20_Init();

    while (1)
    {
        if (ds18b20_read_c100(&c100) != 0U)
        {
            SYS_USART_Printf(SYS_USART_1, "T = %ld.%02ld C\r\n",
                             (long)(c100 / 100), (long)(c100 >= 0 ? c100 % 100 : (-c100) % 100));
        }
        else
        {
            SYS_USART_SendLine(SYS_USART_1, "DS18B20 read fail");
        }

        SYS_TICK_Delay_ms(1000);
    }
}

/* ============================================================
 *  ㉛ 板2 HC-SR04 超声波测距
 *  平台：STM32F407ZGT6 · FWLIB · hcsr04.h · sys_usart.h · sys_tick.h
 *  接线：TRIG = PG6（3.3V 可直驱）  ECHO = PG7（必须分压到 3.3V）
 * ============================================================ */
#include "stm32f4xx.h"
#include "sys_clock.h"
#include "sys_tick.h"
#include "sys_usart.h"
#include "hcsr04.h"

#define SR04_TRIG_PORT  GPIOG
#define SR04_TRIG_PIN   GPIO_Pin_6
#define SR04_ECHO_PORT  GPIOG
#define SR04_ECHO_PIN   GPIO_Pin_7

/* ---- ① 本示例自定义：合法量程内的中值测距 ---- */
/* 作用：连测 5 次取中值，压掉单次抖动；量程边界和错误码在这里统一处理 */
static uint8_t sr04_read_stable_cm(uint16_t *cm_out)
{
    uint16_t cm = 0;
    uint8_t  err = HCSR04_ReadCmMedian(&cm, 5U);   /* 5 次中值,最坏约 160ms */

    if (err != HCSR04_OK) { return 0U; }           /* 含 ERR_NO_ECHO 与 ERR_RANGE */
    if (cm < HCSR04_MIN_CM || cm > HCSR04_MAX_CM) { return 0U; }

    *cm_out = cm;
    return 1U;
}

/* ---- ② 按实测温度修声速（单位 mm/s） ---- */
/* 声速 ≈ 331300 + 606 × 温度(℃)；这里直接给两个常见点做示范 */
static void sr04_set_speed_by_temp(int16_t temp_c)
{
    uint32_t speed = (uint32_t)(331300L + 606L * (int32_t)temp_c);
    HCSR04_SetSpeed(speed);
}

int main(void)
{
    uint16_t cm = 0;

    SYS_CLK_ToHighSpeed();
    SYS_TICK_Init();
    SYS_USART_Init(SYS_USART_1, 115200U);

    if (HCSR04_Init(SR04_TRIG_PORT, SR04_TRIG_PIN,
                    SR04_ECHO_PORT, SR04_ECHO_PIN) != HCSR04_OK)
    {
        SYS_USART_SendLine(SYS_USART_1, "HCSR04 init fail");
        while (1) { }
    }

    sr04_set_speed_by_temp(25);          /* 25℃ 干空气 -> 约 346450 mm/s */

    while (1)
    {
        if (sr04_read_stable_cm(&cm) != 0U)
        {
            SYS_USART_Printf(SYS_USART_1, "DIST = %u cm\r\n", (unsigned)cm);
        }
        else
        {
            /* 拔线、超量程、前方无遮挡都会走到这里 */
            SYS_USART_SendLine(SYS_USART_1, "HCSR04 no echo / out of range");
        }

        SYS_TICK_Delay_ms(200);
    }
}

/* ============================================================
 *  ㉜ 板2 VL53L0X 激光测距（ToF，I2C1 地址 0x29）
 *  平台：STM32F407ZGT6 · FWLIB · vl53l0x.h · sys_i2c.h · sys_usart.h
 *  接线：SCL = PB8、SDA = PB9（模块需 4.7k 上拉到 3.3V）
 * ============================================================ */
#include "stm32f4xx.h"
#include "sys_clock.h"
#include "sys_tick.h"
#include "sys_i2c.h"
#include "sys_usart.h"
#include "vl53l0x.h"

/* ---- ① 上电初始化：把每一步的错误码分开报出来 ---- */
uint8_t tof_boot(void)
{
    uint8_t err;

    /* 400kHz 快速模式：初始化要读几十字节内部校准数据 */
    SYS_I2C_Init(VL53L0X_I2C_ID, VL53L0X_I2C_SPEED);

    if (VL53L0X_IsPresent() == 0U)
    {
        SYS_USART_SendLine(SYS_USART_1, "tof: no device on I2C1 0x29");
        return 0U;
    }

    if (VL53L0X_GetModelID() != VL53L0X_MODEL_ID)
    {
        SYS_USART_SendLine(SYS_USART_1, "tof: model id mismatch");
        return 0U;
    }

    err = VL53L0X_Init();
    if (err != VL53L0X_OK)
    {
        /* SPAD / CALIB 都属于内部校准没读全，字符串交给 ErrStr */
        SYS_USART_Printf(SYS_USART_1, "tof init err: %s\r\n", VL53L0X_ErrStr(err));
        return 0U;
    }

    return 1U;
}

/* ---- ② 单次测量：阻塞约等于预算时间(33ms) ---- */
uint8_t tof_read_once_mm(uint16_t *mm_out)
{
    uint16_t mm = 0;
    uint8_t  st = 0;
    uint8_t  err = VL53L0X_ReadMmEx(&mm, &st);

    if (err != VL53L0X_OK)
    {
        if (VL53L0X_TimeoutOccurred() != 0U)
        {
            SYS_USART_SendLine(SYS_USART_1, "tof: I2C timeout (bus busy?)");
        }
        return 0U;
    }

    /* 状态码不是 OK 说明这一帧测量无效（目标太远/太近/反射太弱） */
    if (st != VL53L0X_OK) { return 0U; }

    *mm_out = mm;
    return 1U;
}

/* ---- ③ 连续测量：芯片自己按周期测,取数几乎不阻塞 ---- */
uint8_t tof_start_continuous_20hz(void)
{
    /* 50ms 周期 -> 约 20Hz；预算仍是 BUDGET_DEFAULT_US = 33000 */
    return VL53L0X_StartContinuous(50U);
}

int main(void)
{
    uint16_t mm = 0;

    SYS_CLK_ToHighSpeed();
    SYS_TICK_Init();
    SYS_USART_Init(SYS_USART_1, 115200U);

    if (tof_boot() == 0U) { while (1) { } }

    while (1)
    {
        if (tof_read_once_mm(&mm) != 0U)
        {
            SYS_USART_Printf(SYS_USART_1, "TOF = %u mm\r\n", (unsigned)mm);
        }
        else
        {
            SYS_USART_SendLine(SYS_USART_1, "TOF invalid frame");
        }

        SYS_TICK_Delay_ms(100);
    }
}

/* ============================================================
 *  ㉝ 板2 MPU6050 六轴：初始化 + 零偏校准 + 读物理量 + 取倾角
 *  平台：STM32F407ZGT6 · FWLIB · mpu6050.h · sys_i2c.h · sys_usart.h
 *  接线：I2C1（SCL = PB8、SDA = PB9）· INT = PC0 · AD0 接地 -> 地址 0x68
 * ============================================================ */
#include "stm32f4xx.h"
#include "sys_clock.h"
#include "sys_tick.h"
#include "sys_i2c.h"
#include "sys_usart.h"
#include "mpu6050.h"

static MpuData_t s_mpu;

/* ---- ① 初始化：地址自检 -> Init -> 静止校准零偏 ---- */
uint8_t mpu_boot(void)
{
    SYS_I2C_Init(MPU6050_I2C_ID, 400000U);

    if (MPU6050_IsOnline() == 0U)
    {
        SYS_USART_SendLine(SYS_USART_1, "mpu: no ack on I2C1");
        return 0U;
    }

    /* WhoAmI 寄存器正常返回 0x68；不对说明地址冲突或芯片型号不对 */
    if (MPU6050_WhoAmI() != MPU6050_ADDR)
    {
        SYS_USART_Printf(SYS_USART_1, "mpu: WhoAmI = 0x%02X, expect 0x68\r\n", (unsigned)MPU6050_WhoAmI());
        return 0U;
    }

    if (MPU6050_Init() == 0U) { return 0U; }

    /* 校准期间板子必须完全静止，所以只放在上电阶段 */
    SYS_USART_SendLine(SYS_USART_1, "keep still, calibrating gyro...");
    if (MPU6050_CalibrateGyro() == 0U) { return 0U; }

    return 1U;
}

/* ---- ② 读一次物理量并做合模长自检 ---- */
uint8_t mpu_read_checked(void)
{
    int32_t bias_x = 0, bias_y = 0, bias_z = 0;

    if (MPU6050_Read(&s_mpu) == 0U) { return 0U; }

    /* 加速度静止时合模长应该接近 1g；差太多说明量程宏和实际配置不匹配 */
    if (s_mpu.az_mg < 800 || s_mpu.az_mg > 1200)
    {
        /* 只做提示，不丢弃：运动过程中 Z 轴本来就不等于 1g */
        SYS_USART_SendLine(SYS_USART_1, "mpu: accel magnitude abnormal");
    }

    MPU6050_GetGyroBias(&bias_x, &bias_y, &bias_z);
    (void)bias_x; (void)bias_y; (void)bias_z;
    return 1U;
}

/* ---- ③ 静态倾角：单位 0.1 度 ---- */
void mpu_tilt_deg10(int16_t *pitch_x10, int16_t *roll_x10)
{
    MPU6050_GetTiltAngle(pitch_x10, roll_x10);
}

/* ---- ④ 本示例自定义：把两板 API 统一成一个函数指针表 ---- */
/* 板1 的 SYS_MPU6050_Init 要传总线号、板2 的 MPU6050_Init 不传参，
 * 上层代码不想到处 ifdef，就在这里做一层薄封装。 */
typedef struct
{
    uint8_t (*init)(void);
    uint8_t (*read)(MpuData_t *out);
} MpuOps_t;

#if defined(USE_BOARD1_SYS_MPU6050)
static uint8_t mpu_init_board1(void) { return SYS_MPU6050_Init(SYS_I2C_1); }
static uint8_t mpu_read_board1(MpuData_t *out) { return SYS_MPU6050_Read(out); }
const MpuOps_t g_mpu_ops = { mpu_init_board1, mpu_read_board1 };
#else
static uint8_t mpu_init_board2(void) { return MPU6050_Init(); }
static uint8_t mpu_read_board2(MpuData_t *out) { return MPU6050_Read(out); }
const MpuOps_t g_mpu_ops = { mpu_init_board2, mpu_read_board2 };
#endif

int main(void)
{
    int16_t pitch = 0, roll = 0;

    SYS_CLK_ToHighSpeed();
    SYS_TICK_Init();
    SYS_USART_Init(SYS_USART_1, 115200U);

    if (mpu_boot() == 0U) { while (1) { } }

    while (1)
    {
        if (mpu_read_checked() != 0U)
        {
            mpu_tilt_deg10(&pitch, &roll);
            SYS_USART_Printf(SYS_USART_1, "pitch = %d.%d deg, roll = %d.%d deg\r\n",
                             (int)(pitch / 10), (int)(pitch >= 0 ? pitch % 10 : (-pitch) % 10),
                             (int)(roll / 10),  (int)(roll >= 0 ? roll % 10 : (-roll) % 10));
        }
        SYS_TICK_Delay_ms(100);
    }
}

/* ============================================================
 *  ㉞ 板2 TB6612 直流电机 + 编码器测速（最小速度闭环）
 *  平台：STM32F407ZGT6 · FWLIB · tb6612.h · sys_encoder.h · pid.h
 *  接线：PWMA = PB6、PWMB = PB7；AIN1/AIN2 = PG2/PG3；
 *        BIN1/BIN2 = PG4/PG5；STBY = PG13
 * ============================================================ */
#include "stm32f4xx.h"
#include "sys_clock.h"
#include "sys_tick.h"
#include "sys_usart.h"
#include "tb6612.h"
#include "sys_encoder.h"
#include "pid.h"

#define ENC_LINES        500U    /* 编码器线数，按实物改 */
#define ENC_MULTIPLE     4U      /* TI12 模式 = 四倍频     */
#define CTRL_PERIOD_MS   50U     /* 速度环周期：50ms = 20Hz */

static Pid_t    s_pid_l;
static Pid_t    s_pid_r;
static uint32_t s_last_tick;

/* ---- ① 本示例自定义：PID 输出(-100~100) 换算成 TB6612 的千分比(0~1000) ---- */
static uint16_t pid_out_to_speed(float out)
{
    float v = out;
    if (v < 0.0f)    { v = 0.0f;    }     /* 本示例只做单向 */
    if (v > 1000.0f) { v = 1000.0f; }
    return (uint16_t)(v + 0.5f);
}

/* ---- ② 电机与编码器一起初始化 ---- */
uint8_t car_boot(void)
{
    if (TB6612_Init() != TB6612_OK) { return 0U; }

    /* 上电默认是待机态，必须显式解除，否则电机一动不动 */
    TB6612_Standby(1);   /* 1 = 解除待机（STBY 拉高）；0 会把整片停掉 */
    TB6612_Stop();

    /* 左右两个轮各占一路编码器，模式固定 TI12（四倍频） */
    if (SYS_ENCODER_Init(SYS_ENCODER_1, SYS_TIM_2, GPIOA, GPIO_Pin_0, GPIO_AF_TIM2, GPIOA, GPIO_Pin_1, GPIO_AF_TIM2, 0U) == 0U) { return 0U; }
    if (SYS_ENCODER_Init(SYS_ENCODER_2, SYS_TIM_3, GPIOA, GPIO_Pin_6, GPIO_AF_TIM3, GPIOA, GPIO_Pin_7, GPIO_AF_TIM3, 0U) == 0U) { return 0U; }

    SYS_ENCODER_Reset(SYS_ENCODER_1);
    SYS_ENCODER_Reset(SYS_ENCODER_2);

    /* PID 输出限幅要覆盖 TB6612 的 0~1000，默认只有 ±100 */
    PID_Init(&s_pid_l, 3.0f, 1.2f, 0.05f);
    PID_Init(&s_pid_r, 3.0f, 1.2f, 0.05f);
    PID_SetOutputLimit(&s_pid_l, 0.0f, 1000.0f);
    PID_SetOutputLimit(&s_pid_r, 0.0f, 1000.0f);
    PID_SetIntegralLimit(&s_pid_l, -300.0f, 300.0f);
    PID_SetIntegralLimit(&s_pid_r, -300.0f, 300.0f);

    s_last_tick = SYS_TICK_GetTick();
    return 1U;
}

/* ---- ③ 一个周期：读增量 -> 算 CPS -> PID -> 写电机 ---- */
void car_step(float target_cps_l, float target_cps_r)
{
    int32_t delta_l = SYS_ENCODER_GetDelta(SYS_ENCODER_1);
    int32_t delta_r = SYS_ENCODER_GetDelta(SYS_ENCODER_2);

    /* CPS 是每秒计数，做反馈量不用管轮径和减速比 */
    int32_t cps_l = SYS_ENCODER_DeltaToCps(delta_l, CTRL_PERIOD_MS);
    int32_t cps_r = SYS_ENCODER_DeltaToCps(delta_r, CTRL_PERIOD_MS);

    float dt = (float)CTRL_PERIOD_MS / 1000.0f;
    float out_l = PID_Update(&s_pid_l, target_cps_l, (float)cps_l, dt);
    float out_r = PID_Update(&s_pid_r, target_cps_r, (float)cps_r, dt);

    TB6612_SetMotor(TB6612_A, TB6612_DIR_FWD, pid_out_to_speed(out_l));
    TB6612_SetMotor(TB6612_B, TB6612_DIR_FWD, pid_out_to_speed(out_r));
}

/* ---- ④ 只要开环：用现成的动作接口 ---- */
void car_open_loop_demo(void)
{
    TB6612_Car(TB6612_CAR_FWD, 600);        /* 前进，速度 600/1000 */
    SYS_TICK_Delay_ms(2000);

    /* 渐变改向：阻塞式，放在低优先级任务或主循环里用 */
    TB6612_CarRamp(700, 400, 20);          /* 左轮 700、右轮 400 -> 右转 */
    SYS_TICK_Delay_ms(1500);

    TB6612_Brake();                         /* 短接急停，比 Stop 停得快 */
}

int main(void)
{
    SYS_CLK_ToHighSpeed();
    SYS_TICK_Init();
    SYS_USART_Init(SYS_USART_1, 115200U);

    if (car_boot() == 0U) { while (1) { } }

    /* 设定 30 秒内左右轮各 3000 counts/s */
    while (1)
    {
        car_step(3000.0f, 3000.0f);
        SYS_TICK_Delay_ms(CTRL_PERIOD_MS);
    }
}

/* ============================================================
 *  ㉟ 板2 ULN2003 步进电机：走角度 + 掉电保护
 *  平台：STM32F407ZGT6 · FWLIB · uln2003.h · sys_tick.h
 *  接线：IN1 ~ IN4 = PC1/PC2/PC3/PC4；电机绕组另接 5V（务必共地）
 * ============================================================ */
#include "stm32f4xx.h"
#include "sys_clock.h"
#include "sys_tick.h"
#include "sys_usart.h"
#include "uln2003.h"

static int32_t s_pos_steps;        /* 本示例自定义：软件维护的绝对位置（步） */

/* ---- ① 本示例自定义：角度换算成步数 ---- */
/* 2038 步 / 360° -> 每度约 5.6611 步；用整数先把角度乘 2038 再除 360，避免累积误差 */
static uint32_t uln_deg_to_steps(uint16_t deg)
{
    return (uint32_t)(((uint32_t)deg * ULN2003_STEPS_PER_REV + 180U) / 360U);
}

/* ---- ② 本示例自定义：按目标角度走，维护软件位置 ---- */
uint8_t uln_goto_deg(uint16_t target_deg)
{
    uint32_t steps = uln_deg_to_steps(target_deg);
    int32_t  current = s_pos_steps % (int32_t)ULN2003_STEPS_PER_REV;
    int32_t  delta = (int32_t)steps - current;
    uint8_t  dir;

    if (delta == 0) { return 1U; }

    /* 走最短路径：超过半圈就反向 */
    if (delta >  (int32_t)ULN2003_STEPS_PER_REV / 2) { delta -= (int32_t)ULN2003_STEPS_PER_REV; }
    if (delta < -(int32_t)ULN2003_STEPS_PER_REV / 2) { delta += (int32_t)ULN2003_STEPS_PER_REV; }

    dir = (delta > 0) ? 1U : 0U;

    /* 这里用 Step 是因为行程短（不超过半圈 = 约 1.5 秒）；行程长要改成分次 OneStep */
    ULN2003_Step((uint32_t)(delta > 0 ? delta : -delta), dir);

    s_pos_steps += (delta > 0 ? delta : -delta) * (dir ? 1 : -1);
    return 1U;
}

/* ---- ③ 提速要渐变：从慢到快，否则失步 ---- */
void uln_speed_up_demo(void)
{
    uint32_t delay_us = 6000U;      /* 起步慢：6ms 一步 */

    while (delay_us > 1200U)
    {
        ULN2003_SetStepDelay(delay_us);
        ULN2003_OneStep(1);          /* 每改一次延时走一步，模拟 8 段加速 */
        delay_us -= 600U;
    }
}

int main(void)
{
    SYS_CLK_ToHighSpeed();
    SYS_TICK_Init();
    SYS_USART_Init(SYS_USART_1, 115200U);

    ULN2003_Init();
    ULN2003_ResetPhase();
    s_pos_steps = 0;

    while (1)
    {
        uln_speed_up_demo();

        uln_goto_deg(90);
        SYS_TICK_Delay_ms(500);
        uln_goto_deg(0);
        SYS_TICK_Delay_ms(500);

        /* 停一会儿就别保持通电：省电、也不烫 */
        ULN2003_Stop();
        SYS_TICK_Delay_ms(1000);
    }
}

/* ============================================================
 *  ㊱ 板2 外扩 SRAM（FSMC NE3，1 MB @ 0x68000000）
 *  平台：STM32F407ZGT6 · FWLIB · sram.h · sys_usart.h
 *  用途：给大缓冲（图像/日志）腾空间，热数据仍放内部 RAM
 * ============================================================ */
#include "stm32f4xx.h"
#include "sys_clock.h"
#include "sys_tick.h"
#include "sys_usart.h"
#include "sram.h"

/* ---- ① 上电自检：不测就等着后面“数据偶尔错” --------------- */
uint8_t sram_boot(void)
{
    uint32_t bad;

    if (SRAM_Init() == 0U)
    {
        SYS_USART_SendLine(SYS_USART_1, "sram: FSMC init fail");
        return 0U;
    }

    if (SRAM_IsReady() == 0U)
    {
        SYS_USART_SendLine(SYS_USART_1, "sram: not ready");
        return 0U;
    }

    /* 只测前 64KB（字节口径）：几毫秒就能跑完，焊接和时序问题都能暴露 */
    bad = SRAM_Test(0U, 65536U);
    if (bad != 0U)
    {
        SYS_USART_Printf(SYS_USART_1, "sram: %lu words mismatch\r\n", (unsigned long)bad);
        return 0U;
    }

    SYS_USART_Printf(SYS_USART_1, "sram ok, size = %lu bytes, speed = %lu us\r\n",
                     (unsigned long)SRAM_GetSize(),
                     (unsigned long)SRAM_SpeedTestUs());
    return 1U;
}

/* ---- ② 用法一：带边界检查的批量读写（调试期用这个） ------ */
uint8_t sram_log_append(uint32_t word_offset, const uint16_t *src, uint32_t count)
{
    /* count 是字数；offset 也是字数（0 ~ SYS_SRAM_WORDS-1） */
    if (word_offset >= SYS_SRAM_WORDS) { return 0U; }
    if (count > (SYS_SRAM_WORDS - word_offset)) { return 0U; }

    return SRAM_WriteWords(word_offset, src, count);
}

/* ---- ③ 用法二：当成超大数组直接下标访问（量产烤机用） ---- */
void sram_fill_pattern(void)
{
    volatile uint16_t *p = SRAM_Ptr();
    uint32_t i;

    /* 16 位宽：这里的 i 是字数下标，不是字节偏移 */
    for (i = 0U; i < 1024U; i++)
    {
        p[i] = (uint16_t)(i & 0xFFFFU);
    }
}

/* ---- ④ 字节流用法：拼 32 位时间戳到外扩 SRAM ---- */
uint8_t sram_store_u32(uint32_t byte_offset, uint32_t value)
{
    uint8_t buf[4];

    buf[0] = (uint8_t)(value & 0xFFU);
    buf[1] = (uint8_t)((value >> 8) & 0xFFU);
    buf[2] = (uint8_t)((value >> 16) & 0xFFU);
    buf[3] = (uint8_t)((value >> 24) & 0xFFU);

    /* 字节接口的 offset 是字节偏移，和 SRAM_WriteWord 的口径不同 */
    return SRAM_WriteBytes(byte_offset, buf, 4U);
}

int main(void)
{
    uint16_t sample[8] = { 1, 2, 3, 4, 5, 6, 7, 8 };

    SYS_CLK_ToHighSpeed();
    SYS_TICK_Init();
    SYS_USART_Init(SYS_USART_1, 115200U);

    if (sram_boot() == 0U) { while (1) { } }

    sram_fill_pattern();
    sram_log_append(0U, sample, 8U);
    sram_store_u32(64U, SYS_TICK_GetTick());

    while (1)
    {
        SYS_TICK_Delay_ms(1000);
    }
}

/* ============================================================
 *  ㊲ 板1 系统 OLED：SSD1306 128x64 @ I2C1（PB8/PB9, 0x3C）
 *  平台：STM32F407ZET6 · 板1 FWLIB · sys_oled.h · sys_i2c.h · sys_tick.h
 *  特点：字符函数第一个参数是「页号」，不是像素 y
 * ============================================================ */
#include "stm32f4xx.h"
#include "sys_clock.h"
#include "sys_tick.h"
#include "sys_i2c.h"
#include "sys_oled.h"

/* ---- ① 初始化：总线号和地址都是运行时参数 ---- */
uint8_t oled_boot(void)
{
    /* 先单独确认器件在不在；不在了再往下跑只会一路报错 */
    if (SYS_I2C_IsDeviceReady(SYS_I2C_1, SYS_OLED_I2C_ADDR) == 0)
    {
        return 0U;   /* 查 4.7k 上拉和 SA0 引脚 */
    }

    SYS_OLED_Init(SYS_I2C_1, SYS_OLED_I2C_ADDR);
    SYS_OLED_Clear();
    SYS_OLED_Refresh();          /* 只 Clear 不 Refresh，屏上没变化 */
    SYS_OLED_DisplayOn();

    return 1U;
}

/* ---- ② 写一屏内容：注意 page 是行号（0~7），不是像素 y ---- */
void oled_draw_page(void)
{
    SYS_OLED_Clear();

    /* 第 0 页：标题 */
    SYS_OLED_ShowString(0U, 0U, "BOARD1 ENV MONITOR");

    /* 第 2 页：温度，横坐标从第 0 列开始 */
    SYS_OLED_ShowString(2U, 0U, "TEMP");
    SYS_OLED_ShowFloat(2U, 40U, 23.45f, 2U);

    /* 第 4 页：光照 */
    SYS_OLED_ShowString(4U, 0U, "LUX ");
    SYS_OLED_ShowNum(4U, 40U, 1234U);
}

/* ---- ③ 只改一行：脏页刷新会自动跳过没动过的页 ---- */
void oled_update_temp(float temp_c)
{
    /* 只重画第 2 页的数值区，其余页不动 */
    SYS_OLED_ShowFloat(2U, 40U, temp_c, 2U);

    /* 每显示周期只刷一次；不要每个改像素都刷 */
    SYS_OLED_RefreshDirty();
}

/* ---- ④ 单像素与位图：SetPixel 用像素坐标，自动换算页和位 ---- */
void oled_draw_border(void)
{
    uint16_t x, y;

    for (x = 0U; x < SYS_OLED_WIDTH; x++)
    {
        SYS_OLED_SetPixel(x, 0U, 1U);
        SYS_OLED_SetPixel(x, SYS_OLED_HEIGHT - 1U, 1U);
    }
    for (y = 0U; y < SYS_OLED_HEIGHT; y++)
    {
        SYS_OLED_SetPixel(0U, y, 1U);
        SYS_OLED_SetPixel(SYS_OLED_WIDTH - 1U, y, 1U);
    }

    SYS_OLED_RefreshDirty();
}

/* ---- ⑤ I2C 自愈：连续出错就复位总线重初始化 ---- */
static uint16_t s_last_err_count;

void oled_health_check(void)
{
    uint16_t now = SYS_OLED_ErrCount();

    if (now > s_last_err_count + 8U)      /* 一个周期内涨了 8 次以上 */
    {
        SYS_I2C_BusReset(SYS_I2C_1);       /* 从机把 SDA 拉死时只有这个能救 */
        SYS_OLED_Init(SYS_I2C_1, SYS_OLED_I2C_ADDR);
        SYS_OLED_MarkAllDirty();
        SYS_OLED_RefreshDirty();

        s_last_err_count = 0U;
        SYS_OLED_ErrClear();
        return;
    }

    s_last_err_count = now;
}

int main(void)
{
    SYS_CLK_ToHighSpeed();
    SYS_TICK_Init();

    if (oled_boot() == 0U) { while (1) { } }

    oled_draw_page();
    oled_draw_border();

    while (1)
    {
        /* 每周期：改内容 -> 刷脏页 -> 查健康度 */
        oled_update_temp(23.45f);
        oled_health_check();
        SYS_TICK_Delay_ms(500);
    }
}

/* ============================================================
 *  ㊳ 蜂鸣器 / 按键 / LED 基础外设（两板引脚对照 + 非阻塞按键）
 *  平台：STM32F407 · FWLIB · led.h / key.h / beep.h / sys_tick.h
 *  板1：LED0~3 = PF9/PF10/PE13/PE14 · KEY1~4 = PA0/PE2/PE3/PE4
 *  板2：LED0~1 = PF9/PF10        · KEY0~3 = PE4/PE3/PE2/PA0
 * ============================================================ */
#include "stm32f4xx.h"
#include "sys_clock.h"
#include "sys_tick.h"
#include "sys_usart.h"
#include "led.h"
#include "key.h"
#include "beep.h"

/* ---- ① 两板按键编号不同，做成一张映射表，业务代码只用逻辑名 ---- */
typedef enum { BTN_OK = 0, BTN_UP, BTN_DOWN, BTN_BACK, BTN_MAX } BtnId_t;

#if defined(BOARD2)
/* 板2：KEY0 = PE4、KEY1 = PE3、KEY2 = PE2、KEY3 = PA0（编号从 0 开始） */
static const uint8_t s_btn_map[BTN_MAX] = { 3U, 2U, 1U, 0U };
#else
/* 板1：KEY1 = PA0、KEY2 = PE2、KEY3 = PE3、KEY4 = PE4（编号从 1 开始） */
static const uint8_t s_btn_map[BTN_MAX] = { 1U, 2U, 3U, 4U };
#endif

/* ---- ② 本示例自定义：读某个逻辑按键，返回 1 表示按下 ---- */
static uint8_t btn_pressed(BtnId_t id)
{
    if (id >= BTN_MAX) { return 0U; }
    return (KEY_Read(s_btn_map[id]) != 0U) ? 1U : 0U;
}

/* ---- ③ 本示例自定义：非阻塞长按检测（不占 CPU、可放主循环） ---- */
#define LONG_PRESS_MS 2000U

static uint32_t s_press_tick;
static uint8_t  s_last_state;

/* 返回 1 表示刚刚检测到“长按满 2 秒”；每 10ms 调用一次 */
static uint8_t btn_long_pressed(BtnId_t id)
{
    uint8_t now = btn_pressed(id);

    if (now != 0U && s_last_state == 0U)
    {
        s_press_tick = SYS_TICK_GetTick();     /* 按下瞬间记时刻 */
    }
    else if (now != 0U && s_last_state != 0U)
    {
        if (SYS_TICK_Elapsed(s_press_tick) >= LONG_PRESS_MS)
        {
            s_last_state = now;
            return 1U;                         /* 触发一次 */
        }
    }

    s_last_state = now;
    return 0U;
}

/* ---- ④ 初始化：先把看得见听得见的东西跑起来 ---- */
void board_boot(void)
{
    LED_Init();
    KEY_Init();
    BEEP_Init();

    LED_AllOff();
    BEEP_Off();

    /* 上电双响：LED 全亮 + 蜂鸣器 100ms，证明板子活着 */
    LED_AllOn();
    BEEP_Beep(1U);   /* 响 1 次，单次时长 BEEP_ON_MS_DEFAULT = 100ms */
    SYS_TICK_Delay_ms(150);
    LED_AllOff();
}

/* ---- ⑤ 主循环：10ms 一轮，和 KEY_DEBOUNCE_MS 对齐 ---- */
int main(void)
{
    static uint32_t tick_led;

    SYS_CLK_ToHighSpeed();
    SYS_TICK_Init();
    SYS_USART_Init(SYS_USART_1, 115200U);

    board_boot();

    while (1)
    {
        /* 按键：只用 KEY_Read，自己做非阻塞长按，不用阻塞的 KEY_Scan */
        if (btn_long_pressed(BTN_OK) != 0U)
        {
            BEEP_KeySound();
            LED_Toggle(0U);   /* 0 = LED0（PF9），两板都有 */
            SYS_USART_SendLine(SYS_USART_1, "long press on OK");
        }

        /* LED 心跳：每 500ms 翻转 LED0，证明主循环没卡住 */
        if (SYS_TICK_Elapsed(tick_led) >= 500U)
        {
            tick_led = SYS_TICK_GetTick();
            LED_Toggle(0U);   /* 0 = LED0（PF9），两板都有 */
        }

        SYS_TICK_Delay_ms(10);
    }
}

