/* ============================================================
 *  ㊴ OTA 固件升级：下载区落盘 + Bootloader 搬运与跳转
 *  平台：STM32F407（板1 ZE 512KB / 板2 ZG 1MB）· SPL + FWLIB
 *  分区（见查找表「OTA 分区与标志位表」）：
 *    0x08000000  16KB   Bootloader（Sector 0，永远不动）
 *    0x08004000  48KB   App 运行区（App 的 IROM1 也改到这里）
 *    0x08010000  ≥48KB  下载区（新固件暂存；板1 64KB / 板2 192KB）
 *    参数区             沿用 sys_flash 的 A/B 两块，升级不许碰
 * ============================================================ */
#include "stm32f4xx.h"
#include <string.h>
#include "sys_flash.h"
#include "sys_usart.h"

#define OTA_MAGIC         0x4F544131UL      /* 'OTA1'：固件头魔数 */
#define OTA_HDR_SIZE      32U               /* 头 32 字节 */
#define OTA_APP_ADDR      0x08004000UL      /* App 运行区基址 */
#define OTA_BACKUP_ADDR   0x08010000UL      /* 下载区基址 */
#define OTA_APP_MAX       0x0000C000UL      /* 运行区容量 48KB */
#define OTA_FLAG_PENDING  0xA5A50001UL      /* 待安装 */
#define OTA_FLAG_DONE     0xA5A50002UL      /* 已安装 */

typedef struct
{
    uint32_t magic;
    uint32_t version;
    uint32_t size;          /* 固件字节数，不含头 */
    uint32_t crc32;         /* 对固件体算的 CRC（ST 硬件 CRC，按字） */
    uint32_t reserved[4];   /* 补齐到 32 字节，以后扩展 */
} OtaHdr_t;

/* ---------- App 侧：把收到的一段固件写进下载区 ---------- */
/* off 是相对下载区基址的字节偏移；off == 0 表示这是第一块，先擦整段 */
uint8_t ota_write_chunk(uint32_t off, const uint8_t *p, uint32_t len)
{
    if ((off & 0x3U) != 0U || (len & 0x3U) != 0U)   /* 按字写，必须 4 字节对齐 */
    {
        return 1U;
    }
    if (off == 0U)
    {
        if (SYS_FLASH_EraseSector(OTA_BACKUP_ADDR) != SYS_FLASH_OK)
        {
            return 2U;
        }
    }
    return (SYS_FLASH_Write(OTA_BACKUP_ADDR + off, p, len) == SYS_FLASH_OK) ? 0U : 3U;
}

/* ---------- 校验固件头 + 整块 CRC，通过返回 0 ---------- */
uint8_t ota_verify(const OtaHdr_t *h)
{
    uint32_t crc;

    if (h->magic != OTA_MAGIC)                     { return 1U; }   /* 没有待安装固件 */
    if (h->size == 0U || h->size > OTA_APP_MAX)    { return 2U; }   /* 长度不合理 */
    if ((h->size & 0x3U) != 0U)                    { return 3U; }   /* 非整字：两端先约定补齐 */

    CRC_ResetDR();                                                  /* 算之前必须复位 */
    crc = CRC_CalcBlockCRC((uint32_t *)(OTA_BACKUP_ADDR + OTA_HDR_SIZE), h->size / 4U);
    return (crc == h->crc32) ? 0U : 4U;
}

/* ---------- 搬运：擦运行区 → 从下载区整块复制 → 回读比对 ---------- */
uint8_t ota_install(const OtaHdr_t *h)
{
    uint8_t  buf[256];
    uint32_t off, n;
    uint32_t total = OTA_HDR_SIZE + h->size;

    if (SYS_FLASH_EraseSector(OTA_APP_ADDR) != SYS_FLASH_OK)        /* ① 先擦运行区 */
    {
        return 1U;
    }

    for (off = 0U; off < total; off += n)                            /* ② 分块复制 */
    {
        n = (total - off > 256U) ? 256U : (total - off);
        n &= ~0x3U;                                                  /* 取 4 字节整数倍 */
        SYS_FLASH_Read(OTA_BACKUP_ADDR + off, buf, n);
        if (SYS_FLASH_Write(OTA_APP_ADDR + off, buf, n) != SYS_FLASH_OK)
        {
            return 2U;
        }
    }

    for (off = 0U; off < total; off += n)                            /* ③ 回读比对 */
    {
        n = (total - off > 256U) ? 256U : (total - off);
        n &= ~0x3U;
        SYS_FLASH_Read(OTA_BACKUP_ADDR + off, buf, n);
        if (memcmp(buf, (const void *)(OTA_APP_ADDR + off), n) != 0)
        {
            return 3U;
        }
    }
    return 0U;
}

/* ---------- 跳转：顺序错一步就是 HardFault ---------- */
typedef void (*app_entry_t)(void);

void ota_jump(uint32_t app)
{
    uint32_t sp = *(volatile uint32_t *)(app);          /* 第 0 个字 = 初始 MSP */
    uint32_t pc = *(volatile uint32_t *)(app + 4U);     /* 第 1 个字 = Reset_Handler */
    int i;

    __disable_irq();                                    /* ① 关总中断 */
    SysTick->CTRL = 0U;                                 /* ② 关节拍，免得跳过去还进旧中断 */
    for (i = 0; i < 8; i++)
    {
        NVIC->ICER[i] = 0xFFFFFFFFUL;                   /* ③ 关掉所有外设中断 */
        NVIC->ICPR[i] = 0xFFFFFFFFUL;                   /*    清掉所有挂起 */
    }
    SCB->VTOR = app;                                    /* ④ 向量表搬到 App（关键） */
    __set_MSP(sp);                                      /* ⑤ 换栈指针 */
    ((app_entry_t)pc)();                                /* ⑥ 跳到 App 的复位入口 */
}

/* ---------- Bootloader 主流程（链接在 0x08000000，Sector 0） ---------- */
int main(void)
{
    const OtaHdr_t *h = (const OtaHdr_t *)OTA_BACKUP_ADDR;

    SYS_USART_Init(SYS_USART_1, 115200U);
    PWR_BackupAccessCmd(ENABLE);                        /* 备份域要先开访问 */

    if (RTC_ReadBackupRegister(RTC_BKP_DR1) == OTA_FLAG_PENDING)
    {
        SYS_USART_SendLine(SYS_USART_1, "[OTA] pending fw found, verifying...");
        if (ota_verify(h) == 0U)
        {
            SYS_USART_SendLine(SYS_USART_1, "[OTA] crc ok, installing...");
            if (ota_install(h) == 0U)
            {
                RTC_WriteBackupRegister(RTC_BKP_DR1, OTA_FLAG_DONE);
                SYS_USART_SendLine(SYS_USART_1, "[OTA] install done");
            }
            /* 装机失败：标志保持“待安装”，下次上电再试；旧程序仍在运行区 */
        }
        else
        {
            SYS_USART_SendLine(SYS_USART_1, "[OTA] verify FAILED, keep running old fw");
        }
    }

    ota_jump(OTA_APP_ADDR);      /* 无论装没装成，都跳去运行区（旧程序还在） */
    for (;;) { }
}

/* ============================================================
 *  App 侧：收完固件之后的收尾（放在 App 的升级任务里）
 * ============================================================ */
void ota_finish(void)
{
    const OtaHdr_t *h = (const OtaHdr_t *)OTA_BACKUP_ADDR;

    if (ota_verify(h) != 0U)
    {
        SYS_USART_SendLine(SYS_USART_1, "[OTA] verify failed, request resend");
        return;                       /* 不置标志，让上位机重发 */
    }

    PWR_BackupAccessCmd(ENABLE);
    RTC_WriteBackupRegister(RTC_BKP_DR1, OTA_FLAG_PENDING);
    SYS_USART_SendLine(SYS_USART_1, "[OTA] download complete, reboot to install");
    NVIC_SystemReset();               /* 软复位，剩下的交给 Bootloader */
}

