/* ============================================================
 *  板1 采集节点：FreeRTOS 主骨架 *   按「FreeRTOS 任务框架引导」11 步搭出来的成品
 *  平台：STM32F407ZET6（GEC-M4）· FreeRTOS V10.4.6 · 堆 30KB · 节拍 1ms
 * ============================================================ */
#include "stm32f4xx.h"
#include "FreeRTOS.h"
#include "task.h"
#include "queue.h"
#include "semphr.h"
#include "sys_usart.h"

/* ---------- 任务优先级（configMAX_PRIORITIES = 8，即 0~7） ---------- */
#define PRIO_MONITOR   5      /* 最高：喂狗 */
#define PRIO_COMM      4      /* 通信：要快 */
#define PRIO_SENSOR    3
#define PRIO_PROCESS   3

/* ---------- 队列深度 ---------- */
#define Q_RAW_LEN      8
#define Q_TX_LEN       8

/* ---------- 任务栈深度（单位：字。128 字 = 512 字节） ---------- */
#define STK_SMALL      128
#define STK_COMM       192

/* ---------- 心跳：每个任务一个 bit ---------- */
#define TASK_BIT_SENSOR     (1u << 0)
#define TASK_BIT_PROCESS    (1u << 1)
#define TASK_BIT_COMM       (1u << 2)
#define TASK_BIT_ALL        (TASK_BIT_SENSOR | TASK_BIT_PROCESS | TASK_BIT_COMM)

/* ---------- 数据结构：队列里传的东西 ---------- */
typedef struct {
    int16_t  temp_x10;      /* 温度 x10 */
    uint16_t humi_x10;      /* 湿度 x10 */
    uint16_t lux;           /* 光照 */
    uint16_t mq135;         /* ADC 原始值 */
} SensorData_t;

/* ---------- 全局通信对象 ---------- */
static QueueHandle_t     qRaw   = NULL;   /* Queue1: 采集 -> 处理 */
static QueueHandle_t     qTx    = NULL;   /* Queue2: 处理 -> 通信 */
static SemaphoreHandle_t i2cMutex = NULL; /* 保护 I2C 总线 */
static SemaphoreHandle_t rxSem    = NULL; /* 串口 ISR -> 接收任务 */

static EventGroupHandle_t hbGroup = NULL; /* 心跳位：谁跑过就置位 */

/* ============================================================
 *  任务 1：采集（优先级 3）
 * ============================================================ */
static void SensorTask(void *arg)
{
    SensorData_t d;
    TickType_t   last = xTaskGetTickCount();
    (void)arg;

    for (;;)
    {
        /* 严格周期唤醒：比 vTaskDelay 准（不受任务执行时间影响） */
        vTaskDelayUntil(&last, pdMS_TO_TICKS(100));   /* 10Hz */

        if (xSemaphoreTake(i2cMutex, pdMS_TO_TICKS(50)) == pdTRUE)
        {
            /* 4 个传感器共用 I2C1，取值包在锁里 */
            /* d.temp_x10 = sht30_read_temp_x10();  ... */
            xSemaphoreGive(i2cMutex);                 /* 必须释放 */
        }
        d.mq135 = 0;   /* ADC+DMA 后台刷新，直接读数组即可 */

        /* 入队给处理任务；0 = 队列满也不等（不能拖慢采集周期） */
        xQueueSend(qRaw, &d, 0);

        xEventGroupSetBits(hbGroup, TASK_BIT_SENSOR);  /* 报到 */
    }
}

/* ============================================================
 *  任务 2：处理（优先级 3）
 * ============================================================ */
static void ProcessTask(void *arg)
{
    SensorData_t d;
    (void)arg;

    for (;;)
    {
        /* 阻塞等队列：没数据时让出 CPU（不占 CPU） */
        if (xQueueReceive(qRaw, &d, portMAX_DELAY) == pdTRUE)
        {
            /* 滤波（滑动平均/中值）、阈值判断、超标报警 */
            xQueueSend(qTx, &d, 0);
            xEventGroupSetBits(hbGroup, TASK_BIT_PROCESS);
        }
    }
}

/* ============================================================
 *  任务 3：通信（优先级 4），组帧后发 LoRa
 * ============================================================ */
static void CommTask(void *arg)
{
    SensorData_t d;
    uint8_t      frame[20];
    (void)arg;

    for (;;)
    {
        if (xQueueReceive(qTx, &d, portMAX_DELAY) == pdTRUE)
        {
            /* frame_build(frame, 0x01, (uint8_t*)&d);  见“帧组包”流程卡 */
            /* SYS_USART_SendBuf(SYS_USART_2, frame, 20); */
            (void)frame;
            xEventGroupSetBits(hbGroup, TASK_BIT_COMM);
        }
    }
}

/* ============================================================
 *  任务 4：监控喂狗（优先级 5，最高）
 * ============================================================ */
static void MonitorTask(void *arg)
{
    const TickType_t period = pdMS_TO_TICKS(1000);
    (void)arg;

    for (;;)
    {
        EventBits_t bits;

        /* 等三个任务都报到（超时 1 秒） */
        bits = xEventGroupWaitBits(hbGroup, TASK_BIT_ALL, pdTRUE, pdTRUE, period);

        if ((bits & TASK_BIT_ALL) == TASK_BIT_ALL)
        {
            /* IWDG_ReloadCounter();  三者到齐才喂狗 */
        }
        /* 有任务没报到 -> 不喂狗 -> 约 2.4s 后看门狗复位 */
    }
}

/* ============================================================
 *  main
 * ============================================================ */
int main(void)
{
    BaseType_t ok;

    /* ① 必须最先设：FreeRTOS 要求 4 位全做抢占 */
    NVIC_PriorityGroupConfig(NVIC_PriorityGroup_4);

    /* ② 再初始化外设（它们的 NVIC 配置依赖上面的分组） */
    SYS_USART_Init(SYS_USART_1, 115200);
    /* SYS_I2C_Init();  SYS_ADC_DmaScanInit(...);  ADC 循环采集 */

    /* ---------- 创建通信对象 ---------- */
    qRaw   = xQueueCreate(Q_RAW_LEN, sizeof(SensorData_t));
    qTx    = xQueueCreate(Q_TX_LEN,  sizeof(SensorData_t));
    i2cMutex = xSemaphoreCreateMutex();

    if (qRaw == NULL || qTx == NULL || i2cMutex == NULL)
    {
        SYS_USART_SendLine(SYS_USART_1, "[RTOS] create object FAILED");
        for (;;) { }        /* 堆不够：调大 configTOTAL_HEAP_SIZE */
    }

    /* ---------- 创建任务 ---------- */
    ok  = xTaskCreate(SensorTask,  "Sensor",  STK_SMALL, NULL, PRIO_SENSOR,  NULL);
    ok &= xTaskCreate(ProcessTask, "Process", STK_SMALL, NULL, PRIO_PROCESS, NULL);
    ok &= xTaskCreate(CommTask,    "Comm",    STK_COMM,  NULL, PRIO_COMM,    NULL);
    ok &= xTaskCreate(MonitorTask, "Monitor", STK_SMALL, NULL, PRIO_MONITOR, NULL);

    if (ok != pdPASS)
    {
        SYS_USART_SendLine(SYS_USART_1, "[RTOS] create task FAILED");
        for (;;) { }
    }

    /* ③ 启动调度器：此函数不返回 */
    vTaskStartScheduler();

    /* 堆不够时才会走到这里（vApplicationMallocFailedHook 也会报） */
    for (;;) { }
}

