/* ============================================================
 *  RTC 电子钟（初始化 + 1秒唤醒中断自动走时） *   按“RTC 电子钟引导”10 步搭出来的成品
 *  平台：STM32F407ZET6（GEC-M4）· 标准外设库
 * ============================================================ */
#include "stm32f4xx.h"
#include <stdio.h>

/* ---------- 全局对象 ---------- */
static RTC_InitTypeDef RTC_InitStructure;
static RTC_TimeTypeDef RTC_TimeStructure;
static RTC_DateTypeDef RTC_DateStructure;

/* 中断与主循环之间用 volatile 标志通信（中断里置 1，主循环清零） */
volatile uint8_t g_rtc_sec_flag = 0;

/* 备份寄存器标记：记录“RTC 是否已配置过”，避免每次复位都重置时间 */
#define RTC_MAGIC        0xA5A5
#define RTC_BKP_REG      RTC_BKP_DR0

/* ---------- 小工具 ---------- */
/* RTC 的寄存器是 BCD 编码，打印前要转成十进制 */
uint8_t bcd2dec(uint8_t bcd)
{
    return (uint8_t)((bcd >> 4) * 10 + (bcd & 0x0F));
}

const char* weekday_cn(uint8_t wd)
{
    switch (wd)
    {
        case RTC_Weekday_Monday:    return "Mon";
        case RTC_Weekday_Tuesday:   return "Tue";
        case RTC_Weekday_Wednesday: return "Wed";
        case RTC_Weekday_Thursday:  return "Thu";
        case RTC_Weekday_Friday:    return "Fri";
        case RTC_Weekday_Saturday:  return "Sat";
        case RTC_Weekday_Sunday:    return "Sun";
        default:                    return "----";
    }
}

/* ============================================================
 *  1. 使能 LSE（外部 32.768kHz 晶振），RTC 的时钟源
 * ============================================================ */
static uint8_t lse_start(void)
{
    uint32_t timeout = 0xFFFFF;

    RCC_APB1PeriphClockCmd(RCC_APB1Periph_PWR, ENABLE);   /* 先开 PWR 时钟 */
    PWR_BackupAccessCmd(ENABLE);                          /* 解锁备份域（改 RTC 必须） */

    RCC_LSEConfig(RCC_LSE_ON);
    while ((RCC_GetFlagStatus(RCC_FLAG_LSERDY) == RESET) && (timeout--))
    {
        /* 等 LSE 起振；一定要有超时，否则晶振没焊/坏了会死在这里 */
    }
    if (RCC_GetFlagStatus(RCC_FLAG_LSERDY) == RESET)
    {
        return 0;      /* LSE 起振失败 */
    }
    return 1;
}

/* ============================================================
 *  2. 选 RTC 时钟源 -> 使能 -> 等同步
 * ============================================================ */
static void rtc_clock_enable(void)
{
    RCC_RTCCLKConfig(RCC_RTCCLKSource_LSE);   /* 选 LSE 作 RTC 时钟 */
    RCC_RTCCLKCmd(ENABLE);                    /* 使能 RTC 时钟 */
    RTC_WaitForSynchro();                     /* 等 APB 与 RTC 寄存器同步 */
    RTC_WaitForLastTask();                    /* 等上一次写操作完成 */
}

/* ============================================================
 *  6~7. 周期唤醒中断（配置侧）：1 秒一次
 * ============================================================ */
static void rtc_wakeup_1s_config(void)
{
    EXTI_InitTypeDef EXTI_InitStructure;
    NVIC_InitTypeDef NVIC_InitStructure;

    /* --- EXTI：把 RTC 周期唤醒事件接到 EXTI 线 22 --- */
    EXTI_InitStructure.EXTI_Line    = EXTI_Line22;
    EXTI_InitStructure.EXTI_Mode    = EXTI_Mode_Interrupt;
    EXTI_InitStructure.EXTI_Trigger = EXTI_Trigger_Rising;
    EXTI_InitStructure.EXTI_LineCmd = ENABLE;
    EXTI_Init(&EXTI_InitStructure);
    EXTI_ClearITPendingBit(EXTI_Line22);       /* 进中断前先清一次挂起 */

    /* --- NVIC：使能 RTC_WKUP 中断通道 --- */
    NVIC_InitStructure.NVIC_IRQChannel                   = RTC_WKUP_IRQn;
    NVIC_InitStructure.NVIC_IRQChannelPreemptionPriority  = 3;
    NVIC_InitStructure.NVIC_IRQChannelSubPriority         = 3;
    NVIC_InitStructure.NVIC_IRQChannelCmd                 = ENABLE;
    NVIC_Init(&NVIC_InitStructure);

    /* --- 唤醒定时器：CK_SPRE 1Hz + 计数 0 -> 每 1 秒触发 --- */
    RTC_WakeUpCmd(DISABLE);
    while ((RTC->ISR & RTC_ISR_WUTWF) == 0)   /* 等写保护解除 */
    {
        /* 空等 */
    }
    RTC_WakeUpClockConfig(RTC_WakeUpClock_CK_SPRE_16bits);
    RTC_SetWakeUpCounter(0);                  /* (0+1) 秒 = 1 秒 */
    RTC_ITConfig(RTC_IT_WUT, ENABLE);         /* 允许唤醒中断 */
    RTC_WakeUpCmd(ENABLE);                    /* 启动唤醒定时器 */
}

/* ============================================================
 *  3~8. RTC 总初始化
 * ============================================================ */
void rtc_init(void)
{
    if (!lse_start())
    {
        return;      /* LSE 失败，直接返回（可接错误处理 / 看门狗复位） */
    }

    rtc_clock_enable();

    if (RTC_ReadBackupRegister(RTC_BKP_REG) != RTC_MAGIC)
    {
        /* ---------- 首次上电：配置并设置初始时间 ---------- */

        RTC_InitStructure.RTC_HourFormat   = RTC_HourFormat_24;
        RTC_InitStructure.RTC_AsynchPrediv = 127;   /* (127+1)x(255+1) = 32768 -> 1Hz */
        RTC_InitStructure.RTC_SynchPrediv  = 255;
        if (RTC_Init(&RTC_InitStructure) == ERROR)
        {
            return;      /* 一般是没有解除备份域写保护 */
        }

        /* 时间：BCD 编码，0x17 = 17 时 */
        RTC_TimeStructure.RTC_H12     = RTC_H12_AM;   /* 24 小时制也必须赋个有效值 */
        RTC_TimeStructure.RTC_Hours   = 0x17;
        RTC_TimeStructure.RTC_Minutes = 0x10;
        RTC_TimeStructure.RTC_Seconds = 0x50;
        RTC_SetTime(RTC_Format_BCD, &RTC_TimeStructure);

        /* 日期：先 SetTime 再 SetDate（硬件要求顺序） */
        RTC_DateStructure.RTC_Year    = 0x26;         /* 20xx，只填后两位 */
        RTC_DateStructure.RTC_Month   = 0x10;
        RTC_DateStructure.RTC_Date    = 0x09;
        RTC_DateStructure.RTC_WeekDay = RTC_Weekday_Friday;
        RTC_SetDate(RTC_Format_BCD, &RTC_DateStructure);

        /* 插上纽扣电池后，打上标记：以后复位不再重置时间 */
        RTC_WriteBackupRegister(RTC_BKP_REG, RTC_MAGIC);
    }

    rtc_wakeup_1s_config();
}

/* ============================================================
 *  9. 中断服务函数：中断里只置标志（不做耗时的事）
 * ============================================================ */
void RTC_WKUP_IRQHandler(void)
{
    if (RTC_GetITStatus(RTC_IT_WUT) != RESET)
    {
        g_rtc_sec_flag = 1;               /* 通知主循环：又过了 1 秒 */
        RTC_ClearITPendingBit(RTC_IT_WUT);
        EXTI_ClearITPendingBit(EXTI_Line22);
    }
}

/* ============================================================
 *  main：初始化一次，之后靠秒中断驱动
 * ============================================================ */
int main(void)
{
    NVIC_PriorityGroupConfig(NVIC_PriorityGroup_2);

    rtc_init();

    while (1)
    {
        if (g_rtc_sec_flag)
        {
            g_rtc_sec_flag = 0;

            RTC_GetTime(RTC_Format_BCD, &RTC_TimeStructure);
            RTC_GetDate(RTC_Format_BCD, &RTC_DateStructure);

            /*
             * 如果接了 OLED（本引导不涉及，可自行加）：
             *   char buf[32];
             *   snprintf(buf, sizeof(buf), "%02d:%02d:%02d",
             *            bcd2dec(RTC_TimeStructure.RTC_Hours),
             *            bcd2dec(RTC_TimeStructure.RTC_Minutes),
             *            bcd2dec(RTC_TimeStructure.RTC_Seconds));
             *   OLED_ShowString(0, 2, (u8*)buf, 16);
             *
             * 没有屏时用串口打印同样能看到“自动走时”：
             */
        }
    }
}

