/* ============================================================
 *  方案 A（推荐）：直接用工程里的 sys_usart
 *  ------------------------------------------------------------
 *  sys_usart.h 已经写明了本板三路串口的接线：
 *      USART1 : TX=PA9  RX=PA10 -> 板载 CH340G（下载/调试）
 *      USART2 : TX=PA2  RX=PA3  -> RS485（与以太网 MDIO 复用，二选一）
 *      USART3 : TX=PB10 RX=PB11 -> ESP8266
 * ============================================================ */
#include "stm32f4xx.h"
#include "sys_usart.h"

#define RX_MAX  256
static uint8_t rxBuf[RX_MAX];
static volatile uint16_t rxLen = 0;

/* 收到一帧后的处理 */
static void on_frame(const uint8_t *buf, uint16_t len)
{
    /* 交给协议解析（见“数据帧组包 + CRC16-MODBUS 校验”流程卡） */
    (void)buf; (void)len;
}

void comm_init(void)
{
    /* 中断接收：数据自动进库内缓冲区，不用自己搬 */
    SYS_USART_InitRxIT(SYS_USART_1, 115200);

    /* 只发不收回环自测时用：先发一段，看能不能读回 */
    SYS_USART_SendLine(SYS_USART_1, "USART1 RX ready");
}

/* 轮询式主循环（最简单，配合 FreeRTOS 时放在任务里加 vTaskDelay） */
void comm_poll(void)
{
    if (SYS_USART_Available(SYS_USART_1))
    {
        rxLen = SYS_USART_RxRead(SYS_USART_1, rxBuf, RX_MAX);
        if (rxLen > 0)
        {
            on_frame(rxBuf, rxLen);
        }
    }
}

