        frameLen = RX_SIZE - DMA_GetCurrDataCounter(DMA2_Stream5);
        frameReady = 1;

        /* 重启 DMA，准备收下一帧 */
        DMA_Cmd(DMA2_Stream5, DISABLE);
        DMA_SetCurrDataCounter(DMA2_Stream5, RX_SIZE);
        DMA_Cmd(DMA2_Stream5, ENABLE);
    }
}

static uint8_t workBuf[RX_SIZE];

int main(void)
{
    usart1_dma_idle_init();

    while (1)
    {
        if (frameReady)
        {
            frameReady = 0;

            /* 先拷出来再解析：避免解析期间 DMA 把新数据写进来 */
            uint16_t n = frameLen;
            memcpy(workBuf, dmaRxBuf, n);

            /* 交给帧解析（见“数据帧组包 + CRC16-MODBUS 校验”流程卡） */
