/* ============================================================
 *  I2C 接传感器（一条总线挂多个器件） *   按「I2C 接传感器引导」7 步搭出来的成品
 *  平台：STM32F407ZET6（GEC-M4）· 优先用工程 sys_i2c
 * ============================================================ */
#include "stm32f4xx.h"
#include "sys_i2c.h"
#include "delay.h"   /* 等转换完成要调 delay_ms */

/* ---------- 本项目要挂的器件与地址（7 位） ---------- */
#define ADDR_BH1750    0x23
#define ADDR_BMP280    0x76    /* SDO 接地；接 VDD 则 0x77 */
#define ADDR_CCS811    0x5A
/* SHT30 = 0x44、SSD1306 = 0x3C：工程 sys_i2c.h 里已有宏 */

/* ---------- 通用：读一个 8 位寄存器 ---------- */
static uint8_t i2c_read_reg8(uint8_t addr7, uint8_t reg, uint8_t *out)
{
    return SYS_I2C_ReadByte(SYS_I2C_1, addr7, reg, out);   /* 返回 0 表示成功 */
}

/* ---------- 通用：写一个 8 位寄存器 ---------- */
static uint8_t i2c_write_reg8(uint8_t addr7, uint8_t reg, uint8_t val)
{
    return SYS_I2C_WriteByte(SYS_I2C_1, addr7, reg, val);
}

/* ============================================================
 *  BH1750 光照：连续 H 模式，读 2 字节（大端）
 * ============================================================ */
uint16_t bh1750_read_lux(void)
{
    uint8_t  buf[2] = {0};
    uint16_t raw;

    /* 0x10 = 连续 H 分辨率模式（1lx），发一次就持续测量；BH1750 没有寄存器号，
     * 写进去的字节就是命令，每条命令一个独立事务（手册：多个 opcode 之间必须插 STOP，不能连发） */
    if (SYS_I2C_WriteCmd(SYS_I2C_1, ADDR_BH1750, 0x10) != 0)
    {
        return 0;
    }

    /* 等一次测量完成（手册：默认 MTreg 下 H 分辨率典型 120ms、最长 180ms） */
    delay_ms(180);

    /* 读 2 字节结果：用 ReadRaw（不发寄存器号，也不会先发一个 0x00 掉电命令） */
    if (SYS_I2C_ReadRaw(SYS_I2C_1, ADDR_BH1750, buf, 2) != 0)
    {
        return 0;
    }

    raw = (uint16_t)((buf[0] << 8) | buf[1]);
    return (uint16_t)(raw / 1.2f);        /* 手册公式：lux = raw / 1.2 */
}

/* ============================================================
 *  上电自检：先扫描总线，确认器件都在
 * ============================================================ */
uint8_t i2c_selftest(void)
{
    uint8_t found = 0;
    uint8_t list[8];
    uint8_t n;
    uint8_t id = 0;

    SYS_I2C_Init(SYS_I2C_1, 100000);   /* 先 100k 调通，稳了再上 400k */

    if (SYS_I2C_IsDeviceReady(SYS_I2C_1, 0x44) == 0) { found |= 0x01; }   /* SHT30 */
    if (SYS_I2C_IsDeviceReady(SYS_I2C_1, 0x23) == 0) { found |= 0x02; }   /* BH1750 */
    if (SYS_I2C_IsDeviceReady(SYS_I2C_1, 0x3C) == 0) { found |= 0x04; }   /* OLED  */
    if (i2c_read_reg8(0x76, 0xD0, &id) == 0 && id == 0x58) { found |= 0x08; }   /* BMP280 ID=0x58 */
    i2c_write_reg8(ADDR_BMP280, 0xF4, 0x4D);   /* 再用写包装试一笔：过采样 ×2/×4 + 强制模式 */

    n = SYS_I2C_Scan(SYS_I2C_1, list, 8);   /* 返回扫到的个数，7 位地址写进 list[] */
    (void)n;                                /* 需要时从串口打印 list[] 核对 */
    return found;
}

/* ---------- 使用 ---------- */
int main(void)
{
    if (i2c_selftest() == 0)
    {
        /* 一个器件都没找到：查上拉、接线、地址 */
        for (;;) { }
    }

    for (;;)
    {
        uint16_t lux = bh1750_read_lux();
        (void)lux;
    }
}

