/* ============================================================
 *  ADC + DMA 循环采集（后台自动刷新数组） *   按「ADC + DMA 循环采集引导」7 步搭出来的成品
 *  平台：STM32F407ZET6（GEC-M4）
 * ============================================================ */
#include "stm32f4xx.h"
#include "sys_adc.h"

#define ADC_CH_NUM   2

/* DMA 直接往这个数组写；声明 volatile 防止编译器优化 */
static volatile uint16_t adcBuf[ADC_CH_NUM];

/* ============================================================
 *  方式一（推荐）：用工程封装
 * ============================================================ */
void adc_start(void)
{
    /* DMA 多通道扫描：后台持续刷新 adcBuf */
    SYS_ADC_DmaScanInit();
}

/* 读取一个通道的原始值（0~4095） */
uint16_t adc_raw(uint8_t ch)
{
    if (ch >= ADC_CH_NUM) { return 0; }
    return adcBuf[ch];        /* 直接读数组，DMA 已在后台更新 */
}

/* 12 位原始值 -> 毫伏：V = raw * 3300 / 4095 */
uint32_t adc_to_mv(uint16_t raw)
{
    return (uint32_t)raw * 3300u / 4095u;
}

/* 多次采样求平均，抑制噪声 */
uint16_t adc_avg(uint8_t ch, uint8_t times)
{
    uint32_t sum = 0;
    uint8_t  i;
    if (ch >= ADC_CH_NUM || times == 0) { return 0; }
    for (i = 0; i < times; i++) { sum += adcBuf[ch]; }
    return (uint16_t)(sum / times);
}

int main(void)
{
    adc_start();
    for (;;)
    {
        uint16_t raw = adc_avg(0, 16);      /* 通道 0：MQ-135 */
        (void)raw;
    }
}

