/* ============================================================
 *  板载 FLASH 参数保存（ZE 512KB / ZG 1MB） *   按「板载 FLASH 扇区配置与参数保存引导」8 步搭出来的成品
 * ============================================================ */
#include "stm32f4xx.h"
#include <string.h>

/* ============================================================
 *  芯片差异：这一行决定一切
 * ------------------------------------------------------------
 *  板1 F407ZET6 = 512KB Flash = FLASH_Sector_0 ~ FLASH_Sector_7
 *  板2 F407ZGT6 = 1MB   Flash = FLASH_Sector_0 ~ FLASH_Sector_11
 *
 *  原理：前 4 个扇区一样（16KB x 4），Sector 4 也是 64KB，
 *        区别在后面 128KB 大扇区的个数：
 *          ZE: Sector 5,6,7        各 128KB  -> 至 0x0807FFFF
 *          ZG: Sector 5,6,7,8,9,10,11 各 128KB -> 至 0x080FFFFF
 *
 *  板1 上用 Sector_8~11 属于访问不存在的扇区，行为未定义。
 * ============================================================ */

/* 板1（ZE）用这个：最后一个扇区 = Sector_7，起始 0x08060000 */
#define PARAM_SECTOR        FLASH_Sector_7
#define PARAM_ADDR          0x08060000UL
#define PARAM_MAGIC         0x50415241UL   /* 'PARA' */

/* 板2（ZG）改成这两个值即可（最后一个扇区 = Sector_11）：
 * #define PARAM_SECTOR     FLASH_Sector_11
 * #define PARAM_ADDR       0x080E0000UL
 */

#define VOLTAGE_RANGE       VoltageRange_3   /* 2.7~3.6V 供电 */

/* ---------- 要保存的参数结构（32 字节以内，方便一页写完） ---------- */
typedef struct {
    uint32_t magic;          /* 标记：判断这块区域是否已初始化 */
    uint16_t year;
    uint8_t  month;
    uint8_t  day;
    uint16_t interval_ms;    /* 采集周期 */
    int16_t  temp_offset;    /* 温度校准偏移 x10 */
    uint16_t crc;            /* 简单校验和（可选） */
} Param_t;

/* ============================================================
 *  1. 擦除一个扇区
 * ============================================================ */
static FLASH_Status flash_erase_param_sector(void)
{
    FLASH_Status st;

    FLASH_Unlock();
    FLASH_ClearFlag(FLASH_FLAG_EOP | FLASH_FLAG_OPERR | FLASH_FLAG_WRPERR |
                    FLASH_FLAG_PGAERR | FLASH_FLAG_PGPERR | FLASH_FLAG_PGSERR);

    st = FLASH_EraseSector(PARAM_SECTOR, VOLTAGE_RANGE);

    FLASH_Lock();
    return st;
}

/* ============================================================
 *  2. 写入参数（先擦再写，一次写完整结构）
 * ============================================================ */
static FLASH_Status flash_save_param(const Param_t *p)
{
    FLASH_Status st;
    const uint32_t *src = (const uint32_t *)p;
    uint32_t addr = PARAM_ADDR;
    uint32_t words = (sizeof(Param_t) + 3u) / 4u;   /* 向上取整到字 */
    uint32_t i;

    /* F4 的 Flash 只能按扇区擦；写之前必须先擦 */
    st = flash_erase_param_sector();
    if (st != FLASH_COMPLETE) { return st; }

    FLASH_Unlock();
    for (i = 0; i < words; i++)
    {
        st = FLASH_ProgramWord(addr, src[i]);
        if (st != FLASH_COMPLETE) { FLASH_Lock(); return st; }
        addr += 4;
    }
    FLASH_Lock();
    return FLASH_COMPLETE;
}

/* ============================================================
 *  3. 读取参数（先判 magic，再判校验）
 * ============================================================ */
static uint8_t flash_load_param(Param_t *p)
{
    const Param_t *src = (const Param_t *)PARAM_ADDR;

    if (src->magic != PARAM_MAGIC) { return 0; }   /* 从未写过的空 Flash */

    memcpy(p, src, sizeof(Param_t));
    return 1;
}

/* ============================================================
 *  4. 使用：读优先，读不到才写默认值
 * ============================================================ */
int main(void)
{
    Param_t p;

    if (!flash_load_param(&p))
    {
        /* 第一次跑：写一份默认参数 */
        memset(&p, 0, sizeof(p));
        p.magic       = PARAM_MAGIC;
        p.year        = 2026;
        p.month       = 10;
        p.day         = 9;
        p.interval_ms = 100;
        p.temp_offset = 0;
        flash_save_param(&p);
    }

    for (;;)
    {
        /* 运行中改参数后：p.interval_ms = 200; flash_save_param(&p); */
    }
}

/* ============================================================
 *  附：常见错误的写法（不要这样）
 * ------------------------------------------------------------
 *  ✗ float 直接转 uint32_t 存：
 *      uint32_t v = *(uint32_t*)&f;   // 可以用，但要知道这是按位复制
 *      float f2 = *(float*)&v;        // 读回来也要按位还原
 *    更稳妥：float 乘 10 变整数再存（温度 25.3 -> 253）。
 *
 *  ✗ 每次改一个参数就擦一次扇区：
 *      Flash 擦写寿命约 1 万次。频繁保存同一个扇区会很快写坏。
 *      做法：内存里改，掉电前/隔一段时间才落盘一次。
 *
 *  ✗ 在中断里擦写 Flash：
 *      擦一个 128KB 扇区要几百毫秒，期间 CPU 从 Flash 取指会停住
 *      （除非代码跑在 RAM 里）。绝不能在中断或高频任务里做。
 * ============================================================ */

f:
/* 168MHz 主频 -> 5 个等待周期（必须在提升主频前设置） */
    FLASH_SetLatency(FLASH_Latency_5);

    /* 把预取/指令缓存/数据缓存打开，能明显改善取指性能 */
    FLASH_PrefetchBufferCmd(ENABLE);
    FLASH_InstructionCacheCmd(ENABLE);
    FLASH_DataCacheCmd(ENABLE);

static FLASH_Status flash_erase_param_sector(void)
{
    FLASH_Status st;

    FLASH_Unlock();

    /* 先清掉旧的状态标志，避免误判 */
    FLASH_ClearFlag(FLASH_FLAG_EOP | FLASH_FLAG_OPERR | FLASH_FLAG_WRPERR |
                    FLASH_FLAG_PGAERR | FLASH_FLAG_PGPERR | FLASH_FLAG_PGSERR);

    st = FLASH_EraseSector(PARAM_SECTOR, VoltageRange_3);

    FLASH_Lock();          /* 用完就锁上 */
    return st;
}

static FLASH_Status flash_save_param(const Param_t *p)
{
    FLASH_Status st;
    const uint32_t *src = (const uint32_t *)p;
    uint32_t addr  = PARAM_ADDR;
    uint32_t words = (sizeof(Param_t) + 3u) / 4u;   /* 向上取整到字 */
    uint32_t i;

    /* 先擦，且必须确认擦成功 */
    st = flash_erase_param_sector();
    if (st != FLASH_COMPLETE) { return st; }

    FLASH_Unlock();
    for (i = 0; i < words; i++)
    {
        st = FLASH_ProgramWord(addr, src[i]);
        if (st != FLASH_COMPLETE)
        {
            FLASH_Lock();
            return st;            /* 出错立刻退出并上锁 */
        }
        addr += 4;
    }
    FLASH_Lock();
    return FLASH_COMPLETE;
}

