    uint32_t addr  = param_addr;
    uint32_t words = (sizeof(param_t) + 3u) / 4u;   /* 向上取整到字 */
    uint32_t i;

    /* 先擦，且必须确认擦成功 */
    st = flash_erase_param_sector();
    if (st != flash_complete) { return st; }

    flash_unlock();
    for (i = 0; i < words; i++)
    {
        st = flash_programword(addr, src[i]);
        if (st != flash_complete)
        {
