#define HB_SENSOR   (1u << 0)
#define HB_PROCESS  (1u << 1)
#define HB_COMM     (1u << 2)
#define HB_ALL      (HB_SENSOR | HB_PROCESS | HB_COMM)

static volatile uint8_t hbFlags = 0;

/* ============================================================
 *  IWDG 初始化（启动后无法用软件关闭）
 * ============================================================ */
void iwdg_init(void)
{
    RCC_APB1PeriphClockCmd(RCC_APB1Periph_IWDG, ENABLE);

    IWDG_WriteAccessCmd(IWDG_WriteAccess_Enable);   /* 解除寄存器写保护 */
    IWDG_SetPrescaler(IWDG_PRESCALER);              /* 先定分频 */
    IWDG_SetReload(IWDG_RELOAD);                    /* 再定重装值 */
    IWDG_ReloadCounter();                           /* 先喂一次，别刚开就复位 */

    IWDG_Enable();                                  /* 开门狗：此后不可关闭 */
}

/* ---------- 各任务报到 ---------- */
void hb_report(uint8_t bit)
{
    hbFlags |= bit;
}

