/* ============================================================
 *  定时器 PWM 输出（TIM3_CH1 / PC6，1kHz 可调占空比） *   按「定时器 PWM 输出引导」8 步搭出来的成品
 * ============================================================ */
#include "stm32f4xx.h"

/* ============================================================
 *  参数计算（TIM3 挂 APB1，定时器时钟 84MHz）
 * ------------------------------------------------------------
 *  频率 = 定时器时钟 / (Prescaler+1) / (Period+1)
 *       = 84MHz / 84 / 1000 = 1kHz
 *
 *  占空比 = TIM_Pulse / (Period+1)
 *  分辨率 = 1 / (Period+1) = 1/1000 = 0.1%
 * ============================================================ */
#define PWM_PRESCALER   83      /* 84MHz/(83+1) = 1MHz 计数时钟 */
#define PWM_PERIOD      999     /* 1MHz/(999+1) = 1kHz PWM 频率 */

/* ============================================================
 *  PWM 初始化
 * ============================================================ */
void pwm_init(void)
{
    GPIO_InitTypeDef        g;
    TIM_TimeBaseInitTypeDef t;
    TIM_OCInitTypeDef       o;

    /* ---- 1. 开时钟：GPIO + 定时器 ---- */
    RCC_AHB1PeriphClockCmd(RCC_AHB1Periph_GPIOC, ENABLE);
    RCC_APB1PeriphClockCmd(RCC_APB1Periph_TIM3, ENABLE);   /* TIM3 在 APB1 */

    /* ---- 2. 引脚复用为 TIM3_CH1（PC6）---- */
    GPIO_PinAFConfig(GPIOC, GPIO_PinSource6, GPIO_AF_TIM3);
    g.GPIO_Pin   = GPIO_Pin_6;
    g.GPIO_Mode  = GPIO_Mode_AF;          /* 复用模式 */
    g.GPIO_OType = GPIO_OType_PP;         /* 推挽输出 */
    g.GPIO_Speed = GPIO_Speed_100MHz;
    g.GPIO_PuPd  = GPIO_PuPd_NOPULL;
    GPIO_Init(GPIOC, &g);

    /* ---- 3. 时基：定 PWM 频率 ---- */
    t.TIM_Prescaler         = PWM_PRESCALER;
    t.TIM_Period            = PWM_PERIOD;
    t.TIM_CounterMode       = TIM_CounterMode_Up;
    t.TIM_ClockDivision     = TIM_CKD_DIV1;
    t.TIM_RepetitionCounter = 0;          /* 高级定时器才用 */
    TIM_TimeBaseInit(TIM3, &t);

    /* ---- 4. 输出通道：PWM1 模式 ---- */
    o.TIM_OCMode      = TIM_OCMode_PWM1;
    o.TIM_OutputState = TIM_OutputState_Enable;
    o.TIM_Pulse       = 500;              /* 初值 50% 占空比 */
    o.TIM_OCPolarity  = TIM_OCPolarity_High;
    TIM_OC1Init(TIM3, &o);

    /* ---- 5. 开预装载：运行时改值才平滑无毛刺 ---- */
    TIM_OC1PreloadConfig(TIM3, TIM_OCPreload_Enable);
    TIM_ARRPreloadConfig(TIM3, ENABLE);

    /* ---- 6. 启动计数 ---- */
    TIM_Cmd(TIM3, ENABLE);

    /* 若换成 TIM1 / TIM8（高级定时器），必须再加这一句，
     *   否则引脚永远没有波形，这是最常见的“PWM 不出波”原因：
     *     TIM_CtrlPWMOutputs(TIM1, ENABLE);
     */
}

/* ============================================================
 *  运行时调占空比
 * ============================================================ */
void pwm_set_duty(uint32_t pulse)     /* pulse: 0 ~ PWM_PERIOD */
{
    if (pulse > PWM_PERIOD) { pulse = PWM_PERIOD; }
    TIM_SetCompare1(TIM3, pulse);      /* 通道 2/3/4 用 TIM_SetCompare2/3/4 */
}

/* ============================================================
 *  呼吸灯示例
 * ============================================================ */
void breathing_led(void)
{
    uint32_t i;
    for (;;)
    {
        for (i = 0; i <= PWM_PERIOD; i += 10) { pwm_set_duty(i); delay_ms(5); }
        for (i = PWM_PERIOD; i > 0; i -= 10)   { pwm_set_duty(i); delay_ms(5); }
    }
}

int main(void)
{
    pwm_init();
    pwm_set_duty(500);       /* 50% */
    for (;;) { }
}

