/* ============================================================
 *  EXTI 外部中断（PA0 按键，下降沿触发 + 软件消抖） *   按「EXTI 外部中断引导」8 步搭出来的成品
 * ============================================================ */
#include "stm32f4xx.h"

/* 中断与主循环之间用 volatile 标志通信 */
static volatile uint8_t g_keyFlag = 0;
static volatile uint32_t g_keyCount = 0;

/* ============================================================
 *  初始化
 * ============================================================ */
void key_exti_init(void)
{
    GPIO_InitTypeDef g;
    EXTI_InitTypeDef e;

    /* ---- 1. 开 SYSCFG 时钟（引脚映射到 EXTI 线必须） ---- */
    RCC_APB2PeriphClockCmd(RCC_APB2Periph_SYSCFG, ENABLE);

    /* ---- 2. 开 GPIO 时钟 ---- */
    RCC_AHB1PeriphClockCmd(RCC_AHB1Periph_GPIOA, ENABLE);

    /* ---- 3. 配引脚为上拉输入（按键按下接地） ---- */
    g.GPIO_Pin  = GPIO_Pin_0;
    g.GPIO_Mode = GPIO_Mode_IN;
    g.GPIO_PuPd = GPIO_PuPd_UP;      /* 上拉：不按时为高，按下为低 */
    GPIO_Init(GPIOA, &g);

    /* ---- 4. 把 PA0 映射到 EXTI0 线（漏这步中断永不触发） ---- */
    SYSCFG_EXTILineConfig(EXTI_PortSourceGPIOA, EXTI_PinSource0);

    /* ---- 5. 配 EXTI 线 ---- */
    e.EXTI_Line    = EXTI_Line0;
    e.EXTI_Mode    = EXTI_Mode_Interrupt;      /* 中断模式（不是事件） */
    e.EXTI_Trigger = EXTI_Trigger_Falling;     /* 按下接地 -> 下降沿 */
    e.EXTI_LineCmd = ENABLE;
    EXTI_Init(&e);

    /* 清掉可能残留的挂起位，避免一使能就进中断 */
    EXTI_ClearITPendingBit(EXTI_Line0);

    /* ---- 6. 开 NVIC 通道 ---- */
    NVIC_InitTypeDef n;
    n.NVIC_IRQChannel                   = EXTI0_IRQn;
    n.NVIC_IRQChannelPreemptionPriority  = 2;
    n.NVIC_IRQChannelSubPriority         = 0;
    n.NVIC_IRQChannelCmd                 = ENABLE;
    NVIC_Init(&n);
}

/* ============================================================
 *  中断服务函数：快进快出，只置标志
 * ============================================================ */
void EXTI0_IRQHandler(void)
{
    if (EXTI_GetITStatus(EXTI_Line0) != RESET)
    {
        EXTI_ClearITPendingBit(EXTI_Line0);   /* 必须先清，防反复进 */
        g_keyFlag = 1;
        g_keyCount++;
    }
}

/* ============================================================
 *  主循环：软件消抖 + 业务处理
 * ============================================================ */
void key_poll(void)
{
    if (g_keyFlag)
    {
        g_keyFlag = 0;

        delay_ms(20);                                        /* ① 消抖延时 */
        if (GPIO_ReadInputDataBit(GPIOA, GPIO_Pin_0) == 0)   /* ② 仍是低 = 真按下 */
        {
            /* ③ 真正的按键业务 */
            /* LED_Toggle(1); */
        }
    }
}

int main(void)
{
    NVIC_PriorityGroupConfig(NVIC_PriorityGroup_2);

    key_exti_init();

    for (;;)
    {
        key_poll();
    }
}

