/* ---- 主循环里消抖 + 处理 ---- */
void key_poll(void)
{
    if (g_keyflag)
    {
        g_keyflag = 0;

        delay_ms(20);                                        /* ① 等抖动过去 */
        if (gpio_readinputdatabit(gpioa, gpio_pin_0) == 0)   /* ② 仍是低 = 真按下 */
        {
            /* ③ 业务处理 */
        }
    }
} 验证：按一下按键，业务应该只执行一次（比如 led 只翻转一次）。
如果不消抖，会看到 led 翻转 2~5 次。
如果 20ms 还不够，可以加到 30~50ms（代价是响应变慢）。 消抖必须在中断外做（中断里不能 delay）。
`delay_ms(20)` 在 freertos 任务里要换成 `vtaskdelay(pdms_to_ticks(20))`，否则会阻塞整个系统。
更严谨的做法是“状态机消抖”：记录连续 n 次采样都是低才确认按下。
长按/短按/双击需要更复杂的状态机，不是简单消抖能解决的。 exti_clearitpendingbit gpio_readinputdatabit 进阶：接进 freertos + 常见故障速查 有了前面的基础，最后把 exti 放进实际项目的两种场景：
① freertos 下：中断里发信号量/任务通知唤醒任务（优先级红线）；
② 故障排查：中断不触发时按清单查。 按下面两个代码块对照使用。 /* ============ freertos：中断 -> 任务 ============
 * 前提：nvic 分组 group_4，且该中断优先级 >= 5
 */
#include "freertos.h"
#include "semphr.h"

static semaphorehandle_t keysem = null;

/* 初始化里： */
/*   keysem = xsemaphorecreatebinary();
 *   n.nvic_irqchannelpreemptionpriority = 5;   // >= 5
 *   n.nvic_irqchannelsubpriority        = 0;
 */

void exti0_irqhandler(void)
{
    basetype_t hpw = pdfalse;

    if (exti_getitstatus(exti_line0) != reset)
    {
        exti_clearitpendingbit(exti_line0);
        xsemaphoregivefromisr(keysem, &hpw);     /* 只发信号量 */
        portyield_from_isr(hpw);
    }
}

static void keytask(void *arg)
{
    (void)arg;
    for (;;)
    {
        if (xsemaphoretake(keysem, portmax_delay) == pdtrue)
        {
            vtaskdelay(pdms_to_ticks(20));                     /* 消抖 */
            if (gpio_readinputdatabit(gpioa, gpio_pin_0) == 0)
            {
                /* 按键业务 */
            }
        }
    }
}

