/* ============================================================
 *  数据帧组包 + CRC16-MODBUS 校验（20 字节帧） *   按「数据帧组包 + CRC16-MODBUS 校验引导」7 步搭出来的成品
 *
 *  协议（设计文档 5 节已定案）：
 *    帧头(2) + 命令(1) + 长度(1) + 数据(12) + CRC16(2) + 帧尾(2) = 20 字节
 *    CRC 范围 = 命令 + 长度 + 数据段（不含帧头帧尾），低字节在前
 *    数据段：大端（高字节在前），温度有符号 short x10
 * ============================================================ */
#include "stm32f4xx.h"
#include <string.h>

#define FRAME_HEAD0     0xAA
#define FRAME_HEAD1     0x55
#define FRAME_TAIL0     0x55
#define FRAME_TAIL1     0xAA

#define FRAME_CMD_ENV   0x01
#define FRAME_DATA_LEN  12
#define FRAME_TOTAL_LEN (2 + 1 + 1 + FRAME_DATA_LEN + 2 + 2)   /* = 20 */

/* ============================================================
 *  CRC16-MODBUS（逐位法，标准实现）
 * ============================================================ */
uint16_t crc16_modbus(const uint8_t *buf, uint16_t len)
{
    uint16_t crc = 0xFFFF;
    uint16_t i;
    uint8_t  j;

    for (i = 0; i < len; i++)
    {
        crc ^= buf[i];
        for (j = 0; j < 8; j++)
        {
            if (crc & 0x0001) { crc = (uint16_t)((crc >> 1) ^ 0xA001); }
            else              { crc = (uint16_t)(crc >> 1); }
        }
    }
    return crc;
}

/* ============================================================
 *  数据段填写（12 字节，大端）
 * ============================================================ */
typedef struct {
    int16_t  temp_x10;    /* 温度 x10，有符号 */
    uint16_t humi_x10;    /* 湿度 x10 */
    uint16_t press_x10;   /* 气压 x10 */
    uint16_t lux;         /* 光照 lx */
    uint16_t tvoc;        /* CCS811 ppb */
    uint16_t mq135;       /* ADC 原始值 */
} EnvData_t;

static void frame_fill_payload(uint8_t *p, const EnvData_t *d)
{
    p[0]  = (uint8_t)(d->temp_x10  >> 8);  p[1]  = (uint8_t)(d->temp_x10);
    p[2]  = (uint8_t)(d->humi_x10  >> 8);  p[3]  = (uint8_t)(d->humi_x10);
    p[4]  = (uint8_t)(d->press_x10 >> 8);  p[5]  = (uint8_t)(d->press_x10);
    p[6]  = (uint8_t)(d->lux       >> 8);  p[7]  = (uint8_t)(d->lux);
    p[8]  = (uint8_t)(d->tvoc      >> 8);  p[9]  = (uint8_t)(d->tvoc);
    p[10] = (uint8_t)(d->mq135     >> 8);  p[11] = (uint8_t)(d->mq135);
}

/* ============================================================
 *  组帧（手动移位拼接）
 * ============================================================ */
uint16_t frame_build(uint8_t *out, uint8_t cmd, const EnvData_t *d)
{
    uint16_t idx = 0;
    uint16_t crc;

    out[idx++] = FRAME_HEAD0;
    out[idx++] = FRAME_HEAD1;
    out[idx++] = cmd;
    out[idx++] = FRAME_DATA_LEN;

    frame_fill_payload(&out[idx], d);
    idx += FRAME_DATA_LEN;

    /* CRC 范围 = 命令 + 长度 + 数据段 = out[2..15]，共 14 字节 */
    crc = crc16_modbus(&out[2], 2 + FRAME_DATA_LEN);
    out[idx++] = (uint8_t)(crc & 0xFF);      /* 低字节在前 */
    out[idx++] = (uint8_t)(crc >> 8);

    out[idx++] = FRAME_TAIL0;
    out[idx++] = FRAME_TAIL1;

    return idx;                              /* 20 */
}

/* ============================================================
 *  解帧：状态机逐字节扫描
 * ============================================================ */
typedef enum {
    ST_HEAD0 = 0, ST_HEAD1, ST_CMD, ST_LEN, ST_DATA, ST_CRC0, ST_CRC1, ST_TAIL0, ST_TAIL1
} ParseState_t;

static ParseState_t st = ST_HEAD0;
static uint8_t      frameBuf[FRAME_TOTAL_LEN];
static uint16_t     frameIdx = 0;
static uint8_t      payLen   = 0;
static uint16_t     crcRx    = 0;

/* 每收到一个字节喂一次；返回 1 表示解出一帧完整好帧 */
uint8_t frame_parse_byte(uint8_t b)
{
    switch (st)
    {
        case ST_HEAD0:
            if (b == FRAME_HEAD0) { frameBuf[0] = b; frameIdx = 1; st = ST_HEAD1; }
            break;

        case ST_HEAD1:
            if (b == FRAME_HEAD1) { frameBuf[1] = b; frameIdx = 2; st = ST_CMD; }
            else { st = (b == FRAME_HEAD0) ? ST_HEAD1 : ST_HEAD0; }   /* 重新找帧头 */
            break;

        case ST_CMD:
            frameBuf[frameIdx++] = b;
            st = ST_LEN;
            break;

        case ST_LEN:
            frameBuf[frameIdx++] = b;
            payLen = b;
            if (payLen > FRAME_DATA_LEN) { st = ST_HEAD0; break; }    /* 长度不合法：丢弃 */
            st = ST_DATA;
            break;

        case ST_DATA:
            frameBuf[frameIdx++] = b;
            if (frameIdx >= (uint16_t)(4 + payLen)) { st = ST_CRC0; }
            break;

        case ST_CRC0:
            frameBuf[frameIdx++] = b;
            crcRx  = b;                                              /* 低字节 */
            st = ST_CRC1;
            break;

        case ST_CRC1:
            frameBuf[frameIdx++] = b;
            crcRx |= ((uint16_t)b << 8);                             /* 高字节 */
            st = ST_TAIL0;
            break;

        case ST_TAIL0:
            frameBuf[frameIdx++] = b;
            st = (b == FRAME_TAIL0) ? ST_TAIL1 : ST_HEAD0;
            break;

        case ST_TAIL1:
            frameBuf[frameIdx++] = b;
            st = ST_HEAD0;                                           /* 无论对错都回起点 */
            if (b == FRAME_TAIL1)
            {
                uint16_t crcCalc = crc16_modbus(&frameBuf[2], (uint16_t)(2 + payLen));
                if (crcCalc == crcRx) { return 1; }                  /* 好帧 */
            }
            break;

        default:
            st = ST_HEAD0;
            break;
    }
    return 0;
}

/* ============================================================
 *  取出数据（有符号）
 * ============================================================ */
static void frame_get_payload(const uint8_t *f, EnvData_t *d)
{
    const uint8_t *p = &f[4];        /* 数据段从第 4 字节开始 */

    d->temp_x10  = (int16_t)(((uint16_t)p[0]  << 8) | p[1]);   /* 有符号 */
    d->humi_x10  = (uint16_t)(((uint16_t)p[2] << 8) | p[3]);
    d->press_x10 = (uint16_t)(((uint16_t)p[4] << 8) | p[5]);
    d->lux       = (uint16_t)(((uint16_t)p[6] << 8) | p[7]);
    d->tvoc      = (uint16_t)(((uint16_t)p[8] << 8) | p[9]);
    d->mq135     = (uint16_t)(((uint16_t)p[10] << 8) | p[11]);
}

/* ============================================================
 *  发送 + 接收串联示例
 * ============================================================ */
void comm_send_env(uint8_t *txbuf, const EnvData_t *d)
{
    uint16_t n = frame_build(txbuf, FRAME_CMD_ENV, d);
    /* SYS_USART_SendBuf(SYS_USART_2, txbuf, n); */
}

void comm_feed_rx(const uint8_t *rbuf, uint16_t len)
{
    uint16_t i;
    for (i = 0; i < len; i++)
    {
