/* ---------- 逐位法实现（最通用，无查表） ---------- */
uint16_t crc16_modbus(const uint8_t *buf, uint16_t len)
{
    uint16_t crc = 0xFFFF;      /* 固定初值 */
    uint16_t i;
    uint8_t  j;

    for (i = 0; i < len; i++)
    {
        crc ^= buf[i];
        for (j = 0; j < 8; j++)
        {
            if (crc & 0x0001) { crc = (uint16_t)((crc >> 1) ^ 0xA001); }
            else              { crc = (uint16_t)(crc >> 1); }
        }
    }
    return crc;
}

/* ---------- 验证用的标准测试向量 ----------
 *  MODBUS 标准示例：对 01 04 02 FF FF 求 CRC
 *  期望结果 = 0xB880（返回的是这个值，
 *                     发送时低字节在前 -> 先发 0x80 再发 0xB8）
 *
 *  在 main 里临时验证：
