    p[0]  = (uint8_t)(d->temp_x10  >> 8);  p[1]  = (uint8_t)(d->temp_x10);
    p[2]  = (uint8_t)(d->humi_x10  >> 8);  p[3]  = (uint8_t)(d->humi_x10);
    p[4]  = (uint8_t)(d->press_x10 >> 8);  p[5]  = (uint8_t)(d->press_x10);
    p[6]  = (uint8_t)(d->lux       >> 8);  p[7]  = (uint8_t)(d->lux);
    p[8]  = (uint8_t)(d->tvoc      >> 8);  p[9]  = (uint8_t)(d->tvoc);
    p[10] = (uint8_t)(d->mq135     >> 8);  p[11] = (uint8_t)(d->mq135);
}

uint16_t frame_build(uint8_t *out, uint8_t cmd, const EnvData_t *d)
{
    uint16_t idx = 0;
    uint16_t crc;

    out[idx++] = 0xAA;                     /* 帧头 */
    out[idx++] = 0x55;
    out[idx++] = cmd;                      /* 命令 */
    out[idx++] = 12;                       /* 长度 = 数据段字节数 */

    frame_fill_payload(&out[idx], d);      /* 数据段 12 字节 */
    idx += 12;

    /* CRC 范围 = 命令 + 长度 + 数据段 = out[2..15]，共 14 字节 */
    crc = crc16_modbus(&out[2], 2 + 12);
    out[idx++] = (uint8_t)(crc & 0xFF);    /* 低字节在前 */
    out[idx++] = (uint8_t)(crc >> 8);

    out[idx++] = 0x55;                     /* 帧尾 */
    out[idx++] = 0xAA;

    return idx;                            /* 返回 20 */
}

typedef enum {
    ST_HEAD0 = 0, ST_HEAD1, ST_CMD, ST_LEN, ST_DATA,
    ST_CRC0, ST_CRC1, ST_TAIL0, ST_TAIL1
} ParseState_t;

static ParseState_t st = ST_HEAD0;
static uint8_t      frameBuf[20];
static uint16_t     frameIdx = 0;
static uint8_t      payLen   = 0;
static uint16_t     crcRx    = 0;

/* 每收到一个字节喂一次；返回 1 = 解出一帧好帧 */
uint8_t frame_parse_byte(uint8_t b)
{
    switch (st)
    {
        case ST_HEAD0:
            if (b == 0xAA) { frameBuf[0] = b; frameIdx = 1; st = ST_HEAD1; }
            break;

        case ST_HEAD1:
            if (b == 0x55) { frameBuf[1] = b; frameIdx = 2; st = ST_CMD; }
            else { st = (b == 0xAA) ? ST_HEAD1 : ST_HEAD0; }   /* 重新找帧头 */
            break;

        case ST_CMD:
            frameBuf[frameIdx++] = b;  st = ST_LEN;  break;

        case ST_LEN:
            frameBuf[frameIdx++] = b;
            payLen = b;
            if (payLen > 12) { st = ST_HEAD0; break; }   /* 长度不合法：丢弃 */
            st = ST_DATA;
            break;

        case ST_DATA:
            frameBuf[frameIdx++] = b;
            if (frameIdx >= (uint16_t)(4 + payLen)) { st = ST_CRC0; }
            break;

        case ST_CRC0:
            frameBuf[frameIdx++] = b;
            crcRx  = b;                        /* 低字节 */
            st = ST_CRC1;
            break;

        case ST_CRC1:
            frameBuf[frameIdx++] = b;
            crcRx |= ((uint16_t)b << 8);       /* 高字节 */
            st = ST_TAIL0;
            break;

        case ST_TAIL0:
            frameBuf[frameIdx++] = b;
            st = (b == 0x55) ? ST_TAIL1 : ST_HEAD0;
            break;

        case ST_TAIL1:
            frameBuf[frameIdx++] = b;
            st = ST_HEAD0;                     /* 无论对错都回起点 */
