 * ------------------------------------------------------------
 *  1 格时间 = (Prescaler + 1) / 定时器时钟
 *      84MHz + Prescaler=83  ->  84MHz/84 = 1MHz  ->  1 格 = 1us
 *
 *  量程 = (Period + 1) x 1 格
 *      Period=65535 -> 65536us ≈ 65.5ms（超过就要累加溢出次数）
 * ============================================================ */
#define IC_PRESCALER   83          /* 1MHz 计数时钟 -> 1 格 = 1us */

/* ---------- 捕获结果（volatile：中断写、主循环读） ---------- */
static volatile uint32_t capRise   = 0;   /* 上升沿时刻 */
static volatile uint32_t capFall   = 0;   /* 下降沿时刻 */
static volatile uint32_t highUs    = 0;   /* 高电平时间(us) */
static volatile uint32_t periodUs  = 0;   /* 完整周期(us) */
static volatile uint8_t  capState  = 0;   /* 0=等上升沿 1=等下降沿 */
static volatile uint8_t  dataReady = 0;   /* 主循环处理标志 */
/* 溢出累加：测长脉冲（>65.5ms）时必须靠它 */
static volatile uint32_t overflowCnt = 0;

/* ============================================================
 *  1~6. 初始化
 * ============================================================ */
void ic_init(void)
{
    GPIO_InitTypeDef        g;
    TIM_TimeBaseInitTypeDef t;
    TIM_ICInitTypeDef       ic;

    /* ---- 1. 开时钟：GPIO + 定时器 ---- */
    RCC_AHB1PeriphClockCmd(RCC_AHB1Periph_GPIOA, ENABLE);
    RCC_APB1PeriphClockCmd(RCC_APB1Periph_TIM2, ENABLE);   /* TIM2 在 APB1 */

    /* ---- 2. 引脚复用为 TIM2_CH1 ---- */
    GPIO_PinAFConfig(GPIOA, GPIO_PinSource0, GPIO_AF_TIM2);
    g.GPIO_Pin   = GPIO_Pin_0;
    g.GPIO_Mode  = GPIO_Mode_AF;          /* 复用模式 */
    g.GPIO_OType = GPIO_OType_PP;
    g.GPIO_Speed = GPIO_Speed_100MHz;
    g.GPIO_PuPd  = GPIO_PuPd_DOWN;        /* 空闲低电平，等上升沿 */
    GPIO_Init(GPIOA, &g);

    /* ---- 3. 时基：定分辨率与量程 ---- */
    t.TIM_Prescaler         = IC_PRESCALER;   /* 1MHz -> 1 格 = 1us */
    t.TIM_Period            = 65535;          /* 最大量程 65.5ms */
    t.TIM_CounterMode       = TIM_CounterMode_Up;
    t.TIM_ClockDivision     = TIM_CKD_DIV1;
    t.TIM_RepetitionCounter = 0;
    TIM_TimeBaseInit(TIM2, &t);

    /* ---- 4. 捕获通道：先捕上升沿 ---- */
    ic.TIM_Channel     = TIM_Channel_1;
    ic.TIM_ICPolarity  = TIM_ICPolarity_Rising;
    ic.TIM_ICSelection = TIM_ICSelection_DirectTI;   /* 通道直连 */
    ic.TIM_ICPrescaler = TIM_ICPSC_DIV1;             /* 每个边沿都捕 */
    ic.TIM_ICFilter    = 0x0;                        /* 信号毛刺多就加大 */
    TIM_ICInit(TIM2, &ic);

    /* ---- 5. 开捕获中断 + 更新中断（更新中断用于累加溢出） ---- */
    TIM_ITConfig(TIM2, TIM_IT_CC1, ENABLE);
    TIM_ITConfig(TIM2, TIM_IT_Update, ENABLE);
    NVIC_EnableIRQ(TIM2_IRQn);

    /* ---- 6. 启动计数 ---- */
    TIM_Cmd(TIM2, ENABLE);
}

/* ============================================================
 *  7. 中断：上升沿记起点 -> 切下降沿 -> 记终点算高电平
 * ============================================================ */
void TIM2_IRQHandler(void)
{
    /* === 溢出：累加计数，处理长脉冲 === */
    if (TIM_GetITStatus(TIM2, TIM_IT_Update) != RESET)
    {
        TIM_ClearITPendingBit(TIM2, TIM_IT_Update);
        overflowCnt++;
    }

    /* === 捕获事件 === */
    if (TIM_GetITStatus(TIM2, TIM_IT_CC1) != RESET)
    {
        TIM_ClearITPendingBit(TIM2, TIM_IT_CC1);

        if (capState == 0)
        {
            /* 捕到上升沿：记起点，改成等下降沿 */
            capRise   = TIM_GetCapture1(TIM2);
            overflowCnt = 0;                       /* 重新计溢出 */
            capState  = 1;
            TIM_OC1PolarityConfig(TIM2, TIM_ICPolarity_Falling);
        }
        else
        {
            /* 捕到下降沿：算高电平时间 */
            uint32_t ov = overflowCnt;

            capFall = TIM_GetCapture1(TIM2);

            /* 高电平时间 = 溢出圈数 x 65536 + 本次差值 */
            highUs = ov * 65536u + (capFall - capRise);

            capState  = 0;
            dataReady = 1;
            TIM_OC1PolarityConfig(TIM2, TIM_ICPolarity_Rising);
        }
    }
}

