/* ============================================================
 *  SPI1 主机 + W25QXX Flash 完整可用代码 *   按「SPI 主机引导」10 步搭出来的成品
 *  平台：STM32F407 · SPI1(PA5/PA6/PA7) · CS=PA4(软件)
 * ============================================================ */
#include "stm32f4xx.h"

#define CS_LOW()   GPIO_ResetBits(GPIOA, GPIO_Pin_4)
#define CS_HIGH()  GPIO_SetBits(GPIOA, GPIO_Pin_4)

/* ---------- 1~4 步：初始化 ---------- */
void SPI1_Init_Mode0(void)
{
    GPIO_InitTypeDef g;
    SPI_InitTypeDef  s;

    RCC_AHB1PeriphClockCmd(RCC_AHB1Periph_GPIOA, ENABLE);
    RCC_APB2PeriphClockCmd(RCC_APB2Periph_SPI1,  ENABLE);

    GPIO_PinAFConfig(GPIOA, GPIO_PinSource5, GPIO_AF_SPI1);
    GPIO_PinAFConfig(GPIOA, GPIO_PinSource6, GPIO_AF_SPI1);
    GPIO_PinAFConfig(GPIOA, GPIO_PinSource7, GPIO_AF_SPI1);

    g.GPIO_Pin   = GPIO_Pin_5 | GPIO_Pin_6 | GPIO_Pin_7;
    g.GPIO_Mode  = GPIO_Mode_AF;
    g.GPIO_OType = GPIO_OType_PP;
    g.GPIO_Speed = GPIO_Speed_100MHz;
    g.GPIO_PuPd  = GPIO_PuPd_UP;
    GPIO_Init(GPIOA, &g);

    g.GPIO_Pin  = GPIO_Pin_4;              /* CS 普通输出 */
    g.GPIO_Mode = GPIO_Mode_OUT;
    GPIO_Init(GPIOA, &g);
    CS_HIGH();

    s.SPI_Direction         = SPI_Direction_2Lines_FullDuplex;
    s.SPI_Mode              = SPI_Mode_Master;
    s.SPI_DataSize          = SPI_DataSize_8b;
    s.SPI_CPOL              = SPI_CPOL_Low;
    s.SPI_CPHA              = SPI_CPHA_1Edge;
    s.SPI_NSS               = SPI_NSS_Soft;
    s.SPI_BaudRatePrescaler = SPI_BaudRatePrescaler_8;
    s.SPI_FirstBit          = SPI_FirstBit_MSB;
    s.SPI_CRCPolynomial     = 7;
    SPI_Init(SPI1, &s);
    SPI_Cmd(SPI1, ENABLE);
}

/* ---------- 5 步：收发一个字节（带超时，不会死等） ---------- */
uint8_t SPI1_Byte(uint8_t tx)
{
    uint32_t to = 200000;
    while (SPI_I2S_GetFlagStatus(SPI1, SPI_I2S_FLAG_TXE) == RESET) { if (to-- == 0) return 0xFF; }
    SPI_I2S_SendData(SPI1, tx);
    to = 200000;
    while (SPI_I2S_GetFlagStatus(SPI1, SPI_I2S_FLAG_RXNE) == RESET) { if (to-- == 0) return 0xFF; }
    return (uint8_t)SPI_I2S_ReceiveData(SPI1);
}

/* ---------- 6~7 步：读 JEDEC ID（W25Q128 = 0xC84018） ---------- */
uint32_t W25XX_ReadID(void)
{
    uint32_t id;
    CS_LOW();
    (void)SPI1_Byte(0x9F);
    id  = (uint32_t)SPI1_Byte(0xFF) << 16;
    id |= (uint32_t)SPI1_Byte(0xFF) << 8;
    id |= (uint32_t)SPI1_Byte(0xFF);
    CS_HIGH();
    return id;
}

/* ---------- 8~9 步：等忙 + 页写 ---------- */
static uint8_t W25XX_ReadStatus(void)
{
    uint8_t st;
    CS_LOW();
    (void)SPI1_Byte(0x05);
    st = SPI1_Byte(0xFF);
    CS_HIGH();
    return st;
}

static void W25XX_WaitBusy(void)
{
    while ((W25XX_ReadStatus() & 0x01) != 0) { }   /* bit0 = BUSY */
}

static void W25XX_WriteEnable(void)
{
    CS_LOW();
    (void)SPI1_Byte(0x06);
    CS_HIGH();
}

void W25XX_WritePage(const uint8_t *src, uint32_t addr, uint16_t len)
{
    uint16_t i;
    if (len > 256) len = 256;

    W25XX_WaitBusy();
    W25XX_WriteEnable();

    CS_LOW();
    (void)SPI1_Byte(0x02);                    /* PAGE PROGRAM */
    (void)SPI1_Byte((uint8_t)(addr >> 16));
    (void)SPI1_Byte((uint8_t)(addr >> 8));
    (void)SPI1_Byte((uint8_t)(addr));
    for (i = 0; i < len; i++) { (void)SPI1_Byte(src[i]); }
    CS_HIGH();

    W25XX_WaitBusy();
}

/* ---------- 擦一个 4KB 扇区 ---------- */
void W25XX_EraseSector(uint32_t addr)
{
    W25XX_WaitBusy();
    W25XX_WriteEnable();
    CS_LOW();
    (void)SPI1_Byte(0x20);                    /* SECTOR ERASE 4KB */
    (void)SPI1_Byte((uint8_t)(addr >> 16));
    (void)SPI1_Byte((uint8_t)(addr >> 8));
    (void)SPI1_Byte((uint8_t)(addr));
    CS_HIGH();
    W25XX_WaitBusy();
}

/* ---------- 自检：读 ID → 擦 → 写 → 读回比对 ---------- */
int SPI_Flash_SelfTest(void)
{
    uint32_t id;
    uint8_t  wr[8] = { 0xA5, 0x5A, 0x12, 0x34, 0x56, 0x78, 0x9A, 0xBC };
    uint8_t  rd[8] = { 0 };
    uint8_t  i;
    uint32_t addr = 0x001000;                 /* 用日志区之外的一页 */

    SPI1_Init_Mode0();

    id = W25XX_ReadID();
    if (id == 0xFFFFFFFF || id == 0x00000000) return 1;   /* 没器件 */
    if ((id & 0xFF) != 0x18)                  return 2;   /* 容量不是 128Mbit */

    W25XX_EraseSector(addr & ~0xFFF);
    W25XX_WritePage(wr, addr, sizeof(wr));

    CS_LOW();
    (void)SPI1_Byte(0x03);                    /* READ DATA */
    (void)SPI1_Byte((uint8_t)(addr >> 16));
    (void)SPI1_Byte((uint8_t)(addr >> 8));
    (void)SPI1_Byte((uint8_t)(addr));
    for (i = 0; i < sizeof(rd); i++) { rd[i] = SPI1_Byte(0xFF); }
    CS_HIGH();

    for (i = 0; i < sizeof(rd); i++)
    {
        if (rd[i] != wr[i]) return 3;         /* 写进去读回来不一致 */
    }
    return 0;                                 /* 0 = SPI 与 Flash 全通 */
}

