    RCC_AHB1PeriphClockCmd(RCC_AHB1Periph_GPIOA, ENABLE);

    /* ③ 要上 DMA 时（SPI1 固定映射到 DMA2）：
     *    RCC_AHB1PeriphClockCmd(RCC_AHB1Periph_DMA2, ENABLE);
     *    SPI1_TX = DMA2_Stream3 / 通道3
     *    SPI1_RX = DMA2_Stream0 / 通道3
     */
}

/* 板1 用 PB3/PB4/PB5 的版本：
 *    RCC_AHB1PeriphClockCmd(RCC_AHB1Periph_GPIOB, ENABLE);
 *    RCC_AHB1PeriphClockCmd(RCC_AHB1Periph_GPIOA | RCC_AHB1Periph_GPIOB, ENABLE);
 */

void SPI1_PinInit(void)
{
    GPIO_InitTypeDef g;

    /* 板1 必做：PB3=JTDO、PB4=NJTRST 默认被 JTAG 占用。
     *   解开后 JTAG 只剩 SWD（PB3/PB4 不再是调试口，SWD 仍可用）。
     *   板2 用 PA5/6/7 没有这个问题，这两行可以注释掉。
     */
    GPIO_PinRemapConfig(GPIO_Remap_SWJ_JTAGDisable, ENABLE);

    /* ---- ① SCK/MISO/MOSI：复用推挽 ---- */
    GPIO_PinAFConfig(GPIOA, GPIO_PinSource5, GPIO_AF_SPI1);   /* SCK  */
    GPIO_PinAFConfig(GPIOA, GPIO_PinSource6, GPIO_AF_SPI1);   /* MISO */
    GPIO_PinAFConfig(GPIOA, GPIO_PinSource7, GPIO_AF_SPI1);   /* MOSI */

    g.GPIO_Pin   = GPIO_Pin_5 | GPIO_Pin_6 | GPIO_Pin_7;
    g.GPIO_Mode  = GPIO_Mode_AF;         /* 复用 */
    g.GPIO_OType = GPIO_OType_PP;        /* 推挽，绝不能是 OD */
    g.GPIO_Speed = GPIO_Speed_100MHz;    /* 高速档 */
    g.GPIO_PuPd  = GPIO_PuPd_UP;
    GPIO_Init(GPIOA, &g);

    /* ---- ② CS：普通推挽输出，空闲拉高 ---- */
    g.GPIO_Pin   = GPIO_Pin_4;
    g.GPIO_Mode  = GPIO_Mode_OUT;        /* 不是 AF。软件控制 */
    g.GPIO_OType = GPIO_OType_PP;
    g.GPIO_Speed = GPIO_Speed_100MHz;
    g.GPIO_PuPd  = GPIO_PuPd_UP;
    GPIO_Init(GPIOA, &g);
    GPIO_SetBits(GPIOA, GPIO_Pin_4);     /* CS 空闲必须是高 */
}

void SPI1_ModeInit(void)
{
    SPI_InitTypeDef s;

    /* 模式 0：CPOL=Low + CPHA=1Edge，W25QXX / NRF24L01 / XPT2046 都用它 */
    s.SPI_Direction         = SPI_Direction_2Lines_FullDuplex;
    s.SPI_Mode              = SPI_Mode_Master;
    s.SPI_DataSize          = SPI_DataSize_8b;
    s.SPI_CPOL              = SPI_CPOL_Low;      /* 空闲时 SCK = 低 */
    s.SPI_CPHA              = SPI_CPHA_1Edge;    /* 第 1 个边沿采样 */
    s.SPI_NSS               = SPI_NSS_Soft;      /* 软件 CS（推荐） */
    s.SPI_BaudRatePrescaler = SPI_BaudRatePrescaler_8;   /* 84MHz/8 = 10.5MHz */
    s.SPI_FirstBit          = SPI_FirstBit_MSB;  /* Flash 必须 MSB 在前 */
    s.SPI_CRCPolynomial     = 7;                 /* 不用硬件 CRC，填 7 即可 */
    SPI_Init(SPI1, &s);

    SPI_Cmd(SPI1, ENABLE);        /* 必须在 SPI_Init 之后 */
}

/* 各模式的对照（拿不准就抄“模式 0”）：
 *   模式 0: CPOL_Low  + CPHA_1Edge    ← 最常用
 *   模式 1: CPOL_Low  + CPHA_2Edge
 *   模式 2: CPOL_High + CPHA_1Edge
 *   模式 3: CPOL_High + CPHA_2Edge
 */

/* 带超时的版本（推荐）：从机没接好也不会把程序卡死 */
uint8_t SPI1_TransferByte(uint8_t tx)
{
    uint32_t to;

    /* ① 等发送缓冲空 */
    to = 200000;
    while (SPI_I2S_GetFlagStatus(SPI1, SPI_I2S_FLAG_TXE) == RESET)
    {
        if (to-- == 0) { return 0xFF; }       /* 超时：SPI 时钟没开或 SPE=0 */
    }
    SPI_I2S_SendData(SPI1, tx);

    /* ② 等接收缓冲非空 */
    to = 200000;
    while (SPI_I2S_GetFlagStatus(SPI1, SPI_I2S_FLAG_RXNE) == RESET)
    {
        if (to-- == 0) { return 0xFF; }
    }
    return (uint8_t)SPI_I2S_ReceiveData(SPI1);
}

/* 关键认知：这个函数“发一个字节”的同时就“收了一个字节”。
 *   读 Flash 数据时那些 SPI1_TransferByte(0xFF)：
 *       并非“给 Flash 写 0xFF”，而是“给 8 个时钟，读 8 位”。
 *
 * 本项目 FWLIB 的实现就是这个（sys_spi.c 的 SYS_SPI_TransferByte），
 *   并且内部还累加 SYS_SPI_TimeoutCount()，出问题时可以直接读这个计数。
 */

static uint8_t W25XX_ReadStatus(void)
{
    uint8_t st;
    GPIO_ResetBits(GPIOA, GPIO_Pin_4);
    (void)SPI1_TransferByte(0x05);             /* READ STATUS REGISTER 1 */
    st = SPI1_TransferByte(0xFF);
    GPIO_SetBits(GPIOA, GPIO_Pin_4);
    return st;
}

/* 等它忙完，带超时，芯片坏了也不会死等 */
static uint8_t W25XX_WaitBusy(void)
{
    uint32_t to = 300000;                      /* 约 300ms 上限 */
    while ((W25XX_ReadStatus() & 0x01) != 0)   /* bit0 = BUSY */
    {
        if (to-- == 0) { return 1; }           /* 超时 */
    }
    return 0;
}

/* WRITE ENABLE：只发一个命令字节，没有参数、没有返回 */
static void W25XX_WriteEnable(void)
{
    GPIO_ResetBits(GPIOA, GPIO_Pin_4);
    (void)SPI1_TransferByte(0x06);
    GPIO_SetBits(GPIOA, GPIO_Pin_4);
}

/* 更稳的写法：发完 WREN 回头确认 WEL 真的置上了。
 *   为什么要确认：如果芯片还在忙、或 CS 时序被打断，WREN 会被静默忽略，
 *   接着发的页写/擦除命令也会被忽略，现象是“写函数返回成功，读回来还是 0xFF”。
 */
static uint8_t W25XX_WriteEnableChecked(void)
{
    W25XX_WriteEnable();
    if ((W25XX_ReadStatus() & 0x02) != 0) { return 0; }   /* bit1 = WEL */
    W25XX_WriteEnable();                                  /* 再给一次机会 */
    if ((W25XX_ReadStatus() & 0x02) != 0) { return 0; }
    return 1;                                             /* 没置上 → 别发写命令 */
}

uint8_t W25QXX_Write(const uint8_t *src, uint32_t addr, uint32_t len)
{
    uint32_t done = 0;

    if (src == 0 || len == 0) { return 1; }

    while (done < len)
    {
        /* 本次最多能写多少：不能跨 256 字节页边界 */
        uint16_t in_page = (uint16_t)(256 - ((addr + done) & 0xFF));
        uint16_t n = (uint16_t)((len - done) > in_page ? in_page : (len - done));
        uint16_t i;

        /* ① 写使能（每页都要重新发。并确认 WEL 置位） */
        if (W25XX_WriteEnableChecked() != 0) { return 3; }

        /* ② 页写命令 0x02 + 24 位地址 + 数据 */
        GPIO_ResetBits(GPIOA, GPIO_Pin_4);
        (void)SPI1_TransferByte(0x02);                 /* PAGE PROGRAM */
        (void)SPI1_TransferByte((uint8_t)((addr + done) >> 16));
        (void)SPI1_TransferByte((uint8_t)((addr + done) >> 8));
        (void)SPI1_TransferByte((uint8_t)((addr + done)));
        for (i = 0; i < n; i++) { (void)SPI1_TransferByte(src[done + i]); }
        GPIO_SetBits(GPIOA, GPIO_Pin_4);     /* CS 拉高才真正开始写。 */

        /* ③ 等它忙完（典型 0.4ms/页） */
        if (W25XX_WaitBusy() != 0) { return 2; }

        done += n;
    }
    return 0;
}

/* 只写得出 1→0：如果目标区域之前写过（不是 0xFF），必须先擦除整扇区。
 *   擦除后读回来应是全 0xFF。读回验证：
 *       W25QXX_Read(buf, addr, len);   // 应该等于刚写的内容
 */

uint8_t W25QXX_EraseSector(uint32_t addr)
{
    /* ① 对齐校验：给非对齐地址芯片会擦掉整个扇区，必须拦住 */
    if ((addr & 0x0FFF) != 0) { return 1; }
    if (addr >= (16UL * 1024UL * 1024UL)) { return 1; }

    /* ② 写使能并确认 WEL（否则擦除命令被静默忽略） */
    if (W25XX_WriteEnableChecked() != 0) { return 3; }

    /* ③ 发命令前确认不忙 */
    if (W25XX_WaitBusy() != 0) { return 2; }

    GPIO_ResetBits(GPIOA, GPIO_Pin_4);
    (void)SPI1_TransferByte(0x20);                      /* SECTOR ERASE 4KB */
    (void)SPI1_TransferByte((uint8_t)(addr >> 16));
    (void)SPI1_TransferByte((uint8_t)(addr >> 8));
    (void)SPI1_TransferByte((uint8_t)(addr));
    GPIO_SetBits(GPIOA, GPIO_Pin_4);

    /* ④ 擦除很慢：典型 45ms，最坏 400ms。这段时间 CPU 是死等的，
     *    调用前建议先喂狗，并放在低优先级任务里。
     */
    return W25XX_WaitBusy();
}

/* ---- 判断一段区域是不是空的（应为全 0xFF） ---- */
uint8_t W25QXX_IsBlank(uint32_t addr, uint32_t len)
{
    uint8_t buf[32];
    while (len > 0)
    {
        uint32_t n = (len > sizeof(buf)) ? (uint32_t)sizeof(buf) : len;
        uint32_t i;
        /* 读一块判一块 */
        /* W25QXX_Read(buf, addr, n); */
        for (i = 0; i < n; i++) { if (buf[i] != 0xFF) { return 0; } }
        addr += n;  len -= n;
    }
    return 1;
}

/* ---- ① 分区规划（写进头文件，别散落在各处） ---- */
#define FLASH_PARAM_ADDR     0x000000UL          /* 参数区：扇区 0~0 */
#define FLASH_LOG_ADDR       0x001000UL          /* 日志区：从扇区 1 开始 */
#define FLASH_LOG_SECTORS    16UL                /* 独占 16 个扇区 = 64KB */
#define FLASH_SECTOR_SIZE    4096UL
#define FLASH_PAGE_SIZE      256UL
#define FLASH_SLOT_SIZE      64UL                /* 每条日志占 64 字节 */
#define FLASH_LOG_CAPACITY   ((FLASH_LOG_SECTORS * FLASH_SECTOR_SIZE) / FLASH_SLOT_SIZE)  /* 1024 条 */

/* ---- ② 用互斥量包住“一整次操作”（FreeRTOS 下） ---- */
#include "FreeRTOS.h"
#include "semphr.h"

static SemaphoreHandle_t s_spi_mutex = NULL;

static void spi_lock_init(void)
{
    s_spi_mutex = xSemaphoreCreateMutex();
}

/* 整条记录写入：拿锁 → 写 → 放锁。锁的范围要盖住 CS 拉低到拉高的全过程 */
uint8_t log_write_safe(uint32_t ts, const uint8_t *data, uint16_t len)
{
    uint8_t ret;

    if (s_spi_mutex != NULL) { (void)xSemaphoreTake(s_spi_mutex, portMAX_DELAY); }

    /* ……这里做真正的 Flash 写（擦扇区判断、页写、写状态字）…… */
    ret = 0;

    if (s_spi_mutex != NULL) { (void)xSemaphoreGive(s_spi_mutex); }
    return ret;
}

/* ---- ③ 溢出计数：丢了数据要让上层知道 ---- */
static uint16_t s_lost = 0;

/* 环形缓冲回绕、不得不擦掉未补传记录时：s_lost++ */
uint16_t log_lost_count(void)
{
    return s_lost;    /* 只要 >0，就说明缓存已经在丢数据：断网太久或补传太慢 */
}

