/* ============================================================
 *  定时器输出比较（OC）三种典型用法 *   按「定时器输出比较 OC 引导」搭出来的成品
 *  平台：STM32F407 · TIM3(等间隔中断) / TIM2(单脉冲 + 模式切换)
 * ============================================================ */
#include "stm32f4xx.h"

static volatile uint32_t g_tick_100us = 0;

/* ---------- 用法 A：纯定时中断（引脚不动） ---------- */
void OC_Timing_Init_100us(void)
{
    TIM_TimeBaseInitTypeDef tb;
    TIM_OCInitTypeDef       oc;
    NVIC_InitTypeDef        ni;

    RCC_APB1PeriphClockCmd(RCC_APB1Periph_TIM3, ENABLE);

    tb.TIM_Prescaler         = 84 - 1;      /* 84MHz/84 = 1MHz = 1µs */
    tb.TIM_CounterMode       = TIM_CounterMode_Up;
    tb.TIM_Period            = 100 - 1;     /* 100µs 一个周期 */
    tb.TIM_ClockDivision     = TIM_CKD_DIV1;
    tb.TIM_RepetitionCounter = 0;
    TIM_TimeBaseInit(TIM3, &tb);

    oc.TIM_OCMode      = TIM_OCMode_Timing;          /* 只置标志，不碰引脚 */
    oc.TIM_OutputState = TIM_OutputState_Disable;    /* 引脚输出关掉 */
    oc.TIM_Pulse       = 50;                         /* 周期中点触发 */
    oc.TIM_OCPolarity  = TIM_OCPolarity_High;
    TIM_OC1Init(TIM3, &oc);

    TIM_ITConfig(TIM3, TIM_IT_CC1, ENABLE);

    ni.NVIC_IRQChannel                   = TIM3_IRQn;
    ni.NVIC_IRQChannelPreemptionPriority = 5;        /* FreeRTOS 红线 ≥5 */
    ni.NVIC_IRQChannelSubPriority        = 0;
    ni.NVIC_IRQChannelCmd                = ENABLE;
    NVIC_Init(&ni);

    TIM_Cmd(TIM3, ENABLE);
}

/* 通用定时器：所有通道共用一个中断函数 */
void TIM3_IRQHandler(void)
{
    if (TIM_GetITStatus(TIM3, TIM_IT_CC1) != RESET)
    {
        TIM_ClearITPendingBit(TIM3, TIM_IT_CC1);     /* 必须清 */
        g_tick_100us++;
        TIM_SetCompare1(TIM3, (uint16_t)(TIM_GetCounter(TIM3) + 50));
    }
}

/* ---------- 用法 B：单次精确脉冲 ---------- */
void OC_OneShot_Init(void)      /* TIM2_CH1 = PA0 */
{
    GPIO_InitTypeDef        g;
    TIM_TimeBaseInitTypeDef tb;
    TIM_OCInitTypeDef       oc;

    RCC_AHB1PeriphClockCmd(RCC_AHB1Periph_GPIOA, ENABLE);
    RCC_APB1PeriphClockCmd(RCC_APB1Periph_TIM2,  ENABLE);

    GPIO_PinAFConfig(GPIOA, GPIO_PinSource0, GPIO_AF_TIM2);
    g.GPIO_Pin   = GPIO_Pin_0;
    g.GPIO_Mode  = GPIO_Mode_AF;
    g.GPIO_OType = GPIO_OType_PP;
    g.GPIO_Speed = GPIO_Speed_100MHz;
    g.GPIO_PuPd  = GPIO_PuPd_UP;
    GPIO_Init(GPIOA, &g);

    tb.TIM_Prescaler         = 84 - 1;      /* 1µs */
    tb.TIM_CounterMode       = TIM_CounterMode_Up;
    tb.TIM_Period            = 0xFFFF;
    tb.TIM_ClockDivision     = TIM_CKD_DIV1;
    tb.TIM_RepetitionCounter = 0;
    TIM_TimeBaseInit(TIM2, &tb);

    oc.TIM_OCMode      = TIM_OCMode_Active;          /* 到 CCR 引脚变高 */
    oc.TIM_OutputState = TIM_OutputState_Enable;
    oc.TIM_Pulse       = 10;
    oc.TIM_OCPolarity  = TIM_OCPolarity_High;
    TIM_OC1Init(TIM2, &oc);
    TIM_OC1PreloadConfig(TIM2, TIM_OCPreload_Disable);   /* 运行期改 CCR 立即生效 */

    TIM_Cmd(TIM2, ENABLE);
}

void Pulse_Once(uint16_t width_us)
{
    TIM_SetCounter(TIM2, 0);
    TIM_SetCompare1(TIM2, width_us);
    TIM_Cmd(TIM2, ENABLE);
    while (TIM_GetCounter(TIM2) < width_us) { }
    TIM_Cmd(TIM2, DISABLE);
    TIM_SetCounter(TIM2, 0);
    GPIO_ResetBits(GPIOA, GPIO_Pin_0);
}

/* ---------- 用法 C：运行期切换模式 / 强制输出 ---------- */
void OC_SwitchDemo(void)
{
    TIM_SelectOCxM(TIM2, TIM_Channel_1, TIM_OCMode_Toggle);   /* 运行期改模式用这个 */
    TIM_CCxCmd(TIM2, TIM_Channel_1, TIM_CCx_Enable);

    TIM_ForcedOC1Config(TIM2, TIM_ForcedAction_Active);       /* 立刻高 */
    TIM_ForcedOC1Config(TIM2, TIM_ForcedAction_Inactive);     /* 立刻低 */
}

/* 本项目 FWLIB：sys_tim.c 有 SYS_TIM_* 封装（PWM 通道 + 频率调整），
 *   但输出比较/单脉冲的清封还没做，要用就照本卡加，
 *    NVIC 优先级 ≥5，且中断函数名别和库里 __weak 的撞。
 */

