void OC_TimeBase_Config(void)
{
    TIM_TimeBaseInitTypeDef tb;

    /* TIM2~5 挂在 APB1 上，但时钟是 APB1 的 2 倍。
     *   本项目 APB1 = 42MHz → TIM2~5 的时钟 = 84MHz
     *   （TIM1/TIM8 在 APB2 上，时钟 = 168MHz） */

    tb.TIM_Prescaler         = 84 - 1;      /* 84MHz / 84 = 1MHz → 1 tick = 1µs */
    tb.TIM_CounterMode       = TIM_CounterMode_Up;
    tb.TIM_Period            = 100 - 1;     /* 数 100 个 tick = 100µs 溢出一次 */
    tb.TIM_ClockDivision     = TIM_CKD_DIV1;/* 仅影响数字滤波器采样，与计数无关 */
    tb.TIM_RepetitionCounter = 0;           /* 只有高级定时器 TIM1/8 用得到 */
    TIM_TimeBaseInit(TIM3, &tb);

    /* 运行期改 ARR 要开影子寄存器预装载，否则改动可能在本周期中途生效 */
    TIM_ARRPreloadConfig(TIM3, ENABLE);
}

/* 算周期的小抄：周期(µs) = (PSC+1) * (ARR+1) / TIMxCLK(MHz)
 *   要 1ms @84MHz：PSC=83, ARR=999
 *   要 10ms @84MHz：PSC=839, ARR=999
 *   要 1s   @84MHz：PSC=8399, ARR=9999
 */

void OC_Channel_Config(void)
{
    TIM_OCInitTypeDef oc;

    /* ===== 用法 A：纯定时（引脚不动） ===== */
    oc.TIM_OCMode      = TIM_OCMode_Timing;
    oc.TIM_OutputState = TIM_OutputState_Disable;    /* 引脚断开 */
    oc.TIM_Pulse       = 50;                         /* 第一次比较点 */
    oc.TIM_OCPolarity  = TIM_OCPolarity_High;
    TIM_OC1Init(TIM3, &oc);

    /* ===== 用法 B：单脉冲（到点翻转引脚） ===== */
    oc.TIM_OCMode      = TIM_OCMode_Toggle;
    oc.TIM_OutputState = TIM_OutputState_Enable;     /* 引脚接上 */
    oc.TIM_Pulse       = 100;
    oc.TIM_OCPolarity  = TIM_OCPolarity_High;        /* Toggle 模式下无实际意义 */
    TIM_OC1Init(TIM2, &oc);

    /* 预装载的意义：
     *   ENABLE  → 新写的 CCR 在下一个更新事件才生效（波形不抖，适合连续调占空比）
     *   DISABLE → 新写的 CCR 立即生效（适合单脉冲这种一次性动作）
     */
    TIM_OC1PreloadConfig(TIM2, TIM_OCPreload_Disable);

    /* 运行期想改模式，只能用这个函数（不要改结构体再 Init）：
     *   TIM_SelectOCxM(TIM2, TIM_Channel_1, TIM_OCMode_Timing);
     */
}

/* 高级定时器 TIM1/TIM8 额外一步：不开主输出引脚没波形
 *   TIM_CtrlPWMOutputs(TIM1, ENABLE);
 *   通用定时器 TIM2~5 不需要这一步。
 */

void OC_IT_Config(void)
{
    NVIC_InitTypeDef ni;

    /* ① 打开通道 1 的比较中断 */
    TIM_ITConfig(TIM3, TIM_IT_CC1, ENABLE);

    /* ② NVIC：数值必须 ≥ configLIBRARY_MAX_SYSCALL_INTERRUPT_PRIORITY(5) */
    ni.NVIC_IRQChannel                   = TIM3_IRQn;
    ni.NVIC_IRQChannelPreemptionPriority = 5;
    ni.NVIC_IRQChannelSubPriority        = 0;
    ni.NVIC_IRQChannelCmd                = ENABLE;
    NVIC_Init(&ni);

    TIM_Cmd(TIM3, ENABLE);
}

/* 通用定时器：一个定时器只有一个中断入口，所有通道都在这里处理 */
void TIM3_IRQHandler(void)
{
    /* 第一件事永远是判断 + 清标志 */
    if (TIM_GetITStatus(TIM3, TIM_IT_CC1) != RESET)
    {
        TIM_ClearITPendingBit(TIM3, TIM_IT_CC1);    /* 不清会反复进。 */
        g_tick_100us++;
        /* 自动重装下一次比较点：形成严格等间隔的中断 */
        TIM_SetCompare1(TIM3, (uint16_t)(TIM_GetCounter(TIM3) + 50));
    }

    /* 如果还开了通道 2，在这里继续判 */
    if (TIM_GetITStatus(TIM3, TIM_IT_CC2) != RESET)
    {
        TIM_ClearITPendingBit(TIM3, TIM_IT_CC2);
        /* ... */
    }
}

/* 高级定时器 TIM1 的向量名不同（容易写错）：
 *   TIM1_BRK_TIM9_IRQHandler
 *   TIM1_UP_TIM10_IRQHandler      ← 更新中断在这里
 *   TIM1_TRG_COM_TIM11_IRQHandler
 *   TIM1_CC_IRQHandler            ← 捕获/比较中断在这里
 */

static volatile uint32_t g_tick_100us = 0;

void TIM3_IRQHandler(void)
{
    if (TIM_GetITStatus(TIM3, TIM_IT_CC1) != RESET)
    {
        TIM_ClearITPendingBit(TIM3, TIM_IT_CC1);

        g_tick_100us++;

        /* 关键：下一次比较点 = 当前计数 + 步长
         *   用“当前值 + step”而不是固定值，可以避免累积误差、
         *   也不会因为中断响应延迟而漏掉比较点。
         */
        TIM_SetCompare1(TIM3, (uint16_t)(TIM_GetCounter(TIM3) + 50));

        /* 在 RTOS 下：这里只置标志/发信号量 */
        /* BaseType_t hpw = pdFALSE;
