/* ============================================================
 *  DAC1 输出 0~3.3V 模拟电压，完整可用代码
 *  按「DAC 模拟电压输出引导」8 步搭出来的成品
 *  平台：STM32F407 · PA4 · VREF=3.3V · 12 位
 * ============================================================ */
#include "stm32f4xx.h"

void DAC1_Init(void)
{
    GPIO_InitTypeDef g;
    DAC_InitTypeDef  d;

    RCC_AHB1PeriphClockCmd(RCC_AHB1Periph_GPIOA, ENABLE);   /* ① 引脚时钟 */
    RCC_APB1PeriphClockCmd(RCC_APB1Periph_DAC,   ENABLE);   /* ② DAC 时钟（APB1） */

    /* ③ 引脚：必须是 GPIO_Mode_AN（模拟），不是 AF */
    g.GPIO_Pin   = GPIO_Pin_4;
    g.GPIO_Mode  = GPIO_Mode_AN;
    g.GPIO_OType = GPIO_OType_PP;
    g.GPIO_Speed = GPIO_Speed_100MHz;
    g.GPIO_PuPd  = GPIO_PuPd_NOPULL;
    GPIO_Init(GPIOA, &g);

    /* ④ 填结构体 */
    d.DAC_Trigger        = DAC_Trigger_None;         /* 软件触发 */
    d.DAC_WaveGeneration = DAC_WaveGeneration_None;  /* 不产生三角/噪声波 */
    d.DAC_LFSRUnmask_TriangleAmplitude = DAC_LFSRUnmask_Bit0;
    d.DAC_OutputBuffer   = DAC_OutputBuffer_Enable;  /* 开缓冲，带载强 */
    DAC_Init(DAC_Channel_1, &d);

    /* ⑤ 使能 + 给初值 */
    DAC_Cmd(DAC_Channel_1, ENABLE);
    DAC_SetChannel1Data(DAC_Align_12b_R, 0);
}

/* ⑥ 设置输出电压（0.0 ~ 3.3V） */
void DAC1_SetVoltage(float v)
{
    uint16_t val;

    if (v < 0.0f) { v = 0.0f; }
    if (v > 3.3f) { v = 3.3f; }

    val = (uint16_t)(v / 3.3f * 4095.0f + 0.5f);

    DAC_SetChannel1Data(DAC_Align_12b_R, val);
    DAC_SoftwareTriggerCmd(DAC_Channel_1, ENABLE);   /* 不调它输出不更新 */
}

/* ⑦ 数字量直出（0 ~ 4095），不经过浮点 */
void DAC1_SetRaw(uint16_t val)
{
    if (val > 4095) { val = 4095; }
    DAC_SetChannel1Data(DAC_Align_12b_R, val);
    DAC_SoftwareTriggerCmd(DAC_Channel_1, ENABLE);
}

/* ⑧ 扫频自检：万用表应看到电压匀速爬升 */
void DAC1_SweepTest(void)
{
    uint16_t i;
    for (i = 0; i < 4096; i += 16)
    {
        DAC1_SetRaw(i);
        delay_ms(5);
    }
}

f:
void DAC1_ClockOn(void)
{
    /* ① DAC 本体在 APB1（不是 APB2） */
    RCC_APB1PeriphClockCmd(RCC_APB1Periph_DAC, ENABLE);

    /* ② 引脚 PA4 的 GPIO 在 AHB1 */
    RCC_AHB1PeriphClockCmd(RCC_AHB1Periph_GPIOA, ENABLE);
}

/* 排查法：调试器里看 RCC->APB1ENR 的 bit29（DACEN）是否为 1。
 *   是 0 就说明这两句没跑到。
 */

void DAC1_PinInit(void)
{
    GPIO_InitTypeDef g;

    g.GPIO_Pin   = GPIO_Pin_4;            /* DAC1 固定 PA4 */
    g.GPIO_Mode  = GPIO_Mode_AN;          /* AN = 模拟，不是 AF。 */
    g.GPIO_OType = GPIO_OType_PP;         /* 模拟模式下无意义，保持默认 */
    g.GPIO_Speed = GPIO_Speed_100MHz;
    g.GPIO_PuPd  = GPIO_PuPd_NOPULL;      /* 禁止上下拉，否则输出电压被拉偏 */
    GPIO_Init(GPIOA, &g);
}

/* 对照记忆：
 *   串口/SPI/PWM 的引脚 → GPIO_Mode_AF   （走复用矩阵）
 *   DAC 的引脚          → GPIO_Mode_AN   （直连模拟端）
 *   ADC 采样的引脚      → GPIO_Mode_AN   （同一个道理）
 */

void DAC1_Enable(void)
{
    /* 先使能通道，否则后面写数据也不会有输出 */
    DAC_Cmd(DAC_Channel_1, ENABLE);

    /* 给初值：12 位右对齐，2048 ≈ 1.65V（便于万用表验证） */
    DAC_SetChannel1Data(DAC_Align_12b_R, 2048);

    /* 软件触发模式下必须触发一次，值才会真正输出 */
    DAC_SoftwareTriggerCmd(DAC_Channel_1, ENABLE);
}

/* 数据对齐方式（12 位时一律用 DAC_Align_12b_R）：
 *   DAC_Align_12b_R : val 的 bit11..0 有效        ← 推荐
 *   DAC_Align_12b_L : val 的 bit15..4 有效
 *   DAC_Align_8b_R  : val 的 bit11..4 有效（8 位精度）
 *
 * 换算：val = 电压 / 3.3f * 4095.0f
 *   0x000 → 0V       0x800 → 1.65V       0xFFF → 3.3V
 */

/* ---- 按数字量输出（0 ~ 4095）：不经过浮点，最快的路径 ---- */
void DAC1_SetRaw(uint16_t val)
{
    if (val > 4095) { val = 4095; }                     /* 限幅 */
    DAC_SetChannel1Data(DAC_Align_12b_R, val);
    DAC_SoftwareTriggerCmd(DAC_Channel_1, ENABLE);      /* 封装在这里，调用方不会再忘 */
}

/* ---- 按电压输出（0.0 ~ 3.3V） ---- */
void DAC1_SetVoltage(float v)
{
    uint16_t val;

    if (v < 0.0f) { v = 0.0f; }                         /* 限幅：负数会换算成无符号大数 */
    if (v > 3.3f) { v = 3.3f; }

    val = (uint16_t)(v / 3.3f * 4095.0f + 0.5f);        /* +0.5 才是四舍五入 */
    DAC1_SetRaw(val);
}

/* 用法：
 *   DAC1_SetVoltage(1.65f);   // 输出 1.65V
 *   DAC1_SetRaw(2048);        // 等价写法，更快
 */

/* ---- ① 预生成一个正弦表（256 点） ---- */
#define WAVE_POINTS  256
static uint16_t g_sine[WAVE_POINTS];

void Wave_Build(void)
{
    uint16_t i;
    for (i = 0; i < WAVE_POINTS; i++)
    {
        /* 0~4095 的正弦：sin 值域 -1~1 → 映射到 0~4095 */
        float s = (float)((i * 2.0 * 3.14159265) / WAVE_POINTS);
        /* 这里用查表法最简单：实际项目可直接把表写死在 Flash 里 */
        g_sine[i] = 2048;   /* 占位：真实项目用库函数算或直接用查表数组 */
        (void)s;
    }
}

/* ---- ② DMA：内存 → DAC 数据寄存器，循环搬运 ---- */
void Wave_DmaInit(void)
{
    DMA_InitTypeDef dma;

    RCC_AHB1PeriphClockCmd(RCC_AHB1Periph_DMA1, ENABLE);

    DMA_DeInit(DMA1_Stream5);                 /* DAC1 固定挂 DMA1_Stream5 / 通道7 */
    dma.DMA_Channel            = DMA_Channel_7;
    dma.DMA_PeripheralBaseAddr = (uint32_t)&DAC->DHR12R1;
    dma.DMA_Memory0BaseAddr    = (uint32_t)g_sine;
    dma.DMA_DIR                = DMA_DIR_MemoryToPeripheral;
    dma.DMA_BufferSize         = WAVE_POINTS;
    dma.DMA_PeripheralInc      = DMA_PeripheralInc_Disable;   /* 外设地址固定 */
    dma.DMA_MemoryInc          = DMA_MemoryInc_Enable;        /* 内存地址递增 */
    dma.DMA_PeripheralDataSize = DMA_PeripheralDataSize_HalfWord;  /* 16 位 */
    dma.DMA_MemoryDataSize     = DMA_MemoryDataSize_HalfWord;
    dma.DMA_Mode               = DMA_Mode_Circular;           /* 循环：永不停止 */
    dma.DMA_Priority           = DMA_Priority_High;
    dma.DMA_FIFOMode           = DMA_FIFOMode_Disable;
    dma.DMA_FIFOThreshold      = DMA_FIFOThreshold_HalfFull;
    dma.DMA_MemoryBurst        = DMA_MemoryBurst_Single;
    dma.DMA_PeripheralBurst    = DMA_PeripheralBurst_Single;
    DMA_Init(DMA1_Stream5, &dma);
}

/* ---- ③ 定时器做 TRGO，决定采样率 ---- */
void Wave_TimInit(void)
{
    TIM_TimeBaseInitTypeDef tb;

    RCC_APB1PeriphClockCmd(RCC_APB1Periph_TIM6, ENABLE);

    /* 84MHz / (0+1) / (83+1) = 1MHz → 每次更新 1µs
     * 256 点 → 一个正弦周期 256µs ≈ 3.9kHz */
    tb.TIM_Prescaler     = 0;
    tb.TIM_CounterMode   = TIM_CounterMode_Up;
    tb.TIM_Period        = 84 - 1;
    tb.TIM_ClockDivision = TIM_CKD_DIV1;
    TIM_TimeBaseInit(TIM6, &tb);

    /* 更新事件产生 TRGO，DAC 收到它就搬一个点 */
    TIM_SelectOutputTrigger(TIM6, TIM_TRGOSource_Update);
    TIM_Cmd(TIM6, ENABLE);
}

/* ---- ④ 启动 ---- */
void Wave_Start(void)
{
    DAC_InitTypeDef d;

    /* 触发源改成 TIM6 的 TRGO */
    d.DAC_Trigger        = DAC_Trigger_T6_TRGO;
    d.DAC_WaveGeneration = DAC_WaveGeneration_None;
    d.DAC_LFSRUnmask_TriangleAmplitude = DAC_LFSRUnmask_Bit0;
    d.DAC_OutputBuffer   = DAC_OutputBuffer_Enable;
    DAC_Init(DAC_Channel_1, &d);

    DAC_Cmd(DAC_Channel_1, ENABLE);
    DAC_DMACmd(DAC_Channel_1, ENABLE);        /* 不开这句 DMA 搬不动 */
    DMA_Cmd(DMA1_Stream5, ENABLE);
}

/* 常见问题：
 * 1) DMA 通道选错：DAC1 固定是 DMA1_Stream5 / 通道7（查参考手册的 DMA 请求映射表）。
 * 2) 忘了 DAC_DMACmd(ENABLE) → DMA 配得再对也搬不动。
 * 3) DMA 忘了设循环模式 → 输出一个周期就停，现象是“只响一下”。
 * 4) 数据宽度设成 Byte → 12 位数据被截成 8 位，波形台阶明显。
 */

