static volatile uint8_t  g_alarm_fired = 0;   /* 必须 volatile */
static volatile uint32_t g_wakeup_cnt  = 0;

void RTC_Alarm_IRQHandler(void)
{
    /* ---- ALARM A ---- */
    if (RTC_GetITStatus(RTC_IT_ALRA) != RESET)
    {
        RTC_ClearITPendingBit(RTC_IT_ALRA);       /* ① 清 RTC 标志 */
        EXTI_ClearITPendingBit(EXTI_Line17);      /* ② 清 EXTI 挂起位 */
        g_alarm_fired = 1;                        /* ③ 只置标志，不干活 */
    }

    /* ---- ALARM B ---- */
    if (RTC_GetITStatus(RTC_IT_ALRB) != RESET)
    {
        RTC_ClearITPendingBit(RTC_IT_ALRB);
        EXTI_ClearITPendingBit(EXTI_Line17);
    }

    /* ---- 周期唤醒 ---- */
    if (RTC_GetITStatus(RTC_IT_WUT) != RESET)
    {
        RTC_ClearITPendingBit(RTC_IT_WUT);
        EXTI_ClearITPendingBit(EXTI_Line22);      /* 唤醒走 22，不是 17 */
        g_wakeup_cnt++;
    }
}

