static uint8_t flash_check(void)
{
    uint32_t id = W25QXX_ReadID();

    if (id == 0xFFFFFFUL || id == 0x000000UL) { return 1U; }  /* 通信本身就不通 */
    if ((id & 0xFFUL) != 0x18UL)             { return 2U; }  /* 容量不是 128Mbit */

    /* 把厂商记下来，打印用，不参与判定 */
    return 0U;
}

