/* ============================================================
 *  LoRa E22-400T22S 点对点链路，完整可用代码（引导 10 步的成品）
 *  板1（检测端，发送）：DHT11 → 组 20 字节帧 → LoRa 发出
 *  板2（数据通信端，接收）：LoRa 收帧 → 三重确认解析 → 落 Flash / 转发
 *  平台：STM32F407 · E22-400T22S · 9600 8N1 · 透明传输
 * ============================================================ */
#include "stm32f4xx.h"
#include "lora_e22.h"
#include "sys_modbus.h"

#include <string.h>

/* ---------------- 1. 帧格式：20 字节，字段偏移全部宏化 ---------------- */
#define FRAME_TOTAL   20U
#define FRAME_CMD_ENV 0x01U      /* 环境数据帧 */
#define FRAME_LEN_ENV 0x0CU      /* 数据段 12 字节 */
#define FRAME_TEMP_OFF   4U
#define FRAME_HUMI_OFF   6U
#define FRAME_PRESS_OFF  8U
#define FRAME_LIGHT_OFF  10U
#define FRAME_TVOC_OFF   12U
#define FRAME_MQ135_OFF  14U
#define FRAME_CRC_OFF    16U

/*   [0][1]  AA 55           帧头
 *   [2]     命令字 0x01
 *   [3]     长度   0x0C
 *   [4..15] 数据段 12 字节，大端（高字节在前）
 *   [16][17] CRC16-MODBUS，低字节在前，范围 [2..16) 共 14 字节
 *   [18][19] 55 AA           帧尾
 *
 *   为什么必须有帧头帧尾 + CRC 三重确认：
 *     帧尾 55 AA 与下一帧帧头 AA 55 会拼成 ...55 AA AA 55...，
 *     只认帧头就会错位。本项目接收端对 [2..18) 整段再算一次 CRC，
 *     必须为 0，错位后一定不为 0，一票否决。 */

static volatile uint32_t s_tx_ok, s_tx_fail;
static volatile uint32_t s_rx_ok, s_rx_bad;

static void put_u16_be(uint8_t *p, uint16_t v)
{
    p[0] = (uint8_t)(v >> 8);
    p[1] = (uint8_t)(v & 0xFFU);
}

/* ---------------- 2. 组帧（板1） ---------------- */
static void frame_build(uint8_t *f, float temp_c, float humi_rh)
{
    uint16_t crc;

    memset(f, 0, FRAME_TOTAL);

    f[0] = 0xAAU;
    f[1] = 0x55U;
    f[2] = FRAME_CMD_ENV;
    f[3] = FRAME_LEN_ENV;

    /* 温度 int16 ×100（负数是补码：-5.00℃ → 0xFE0C）；湿度 uint16 ×100 */
    put_u16_be(&f[FRAME_TEMP_OFF], (uint16_t)(int16_t)(temp_c * 100.0f));
    put_u16_be(&f[FRAME_HUMI_OFF], (uint16_t)(humi_rh * 100.0f));
    /* 气压只能 ×10：1013.25 × 100 = 101325 已经超 uint16 上限 */
    put_u16_be(&f[FRAME_PRESS_OFF], (uint16_t)(1013.2f * 10.0f));

    /* CRC 范围 = 命令 + 长度 + 数据段 = 14 字节，不含帧头帧尾 */
    crc = SYS_MODBUS_Crc16(&f[2], 14U);
    f[FRAME_CRC_OFF]      = (uint8_t)(crc & 0xFFU);   /* 低字节在前 */
    f[FRAME_CRC_OFF + 1U] = (uint8_t)(crc >> 8);

    f[18] = 0x55U;
    f[19] = 0xAAU;
}

/* ---------------- 3. 解析（板2）：帧头 + 长度 + CRC 三重确认 ---------------- */
static uint8_t frame_parse(const uint8_t *f, uint16_t n,
                           int16_t *temp100, uint16_t *humi100)
{
    if (n != FRAME_TOTAL)                     return 0U;   /* 长度不对 */
    if ((f[0] != 0xAAU) || (f[1] != 0x55U))   return 0U;   /* 帧头不对 */
    if ((f[18] != 0x55U) || (f[19] != 0xAAU)) return 0U;   /* 帧尾不对 */
    if (f[2] != FRAME_CMD_ENV)                return 0U;   /* 命令不认识 */
    if (f[3] != FRAME_LEN_ENV)                return 0U;   /* 长度字段不对 */

    /* 第三重确认：对含 CRC 的整段再算一遍，必须为 0 */
    if (SYS_MODBUS_Crc16(&f[2], 16U) != 0U)   return 0U;

    *temp100 = (int16_t)((uint16_t)((f[FRAME_TEMP_OFF] << 8) |
                                     f[FRAME_TEMP_OFF + 1U]));
    *humi100 = (uint16_t)((f[FRAME_HUMI_OFF] << 8) | f[FRAME_HUMI_OFF + 1U]);
    return 1U;
}

/* ---------------- 4. 初始化：先摆 M0/M1，再开串口 ---------------- */
uint8_t lora_link_init(void)
{
    uint8_t r;
    char    cfg[128];

    r = LORA_E22_Init();     /* ① 摆透传 ② AUX 输入上拉 ③ 开中断接收 ④ 等就绪 */
    if (r != LORA_E22_OK) {
        return r;            /* 1 = ERR_AUX：AUX 一直低，查供电/接线/共地 */
    }

    /* 开机读一次配置：地址 / 网络ID / 信道 三项一眼可见 */
    memset(cfg, 0, sizeof(cfg));
    if (LORA_E22_ReadConfig(cfg, sizeof(cfg)) == LORA_E22_OK) {
        printf("LoRa 配置 = %s\r\n", cfg);
    }

    /* AT 连通性：能回 OK 就说明切配置模式 + 串口收发 + 波特率都通 */
    r = LORA_E22_SendAT("AT");
    if (r != LORA_E22_OK) {
        return r;            /* 2 = ERR_NO_MODULE；3 = ERR_AT_ERROR */
    }

    /* 切回透传，并确认 AUX 已空闲（不确认就可能丢第一包） */
    r = LORA_E22_SetMode(LORA_E22_MODE_TRANSPARENT);
    if (r != LORA_E22_OK) {
        return r;
    }
    if (LORA_E22_WaitReady(1000U) == 0U) {
        return LORA_E22_ERR_AUX;
    }
    return LORA_E22_OK;
}

/* ---------------- 5. 发送（板1） ---------------- */
static uint8_t lora_send_frame(const uint8_t *f)
{
    uint8_t r;

    if (SYS_MODBUS_Crc16(&f[2], 16U) != 0U) {   /* 自检：必须自洽 */
        return LORA_E22_ERR_PARAM;
    }

    r = LORA_E22_Send(f, FRAME_TOTAL);   /* 内部先等 AUX，再阻塞发完 */
    if (r == LORA_E22_OK) {
        s_tx_ok++;
    } else {
        s_tx_fail++;
    }
    return r;
}

/* ---------------- 6. 接收轮询（板2）：必须周期性调用 ---------------- */
static void lora_rx_poll(void)
{
    uint8_t  buf[64];
    uint16_t n = 0U;
    uint8_t  r;
    int16_t  t100;
    uint16_t h100;

    r = LORA_E22_Recv(buf, (uint16_t)sizeof(buf), &n);

    if (r == LORA_E22_OK) {
        if (frame_parse(buf, n, &t100, &h100) != 0U) {
            s_rx_ok++;
            printf("[接收] T=%d.%02d C H=%u.%02u RH\r\n",
                   (int)(t100 / 100), (int)((t100 < 0 ? -t100 : t100) % 100),
                   (unsigned)(h100 / 100U), (unsigned)(h100 % 100U));
            (void)xQueueSend(s_q_frame, buf, 0);   /* 满就丢，不阻塞接收 */
        } else {
            s_rx_bad++;
        }
    } else if (r == LORA_E22_ERR_OVERFLOW) {
        s_rx_bad++;                  /* 超长帧，整帧已丢弃 */
    } else if (r == LORA_E22_ERR_NO_DATA) {
        /* 不是错误，什么都不做 */
    }

    vTaskDelay(pdMS_TO_TICKS(20));   /* 20ms 远小于 2s 帧间隔，不会粘帧 */
}

