/* 观察“切模式 → AUX 拉低 → AUX 恢复高”这段时序 */
uint8_t demo_aux_timing(void)
{
    uint32_t t0;

    /* 1. 切配置模式：SetMode 内部会等 AUX 空闲后才返回 */
    if (LORA_E22_SetMode(LORA_E22_MODE_CONFIG) != LORA_E22_OK) {
        return LORA_E22_ERR_AUX;
    }

    /* 2. 此刻 AUX 应该是高的（SetMode 已经帮我们等过了） */
    if (LORA_E22_IsBusy() != 0U) {
        return LORA_E22_ERR_AUX;
    }

    /* 3. 切回透传：这一步会重新初始化射频，等待上限 1s */
    if (LORA_E22_SetMode(LORA_E22_MODE_TRANSPARENT) != LORA_E22_OK) {
        return LORA_E22_ERR_AUX;
    }

    /* 4. 再显式等一次，并量出等了多久（写业务代码时这一步别省） */
    t0 = DWT->CYCCNT;
    if (LORA_E22_WaitReady(1000U) == 0U) {
        return LORA_E22_ERR_AUX;    /* 1s 还忙：查 M0/M1/AUX 接线 */
    }
    printf("切回透传等待了 %u ms\r\n",
           (unsigned)((DWT->CYCCNT - t0) / (SystemCoreClock / 1000U)));

    return LORA_E22_OK;
}

/* ---- 自己写一遍：看清 Init 内部到底做了什么 ---- */
uint8_t my_lora_init(void)
{
    /* ① M0/M1：推挽输出。必须在开串口之前 */
    GPIO_OutInit(SYS_LORA_M0_PORT, SYS_LORA_M0_PIN);
    GPIO_OutInit(SYS_LORA_M1_PORT, SYS_LORA_M1_PIN);
    GPIO_OutWrite(SYS_LORA_M0_PORT, SYS_LORA_M0_PIN, 0U);   /* 透传 00 */
    GPIO_OutWrite(SYS_LORA_M1_PORT, SYS_LORA_M1_PIN, 0U);

    /* ② AUX：模块的输出，MCU 侧配输入上拉 */
    GPIO_InInit(SYS_LORA_AUX_PORT, SYS_LORA_AUX_PIN, GPIO_PuPd_UP);

    /* ③ 串口：中断接收。之后不要再对它做别的 DMA 配置 */
    SYS_USART_InitRxIT(SYS_LORA_UART, SYS_LORA_BAUD);
    SYS_USART_RxFlush(SYS_LORA_UART);

    /* ④ 等模块就绪：上电后它自己要初始化射频（典型十几毫秒） */
    if (LORA_E22_WaitReady(SYS_LORA_AUX_TIMEOUT_MS) == 0U) {
        return LORA_E22_ERR_AUX;        /* AUX 一直低 */
    }
    return LORA_E22_OK;
}

/* 实际项目里直接用驱动封装好的那一个就行： */
/*   uint8_t r = LORA_E22_Init();   // 重复调用是安全的（重开会重新清缓冲） */

/* 开机配置 + 读回确认：端口参数对齐的标准写法 */
static uint8_t lora_config_pair(void)
{
    char    cfg[128];
    uint8_t r;

    /* 1. 连通性先确认：AT 能回 OK，说明切模式 + 串口都通 */
    r = LORA_E22_SendAT("AT");
    if (r != LORA_E22_OK) {
        return r;   /* 2 = ERR_NO_MODULE（没接 M0M1 / 波特率不符 / TXRX 反）
                     * 3 = ERR_AT_ERROR（指令本身写错） */
    }

    /* 2. 写入空口参数。两端的这两项必须写成完全一样的值 */
    r = LORA_E22_SendAT("AT+NETID=18");
    if (r != LORA_E22_OK) {
        return r;
    }
    r = LORA_E22_SendAT("AT+ADDR=1234");
    if (r != LORA_E22_OK) {
        return r;
    }

    /* 3. 改完必须复位，新参数才会在透传模式下生效。
     *    LORA_E22_Reset() 内部发 AT+RESET，等 OK，再切回透传并等就绪。 */
    r = LORA_E22_Reset();
    if (r != LORA_E22_OK) {
        return r;
    }

    /* 4. 读回来确认，而不是“相信它改成功了”。
     *    ReadConfig 内部问 AT+VER / AT+ADDR / AT+NETID / AT+REG0，
     *    把多行折成一行（建议 out ≥ 96 字节）。 */
    memset(cfg, 0, sizeof(cfg));
    r = LORA_E22_ReadConfig(cfg, sizeof(cfg));
    if (r != LORA_E22_OK) {
        return r;   /* 2 = ERR_NO_MODULE */
    }
    printf("模块配置 = %s\r\n", cfg);

    /* 5. 切回透传，业务数据只在这个模式下收发 */
    return LORA_E22_SetMode(LORA_E22_MODE_TRANSPARENT);
}

/* ---- 组帧： CRC 低字节在前、数据段大端 ---- */
#define FRAME_TOTAL   20U
#define FRAME_CMD_ENV 0x01U
#define FRAME_LEN_ENV 0x0CU
#define FRAME_CRC_OFF 16U

static void put_u16_be(uint8_t *p, uint16_t v)
{
    p[0] = (uint8_t)(v >> 8);       /* 大端：高字节在前 */
    p[1] = (uint8_t)(v & 0xFFU);
}

static void frame_build(uint8_t *f, float temp_c, float humi_rh)
{
    uint16_t crc;

    memset(f, 0, FRAME_TOTAL);
    f[0] = 0xAAU;
    f[1] = 0x55U;
    f[2] = FRAME_CMD_ENV;
    f[3] = FRAME_LEN_ENV;

    /* 温度 int16 ×100（负数为补码）；湿度 uint16 ×100 */
    put_u16_be(&f[4], (uint16_t)(int16_t)(temp_c * 100.0f));
    put_u16_be(&f[6], (uint16_t)(humi_rh * 100.0f));

    /* CRC 范围 = 命令 + 长度 + 数据段 = 14 字节 */
    crc = SYS_MODBUS_Crc16(&f[2], 14U);
    f[FRAME_CRC_OFF]      = (uint8_t)(crc & 0xFFU);   /* 低字节在前 */
    f[FRAME_CRC_OFF + 1U] = (uint8_t)(crc >> 8);

    f[18] = 0x55U;
    f[19] = 0xAAU;
}

/* ---- 解析：六项逐一确认，任何一项不符就整帧丢弃 ---- */
static uint8_t frame_parse(const uint8_t *f, uint16_t n, int16_t *t100)
{
    if (n != FRAME_TOTAL)                       return 0U;
    if ((f[0] != 0xAAU) || (f[1] != 0x55U))     return 0U;
    if ((f[18] != 0x55U) || (f[19] != 0xAAU))   return 0U;
    if (f[2] != FRAME_CMD_ENV)                  return 0U;
    if (f[3] != FRAME_LEN_ENV)                  return 0U;
    if (SYS_MODBUS_Crc16(&f[2], 16U) != 0U)     return 0U;   /* 第三重 */

    *t100 = (int16_t)((uint16_t)((f[4] << 8) | f[5]));
    return 1U;
}

/* ---- 接收轮询：返回码必须分类处理 ---- */
void lora_rx_task(void *pv)
{
    uint8_t  buf[64];       /* ≥ 32 字节：20 字节帧 + 余量 */
    uint16_t n;
    uint8_t  r;
    int16_t  t100;

    (void)pv;
    for (;;) {
        n = 0U;
        r = LORA_E22_Recv(buf, (uint16_t)sizeof(buf), &n);

        if (r == LORA_E22_OK) {
            if (frame_parse(buf, n, &t100) != 0U) {
                s_rx_ok++;
                /* 队列满就丢，绝不阻塞：阻塞会拉长两次 Recv 的间隔，
                 *   把后面的帧粘在一起，造成连锁丢帧。 */
                (void)xQueueSend(s_q_frame, buf, 0);
            } else {
                s_rx_bad++;     /* 帧头/长度/CRC 不符，丢弃 */
            }
        } else if (r == LORA_E22_ERR_OVERFLOW) {
            s_rx_bad++;         /* 超长帧，驱动已整帧丢弃并复位状态 */
        } else if (r == LORA_E22_ERR_NO_DATA) {
            /* 不是错误：就是“这轮没收到”，下轮再来。
             *   这里刻意什么都不写，也不加计数。 */
        }

        vTaskDelay(pdMS_TO_TICKS(20));   /* 20ms << 2s 帧间隔，不会粘帧 */
    }
}

/* 监控打印：一眼看出链路是不是健康的 */
printf("[监控] LoRa: 发成功 %u / 发失败 %u | 收成功 %u / 坏帧 %u\r\n",
       (unsigned)s_tx_ok, (unsigned)s_tx_fail,
       (unsigned)s_rx_ok, (unsigned)s_rx_bad);

/* 掉线重连：丢掉半截帧再重新初始化（重复调用 Init 是安全的） */
uint8_t lora_reconnect(void)
{
    LORA_E22_Flush();               /* 丢掉半截帧与残留字节 */
    if (LORA_E22_Init() != LORA_E22_OK) {
        return LORA_E22_ERR_AUX;    /* AUX 一直低：查供电 / M0M1 / 共地 */
    }
    return LORA_E22_SetMode(LORA_E22_MODE_TRANSPARENT);
}

/* 自检 09 的骨架（两板 main.c 里就是这几句）：
 *   r = LORA_E22_Init();           打印 r（0=OK 1=AUX 一直忙 2=没模块）
 *   r = LORA_E22_ReadConfig(cfg, sizeof(cfg));   打印模块配置
 *   r = LORA_E22_SendAT("AT");     检查“切配置模式 + 串口收发”通不通
 *   r = LORA_E22_SetMode(LORA_E22_MODE_TRANSPARENT);  确认能切回透传
 *   printf(AUX = %u, LORA_E22_IsBusy());   1 = 模块忙，不能灌数据
 *
 * 排查顺序（不要跳步）：
 *   ① Init 返回 0 了吗？不是 0 就别往下查；
 *   ② 两端 地址/网络ID/信道 三项相同吗？这是收不到的头号原因；
 *   ③ SendAT 回 OK 吗？不回就是没进配置模式（M0M1 / 波特率 / TXRX 反）；
 *   ④ 空口：天线接了吗、距离多远、有遮挡吗。
 */

