/* ============================================================
 *  ⑳ ESP8266 AT + MQTT 成品程序，把引导各步合成一个能跑的骨架
 *  平台：STM32F407 · ESP8266 接 USART3（PB10/PB11）· 115200 8N1
 * ============================================================ */
#include "stm32f4xx.h"
#include "sys_usart.h"
#include "delay.h"
#include "esp8266.h"
#include "mqtt.h"

#define WIFI_SSID   "lab-wifi-2.4g"      /* 只支持 2.4GHz */
#define WIFI_PASS   "lab-pass"
#define SRV_HOST    "bemfa.com"         /* 巴法云；也可先用 broker.emqx.io 自检 */
#define SRV_PORT    9501U               /* 巴法云 MQTT 明文端口；EMQX 是 1883 */
#define CLIENT_ID   "f407-board2"
#define TOPIC_UP    "lab001"            /* 巴法云控制台里登记的主题名 */
#define TOPIC_DOWN  "lab001"

static MqttMsg_t s_msg;

static void on_downlink(const char *topic, const char *payload)
{
    (void)topic;
    (void)payload;      /* 下发的控制命令在这里解析（载荷是 # 分隔的文本） */
}

/* ---- 第 1~4 步：上电 → 握手 → 站点模式 → 连路由 → 建 TCP → 连云 ---- */
static uint8_t net_connect(void)
{
    uint8_t r;

    if (ESP8266_Init(115200U) != 0U) { return 1U; }            /* AT+RST / AT */
    if (ESP8266_SetMode(ESP8266_MODE_STA) != 0U) { return 2U; } /* AT+CWMODE=1 */
    if (ESP8266_JoinAP(WIFI_SSID, WIFI_PASS) != 0U) { return 3U; } /* AT+CWJAP */

    r = MQTT_Connect(SRV_HOST, SRV_PORT, CLIENT_ID, 0, 0);      /* 内含 AT+CIPMUX=0 + AT+CIPSTART */
    if (r != MQTT_OK) {
        /* 连不上时先看 CONNACK 返回码：0 成功 / 1 协议版本 / 2 客户端 ID /
         * 3 服务器不可用 / 4 用户名或密码错 / 5 未授权 */
        (void)MQTT_GetConnackCode();
        return 4U;
    }

    (void)MQTT_Subscribe(TOPIC_DOWN, 0U);
    /* 订阅报文发出去就返回 OK，服务器授不授权要看 SUBACK：0x80 = 被拒 */
    if (MQTT_GetSubAck() == 0x80U) { return 5U; }
    return 0U;
}

/* ---- 第 8~10 步：收下行（可能一个 TCP 段多条）+ 心跳判活 + 30s 上报 ---- */
static void net_task_20ms(void)
{
    static uint16_t div = 0U;

    if (MQTT_IsConnected() == 0U) {
        /* 掉线期间的数据交给 ⑱ 的 W25QXX 日志落盘；每 5s 试一次重连 */
        if ((++div % 250U) == 0U) { (void)net_connect(); }
        return;
    }

    /* MQTT_Poll 会按剩余长度把一条报文取干净，段内还有报文就再来一次 */
    while (MQTT_Poll(&s_msg) == MQTT_OK) { on_downlink(s_msg.topic, s_msg.payload); }

    /* 先听（有没有收到任何字节）→ 到半周期发 PINGREQ → 超时判死
     * 返回 8（MQTT_ERR_ALIVE_TIMEOUT）表示链路已断，s_connected 已被清 0 */
    if (MQTT_KeepAliveService() == MQTT_ERR_ALIVE_TIMEOUT) { return; }

    if ((++div % 1500U) == 0U) {      /* 20ms × 1500 = 30s */
        (void)MQTT_PublishStr(TOPIC_UP, "#25.30#48.55#1013.2#500#50#1234#01");
    }
}

int main(void)
{
    SYS_NVIC_Init();                                  /* 先定 NVIC 优先级分组 */
    SYS_USART_Init(SYS_USART_1, 115200U);             /* 调试串口 */
    SYS_USART_InitRxIT(SYS_USART_1, 115200U);
    delay_ms_dwt(200U);                               /* 等 USB 转串口枚举完 */

    (void)net_connect();                              /* 失败也不死等，主循环里会重试 */

    for (;;) {
        net_task_20ms();
        delay_ms_dwt(20U);
    }
}

