/* 硬件相关的值都集中在头文件里，别散落在业务代码中 */
#define ESP8266_USART        SYS_USART_3      /* PB10 = TX / PB11 = RX，跳线 P10 选 WIFI */
#define ESP8266_DEFAULT_BAUD 115200UL         /* 8N1，模块出厂就是这个 */

/* 初始化时先把中断接收开起来，再等模块上电日志吐完 */
SYS_USART_InitRxIT(ESP8266_USART, ESP8266_DEFAULT_BAUD);
delay_ms(200U);

/* 返回码分级（全文件一致）：
 *   0 = 命中期望词     -> 成功
 *   1 = 超时模块没表态 -> 查接线 / 供电 / 波特率
 *   2 = 回了 ERROR/FAIL -> 查命令拼写 / 模块是否支持
 */
if (ESP8266_Init(115200U) != 0U) {
    /* 先打印原文，再决定往哪个方向查 */
    P("ESP8266 reply: %s\r\n", ESP8266_GetLastReply());
    return 1U;
}

/* SendCmd 内部：先 Flush，再发 命令 + 回车换行，然后一边搬数据一边找期望词，
 * 同时盯 ERROR / FAIL，只要出现 ERROR 就立刻返回 2，不干等到超时 */
if (ESP8266_SendCmd("AT", "OK", 1000U) != 0U) { return 2U; }

/* 站点模式：AT+CWMODE=1（工程里手工拼字符串，不用 sprintf） */
if (ESP8266_SetMode(ESP8266_MODE_STA) != 0U) { return 2U; }

/* 连路由器：AT+CWJAP="ssid","pwd"，超时单独给 15s */
if (ESP8266_JoinAP(WIFI_SSID, WIFI_PASS) != 0U) { return 3U; }

/* 连上之后把 IP 打出来，这一行是「真的连上了」最直接的证据 */
{
    char ip[20];
    if (ESP8266_GetIP(ip, sizeof(ip)) == 0U) { P("STA IP = %s\r\n", ip); }
    else                                     { P("CIFSR failed\r\n"); }
}

/* 单连接模式：要同时连两个服务器才改成 1 */
(void)ESP8266_SendCmd("AT+CIPMUX=0", "OK", ESP8266_CMD_TIMEOUT_MS);

/* 拼 AT+CIPSTART="TCP","host",port（端口转十进制，不用 sprintf）
 * 返回 0 = 收到 OK；1 = 超时；2 = 模块回 ERROR（多半是 host/端口写错或没联网） */
if (ESP8266_ConnectTCP(SRV_HOST, SRV_PORT) != 0U) { return 4U; }

/* 通了之后再交给 MQTT 层做 CONNECT；断开用 AT+CIPCLOSE */
/* (void)ESP8266_CloseTCP(); */

/* 长度转十进制（低位在前，后面倒着放） */
while (v > 0U && n < 5U) { tmp[n++] = (char)('0' + (v % 10U)); v /= 10U; }

/* 手工拼 AT+CIPSEND=，等号在下标 10 */
cmd[0]='A'; cmd[1]='T'; cmd[2]='+'; cmd[3]='C'; cmd[4]='I';
cmd[5]='P'; cmd[6]='S'; cmd[7]='E'; cmd[8]='N'; cmd[9]='D';
cmd[10]='='; cmd[11]=0;

/* 关键：从字符串末尾（strlen）起算，绝不能写死 10，写死 10 就会把
 *   那个等号覆盖成数字，发出去变成 AT+CIPSEND100（非法命令）→ 模块回 ERROR
 *   → 客户端模式下所有 TCP 上行全失败。 */
k = (uint8_t)strlen(cmd);
while (n > 0U) { cmd[k++] = tmp[--n]; }
cmd[k] = 0;

if (ESP8266_SendCmd(cmd, ">", 3000U) != 0U) {
    /* 模块可能已经回过 '>' 而现在停在数据模式：先 +++ 退出，再发 AT 确认。
     * +++ 不带回车换行，且前后要静默 20ms 以上（这里用 50ms 保险）。
     * 已在命令模式时 +++ 只会回 ERROR，无害，所以可以无条件做。 */
    SYS_USART_SendString(ESP8266_USART, "+++");
    delay_ms_dwt(50U);
    (void)ESP8266_SendCmd("AT", "OK", 500U);
    return 1U;
}

/* 命中 '>' 才灌数据：这里必须走原始写，不能补回车换行 */
SYS_USART_SendBuf(ESP8266_USART, buf, len);
return ESP8266_SendCmd("", "SEND OK", 5000U);

/* 在原始字节里找 +IPD,<len>:，不能用 strstr，报文里有 0x00 */
if (buf[i] != (uint8_t)'+') { continue; }
if (memcmp(&buf[i], "+IPD,", 5U) != 0) { continue; }
/* 之后逐位解析十进制长度，必须等到 ':'，并且
 * j + n > len 时说明数据还没收全，直接放弃这一轮，等下次再拼 */
if ((uint32_t)j + n > (uint32_t)len) { continue; }

/* 报文真正的结尾 = 固定头(1 + 剩余长度字段字节数) + 剩余长度，
 * 不是 +IPD 的总长；用 uint32_t 算完再钳位，避免 uint16_t 回绕 */
pkt_end = (uint32_t)off + 1U + ((uint32_t)shift + 6U) / 7U + rem;
if (pkt_end > (uint32_t)end) { pkt_end = (uint32_t)end; }   /* 段内不完整就截断 */
end = (uint16_t)pkt_end;

/* 组包约定：buf[0]=类型，buf[1] 先占 1 字节，正文从 buf[2] 起 */
buf[n++] = MQTT_PKT_CONNECT;      /* 0x10 */
buf[n++] = 0U;                    /* 剩余长度占位，最后回填 */
n = (uint16_t)(n + mqtt_put_str(&buf[n], "MQTT"));   /* 协议名：不是 MQIsdp */
buf[n++] = 0x04U;                 /* 协议级别 4 = MQTT 3.1.1 */

/* 标志位：密码标志只有在用户名标志为 1 时才允许置 1，成对出现 */
if (userlen == 0U) { passlen = 0U; }   /* 没有用户名就把密码一起丢掉 */
if (userlen > 0U) { flags |= 0x80U; }
if (passlen > 0U) { flags |= 0x40U; }

n = mqtt_finalize(buf, n);        /* 回填剩余长度，多 1 字节时正文右移 */

r = MQTT_ConnectSimple(broker, client_id);
if (r != MQTT_OK) {
    /* 0 成功 / 1 协议版本 / 2 客户端 ID / 3 服务器不可用 / 4 账号密码 / 5 未授权 */
    P("CONNACK = %u\r\n", MQTT_GetConnackCode());
    return 1U;
}

(void)MQTT_Subscribe(TOPIC_DOWN, 0U);
/* 订阅发出去就返回 OK，服务器授没授权只有 SUBACK 说了算：0x80 = 被拒 */
if (MQTT_GetSubAck() == 0x80U) { return 2U; }

/* 收包循环里：SUBACK 要记返回码后继续往后找，不能整段当没数据丢掉 */
if ((b0 & 0xF0U) == 0x90U) {          /* SUBACK 固定高 4 位 0x90 */
    s_suback = rx[(uint16_t)(p + 2U)];
    s_rx_cursor = end;
    return MQTT_ERR_TIMEOUT;          /* 对调用方仍是「这条不是消息」 */
}

/* 先听：距上次收到 broker 任何字节是否还在超时以内（只读、无副作用） */
uint8_t MQTT_IsAlive(void)
{
    if (s_connected == 0U) { return 0U; }
    if (DWT_ElapsedUs(s_last_rx) >= ((uint32_t)MQTT_ALIVE_TIMEOUT_S * 1000000UL)) {
        return 0U;
    }
    return 1U;
}

/* 维护函数里的顺序不能改：先听 -> 再按半周期发心跳 -> 最后判死 */
got = mqtt_alive_check_rx();            /* 收到了任何字节就刷新 s_last_rx */
if (DWT_ElapsedUs(s_last_tx) >= ((uint32_t)(MQTT_KEEPALIVE_S / 2U) * 1000000UL)) {
    if (MQTT_Ping() != MQTT_OK) { return MQTT_ERR_TX; }
}
if (got != 0U) { return MQTT_OK; }
if (DWT_ElapsedUs(s_last_rx) >= ((uint32_t)MQTT_ALIVE_TIMEOUT_S * 1000000UL)) {
    s_connected = 0U;                   /* 判死：上层由此转 ⑱ 本地缓存 */
    return MQTT_ERR_ALIVE_TIMEOUT;      /* = 8 */
}

