    static const uint8_t ref[6] = { 0x01U, 0x03U, 0x00U, 0x00U, 0x00U, 0x02U };
    uint16_t crc = MODBUS_CRC16(ref, 6U);
    return (uint8_t)((crc == 0x0BC4U) ? 1U : 0U);
