/* ============================================================
 *  sys_frame 自定义帧协议，完整可用成品代码
 *  线上格式：AA 55 | CMD | LEN | DATA(LEN) | CRC低 CRC高 | 55 AA
 *  整帧长度 = 8 + LEN；CRC 范围 = [2 .. 4+LEN) 共 LEN+2 字节
 *  平台：STM32F407 · 板1 ⇄ 板2 · 物理层 LoRa(E22) 或 RS485
 *  对应 FWLIB：sys_frame.c / sys_frame.h（两板逐字节相同）+ sys_usart.c
 *  说明：本文件把 sys_frame 模块要用的东西摊开写成一份自包含实现，
 *        方便先在 PC 或开发板上验证「组帧—解析」自洽，再换成库调用。
 * ============================================================ */
#include "stm32f4xx.h"
#include <string.h>

/* ================= 区块 1：协议常量（换协议只改这一段） ================= */
#define SYS_FRAME_HEAD_HI       0xAAU
#define SYS_FRAME_HEAD_LO       0x55U
#define SYS_FRAME_TAIL_HI       0x55U
#define SYS_FRAME_TAIL_LO       0xAAU
#define SYS_FRAME_OVERHEAD      8U
#define SYS_FRAME_MAX_PAYLOAD   64U

#define SYS_FRAME_OK            0U
#define SYS_FRAME_ERR_HEAD      1U
#define SYS_FRAME_ERR_TAIL      2U
#define SYS_FRAME_ERR_LEN       3U
#define SYS_FRAME_ERR_CRC       4U
#define SYS_FRAME_ERR_PARAM     5U

#define SYS_FRAME_CMD_ENV       0x01U
#define SYS_FRAME_ENV_LEN       0x0CU
#define SYS_FRAME_ENV_TEMP_OFF   0U
#define SYS_FRAME_ENV_HUMI_OFF   2U
#define SYS_FRAME_ENV_PRESS_OFF  4U
#define SYS_FRAME_ENV_LIGHT_OFF  6U
#define SYS_FRAME_ENV_TVOC_OFF   8U
#define SYS_FRAME_ENV_MQ135_OFF 10U

/* 本路串口超过这么多毫秒没有新字节，就把收帧状态机复位（丢半帧） */
#define FRAME_RX_TIMEOUT_MS     5U

static uint32_t s_last_ms[2];        /* 0 = LoRa 口，1 = RS485 口 */

/* ================= 区块 2：CRC16-MODBUS ================= */
static uint16_t frame_crc16_update(uint16_t crc, uint8_t byte)
{
    uint8_t i;

    crc ^= (uint16_t)byte;
    for (i = 0U; i < 8U; i++)
    {
        crc = ((crc & 1U) != 0U) ? (uint16_t)((crc >> 1) ^ 0xA001U)
                                 : (uint16_t)(crc >> 1);
    }
    return crc;
}

static uint16_t frame_crc16(const uint8_t *buf, uint16_t len)
{
    uint16_t crc = 0xFFFFU;
    uint16_t i;

    for (i = 0U; i < len; i++) { crc = frame_crc16_update(crc, buf[i]); }
    return crc;
}

static void     frame_put_u16_be(uint8_t *p, uint16_t v)
{ p[0] = (uint8_t)(v >> 8); p[1] = (uint8_t)(v & 0xFFU); }

static uint16_t frame_get_u16_be(const uint8_t *p)
{ return (uint16_t)(((uint16_t)p[0] << 8) | (uint16_t)p[1]); }

/* ================= 区块 3：组帧 ================= */
static uint16_t frame_build(uint8_t cmd, const uint8_t *payload, uint16_t len,
                            uint8_t *out, uint16_t cap)
{
    uint16_t crc, i;

    if (out == 0)                                   { return 0U; }
    if (len > SYS_FRAME_MAX_PAYLOAD)                { return 0U; }
    if ((payload == 0) && (len != 0U))              { return 0U; }
    if (cap < (uint16_t)(len + SYS_FRAME_OVERHEAD)) { return 0U; }

    out[0] = SYS_FRAME_HEAD_HI;
    out[1] = SYS_FRAME_HEAD_LO;
    out[2] = cmd;
    out[3] = (uint8_t)len;
    for (i = 0U; i < len; i++) { out[4U + i] = payload[i]; }

    /* CRC 覆盖 CMD + LEN + DATA：从 out[2] 起共 len + 2 字节 */
    crc = frame_crc16(&out[2], (uint16_t)(len + 2U));
    out[4U + len] = (uint8_t)(crc & 0xFFU);          /* 低字节在前 */
    out[5U + len] = (uint8_t)(crc >> 8);
    out[6U + len] = SYS_FRAME_TAIL_HI;
    out[7U + len] = SYS_FRAME_TAIL_LO;
    return (uint16_t)(len + SYS_FRAME_OVERHEAD);
}

static uint16_t frame_build_env(uint8_t *out, uint16_t cap,
                                int16_t temp_x100, int16_t humi_x100,
                                int16_t press_x10, uint16_t light,
                                uint16_t tvoc, uint16_t mq135)
{
    uint8_t env[SYS_FRAME_ENV_LEN];

    if (out == 0) { return 0U; }
    frame_put_u16_be(&env[SYS_FRAME_ENV_TEMP_OFF],  (uint16_t)temp_x100);
    frame_put_u16_be(&env[SYS_FRAME_ENV_HUMI_OFF],  (uint16_t)humi_x100);
    frame_put_u16_be(&env[SYS_FRAME_ENV_PRESS_OFF], (uint16_t)press_x10);
    frame_put_u16_be(&env[SYS_FRAME_ENV_LIGHT_OFF], light);
    frame_put_u16_be(&env[SYS_FRAME_ENV_TVOC_OFF],  tvoc);
    frame_put_u16_be(&env[SYS_FRAME_ENV_MQ135_OFF], mq135);
    return frame_build(SYS_FRAME_CMD_ENV, env, SYS_FRAME_ENV_LEN, out, cap);
}

/* ================= 区块 4：整帧校验（三重确认） ================= */
static uint8_t frame_verify(const uint8_t *buf, uint16_t len)
{
    uint16_t crc, dlen;

    if (buf == 0)                 { return SYS_FRAME_ERR_PARAM; }
    if (len < SYS_FRAME_OVERHEAD) { return SYS_FRAME_ERR_PARAM; }

    if ((buf[0] != SYS_FRAME_HEAD_HI) || (buf[1] != SYS_FRAME_HEAD_LO))
    { return SYS_FRAME_ERR_HEAD; }
    if ((buf[len - 2U] != SYS_FRAME_TAIL_HI) || (buf[len - 1U] != SYS_FRAME_TAIL_LO))
    { return SYS_FRAME_ERR_TAIL; }

    dlen = (uint16_t)buf[3];
    if ((dlen + SYS_FRAME_OVERHEAD) != len) { return SYS_FRAME_ERR_LEN; }

    crc = frame_crc16(&buf[2], (uint16_t)(dlen + 2U));
    if ((buf[4U + dlen] != (uint8_t)(crc & 0xFFU)) ||
        (buf[5U + dlen] != (uint8_t)(crc >> 8)))       { return SYS_FRAME_ERR_CRC; }
    return SYS_FRAME_OK;
}

/* ================= 区块 5：每路串口一套收帧状态机 ================= */
enum {
    FX_ST_HEAD_HI = 0U, FX_ST_HEAD_LO, FX_ST_CMD, FX_ST_LEN, FX_ST_DATA,
    FX_ST_CRC_LO, FX_ST_CRC_HI, FX_ST_TAIL_HI, FX_ST_TAIL_LO
};

typedef struct {
    uint8_t  state, cmd, idx, dlen;
    uint8_t  data[SYS_FRAME_MAX_PAYLOAD];
    uint16_t crc;
    uint8_t  rcrc_lo;
    volatile uint8_t  ready, rcmd;
    volatile uint16_t rlen;
    uint8_t  rbuf[SYS_FRAME_MAX_PAYLOAD];
    volatile uint16_t err;
} FrameRx_t;

static FrameRx_t fx[2];              /* 0 = LoRa 口，1 = RS485 口 */

static void fx_restart(FrameRx_t *f, uint8_t byte)
{
    f->crc   = 0xFFFFU;
    f->state = (byte == SYS_FRAME_HEAD_HI) ? FX_ST_HEAD_LO : FX_ST_HEAD_HI;
}

static uint8_t fx_feed(FrameRx_t *f, uint8_t byte)
{
    uint8_t k;

    switch (f->state)
    {
    case FX_ST_HEAD_HI:
        if (byte == SYS_FRAME_HEAD_HI) { f->state = FX_ST_HEAD_LO; }
        return 0U;
    case FX_ST_HEAD_LO:
        if (byte == SYS_FRAME_HEAD_LO)      { f->crc = 0xFFFFU; f->state = FX_ST_CMD; }
        else if (byte != SYS_FRAME_HEAD_HI) { f->state = FX_ST_HEAD_HI; }
        return 0U;
    case FX_ST_CMD:
        f->cmd = byte; f->crc = frame_crc16_update(f->crc, byte);
        f->state = FX_ST_LEN; return 0U;
    case FX_ST_LEN:
        if (byte > SYS_FRAME_MAX_PAYLOAD) { f->err++; fx_restart(f, byte); return 0U; }
        f->dlen = byte; f->crc = frame_crc16_update(f->crc, byte); f->idx = 0U;
        f->state = (byte == 0U) ? FX_ST_CRC_LO : FX_ST_DATA;
        return 0U;
    case FX_ST_DATA:
        f->data[f->idx] = byte; f->idx++;
        f->crc = frame_crc16_update(f->crc, byte);
        if (f->idx >= f->dlen) { f->state = FX_ST_CRC_LO; }
        return 0U;
    case FX_ST_CRC_LO:
        f->rcrc_lo = byte; f->state = FX_ST_CRC_HI; return 0U;
    case FX_ST_CRC_HI:
        if ((uint16_t)(((uint16_t)byte << 8) | f->rcrc_lo) != f->crc)
        { f->err++; fx_restart(f, byte); return 0U; }
        f->state = FX_ST_TAIL_HI; return 0U;
    case FX_ST_TAIL_HI:
        if (byte != SYS_FRAME_TAIL_HI) { f->err++; fx_restart(f, byte); return 0U; }
        f->state = FX_ST_TAIL_LO; return 0U;
    case FX_ST_TAIL_LO:
        if (byte != SYS_FRAME_TAIL_LO) { f->err++; fx_restart(f, byte); return 0U; }
        f->rcmd = f->cmd; f->rlen = f->dlen;
        for (k = 0U; k < f->dlen; k++) { f->rbuf[k] = f->data[k]; }
        f->ready = 1U; f->state = FX_ST_HEAD_HI;
        return 1U;
    default:
        f->state = FX_ST_HEAD_HI; return 0U;
    }
}

/* 超时看护：本路串口超过 FRAME_RX_TIMEOUT_MS 没进字节就复位状态机。
 *   不做这一步，收到半个帧头后链路一安静，状态机就永久卡在等 0x55 上。 */
static void frame_poll_timeout(uint8_t port, uint32_t now_ms)
{
    if ((uint32_t)(now_ms - s_last_ms[port]) > FRAME_RX_TIMEOUT_MS)
    {
        if (fx[port].state != FX_ST_HEAD_HI)
        {
            fx[port].state = FX_ST_HEAD_HI;   /* 丢掉半帧，重新找帧头 */
            fx[port].idx   = 0U;
            fx[port].crc   = 0xFFFFU;
            fx[port].err++;                   /* 计入出错统计，别静默 */
        }
    }
}

/* ================= 区块 6：拆环境帧的数据段 ================= */
static uint8_t frame_unpack_env(const uint8_t *payload, uint16_t len,
                                int16_t *temp_x100, int16_t *humi_x100,
                                int16_t *press_x10, uint16_t *light,
                                uint16_t *tvoc, uint16_t *mq135)
{
    if (payload == 0)                    { return SYS_FRAME_ERR_PARAM; }
    if (len < SYS_FRAME_ENV_LEN)         { return SYS_FRAME_ERR_PARAM; }

    if (temp_x100)  { *temp_x100  = (int16_t)frame_get_u16_be(&payload[SYS_FRAME_ENV_TEMP_OFF]); }
    if (humi_x100)  { *humi_x100  = (int16_t)frame_get_u16_be(&payload[SYS_FRAME_ENV_HUMI_OFF]); }
    if (press_x10)  { *press_x10  = (int16_t)frame_get_u16_be(&payload[SYS_FRAME_ENV_PRESS_OFF]); }
    if (light)      { *light      = frame_get_u16_be(&payload[SYS_FRAME_ENV_LIGHT_OFF]); }
    if (tvoc)       { *tvoc       = frame_get_u16_be(&payload[SYS_FRAME_ENV_TVOC_OFF]); }
    if (mq135)      { *mq135      = frame_get_u16_be(&payload[SYS_FRAME_ENV_MQ135_OFF]); }
    return SYS_FRAME_OK;
}

/* ================= 区块 7：收发整条链路 ================= */
/* 发：组帧 → 自检（整段重算必须为 0）→ 整帧一次交给物理层 */
static uint8_t app_send_env(uint8_t port, float temp_c, float humi_rh, float press_hpa,
                            uint16_t light, uint16_t tvoc, uint16_t mq135)
{
    uint8_t  f[20];
    uint16_t n;

    /* 气压 ×10；温度、湿度 ×100。×100 的气压会溢出 uint16 */
    n = frame_build_env(f, sizeof(f),
                        (int16_t)(temp_c * 100.0f),
                        (int16_t)(humi_rh * 100.0f),
                        (int16_t)(press_hpa * 10.0f),
                        light, tvoc, mq135);
    if (n != 20U) { return 1U; }

    if (frame_verify(f, n) != SYS_FRAME_OK) { return 2U; }
    if (frame_crc16(&f[2], 16U) != 0U)      { return 3U; }   /* 联调判据 */

    /* W25QXX_LogWrite(ts, f, n);                         断网缓存整帧 */
    /* LORA_E22_Send(f, n) / RS485_SendBuf(f, n);         整帧一次发出 */
    (void)port;
    return 0U;
}

/* 收：把本路串口收到的字节喂进状态机，凑成一帧就解析 */
static void app_rx_poll(uint8_t port, const uint8_t *chunk, uint16_t n, uint32_t now_ms)
{
    uint16_t i;
    int16_t  t100, h100, p10;
    uint16_t lx, tv, mq;

    s_last_ms[port] = now_ms;
    for (i = 0U; i < n; i++)
    {
        if (fx_feed(&fx[port], chunk[i]) == 0U) { continue; }

        /* 先整帧复核（缓冲里已是完整帧时走这条），再按命令字分发 */
        if (fx[port].rcmd == SYS_FRAME_CMD_ENV)
        {
            if (frame_unpack_env(fx[port].rbuf, fx[port].rlen, &t100, &h100, &p10,
                                 &lx, &tv, &mq) == SYS_FRAME_OK)
            {
                /* 打印：温度 t100/100.0f ℃，气压 p10/10.0f hPa */
                (void)t100; (void)h100; (void)p10; (void)lx; (void)tv; (void)mq;
            }
        }
    }
    frame_poll_timeout(port, now_ms);
}

/* ================= 区块 8：自测（三步都过才算通） ================= */
uint8_t frame_selftest(void)
{
    uint8_t  f[20];
    uint16_t n, i;
    int16_t  t, h, p;

    n = frame_build_env(f, sizeof(f), 2560, 6030, 10132, 320U, 15U, 812U);
    if (n != 20U)                       { return 1U; }
    if (frame_verify(f, n) != SYS_FRAME_OK) { return 2U; }      /* 三重确认 */
    if (frame_crc16(&f[2], 16U) != 0U)  { return 3U; }          /* 整段重算 = 0 */

    fx[0].state = FX_ST_HEAD_HI; fx[0].ready = 0U; fx[0].err = 0U;
    for (i = 0U; i < n; i++) { (void)fx_feed(&fx[0], f[i]); }
    if (fx[0].ready == 0U)              { return 4U; }
    if (fx[0].rlen != SYS_FRAME_ENV_LEN){ return 5U; }

    t = (int16_t)frame_get_u16_be(&fx[0].rbuf[SYS_FRAME_ENV_TEMP_OFF]);
    h = (int16_t)frame_get_u16_be(&fx[0].rbuf[SYS_FRAME_ENV_HUMI_OFF]);
    p = (int16_t)frame_get_u16_be(&fx[0].rbuf[SYS_FRAME_ENV_PRESS_OFF]);
    if (t != 2560)  { return 6U; }
    if (h != 6030)  { return 7U; }
    if (p != 10132) { return 8U; }

    /* 再验一次「半帧被超时丢弃」：只喂 4 字节，然后时间快进 */
    fx[0].state = FX_ST_HEAD_HI; fx[0].ready = 0U;
    for (i = 0U; i < 4U; i++) { (void)fx_feed(&fx[0], f[i]); }
    if (fx[0].state == FX_ST_HEAD_HI)   { return 9U; }   /* 此时正卡在半帧上 */
    frame_poll_timeout(0U, (uint32_t)(FRAME_RX_TIMEOUT_MS + 1U));
    if (fx[0].state != FX_ST_HEAD_HI)   { return 10U; }  /* 超时应能救回来 */

    return 0U;
}

f:
/* 组帧侧：输出缓冲容量检查必须在写之前 */
if (cap < (uint16_t)(len + SYS_FRAME_OVERHEAD)) { return 0U; }

/* 收帧侧：长度字段先判上界，再拿去索引数组，顺序不能反 */
case FX_ST_LEN:
    if (byte > SYS_FRAME_MAX_PAYLOAD)
    {
        f->err++;
        fx_restart(f, byte);          /* 丢帧，回到找帧头 */
        return 0U;
    }
    f->dlen = byte;
    f->crc  = frame_crc16_update(f->crc, byte);   /* LEN 也参与 CRC */
    f->idx  = 0U;
    /* 数据段长度为 0 的帧直接进 CRC 态（这就是 8 字节短帧） */
    f->state = (byte == 0U) ? FX_ST_CRC_LO : FX_ST_DATA;
    return 0U;

/* CRC16-MODBUS：初值 0xFFFF，反射多项式 0xA001，末尾不异或 */
static uint16_t frame_crc16_update(uint16_t crc, uint8_t byte)
{
    uint8_t i;

    crc ^= (uint16_t)byte;
    for (i = 0U; i < 8U; i++)
    {
        if ((crc & 0x0001U) != 0U) { crc = (uint16_t)((crc >> 1) ^ 0xA001U); }
        else                       { crc = (uint16_t)(crc >> 1); }
    }
    return crc;
}

static uint16_t frame_crc16(const uint8_t *buf, uint16_t len)
{
    uint16_t crc = 0xFFFFU;
    uint16_t i;

    if (buf == 0) { return crc; }                 /* 防野指针 */
    for (i = 0U; i < len; i++) { crc = frame_crc16_update(crc, buf[i]); }
    return crc;
}

/* CRC 覆盖范围，写错这一行，算出来的校验值永远对不上 */

/* 生成 / 核对 CRC：范围 = CMD + LEN + DATA
 * 20 字节帧就是 &out[2] 起 14 字节（LEN 12 + 2） */
crc = frame_crc16(&out[2], (uint16_t)(len + 2U));
out[4U + len] = (uint8_t)(crc & 0xFFU);      /* 低字节在前 */
out[5U + len] = (uint8_t)(crc >> 8);

/* 校验侧（数据缓冲区里已是一整帧） */
crc = frame_crc16(&buf[2], (uint16_t)(dlen + 2U));
if ((buf[4U + dlen] != (uint8_t)(crc & 0xFFU)) ||
    (buf[5U + dlen] != (uint8_t)(crc >> 8)))
{ return SYS_FRAME_ERR_CRC; }

/* 自检侧：这次要把 CRC 两字节也算进去，整段重算结果必须是 0
 * 长度是 16（14 + 2），和上面的 14 含义不同 */
if (frame_crc16(&f[2], 16U) != 0U) { /* 组帧与 CRC 不自洽 */ }

/* 失败后重启：失败字节若是 0xAA，直接当新帧头高字节起头
 *   这就是「帧同步」，丢一个字节后还能自动恢复的关键 */
static void fx_restart(FrameRx_t *f, uint8_t byte)
{
    f->crc   = 0xFFFFU;
    f->state = (byte == SYS_FRAME_HEAD_HI) ? FX_ST_HEAD_LO : FX_ST_HEAD_HI;
}

static uint8_t fx_feed(FrameRx_t *f, uint8_t byte)
{
    uint8_t k;

    switch (f->state)
    {
    case FX_ST_HEAD_HI:
        if (byte == SYS_FRAME_HEAD_HI) { f->state = FX_ST_HEAD_LO; }
        return 0U;

    case FX_ST_HEAD_LO:
        if (byte == SYS_FRAME_HEAD_LO)      { f->crc = 0xFFFFU; f->state = FX_ST_CMD; }
        else if (byte != SYS_FRAME_HEAD_HI) { f->state = FX_ST_HEAD_HI; }
        return 0U;      /* byte == 0xAA：连着两个 AA，状态不动，继续等 0x55 */

    case FX_ST_CMD:
        f->cmd = byte; f->crc = frame_crc16_update(f->crc, byte);
        f->state = FX_ST_LEN; return 0U;

    case FX_ST_LEN:
        if (byte > SYS_FRAME_MAX_PAYLOAD) { f->err++; fx_restart(f, byte); return 0U; }
        f->dlen = byte; f->crc = frame_crc16_update(f->crc, byte); f->idx = 0U;
        f->state = (byte == 0U) ? FX_ST_CRC_LO : FX_ST_DATA;
        return 0U;

    case FX_ST_DATA:
        f->data[f->idx] = byte; f->idx++;
        f->crc = frame_crc16_update(f->crc, byte);
        if (f->idx >= f->dlen) { f->state = FX_ST_CRC_LO; }
        return 0U;

    case FX_ST_CRC_LO:
        f->rcrc_lo = byte; f->state = FX_ST_CRC_HI; return 0U;

    case FX_ST_CRC_HI:
        if ((uint16_t)(((uint16_t)byte << 8) | f->rcrc_lo) != f->crc)
        { f->err++; fx_restart(f, byte); return 0U; }
        f->state = FX_ST_TAIL_HI; return 0U;

    case FX_ST_TAIL_HI:
        if (byte != SYS_FRAME_TAIL_HI) { f->err++; fx_restart(f, byte); return 0U; }
        f->state = FX_ST_TAIL_LO; return 0U;

    case FX_ST_TAIL_LO:
        if (byte != SYS_FRAME_TAIL_LO) { f->err++; fx_restart(f, byte); return 0U; }
        f->rcmd = f->cmd; f->rlen = f->dlen;
        for (k = 0U; k < f->dlen; k++) { f->rbuf[k] = f->data[k]; }
        f->ready = 1U; f->state = FX_ST_HEAD_HI;
        return 1U;      /* 完整一帧，已存入就绪槽 */

    default:
        f->state = FX_ST_HEAD_HI; return 0U;
    }
}

/* 超时看护：本路串口超过 FRAME_RX_TIMEOUT_MS 没进字节就复位状态机
 *
 *  取 5ms 的依据：9600bps 下一个字节约 1.04ms，5 个字节约 5ms；
 *  本项目帧是每秒一条、一次连续发出，字节之间没有间隙，5ms 非常安全。
 *  不做这一步，收到半个帧头后链路一安静，状态机就永久卡在等 0x55 上。
 */
#define FRAME_RX_TIMEOUT_MS  5U

static void frame_poll_timeout(uint8_t port, uint32_t now_ms)
{
    if ((uint32_t)(now_ms - s_last_ms[port]) > FRAME_RX_TIMEOUT_MS)
    {
        if (fx[port].state != FX_ST_HEAD_HI)
        {
            fx[port].state = FX_ST_HEAD_HI;   /* 丢掉半帧，重新找帧头 */
            fx[port].idx   = 0U;
            fx[port].crc   = 0xFFFFU;
            fx[port].err++;                   /* 计入出错统计，不许静默 */
        }
    }
}

/* 收到字节时刷新时间戳；每轮轮询结束调一次看护 */
static void app_rx_poll(uint8_t port, const uint8_t *chunk, uint16_t n, uint32_t now_ms)
{
    uint16_t i;

    s_last_ms[port] = now_ms;
    for (i = 0U; i < n; i++) { (void)fx_feed(&fx[port], chunk[i]); }
    frame_poll_timeout(port, now_ms);
}

/* 环境帧字段在数据段内的偏移（不含帧头/CMD/LEN，从 0 数起） */
#define SYS_FRAME_ENV_TEMP_OFF   0U
#define SYS_FRAME_ENV_HUMI_OFF   2U
#define SYS_FRAME_ENV_PRESS_OFF  4U
#define SYS_FRAME_ENV_LIGHT_OFF  6U
#define SYS_FRAME_ENV_TVOC_OFF   8U
#define SYS_FRAME_ENV_MQ135_OFF 10U

/* 大端存取：数据段一律高字节在前 */
static void frame_put_u16_be(uint8_t *p, uint16_t v)
{ p[0] = (uint8_t)(v >> 8); p[1] = (uint8_t)(v & 0xFFU); }

static uint16_t frame_get_u16_be(const uint8_t *p)
{ return (uint16_t)(((uint16_t)p[0] << 8) | (uint16_t)p[1]); }

static uint16_t frame_build_env(uint8_t *out, uint16_t cap,
                                int16_t temp_x100, int16_t humi_x100,
                                int16_t press_x10, uint16_t light,
                                uint16_t tvoc, uint16_t mq135)
{
    uint8_t env[SYS_FRAME_ENV_LEN];

    if (out == 0) { return 0U; }
    frame_put_u16_be(&env[SYS_FRAME_ENV_TEMP_OFF],  (uint16_t)temp_x100);
    frame_put_u16_be(&env[SYS_FRAME_ENV_HUMI_OFF],  (uint16_t)humi_x100);
    frame_put_u16_be(&env[SYS_FRAME_ENV_PRESS_OFF], (uint16_t)press_x10);
    frame_put_u16_be(&env[SYS_FRAME_ENV_LIGHT_OFF], light);
    frame_put_u16_be(&env[SYS_FRAME_ENV_TVOC_OFF],  tvoc);
    frame_put_u16_be(&env[SYS_FRAME_ENV_MQ135_OFF], mq135);

    /* 信封交给通用组帧：AA 55 01 0C 数据… CRC低 CRC高 55 AA = 20 字节 */
    return frame_build(SYS_FRAME_CMD_ENV, env, SYS_FRAME_ENV_LEN, out, cap);
}

/* 调用侧：气压 ×10，温度湿度 ×100 */
n = frame_build_env(f, sizeof(f),
                    (int16_t)(temp_c   * 100.0f),
                    (int16_t)(humi_rh  * 100.0f),
                    (int16_t)(press_hpa * 10.0f),   /* 不是 ×100 */
                    light, tvoc, mq135);

/* 整帧校验：三重确认，返回 SYS_FRAME_OK(0) = 合法
 *   1 = 帧头 / 2 = 帧尾 / 3 = 长度不符 / 4 = CRC 错 / 5 = 参数错 */
static uint8_t frame_verify(const uint8_t *buf, uint16_t len)
{
    uint16_t crc, dlen;

    if (buf == 0)                 { return SYS_FRAME_ERR_PARAM; }
    if (len < SYS_FRAME_OVERHEAD) { return SYS_FRAME_ERR_PARAM; }

    /* 第一道：帧头必须连续两字节 AA 55 */
    if ((buf[0] != SYS_FRAME_HEAD_HI) || (buf[1] != SYS_FRAME_HEAD_LO))
    { return SYS_FRAME_ERR_HEAD; }

    /* 帧尾 55 AA */
    if ((buf[len - 2U] != SYS_FRAME_TAIL_HI) || (buf[len - 1U] != SYS_FRAME_TAIL_LO))
    { return SYS_FRAME_ERR_TAIL; }

    /* 第二道：长度字段自洽，两帧粘接在这里被抓住 */
    dlen = (uint16_t)buf[3];
    if ((dlen + SYS_FRAME_OVERHEAD) != len) { return SYS_FRAME_ERR_LEN; }

    /* 第三道：重算 CRC16，与帧内两字节比较（帧内低字节在前） */
    crc = frame_crc16(&buf[2], (uint16_t)(dlen + 2U));
    if ((buf[4U + dlen] != (uint8_t)(crc & 0xFFU)) ||
        (buf[5U + dlen] != (uint8_t)(crc >> 8)))       { return SYS_FRAME_ERR_CRC; }

    return SYS_FRAME_OK;
}

/* ---- 发送侧：组帧 → 自检 → 整帧一次发出 ---- */
static uint8_t app_send_env(uint8_t port, float temp_c, float humi_rh, float press_hpa,
                            uint16_t light, uint16_t tvoc, uint16_t mq135)
{
    uint8_t  f[20];
    uint16_t n;

    n = frame_build_env(f, sizeof(f),
                        (int16_t)(temp_c * 100.0f),
                        (int16_t)(humi_rh * 100.0f),
                        (int16_t)(press_hpa * 10.0f),   /* 气压 ×10 */
                        light, tvoc, mq135);
    if (n != 20U)                           { return 1U; }
    if (frame_verify(f, n) != SYS_FRAME_OK) { return 2U; }
    if (frame_crc16(&f[2], 16U) != 0U)      { return 3U; }   /* 联调判据 */

    /* W25QXX_LogWrite(ts, f, n);                       断网先存整帧 */
    /* LORA_E22_Send(f, n);  或 RS485 方向切换后发 */
    return 0U;
}

/* ---- 接收侧：中断进环形缓冲，任务里 Poll 喂状态机并解析 ---- */
static void app_rx_poll(uint8_t port, const uint8_t *chunk, uint16_t n, uint32_t now_ms)
{
    uint16_t i;
    int16_t  t100, h100, p10;
    uint16_t lx, tv, mq;

    s_last_ms[port] = now_ms;
    for (i = 0U; i < n; i++)
    {
        if (fx_feed(&fx[port], chunk[i]) == 0U) { continue; }
        if (fx[port].rcmd == SYS_FRAME_CMD_ENV)
        {
            if (frame_unpack_env(fx[port].rbuf, fx[port].rlen, &t100, &h100, &p10,
                                 &lx, &tv, &mq) == SYS_FRAME_OK)
            {
                /* 打印：温度 = t100 / 100.0f ℃，气压 = p10 / 10.0f hPa */
                (void)t100; (void)h100; (void)p10; (void)lx; (void)tv; (void)mq;
            }
        }
    }
    frame_poll_timeout(port, now_ms);
}

/* ---- 自测：三步全过才算协议自洽，返回 0 = 通过 ---- */
uint8_t frame_selftest(void)
{
    uint8_t  f[20];
    uint16_t n, i;
    int16_t  t, h, p;

    /* 第 1 步：组帧 + 整帧校验 */
    n = frame_build_env(f, sizeof(f), 2560, 6030, 10132, 320U, 15U, 812U);
    if (n != 20U)                           { return 1U; }
    if (frame_verify(f, n) != SYS_FRAME_OK) { return 2U; }

    /* 第 2 步：整段重算 = 0（CRC16-MODBUS 的附带性质） */
    if (frame_crc16(&f[2], 16U) != 0U)      { return 3U; }

    /* 第 3 步：逐字节喂状态机，应当恰好凑成 1 帧并还原原值 */
    fx[0].state = FX_ST_HEAD_HI; fx[0].ready = 0U; fx[0].err = 0U;
    for (i = 0U; i < n; i++) { (void)fx_feed(&fx[0], f[i]); }
    if (fx[0].ready == 0U)                  { return 4U; }
    if (fx[0].rlen != SYS_FRAME_ENV_LEN)    { return 5U; }

    t = (int16_t)frame_get_u16_be(&fx[0].rbuf[SYS_FRAME_ENV_TEMP_OFF]);
    h = (int16_t)frame_get_u16_be(&fx[0].rbuf[SYS_FRAME_ENV_HUMI_OFF]);
    p = (int16_t)frame_get_u16_be(&fx[0].rbuf[SYS_FRAME_ENV_PRESS_OFF]);
    if (t != 2560)  { return 6U; }
    if (h != 6030)  { return 7U; }
    if (p != 10132) { return 8U; }

    /* 第 4 步：半帧被超时救回（这条最容易漏测） */
    fx[0].state = FX_ST_HEAD_HI; fx[0].ready = 0U;
    for (i = 0U; i < 4U; i++) { (void)fx_feed(&fx[0], f[i]); }
    if (fx[0].state == FX_ST_HEAD_HI)       { return 9U; }   /* 此时正卡在半帧 */
    frame_poll_timeout(0U, (uint32_t)(FRAME_RX_TIMEOUT_MS + 1U));
    if (fx[0].state != FX_ST_HEAD_HI)       { return 10U; }  /* 超时救回 */

    return 0U;              /* 0 = 组帧 / 校验 / 收帧 / 超时恢复 全部自洽 */
}

/* ---- 整合清单（下一步该做的事，改完协议只有一份实现）----
 *  1. 板1 main.c：删掉 FRAME_CMD_ENV…FRAME_CRC_OFF 一组宏、
