为什么 sys_frame.c 自己带一份 crc 实现，而不调用板子上的 modbus 例程？ 因为板1 的例程在 `sys_modbus.h` 里叫 `sys_modbus_crc16`、板2 的在 `modbus.h` 里叫 `modbus_crc16`。这份文件必须在两块板上逐字节相同（两板靠它互通），只要 include 任何一边的头文件，「两板同源」的前提就断了。代价是几十字节 rom 里有两份实现，收益是这个文件可以整文件复制到任意板。 实现两个函数：逐字节更新的 `frame_crc16_update(crc, byte)` 和整段的 `frame_crc16(buf, len)`。整段函数内部先 `crc = 0xffff` 再逐字节更新。
写完后立刻做一次自检：把 crc 两字节附加在消息后面，整段重算应当为 0。这一步不做，后面所有联调都是在猜。 /* crc16-modbus：初值 0xffff，反射多项式 0xa001，末尾不异或 */
static uint16_t frame_crc16_update(uint16_t crc, uint8_t byte)
{
    uint8_t i;

    crc ^= (uint16_t)byte;
    for (i = 0u; i < 8u; i++)
    {
        if ((crc & 0x0001u) != 0u) { crc = (uint16_t)((crc >> 1) ^ 0xa001u); }
        else                       { crc = (uint16_t)(crc >> 1); }
    }
    return crc;
}

static uint16_t frame_crc16(const uint8_t *buf, uint16_t len)
{
    uint16_t crc = 0xffffu;
    uint16_t i;

    if (buf == 0) { return crc; }                 /* 防野指针 */
    for (i = 0u; i < len; i++) { crc = frame_crc16_update(crc, buf[i]); }
    return crc;
