static char s_line_last[4][24];

/* ---------------- 二、板上电第一步：先确认总线上有谁 ---------------- */
static uint8_t oled_probe(void)
{
    uint8_t list[8];
    uint8_t n;
    uint8_t i;
    uint8_t found = 0U;

    SYS_I2C_Init(SYS_I2C_1, 400000U);      /* OLED 支持 400kHz */
    n = SYS_I2C_Scan(SYS_I2C_1, list, 8U);
    printf("[OLED] I2C1 scan: %u device(s)\r\n", (unsigned)n);
    for (i = 0U; i < n; i++) {
        printf("       0x%02X\r\n", list[i]);
        if (list[i] == 0x3CU || list[i] == 0x3DU) found = 1U;
    }
    if (!found) {
        printf("[OLED] 0x3C 不在总线上：查四根线 / 上拉 / 供电\r\n");
        return 1U;
    }
    if (SYS_I2C_IsDeviceReady(SYS_I2C_1, 0x3CU) != SYS_I2C_OK) {
        printf("[OLED] %s\r\n", SYS_I2C_ErrStr(SYS_I2C_ERR_ADDR));
        return 1U;
    }
    return 0U;
}

/* ---------------- 三、初始化 ---------------- */
static uint8_t oled_setup(void)
{
    if (oled_probe() != 0U) return 1U;

    /* OLED_Init() 内部已经按源码里的序列发完所有指令，
     * 并且自带 ClearBuffer + Refresh 清成一屏全黑，最后 0xAF 开显示。
     * 上电初始化阶段调度器还没跑，SYS_I2C_Lock 是空操作，安全。 */
    OLED_Init();

    if (OLED_IsOnline() == 0U) {
        printf("[OLED] 寻址不到设备\r\n");
        return 1U;
    }
    OLED_ErrClear();
    if (OLED_Refresh() != 0U) {
        /* 能寻址但写不进去：上拉不足 / 走线过长 / 地址错。
         * IsOnline 在这类场合仍会返回 1，必须看 Refresh 的返回值和 ErrCount。 */
        printf("[OLED] 首屏刷新失败，LastErr=%u ErrCnt=%u\r\n",
               (unsigned)OLED_LastErr(), (unsigned)OLED_ErrCount());
        return 1U;
    }
    printf("[OLED] init ok, addr=0x3C\r\n");
    return 0U;
}

