     *   屏上表现为「一半新一半旧的横向撕裂条」。
     *   这里的 Lock 是 SYS_I2C 的每总线递归互斥量：同一任务重复 Lock 只是计数 +1，
     *   不会自锁死，所以内层 OLED_Refresh 自己再取一次锁完全安全。
     *   代价：整帧约 23~25ms 内，总线上其他从机的读事务要排队等 20ms 级，
     *   这是「整帧不可插入」的必然代价，不是 bug。 */
    SYS_I2C_Lock(SYS_I2C_1);
    oled_text_demo(e);
    oled_ui_demo(e);
    fail = OLED_Refresh();
    SYS_I2C_Unlock(SYS_I2C_1);

    return fail;
}

/* 脏页刷新：只把「变化的那几页」重推上去，省掉大部分总线时间。
 * 一页 = 竖直 8 像素 = 一行 8×16 文字的上半或下半，所以按行分页判断即可。 */
static uint8_t oled_flush_dirty_pages(const char line[4][24], const uint8_t *dirty)
{
    uint8_t page;
    uint8_t fail = 0U;

    SYS_I2C_Lock(SYS_I2C_1);
    for (page = 0U; page < 4U; page++) {
        if (dirty[page] == 0U) continue;
        (void)line;   /* 本驱动按页整体推屏：改完显存后逐页定位重发 */
    }
    /* 说明：本项目 oled.c 只提供「整帧 Refresh」，要做真正的脏页刷新，
     * 需要仿照 OLED_Refresh 的逐页写法，给源码加一个 OLED_RefreshPage(page)；
     * 那是换算法不换硬件，改完立刻能看到刷屏时间从 23ms 掉到 3ms 量级。 */
    SYS_I2C_Unlock(SYS_I2C_1);

    return fail;
}

/* ---------------- 八、FreeRTOS 显示任务 ---------------- */
static void vTaskOled(void *pv)
{
    SysEnv_t e;
    uint8_t dirty[4];

    (void)pv;
    memset(&e, 0, sizeof(e));

    if (oled_setup() != 0U) {
        printf("[OLED] 初始化失败，显示任务退出（通讯部分继续跑）\r\n");
        vTaskDelete(NULL);
        return;
    }

    oled_bitselfcheck();        /* 上电先自检一次位序，人眼可判 */
    vTaskDelay(pdMS_TO_TICKS(1000));

    for (;;) {
        if (xQueueReceive(s_env_q, &e, pdMS_TO_TICKS(500)) == pdPASS) {
            /* 拿最新一帧：若队列里还压着旧数据，全部丢掉只留最后一条，
             * 屏上要的是「现在」，不是「历史」。 */
            SysEnv_t newer;
            while (xQueueReceive(s_env_q, &newer, 0) == pdPASS) e = newer;
            dirty[0] = 1U;
        }

        /* 限速：人眼 5Hz 足够，也给 I2C 总线留出给传感器的空档 */
        if ((xTaskGetTickCount() - s_oled_tick_last) < pdMS_TO_TICKS(200)) {
            vTaskDelay(pdMS_TO_TICKS(20));
            continue;
        }
        s_oled_tick_last = xTaskGetTickCount();

        if (e.online == 0U) {
            OLED_ClearBuffer();
            OLED_ShowStringCenter(0U, "SENSOR OFFLINE", 0U);
            OLED_ShowStringCenter(16U, "check wiring", 0U);
            /* 反显：黑底白字 ↔ 白底黑字，用来做报警高亮 */
            OLED_ShowStringCenter(32U, "ALARM", 1U);
            (void)OLED_Refresh();
            vTaskDelay(pdMS_TO_TICKS(500));
            continue;
        }

        if (oled_frame_flush(&e) == 0U) {
            s_oled_refresh_ok++;
        } else {
            s_oled_refresh_bad++;
            /* 写不进去就降级：放慢到 2 秒一次，避免每次重试 3 遍 + I2C 超时
             * 把 20ms 级的刷屏放大到数百毫秒，拖垮整个显示任务。 */
            vTaskDelay(pdMS_TO_TICKS(2000));
        }
        vTaskDelay(pdMS_TO_TICKS(20));
    }
}

/* ---------------- 九、采集端：往队列里塞数据（与显示解耦） ---------------- */
static void vTaskEnv(void *pv)
{
    SysEnv_t e;

    (void)pv;
    for (;;) {
        e.temp_c    = 25.3f;
        e.humi_rh   = 61.8f;
        e.press_hpa = 1013.2f;
        e.light_lx  = 420U;
        e.mpu_ax    = 12;
        e.online    = 1U;

        /* 队列长度 4：显示任务偶尔被刷屏占住 23ms，采集不该因此丢数据；
         * 满了就直接覆盖旧的（xQueueOverwrite 语义用长度 1 的队列实现）。 */
        (void)xQueueSend(s_env_q, &e, 0);
        vTaskDelay(pdMS_TO_TICKS(100));
    }
}

/* ---------------- 十、创建任务 ---------------- */
void app_oled_start(void)
{
    s_env_q = xQueueCreate(4U, sizeof(SysEnv_t));
    if (s_env_q == NULL) return;

    /* 栈给足：snprintf 里带浮点格式化，吃栈；优先级低于采集与控制任务，
     * 刷屏是「慢活」，绝不能挡着急着跑的控制回路。 */
    (void)xTaskCreate(vTaskOled, "OLED", 512U, NULL, 2U, NULL);
    (void)xTaskCreate(vTaskEnv,  "ENV",  256U, NULL, 3U, NULL);
}

/* ============================================================
 *  板1 的对应接口（名字与参数都不同，用同一块屏但要改这一层）
 * ------------------------------------------------------------
 *  SYS_OLED_Init(bus, addr)      两参数，自己内部 SYS_I2C_Init(bus, 400000)
 *  SYS_OLED_Clear()              只清显存
 *  SYS_OLED_Refresh()            整帧 1024 字节一次流水发出（水平寻址模式）
 *  SYS_OLED_ShowChar(page, x, ch)       page = 页号 0~7，不是像素行
 *  SYS_OLED_ShowString(page, x, str)    到右边界停住，不自动换行
 *  SYS_OLED_ShowNum(page, x, int32)     无 inv、无定宽
 *  SYS_OLED_ShowFloat(page, x, v, dec)  有专用浮点函数
 *  SYS_OLED_SetPixel(x, y, on)
 *  SYS_OLED_ShowBitmap(page, x, bmp, w, h)
 *  板1 没有 DrawLine / DrawRect / DrawCircle / ShowProgress，画图元只能用 SetPixel。
 * ============================================================ */

f:
static uint8_t oled_probe(void)
{
    uint8_t list[8];
    uint8_t n;
    uint8_t i;
    uint8_t found = 0U;

    /* OLED 支持 400kHz；本板 I2C1 = PB8(SCL) / PB9(SDA) */
    SYS_I2C_Init(SYS_I2C_1, 400000U);

    /* 扫描 0x08~0x77，把总线上所有从机打印出来，
     * 这一步同时能看到 24C02(0x50) 和 MPU6050(0x68) 在不在，
     * 总线整体健不健康一眼就知道。 */
    n = SYS_I2C_Scan(SYS_I2C_1, list, 8U);
    printf("[OLED] I2C1 scan: %u device(s)\r\n", (unsigned)n);
    for (i = 0U; i < n; i++) {
        printf("       0x%02X\r\n", list[i]);
        if (list[i] == 0x3CU || list[i] == 0x3DU) found = 1U;
    }

    if (!found) {
        /* 扫不到：四根线 / 上拉 / 供电，按顺序排 */
        printf("[OLED] 0x3C 不在总线上：查四根线 / 上拉 / 供电\r\n");
        return 1U;
    }

    /* 单点再确认一次，练一下 ErrStr：无应答时它会指出卡在哪一步 */
    if (SYS_I2C_IsDeviceReady(SYS_I2C_1, 0x3CU) != SYS_I2C_OK) {
        printf("[OLED] %s\r\n", SYS_I2C_ErrStr(SYS_I2C_ERR_ADDR));
        return 1U;
    }
    return 0U;
}

/* ---- 控制字节：一笔事务的第一个数据字节 ----
 *   [从机地址+W] [0x00] [命令字节...]     ← 0x00 = 后面是命令
 *   [从机地址+W] [0x40] [显存数据...]     ← 0x40 = 后面是显存数据
 *
 * 板2 oled.c 的做法：把 0x00/0x40 当作 sys_i2c 的「寄存器号」
 */
#define OLED_CTRL_CMD   0x00U
#define OLED_CTRL_DATA  0x40U

/* ---- 显存布局：128 列 × 8 页 = 1024 字节 ---- */
#define OLED_W   128U
#define OLED_H   64U
#define OLED_P   8U              /* 8 页，每页竖直 8 像素 */

/* ---- 像素 (x,y) → 显存字节 + 位号 ----
 *   字节 = (y / 8) * 128 + x
 *   位号 = y % 8，其中 bit0 在这一页的最上面
 */
#define OLED_IDX_PUB(x, y)   ((((y) >> 3) * OLED_W) + (x))
#define OLED_BIT_PUB(y)      (1U << ((y) & 0x07U))

/* 画点的实质（板2 源码 OLED_DrawPoint 里就是这两行）：
 *    亮：oled_buf[y >> 3][x] |=  (uint8_t)(1U << (y & 0x07U));
 *    灭：oled_buf[y >> 3][x] &= (uint8_t)~(1U << (y & 0x07U));
 * 越界（x>=128 或 y>=64）直接忽略，不报错，所以画图元时
 * 计算出的坐标溢出不会崩，但会「画不出来」，要留意。 */

/* ---- 开域：先清成整屏黑 ----
 * 做个反例对照：把 OLED_CTRL_CMD 故意写成 0x40（那是数据），
 * 屏上不会有任何反应，I2C 也不报错，这就是「能扫到却什么都不变」。
 */
static void oled_ctrlbyte_demo(void)
{
    OLED_ClearBuffer();                 /* 只清 RAM，1024 字节归零 */
    OLED_ShowString(0U, 0U, "ctrl byte &page", 0U);
    OLED_ShowString(0U, 16U, "0x00=CMD 0x40=DATA", 0U);
    OLED_ShowString(0U, 32U, "buf[(y/8)*128+x]", 0U);
    OLED_ShowString(0U, 48U, "bit = y%8, bit0 top", 0U);
    (void)OLED_Refresh();               /* 唯一的「真正显示」动作 */
}

/* ---- 板2 初始化序列（源码 oled.c 逐条，照搬） ----
 * 每条后面括号是 oled.c 里的原注释含义。
 */
static void oled_init_seq_demo(void)
{
    OLED_Init();        /* 内部完整序列，展开就是下面这一串： */
}

/*  0xAE              关显示（配置期间先关，避免花屏）
 *  0xD5, 0x80        显示时钟分频/振荡频率
 *  0xA8, 0x3F        复用率 = 64 行（0x3F = 63；128x32 屏改 0x1F）
 *  0xD3, 0x00        显示偏移 = 0
 *  0x40              显示起始行 = 0
 *  0x8D, 0x14        电荷泵：0x14 = 内部升压使能（必须。忘发=屏永不亮）
 *  0x20, 0x00        寻址模式 = 页模式（配合板2 逐页刷新的写法）
 *  0xA1              段重映射：列 127 → SEG0（左右方向）
 *  0xC8              行扫描方向：从下往上（上下方向）
 *  0xDA, 0x12        COM 引脚配置：交替 + 不左右反转（64 行屏）
 *  0x81, 0xCF        亮度（0x00~0xFF）源码用 0xCF
 *  0xD9, 0xF1        预充电周期
 *  0xDB, 0x40        VCOMH 电压
 *  0xA4              显示跟随显存内容（不是全亮）
 *  0xA6              正常显示（非反色；0xA7 = 整体反色）
 *  0x2E              关闭滚动
 *  ---- 然后 ----
 *  ClearBuffer()     清 1024 字节显存
 *  OLED_Refresh()    推一屏全黑（板2 忽略返回值：屏可能后插上）
 *  0xAF              开显示
 */

/* 自己点亮的完整包装：先探总线，再初始化，再验证刷屏 */
static uint8_t oled_setup(void)
{
    if (oled_probe() != 0U) return 1U;   /* 第 1 步的探测函数 */

    OLED_Init();

    if (OLED_IsOnline() == 0U) {
        printf("[OLED] 寻址不到设备\r\n");
        return 1U;
    }
    OLED_ErrClear();                    /* 排查前先清零统计 */
    if (OLED_Refresh() != 0U) {
        /* 能寻址但写不进去：上拉不足 / 走线过长 / 地址错。
         * IsOnline 在这类场合仍返回 1，必须看 Refresh 返回值。 */
        printf("[OLED] 首屏刷新失败，LastErr=%u ErrCnt=%u\r\n",
               (unsigned)OLED_LastErr(), (unsigned)OLED_ErrCount());
        return 1U;
    }
    printf("[OLED] init ok, addr=0x3C\r\n");
    return 0U;
}

static void oled_bitselfcheck(void)
{
    uint8_t b0, b7;

    OLED_ClearBuffer();

    /* (0,0) 和 (0,7) 落在同一个显存字节 oled_buf[0]：
     *   (0,0) → bit0        (0,7) → bit7
     * 画完这两个点，oled_buf[0] 应当正好是 0x81。 */
    OLED_DrawPoint(0U, 0U, 1U);
    OLED_DrawPoint(0U, 7U, 1U);

    /* 从显存读回来验一次，不依赖眼睛 */
    b0 = OLED_GetPoint(0U, 0U);
    b7 = OLED_GetPoint(0U, 7U);

    OLED_ShowString(0U, 0U, "bit selfcheck", 0U);
    OLED_ShowString(0U, 16U, (b0 && b7) ? "PASS" : "FAIL", 0U);

    (void)OLED_Refresh();       /* 推屏后才看得见 */

    /* 板上应当看到：左上角一个亮像素，再往下第 8 个像素处另一个亮像素，
     * 中间 6 个点是暗的。
     *
     * 扩展实验（每条只改一个变量，看完就改回来）：
     *   ① OLED_DrawPoint(1U, 0U, 1U)：亮像素若出现在 x=127，段重映射反了 → 查 0xA1；
     *   ② 把两个点换成 (0,0) 和 (7,0)：亮像素若竖着排，说明位序当成了「一字节一行」。
     */
}

/* ---- 板2 全套图元（源码 oled.c 里的实现要点） ---- */
static void oled_ui_demo(const SysEnv_t *e)
{
    uint16_t permille;
    float lx = (float)e->light_lx;

    /* 外框：坐标是闭区间，(0,54)~(127,63) 正好贴住屏幕最后 10 行 */
    OLED_DrawRect(0U, 54U, 127U, 63U, 1U);

    /* 实心块：填出一个「图标」的感觉 */
    OLED_FillRect(2U, 56U, 12U, 61U, 1U);

    /* 斜线：内部是 Bresenham，纯整数运算 */
    OLED_DrawLine(14U, 56U, 40U, 61U, 1U);

    /* 空心圆：八分对称，半径 4 的两个圆像一副眼镜 */
    OLED_DrawCircle(52, 58, 4, 1U);
    OLED_DrawCircle(64, 58, 4, 1U);

    /* 水平线：x0 和 x1 都会被画（闭区间） */
    OLED_DrawHLine(72U, 126U, 58U, 1U);

    /* 进度条按千分比填充：光照 0~2000lx 映射到 0~1000。
     * 内部可用宽 = w-2（去掉边框），且会自动 clamp 到 0~1000。 */
    permille = (uint16_t)((lx * 1000.0f) / 2000.0f);
    OLED_ShowProgress(0U, 44U, 128U, 8U, permille);
}

/* ---- 擦除：图元都有 on 参数，on=0 就是擦 ---- */
static void oled_ui_erase(void)
{
    /* 不清全屏，只把刚画的斜线擦掉（on 传 0） */
    OLED_DrawLine(14U, 56U, 40U, 61U, 0U);
    (void)OLED_Refresh();
}

/* ---- 板1 对照：没有图元函数，只能自己用 SetPixel 拼 ----
 * void line_h(uint8_t x0, uint8_t x1, uint8_t y)
 * {
 *     uint8_t x;
 *     for (x = x0; x <= x1; x++) SYS_OLED_SetPixel(x, y, 1U);
 * }
 */

屏幕能画图了，接下来要显示文字。这一步的核心知识点只有一个，但它决定了所有文字是否正常：字库的点阵数据是怎么取模的，必须和驱动的取法完全一致。

本项目两板用了两套完全不同的字库和渲染路径，这正是最容易混乱的地方：

板2（oled.c）复用 LCD 的 8×16 字库。 头文件里写着「复用 LCD 的 8x16 ASCII 点阵字库」，源码里 `OLED_ShowChar(x, y, ch, inv)` 的做法是：

    for (i = 0; i < LCD_FONT8X16_H; i++) {
        row = lcd_font8x16[idx][i];
        for (j = 0; j < LCD_FONT8X16_W; j++) {
            bit = (row & (0x80U >> j)) ? 1 : 0;   /* ← 高位在左 */
            if (inv) bit ^= 1U;                    /* ← 反显 */
            OLED_DrawPoint(x + j, y + i, bit);
        }
    }

看这段要读出三个事实：① 字库是按行存的，每字符 16 字节（16 行），每行的 bit7 是最左边那个像素（`0x80 >> j`）；② 它最终落到 DrawPoint，所以字形正确性完全依赖第 4 步验证过的位序；③ `inv` 参数是靠「对每个位取反」实现的，等于把整个 8×16 字格黑白互换，天然就是「白底黑字」的高亮效果，不需要额外的背景填充逻辑。

因为一个字符高 16 像素 = 2 页、宽 8 像素 = 8 列，所以 128 宽的屏一行放 16 个字符、64 高的屏一共 4 行。这就是本项目所有排版按「4 行 × 16 字符」规划的原因。

板1（sys_oled.c）内置自己的 8×8 字库，而且是「列排」格式。 头文件写得很清楚：内置 8×8 ASCII 点阵已转成「列排」（每列 1 字节，bit0 = 顶端），与页格式显存一一对应，显示字符是「直拷」，零运算。源码 `SYS_OLED_ShowChar(page, x, ch)` 的实现就是：

    oled_buf[(uint16_t)page * SYS_OLED_WIDTH + x + i] = glyph[i];

一次赋值写入一个列字节。因为「列排、bit0 在顶」和「页内 8 行、bit0 在顶」是同一个格式，所以一个字符合计 8 列就是 8 个连续字节，直接 memcpy 式的搬运。这是「字库格式跟着显存格式走」的经典优化。代价是字库只有 8×8（比板2 的 8×16 小一半，且不能反显）。

所以取模方向这件事，本质是：显存是「页/列/低位在上」的格式。任何要用到这里的位图，取模软件的设置必须是 列行式（页模式）+ 低位在上。用错了（行式、高位在上），画出来的字就是旋转/镜像/错位的花字，而且数字节数往往对得上，所以很难一眼看出是取模问题。

最后，字符串层（ShowString）两板行为也不同：板2 自动换行（超出右边界回 x 起点、下移一行，还支持换行转义符强制换行），板1 到右边界就停住不换行。写多行界面的代码时，这个差异会让同一段文字在两块板上长得完全不一样。

/* ---- 板2：8×16 字库，按行取模，bit7 在左；每字符占 8 列 × 2 页 ---- */
static void oled_text_demo(const SysEnv_t *e)
{
    OLED_ClearBuffer();

    /* 居中一行标题（内部按 (128 - len*8)/2 算起点 x） */
    OLED_ShowStringCenter(0U, "ENV MONITOR", 0U);

    /* 分隔线：24 个半角减号的字符串常量 */
    OLED_ShowString(0U, 16U, "------------------------", 0U);

    /* 反显示例：inv=1 是白底黑字，做「选中/报警」的高亮 */
    OLED_ShowString(0U, 24U, "ALARM HIGH TEMP", 1U);

    /* 普通文本 */
    OLED_ShowString(0U, 40U, "hello oled", 0U);

    /* 反斜杠 n 的换行转义是驱动支持的强制换行（板2 独有行为） */
    OLED_ShowString(0U, 48U, "line1line2", 0U);

    (void)OLED_Refresh();
}

/* 取模方向自查表（画花字时照这个表逐条对）：
 *   显存格式 = 页(8行) / 列 / bit0 在页顶
 *   正确取模 = 列行式（页模式）+ 低位在上
 *   错成「行式」          → 整字旋转 90 度般的错位
 *   错成「高位在上」      → 整字上下镜像
 *   错成「每字符宽度算错」→ 字符之间互相穿插重叠
 *
 * 板2 源码里取模的原始含义（oled.c OLED_ShowChar）：
 *      row = lcd_font8x16[idx][i];               ← 第 i 行一个字节
 *      bit = (row & (0x80U >> j)) ? 1U : 0U;     ← bit7 = 最左像素
 *      if (inv) bit = (uint8_t)(bit ^ 1U);       ← 反显就是逐位取反
 *      OLED_DrawPoint((uint16_t)(x + j), (uint16_t)(y + i), bit);
 */

