/* ---- 完全避开浮点 printf 的路线：定点数自己拆 ---- */
static void oled_fixed_demo(int16_t temp_x100)
{
    int32_t v = (int32_t)temp_x100;      /* 2530 = 25.30C */
    uint8_t neg = 0U;

    if (v < 0) { neg = 1U; v = -v; }
    OLED_ShowString(0U, 32U, neg ? "T: -" : "T:  ", 0U);
    OLED_ShowNum(24U, 32U, (uint32_t)(v / 100), 2U, 0U);   /* 整数位，定宽 2 */
    OLED_ShowString(40U, 32U, ".", 0U);
    OLED_ShowNum(48U, 32U, (uint32_t)(v % 100), 2U, 0U);   /* 两位小数，定宽 2 */
    OLED_ShowString(64U, 32U, " C", 0U);
