 */
static void oled_init_seq_demo(void)
{
    oled_init();        /* 内部完整序列，展开就是下面这一串： */
}

/*  0xae              关显示（配置期间先关，避免花屏）
 *  0xd5, 0x80        显示时钟分频/振荡频率
 *  0xa8, 0x3f        复用率 = 64 行（0x3f = 63；128x32 屏改 0x1f）
 *  0xd3, 0x00        显示偏移 = 0
 *  0x40              显示起始行 = 0
 *  0x8d, 0x14        电荷泵：0x14 = 内部升压使能（必须。忘发=屏永不亮）
 *  0x20, 0x00        寻址模式 = 页模式（配合板2 逐页刷新的写法）
 *  0xa1              段重映射：列 127 → seg0（左右方向）
 *  0xc8              行扫描方向：从下往上（上下方向）
 *  0xda, 0x12        com 引脚配置：交替 + 不左右反转（64 行屏）
 *  0x81, 0xcf        亮度（0x00~0xff）源码用 0xcf
 *  0xd9, 0xf1        预充电周期
 *  0xdb, 0x40        vcomh 电压
 *  0xa4              显示跟随显存内容（不是全亮）
 *  0xa6              正常显示（非反色；0xa7 = 整体反色）
 *  0x2e              关闭滚动
 *  ---- 然后 ----
 *  clearbuffer()     清 1024 字节显存
 *  oled_refresh()    推一屏全黑（板2 忽略返回值：屏可能后插上）
 *  0xaf              开显示
 */

/* 自己点亮的完整包装：先探总线，再初始化，再验证刷屏 */
static uint8_t oled_setup(void)
{
    if (oled_probe() != 0u) return 1u;   /* 第 1 步的探测函数 */

    oled_init();

    if (oled_isonline() == 0u) {
        printf("[oled] 寻址不到设备\r\n");
        return 1u;
    }
    oled_errclear();                    /* 排查前先清零统计 */
    if (oled_refresh() != 0u) {
        /* 能寻址但写不进去：上拉不足 / 走线过长 / 地址错。
         * isonline 在这类场合仍返回 1，必须看 refresh 返回值。 */
        printf("[oled] 首屏刷新失败，lasterr=%u errcnt=%u\r\n",
               (unsigned)oled_lasterr(), (unsigned)oled_errcount());
        return 1u;
    }
    printf("[oled] init ok, addr=0x3c\r\n");
    return 0u;
} oled_init() 执行完之后：① 屏上整片干净的黑（没有残留雪花点、没有半屏乱码）；② oled_isonline() 返回 1；③ oled_refresh() 返回 0（0 表示 8 页全部写成功）；④ oled_errcount() 自 errclear 之后保持 0。
四个条件全过，屏就算「点亮了」。此时屏是黑的，黑屏就是成功，因为显存刚被清空，这一步本来就不该有内容。 漏发电荷泵（0x8d,0x14）是「i2c 一切正常但屏全黑」的第一原因，而且不报任何错。排查顺序永远是：先看这一条发了没有。
对比度不要照搬其他教程：本项目两板源码均用 0x81,0xcf。改小到 0x7f 只是变暗，但如果在昏暗环境里调试，很容易误判成「屏坏了」。
0xa5 是全屏点亮（老化测试用），不是「开显示」。真正的开显示是 0xaf。这两个混淆会出现「灯全亮但什么都不显示」的壮观场面。
板1（sys_oled.c）的 init 是两参数 sys_oled_init(bus, addr)，返回 0 才是成功、1 是无应答，和板2 的 void oled_init() 完全不同；板1 内部还会自己调 sys_i2c_init(bus, 400000) 和 sys_i2c_isdeviceready，所以板1 不需要先开总线。若总线上还有只认 100khz 的老器件，初始化完后可以再 sys_i2c_init(bus, 100000) 降回来（oled 仍可用）。
复用率 0xa8 必须和屏的实际行数匹配：128×32 的屏写 0x3f 就会出现「只显示一半、另一半错位」。
