    b0 = oled_getpoint(0u, 0u);
    b7 = oled_getpoint(0u, 7u);

    oled_showstring(0u, 0u, "bit selfcheck", 0u);
    oled_showstring(0u, 16u, (b0 && b7) ? "pass" : "fail", 0u);

    (void)oled_refresh();       /* 推屏后才看得见 */

    /* 板上应当看到：左上角一个亮像素，再往下第 8 个像素处另一个亮像素，
     * 中间 6 个点是暗的。
     *
     * 扩展实验（每条只改一个变量，看完就改回来）：
     *   ① oled_drawpoint(1u, 0u, 1u)：亮像素若出现在 x=127，段重映射反了 → 查 0xa1；
     *   ② 把两个点换成 (0,0) 和 (7,0)：亮像素若竖着排，说明位序当成了「一字节一行」。
     */
} 屏上左上角出现一上一下两个亮像素，竖直间隔 7 个像素；串口/日志里 pass；oled_getpoint(0,0)==1 且 oled_getpoint(0,7)==1。
再补一个「读回来」的硬验证：调试器里看 oled_buf[0] == 0x81。
这一步过了，就可以放心往上画线、画框、写文字，地基是对的。 最隐蔽的错法是把 `y>>3` 和 `y&7` 用反（写成 buf[y&7][x]），前几个点看着「差不多对」，一画满屏就彻底错位。
越界不报错：oled_drawpoint 在 x>=128 或 y>=64 时直接 return（板2 源码就是这么写的），所以算出负数坐标（无符号回绕成 65535）不会崩，只会静默画不出来。调试「图元某一段消失」时要先怀疑坐标越界。
板1 用的是 `sys_oled_setpixel(x, y, on)`，语义与板2 的 drawpoint 相同，但板1 没有 getpoint，想「读回来验证」在板1 上做不到，只能靠眼睛。这是两板接口不对等的一处，写跨板代码时要。
别在没 clearbuffer 的显存上做位序实验：旧内容的残留位会让「0x81」这个判据失效。
想验证得更狠一点，可以一次画一条竖线 x=0, y=0..7（8 个点），oled_buf[0] 应当等于 0xff，这是「一个字节管竖直 8 像素」最直观的证明。 ㉓ 本卡的第 2 步 · ㉓ 本卡的第 3 步 · 板2 oled_drawpoint / oled_getpoint · 板1 sys_oled_setpixel · ⑧ i2c 总线 画线、矩形、圆与进度条 有了正确的位序，图元就只是算法问题了，但在显存上画图元和「在纸上画图」有一个本质区别，值得讲清。

区别一：所有图元最终都要落到「置位/清位」这一个操作上。 板2 的实现很典型，oled_drawline 是 bresenham，oled_drawrect 是四条 hline/vline，oled_fillrect 是逐行 hline，oled_drawcircle 是八分对称画八次点，oled_showprogress 是先画外框再按比例填竖线。它们全部只调用 oled_drawpoint。这带来两个好处：越界处理只需要在唯一一个地方做一次（drawpoint 里 return），以及每一层都能独立测试。

区别二：画图元改的是显存里的位，而非「画上去」，所以有 on 参数。 板2 每个图元都有 `on` 参数（1 画、0 擦）。这不是可有可无的，不做全屏清的局部刷新，就是靠 `on=0` 把旧图形「擦掉」。理解这一点，才能理解为什么「局部刷新」可行：擦和画走同一套代码。

区别三：所有图元的坐标是「闭区间」。 oled_drawhline(x0, x1, y, on) 的 x0 和 x1 都会画，oled_drawrect(x0,y0,x1,y1,on) 画的是从 (x0,y0) 到 (x1,y1) 的四条边。所以矩形宽度是 `x1-x0+1`。写代码时忘记这个 +1，画出 127 宽而不是 128 宽的框，是很难发现的「差一像素」问题。

bresenham 为什么在这里比「按斜率算浮点」好？ 因为它只用整数加减和比较，没有乘除、没有浮点、没有累积误差，而且天然均匀。f407 有 fpu，浮点也不慢，但在显存逐点写这种每像素一次函数调用的场景里，省掉的每次除法都是实打实的循环开销。板2 的 drawline 和 lcd 模块共用同一套 bresenham，是为了复用与速度。

进度条和柱状图用的是千分比（permille，0~1000）而不是百分比。源码里 `oled_showprogress(x, y, w, h, permille)`：先画外框矩形，内部可用宽度是 `w-2`（去掉左右各 1 像素边框），填充宽度是 `(w-2) * permille / 1000`。用千分比是为了避免整数百分比在窄条上的量化误差（128 像素的条，1% 只有 1.28 像素）。它会自己把 permille 截到 1000 以内，超了不会画出去。

图标/位图的取模格式也是同一套页模型：板1 的 `sys_oled_showbitmap(page, x, bmp, w, h)` 要求数据「按页、列排，先第 0 页 8 行逐列 1 字节，再第 1 页……每字节 bit0 在页顶」。取模软件的设置必须是「页模式/列行式、低位在上」。这个格式与显存格式一模一样，所以 showbitmap 可以整块搬运，不需要任何转换。 ① 先画只有 1 像素宽/高的线，确认端点位置（尤其确认闭合区间没算错）。
② 画矩形框 drawrect，再 fillrect 填充，看边框占了几像素、填充有没有盖住边框。
③ 画圆：圆心 + 半径，看边缘有没有缺口、有没有明显不对称。
④ 画进度条：传 0、500、1000 三个值，看空/半/满，以及外框是否完整。
⑤ 两板差异：板2 有全套图元，板1 只有 setpixel，板1 画线/框要自己写循环。 /* ---- 板2 全套图元（源码 oled.c 里的实现要点） ---- */
static void oled_ui_demo(const sysenv_t *e)
{
    uint16_t permille;
    float lx = (float)e->light_lx;

    /* 外框：坐标是闭区间，(0,54)~(127,63) 正好贴住屏幕最后 10 行 */
    oled_drawrect(0u, 54u, 127u, 63u, 1u);

    /* 实心块：填出一个「图标」的感觉 */
    oled_fillrect(2u, 56u, 12u, 61u, 1u);

    /* 斜线：内部是 bresenham，纯整数运算 */
    oled_drawline(14u, 56u, 40u, 61u, 1u);

    /* 空心圆：八分对称，半径 4 的两个圆像一副眼镜 */
    oled_drawcircle(52, 58, 4, 1u);
    oled_drawcircle(64, 58, 4, 1u);

    /* 水平线：x0 和 x1 都会被画（闭区间） */
    oled_drawhline(72u, 126u, 58u, 1u);

    /* 进度条按千分比填充：光照 0~2000lx 映射到 0~1000。
     * 内部可用宽 = w-2（去掉边框），且会自动 clamp 到 0~1000。 */
    permille = (uint16_t)((lx * 1000.0f) / 2000.0f);
    oled_showprogress(0u, 44u, 128u, 8u, permille);
}

/* ---- 擦除：图元都有 on 参数，on=0 就是擦 ---- */
static void oled_ui_erase(void)
{
    /* 不清全屏，只把刚画的斜线擦掉（on 传 0） */
    oled_drawline(14u, 56u, 40u, 61u, 0u);
    (void)oled_refresh();
}

/* ---- 板1 对照：没有图元函数，只能自己用 setpixel 拼 ----
 * void line_h(uint8_t x0, uint8_t x1, uint8_t y)
 * {
 *     uint8_t x;
 *     for (x = x0; x <= x1; x++) sys_oled_setpixel(x, y, 1u);
 * }
 */ 屏的最下面 10 行出现一条完整的边框条，里面有实心块、斜线、两个圆和一段水平线；进度条在 lx=0 时全空、lx=1000 时半满、lx=2000 时全满。
四个关键检查：① 边框的右边和下边没有被裁掉（说明闭区间算对了）；② 圆的左右上下对称（说明八分对称画法没漏象限）；③ 进度条在 0 和 1000 两个端点没有溢出外框；④ 斜线是连续的单像素宽，没有断点。 闭区间。oled_drawrect(x0,y0,x1,y1) 的宽度是 x1-x0+1。想画满 128 列必须写 x1=127，写 x1=128 会被 drawpoint 静默忽略掉最后一列。
先画框再填充时， fillrect 会不会盖住边框，板2 的 fillrect 从 y0 填到 y1 全填，会覆盖边框，想要边框可见就要留 1 像素内缩。
大量 drawpoint 调用的开销是真实的：板2 的每个公共函数都自己取一次锁（oled_drawpoint 内部 oled_frame_lock），所以 fillrect 里逐行调 drawhline、drawhline 再逐列调 drawpoint，就是几百万次「取锁/放锁」的调用链。递归锁同一个任务只是计数加减，代价可接受，但这就是为什么绘图不要在中断里做、也不要每个像素都套一层自己的 lock。
画大幅动态图形（例如实时波形）时，逐点画 + 全屏刷新的开销会让只能做到几 hz。真正的做法是脏页刷新（见第 10 步），只推变化的那一两页。
板1 没有 drawline/drawrect/drawcircle/showprogress，用板1 的 api 直接写板2 的例程会编译不过，这是跨板移植最常见的报错来源。 ㉓ 本卡的第 4 步 · ㉓ 本卡的第 7 步 · 板2 oled_drawline / oled_drawrect / oled_fillrect / oled_drawcircle / oled_showprogress / oled_drawhline / oled_drawvline · 板1 sys_oled_setpixel 显示字符与字符串：字库取模方向决定成败 屏幕能画图了，接下来要显示文字。这一步的核心知识点只有一个，但它决定了所有文字是否正常：字库的点阵数据是怎么取模的，必须和驱动的取法完全一致。

本项目两板用了两套完全不同的字库和渲染路径，这正是最容易混乱的地方：

板2（oled.c）复用 lcd 的 8×16 字库。 头文件里写着「复用 lcd 的 8x16 ascii 点阵字库」，源码里 `oled_showchar(x, y, ch, inv)` 的做法是：

    for (i = 0; i < lcd_font8x16_h; i++) {
        row = lcd_font8x16[idx][i];
        for (j = 0; j < lcd_font8x16_w; j++) {
            bit = (row & (0x80u >> j)) ? 1 : 0;   /* ← 高位在左 */
            if (inv) bit ^= 1u;                    /* ← 反显 */
            oled_drawpoint(x + j, y + i, bit);
        }
    }

看这段要读出三个事实：① 字库是按行存的，每字符 16 字节（16 行），每行的 bit7 是最左边那个像素（`0x80 >> j`）；② 它最终落到 drawpoint，所以字形正确性完全依赖第 4 步验证过的位序；③ `inv` 参数是靠「对每个位取反」实现的，等于把整个 8×16 字格黑白互换，天然就是「白底黑字」的高亮效果，不需要额外的背景填充逻辑。

因为一个字符高 16 像素 = 2 页、宽 8 像素 = 8 列，所以 128 宽的屏一行放 16 个字符、64 高的屏一共 4 行。这就是本项目所有排版按「4 行 × 16 字符」规划的原因。

板1（sys_oled.c）内置自己的 8×8 字库，而且是「列排」格式。 头文件写得很清楚：内置 8×8 ascii 点阵已转成「列排」（每列 1 字节，bit0 = 顶端），与页格式显存一一对应，显示字符是「直拷」，零运算。源码 `sys_oled_showchar(page, x, ch)` 的实现就是：

    oled_buf[(uint16_t)page * sys_oled_width + x + i] = glyph[i];

一次赋值写入一个列字节。因为「列排、bit0 在顶」和「页内 8 行、bit0 在顶」是同一个格式，所以一个字符合计 8 列就是 8 个连续字节，直接 memcpy 式的搬运。这是「字库格式跟着显存格式走」的经典优化。代价是字库只有 8×8（比板2 的 8×16 小一半，且不能反显）。

所以取模方向这件事，本质是：显存是「页/列/低位在上」的格式。任何要用到这里的位图，取模软件的设置必须是 列行式（页模式）+ 低位在上。用错了（行式、高位在上），画出来的字就是旋转/镜像/错位的花字，而且数字节数往往对得上，所以很难一眼看出是取模问题。

最后，字符串层（showstring）两板行为也不同：板2 自动换行（超出右边界回 x 起点、下移一行，还支持换行转义符强制换行），板1 到右边界就停住不换行。写多行界面的代码时，这个差异会让同一段文字在两块板上长得完全不一样。 ① 先显示单个字符 'a'，确认字形正、不歪、不花。
② 再显示整串 "hello oled"，确认字符间距是 8 像素（字格宽），没有重叠。
③ 显示 16 个字符的一整行，确认正好占满 128 像素。
④ 在板2 上试 oled_showstring(0,0,"...",1) 的反显，做高亮效果。
⑤ 试 oled_showstringcenter，确认居中算法是按 8 像素字格算的。
⑥ 换到板1 时，把函数的第一个参数从「像素 y」改成「页号 0~7」。 /* ---- 板2：8×16 字库，按行取模，bit7 在左；每字符占 8 列 × 2 页 ---- */
static void oled_text_demo(const sysenv_t *e)
{
    oled_clearbuffer();

    /* 居中一行标题（内部按 (128 - len*8)/2 算起点 x） */
    oled_showstringcenter(0u, "env monitor", 0u);

    /* 分隔线：24 个半角减号的字符串常量 */
    oled_showstring(0u, 16u, "------------------------", 0u);

    /* 反显示例：inv=1 是白底黑字，做「选中/报警」的高亮 */
    oled_showstring(0u, 24u, "alarm high temp", 1u);

    /* 普通文本 */
    oled_showstring(0u, 40u, "hello oled", 0u);

    /* 反斜杠 n 的换行转义是驱动支持的强制换行（板2 独有行为） */
    oled_showstring(0u, 48u, "line1line2", 0u);

    (void)oled_refresh();
}

/* 取模方向自查表（画花字时照这个表逐条对）：
 *   显存格式 = 页(8行) / 列 / bit0 在页顶
 *   正确取模 = 列行式（页模式）+ 低位在上
 *   错成「行式」          → 整字旋转 90 度般的错位
 *   错成「高位在上」      → 整字上下镜像
 *   错成「每字符宽度算错」→ 字符之间互相穿插重叠
 *
 * 板2 源码里取模的原始含义（oled.c oled_showchar）：
 *      row = lcd_font8x16[idx][i];               ← 第 i 行一个字节
 *      bit = (row & (0x80u >> j)) ? 1u : 0u;     ← bit7 = 最左像素
 *      if (inv) bit = (uint8_t)(bit ^ 1u);       ← 反显就是逐位取反
 *      oled_drawpoint((uint16_t)(x + j), (uint16_t)(y + i), bit);
 */

/* ---- 板1 对照：内置 8×8 列排字库，一个字 = 8 个连续字节直拷 ----
 * void sys_oled_showchar(uint8_t page, uint8_t x, char ch)
 * {
 *     ... 取 glyph[8] ...
 *     for (i = 0; i < 8u; i++)
 *         oled_buf[(uint16_t)page * sys_oled_width + x + i] = glyph[i];
 * }
 * page 是页号 0~7，不是像素行；且没有 inv 反显参数。
 */ 屏上出现居中的 env monitor 标题、一条 24 字符宽的分隔线、一行反显（白底黑字）的 alarm high temp，以及正常的 hello oled。
四个检查：① 每个字符字形正（不歪不镜像）；② 字符间距均匀、不重叠；③ 16 个字符正好占满一整行 128 像素；④ 反显那一行确实是「黑字白底」，与相邻的「白字黑底」形成明显对比。 字库取模方向与显存格式必须完全一致（页/列/低位在上）。最常见的误配是「行式 + 高位在上」，画出来的字像被切碎又重排，而且字节数看起来是对的，极具欺骗性。
板2 的字库复用 lcd_font.h（8×16），板1 用自己的 8×8。两者不能互换，换了就是花字，不是字库坏了，是格式不对。
一个字符高 16 像素 = 跨 2 页。所以板2 里「一行文字」实际占 2 个页，改一行文字会动到 2 页显存；做脏页刷新时按页判断要这个对应关系。
字符编码只支持 ascii 0x20~0x7e：板2 把范围外的字符当空格处理，板1 是「其余字符显示为空格」。所以中文直接显示会是一片空白，不会报错，想显示中文必须自己加中文点阵字库。
板2 的 `inv` 参数在板1 不存在。从板2 移植文字代码到板1 时，多出来的那个参数会导致编译错误；要发光高亮只能自己画一个 fillrect 当背景。
板2 的 showstring 支持换行转义符和自动换行，板1 到右边界停住不换行。用同一份界面代码时，长字符串在板1 上会被直接截断。
字符串字面量里如果要显示半角双引号，在 c 源码里要写转义；而在本卡片的数据文件里写 c 代码时，字面 crlf 要写成双反斜杠 r 双反斜杠 n（见本文件开头的数据格式约定）。 ㉓ 本卡的第 4 步 · ㉓ 本卡的第 7 步 · 板2 oled_showchar / oled_showstring / oled_showstringcenter · 板1 sys_oled_showchar / sys_oled_showstring · 板2 lcd_font.h 的 lcd_font8x16 显示数字与浮点：定长对齐、别用 %f 数字显示比字符串多一个陷阱：它的宽度会变。`25`、`-25`、`1013.2`、`-0.5` 的字符数都不同，如果每次都从同一个 x 开始画、却不清掉上一次的残留，屏上就会出现「25.3」变成「25.30」、或者「1013.2」变成「1013.20」这种叠字；若每次全屏清，又会闪。这是嵌入式 ui 的经典问题。

本项目给了两种武器，理解它们的分工很重要：

武器一：先在 ram 里拼字符串，再整串刷上去。 这是最灵活也最好控的做法，成品代码用的就是它，`snprintf` 把变长的数值格式化成固定宽度（带前导空格）的字符串，然后 `oled_showstring` 一次贴上。前导空格会自然覆盖掉上一次的残留字符（空格字符本身就是「8×16 的空白」），所以既不用全屏清、也不会叠字。这也是为什么模板里写 `%6.2f` 而不是 `%f`：宽度固定了，`25.30` 和 `-5.00` 占位一致，数字就不会左右跳。

武器二：驱动自带的数字函数。 板2 有两个：

    oled_shownum(x, y, num, len, inv)          /* uint32，定宽，前导补空格 */
    oled_showfixed(x, y, val, frac, int_len, inv)  /* 定点小数，不用浮点 */

板2 的 shownum 是「定宽显示无符号整数，前导补空格，方便数值原地刷新」，它是无符号的 uint32，负数要自己转或换 showfixed。showfixed 的示例是 `oled_showfixed(0, 32, 253, 1, 3, 0)` 显示成 ` 25.3`（val=253、frac=1 表示 25.3），它是不用浮点的定点实现，这对没有 fpu 或不想在中断/任务里触发浮点上下文的场景很有价值，参数里的 int_len 控制整数部分宽度。

板1 的武器二不一样：`sys_oled_shownum(page, x, int32_t num)` 不是定宽（内部就是从左到右逐位输出，负数先画个 '-'），`sys_oled_showfloat(page, x, value, dec)` 则有专用浮点函数，内部自己做四舍五入和进位（小数进位会回卷到整数部分），dec 最大 3 位。所以板1 反而比板2 更方便直接显示浮点，两板的数字能力相反，这是移植时最容易出错的一处。

「别用 %f」的确切含义：并非「用了会错」，而是许多嵌入式 printf 的浮点支持默认关闭，需要额外链接浮点格式化支持，会显著增加代码量与栈占用。所以本项目成品代码里用 snprintf 的 %f 只出现在「已经确认工具链开了浮点 printf」的场合；更稳妥的路线是先算成整数再格式化（温度 ×100 存 int16，显示时拆成整数位和小数位），这正是 showfixed 的思路，也是两条数据链路上通用的做法。

最后别忘了板1 的 `showfloat` 会把负数先画 '-'，写定宽对齐时要把它多占的一个字符宽度算进去。 ① 先用整型：oled_shownum 显示 0、9、12345，观察宽度变化带来的对齐问题。
② 用 shownum 的 len 参数做定宽：显示值 5、len=5，看是不是「    5」（前导补空格）。
③ 用 showfixed 显示定点小数：val=253、frac=1 → 25.3。
④ 在板2 上用自家 showstring + snprintf 做定宽，比较两种做法的灵活性。
⑤ 连续刷新同一个数值字段（例如每次 +1），确认没有叠字、也没有整屏闪烁。
⑥ 换到板1 时改用 sys_oled_shownum / sys_oled_showfloat， shownum 不定宽。 /* ---- 板2：定长对齐的完整做法（成品代码里的那一套） ---- */
static void oled_numbers_demo(const sysenv_t *e)
{
    oled_clearbuffer();

    /* 关键：所有变长字段都先格式化成「固定宽度 + 前导空格」的字符串，
     *   再整串刷上去。前导空格天然覆盖上一次的残留，既不用清屏也不叠字。
     *   格式化出来的字符串缓存到 s_line_last[]，下一轮还能用来做脏页比较。 */
    snprintf(s_line_last[0], sizeof(s_line_last[0]),
             "t: %6.2f c  ", (double)e->temp_c);
    snprintf(s_line_last[1], sizeof(s_line_last[1]),
             "h: %6.2f %%  ", (double)e->humi_rh);
    snprintf(s_line_last[2], sizeof(s_line_last[2]),
             "p: %7.1f hpa", (double)e->press_hpa);
    snprintf(s_line_last[3], sizeof(s_line_last[3]),
             "l: %5u lx  ", (unsigned)e->light_lx);

    oled_showstring(0u, 24u, s_line_last[0], 0u);
    oled_showstring(0u, 32u, s_line_last[1], 0u);
    oled_showstring(0u, 40u, s_line_last[2], 0u);
    oled_showstring(0u, 48u, s_line_last[3], 0u);

    (void)oled_refresh();
}

/* ---- 完全避开浮点 printf 的路线：定点数自己拆 ---- */
static void oled_fixed_demo(int16_t temp_x100)
{
    int32_t v = (int32_t)temp_x100;      /* 2530 = 25.30c */
    uint8_t neg = 0u;

    if (v < 0) { neg = 1u; v = -v; }
    oled_showstring(0u, 32u, neg ? "t: -" : "t:  ", 0u);
    oled_shownum(24u, 32u, (uint32_t)(v / 100), 2u, 0u);   /* 整数位，定宽 2 */
    oled_showstring(40u, 32u, ".", 0u);
    oled_shownum(48u, 32u, (uint32_t)(v % 100), 2u, 0u);   /* 两位小数，定宽 2 */
    oled_showstring(64u, 32u, " c", 0u);
    (void)oled_refresh();
}

/* ---- 板1 对照：有专用浮点函数，但 shownum 不定宽 ----
 * sys_oled_shownum(2, 0, -1234);           函数式，内部逐位输出，不是定宽
 * sys_oled_showfloat(2, 48, 25.43f, 1);    专用浮点，四舍五入，dec 最大 3
 *   例：25.43f, dec=1 → 屏上显示 25.4
 * 小数进位会回卷到整数部分；负数会先画一个 '-'，占 1 个字符宽。
 */ 连续刷新同一个数字字段（例如每秒 +1），屏上数字原地变化：① 没有出现「12」和「3」叠成「123」以外的残留；② 位数变长变短时不会左右跳动；③ 全屏不闪。
对温度做一次极端测试：从 25.30 变到 -5.00，再变到 1013.2，三次都保持列对齐。
再验一次「不用浮点」的那条路：把 temp_x100=2530 与 253、-5 都跑一遍，输出分别是 25.30、2.53、-0.05。 定宽靠前导空格，不是靠清屏。以为「每次都 clear 一下就好」的做法会闪，而且会中断其他区域的显示（局部刷新时尤其明显）。
板2 的 `oled_shownum` 是 uint32、且有 len 参数（定宽）；板1 的 `sys_oled_shownum` 是 int32、没有 len（不定宽）。同名不同参、连符号性都相反，这是两板最容易搞混的一对函数，必须查源码确认。
浮点能力也是反的：板2 没有 showfloat（要用 showfixed 做定点，或自己 snprintf），板1 有 sys_oled_showfloat。别按名字想当然。
`%f` 能不能用取决于工具链有没有开浮点 printf 支持。没开时链接会报 undefined reference to _printf_float 之类，或者干脆不输出，所以成品代码优先走「乘 100 存整数 + 自己拆显示」这条路。
`snprintf` 吃栈：成品代码给显示任务开 512 字（word）栈，就是为了容纳带格式化的调用链。栈给小了会 hardfault，而且现象是「偶发死机」，极难定位。
小数进位别忘了：25.999 显示 1 位小数应当是 26.0，不是 25.9。板1 的 showfloat 内部处理了 `if (frac >= scale) { frac -= scale; ip++; }`，自己实现时要照做。 ㉓ 本卡的第 6 步 · ㉓ 本卡的第 8 步 · 板2 oled_shownum / oled_showfixed · 板1 sys_oled_shownum / sys_oled_showfloat 多任务下的整帧加锁：40 次事务不能被插进来 这一步是本项目 oled 部分真正的难点，也是它和「网上抄个 oled 驱动」最大的区别。

先看问题的规模。 板2 的 oled_refresh 是「逐页写」：8 页，每页先发一条 3 字节的定位命令（页地址 0xb0|p、列低 0x00、列高 0x10），再把 128 字节显存分成 4 块（oled_chunk = 32）发出去。所以刷一屏 = 8 × (1 + 4) = 40 次独立的 i2c 事务，整屏 1024 字节在 400khz 下约 23~25ms。

问题来了：这 40 次事务之间不是原子的。 freertos 是抢占式调度，i2c1 上还挂着 24c02（0x50）和 mpu6050（0x68）。如果显示任务刷到第 3 页时被抢占，另一个任务插进来发了一条 mpu6050 的读事务，然后显示任务接着刷第 4 页，同一帧的 40 次事务被别的器件插断了。后果并非「数据错」，而是屏上出现一半新一半旧的横向撕裂条：上半屏是这一帧的内容，下半屏是上一帧的。因为写进去的每一页本身都是合法的，只是它们不属于同一帧。

解决方案：整帧持锁。 项目在 sys_i2c 里提供了每总线一把的递归互斥量：`sys_i2c_lock(bus)` / `sys_i2c_unlock(bus)`。板2 的 oled.c 用两个宏包住：

    #define oled_frame_lock()    sys_i2c_lock(oled_i2c_id)
    #define oled_frame_unlock()  sys_i2c_unlock(oled_i2c_id)

而 oled_refresh 内部整段就持着这把锁，从第 1 页到第 8 页，一次都不放。

为什么要用「递归」锁？ 因为 oled.c 里每个公共函数都自己取锁（clearbuffer、drawpoint、showchar……全都取）。于是会出现「外层包一段 → 内层函数各自再取」的嵌套：`oled_clear()` 取锁 → 调 `oled_clearbuffer()`（再取一次）→ 调 `oled_refresh()`（再取一次）。如果锁不能重入，同一个任务第二次 lock 就会把自己锁死（经典的死锁）。递归锁的语义是「同一任务重复 lock 只是计数 +1，配对 unlock 递减」，所以这种嵌套天然安全。

为什么绘图函数（只改 ram）也要取锁？ 因为它们会和 refresh 并发。如果刷到第 5 页时另一个任务改了显存，那第 5~8 页推上去的就不是同一帧的内容，同一块显存被写的同时被读。锁保护的既是「总线」这个共享资源，也是「帧缓冲」这个共享资源。

代价必须讲明白： 整帧持锁期间，mpu6050 / 24c02 的读事务进不来，要等 20ms 量级。这是「整帧不可插入」的必然代价，不是可以优化掉的 bug。所以：
- 刷屏频率要克制（成品代码限到 5hz，并给传感器留空档）；
- 绝对不要在中断里调用任何 oled 公共函数，sys_i2c 用 `__get_ipsr()` 判断中断上下文并自动跳过加锁，在中断里调用等于「无锁直冲」，同时 20ms 级的刷屏会直接毁掉实时性；
- 加锁不关中断、也不该关：用 `__disable_irq` 保护 23ms 的刷屏会把整个系统的时间基准搞崩；
- 上电初始化阶段（调度器未启动）加锁是空操作，那时单线程，本来就没有并发，所以安全。

板1 的实现思路一样，但规模小得多：它用水平寻址模式设好「整屏窗口」（0x21 设列 0~127、0x22 设页 0~7），然后一次事务把 1024 字节流水发完。整帧只有 1~2 次事务，仍然持锁，但被插断的窗口小得多。 ① 确认 sys_i2c 的锁是每总线一把、递归的（sys_i2c.h 区块 2b 有完整语义说明）。
② 用 oled_frame_lock/unlock 宏包住「改显存 + 推屏」的整段操作。
③ 验证嵌套安全：oled_clear() 内部会嵌套三层取锁，跑起来不该卡死。
④ 造一个并发场景：让显示任务持续刷屏，同时另一个任务高频读 mpu6050，看屏上有没有撕裂条。
⑤ 检查中断：确认没有任何 oled 调用出现在 isr 里。
⑥ 测一次最坏情况：拔掉屏，看 oled_refresh 因重试+超时放大到数百毫秒时，任务有没有降级处理。 /* ---- 板2：整帧持锁（源码 oled_refresh 的骨架） ---- */
uint8_t oled_refresh(void)
{
    uint8_t  p;
    uint16_t off;
    uint8_t  fail = 0u;

    /* 40 次事须须在同一临界区内，否则别的器件会插进这一帧，
     *   屏上就是「一半新一半旧」的撕裂横条。 */
    oled_frame_lock();

    for (p = 0u; p < oled_page_cnt; p++) {
        uint8_t page_ok = 1u;
        uint8_t pos[3];

        /* 3 条定位命令合并成一次事务：页地址 + 列低 + 列高 */
        pos[0] = (uint8_t)(0xb0u | p);
        pos[1] = 0x00u;
        pos[2] = 0x10u;
        if (oled_wr(0x00u, pos, 3u) != 0u) page_ok = 0u;

        /* 一页 128 字节，按 oled_chunk = 32 分成 4 块 */
        for (off = 0u; off < oled_width; off += oled_chunk) {
            uint16_t n = oled_chunk;
            if ((uint16_t)(off + n) > oled_width) n = (uint16_t)(oled_width - off);
            if (oled_wr(0x40u, &oled_buf[p][off], n) != 0u) page_ok = 0u;
        }

        if (page_ok == 0u) fail++;      /* 返回失败页数，调用方可降级 */
    }

    oled_frame_unlock();
    return fail;
}

/* ---- 应用层：把「一组绘图 + 一次推屏」整体原子化 ---- */
static uint8_t oled_frame_flush(const sysenv_t *e)
{
    uint8_t fail;

    /* 外层再包一层锁：保证从「开始改显存」到「推屏结束」之间，
     * 没有任何别的任务能看到半成品的显存。内层 oled_refresh 自己
     * 也会取锁，递归锁允许重入，不会自锁死。 */
    sys_i2c_lock(sys_i2c_1);
    oled_text_demo(e);
    oled_ui_demo(e);
    fail = oled_refresh();
    sys_i2c_unlock(sys_i2c_1);

    return fail;
}

/* ---- 板1 对照：整帧一次性流水发出（水平寻址模式） ----------------
 * sys_oled_refresh() 内部：
 *     tmp[0]=0x21; tmp[1]=0x00; tmp[2]=127;  ← 设列窗口 0~127
 *     tmp[0]=0x22; tmp[1]=0x00; tmp[2]=7;    ← 设页窗口 0~7
 *     然后一次事务把 1024 字节全部发出。
 * 事务数少，但同样持锁；代价是长事务期间总线被独占的时间反而更集中。
 */ 屏上不再出现「上半屏新、下半屏旧」的横向撕裂条，即使另一个任务在高频读 mpu6050。
三个可观测的验证点：① 让显示任务以 20hz 疯狂刷屏、同时让 i2c 读任务以 200hz 读 mpu6050，观察 1 分钟无撕裂；② 串口打印一次刷屏耗时，应当在 23~25ms（400khz）；③ 最坏情况测试：刷屏期间读 mpu6050 的耗时会被拉长到 20ms 量级，这是预期行为，不是故障，日志里看到它变慢不要去「修」。 中断里调用 oled 任何公共函数都是错的：sys_i2c 检测到中断上下文会自动跳过加锁，于是在中断里既没有互斥保护，又会因为 20ms 级刷屏拖垮整个实时性。isr 里要显示，只能发队列/信号量把活交给任务。
不要用 `__disable_irq` / `taskenter_critical` 来保护刷屏。锁的设计就是「让出 cpu 等」，不关中断；关 23ms 中断会直接毁掉系统时间基准（tick、串口、adc 全都受影响）。
递归锁是这套写法成立的前提。如果换成普通二值信号量，oled_clear → clearbuffer → refresh 这条嵌套链会在第二次 lock 处自死锁，而且现象是「一调用就卡住」，很容易误判成硬件问题。
代价要心里有数：整帧持锁期间，24c02 存日志、mpu6050 取姿态都要排队等 20ms 量级。如果控制回路里 mpu6050 是 1khz 采样的，那显示刷新频率就必须压到很低（或改成脏页刷新），否则姿态控制会被屏拖垮。
refresh 的返回值必须处理。屏没插好时，每次 oled_wr 会重试 oled_retry=3 次并等 i2c 超时，最坏可以把 23ms 放大到数百毫秒。成品代码的做法是失败后降级到 2 秒一次，避免显示任务把 cpu 和总线都占死。
板2 的 `oled_isonline()` 只看「发地址有没有应答」，「能寻址」不等于「写得进去」：上拉不足或走线过长时它仍返回 1。判断「到底写没写进去」要看 oled_refresh() 的返回值和 oled_errcount()。 ㉓ 本卡的第 3 步 · ㉓ 本卡的第 10 步 · ① freertos 任务 · ⑧ i2c 总线 · sys_i2c_lock · sys_i2c_unlock · sys_i2c_count · sys_i2c_writebytes · 板2 oled_refresh / oled_errcount / oled_lasterr 接进 freertos 显示任务，和传感器数据对接 到这里屏本身完全能用了。但必须如实说明本项目的现状：这两个 oled 模块目前全工程没有调用者。板2 的 `oled_init` 只在 `oled.c:101` 定义，板1 的 `sys_oled_init` 只在 `sys_oled.c:259` 定义，两板的 `main.c` 都没有 include 对应的头、也没有调用，它是一套写好但还没接线的驱动。这一步要把现有任务真正接进去，而非「改现有任务」，是本卡的核心交付步骤。

第一步：解耦。 显示任务绝不能自己去做传感器读取。原因有三：① 传感器读取的时序要求（例如 dht11 的微秒级时序、mpu6050 需要在固定周期采样）和刷屏的 23ms 阻塞互相冲突；② 刷屏期间持锁 20ms，采集任务不该被连带阻塞；③ 采集频率和显示频率天然不同（采集可能 10hz，人眼 5hz 就够）。所以正确结构是：采集任务 → 队列 → 显示任务。

第二步：队列的取舍。 显示是「要最新值」而不是「要每一个值」的典型场景，所以：队列长度不用大（4 足够），而且显示任务拿到一帧后应该把队列里压着的旧数据全部抽干、只留最后一条（成品代码里那个 while 循环就是在做这件事）。如果老老实实按 fifo 一条条显示，会永远在追历史，屏上显示的是几秒前的数据。

第三步：限速与降级。 人眼 5hz 完全够，所以加一个 tick 判断，200ms 没到就 vtaskdelay 让出 cpu。降级路径也必须有：oled_refresh 返回非 0（有页没写成功）时，把刷新周期放慢到 2 秒，避免在屏故障时反复重试把系统拖垮；同时累计 s_oled_refresh_ok / s_oled_refresh_bad 两个计数，遥测里能看到屏的健康度。

第四步：任务参数。 显示任务的优先级应当低于采集和控制任务，刷屏是慢活，绝不能挡着急着跑的控制回路；栈要给足（成品代码给 512 字），因为 snprintf 带格式化的调用链吃栈。

第五步：异常态要有画面。 传感器掉线时（online==0）不能只是继续显示旧值，那会让操作员以为数据是新的。正确做法是整屏换成醒目的告警画面（成品代码里用反显的 alarm 强调）。显示系统的职责之一是让异常显眼，不是让画面好看。

最后：上电自检画面。 成品代码在任务开头调了一次 oled_bitselfcheck 并停 1 秒，保留一个「屏自己能证明自己活着」的画面，在现场排障时极其有用。 ① 在 main 里（或者一个 app_oled_start 里）创建队列和两个任务：采集任务、显示任务。
② 采集任务周期采数据、xqueuesend 塞进队列，不碰 oled。
③ 显示任务：xqueuereceive 拿数据 → 抽干队列只留最新 → 限速判断 → 调 oled_frame_flush。
④ 加降级：refresh 返回值非 0 就放慢到 2 秒一次，并累计好坏计数。
⑤ 加异常画面：传感器 offline 时整屏换告警画面（用 inv=1 反显强调）。
⑥ 确认优先级与栈：显示任务优先级低于采集/控制，栈 512 字起。
⑦ 确认工程里真的 include 了 oled.h 并加入了 oled.c（现状是两板 main.c 都没接，必须自己加）。 /* ---- 显示任务：队列解耦 + 限速 + 降级 + 异常画面 ---- */
static void vtaskoled(void *pv)
{
    sysenv_t e;

    (void)pv;
    memset(&e, 0, sizeof(e));

    if (oled_setup() != 0u) {
        printf("[oled] 初始化失败，显示任务退出（通讯部分继续跑）\r\n");
        vtaskdelete(null);      /* 屏坏了不该拖垮整个系统 */
        return;
    }

    oled_bitselfcheck();                       /* 上电自检画面，留 1 秒 */
    vtaskdelay(pdms_to_ticks(1000));

    for (;;) {
        if (xqueuereceive(s_env_q, &e, pdms_to_ticks(500)) == pdpass) {
            /* 抽干队列只留最新：显示要的是「现在」，不是「历史」。
             *   按 fifo 一条条显示会永远在追旧数据。 */
            sysenv_t newer;
            while (xqueuereceive(s_env_q, &newer, 0) == pdpass) e = newer;
        }

        /* 限速 5hz：人眼足够，也给 i2c 总线留出给传感器的空档 */
        if ((xtaskgettickcount() - s_oled_tick_last) < pdms_to_ticks(200)) {
            vtaskdelay(pdms_to_ticks(20));
            continue;
        }
        s_oled_tick_last = xtaskgettickcount();

        if (e.online == 0u) {
            /* 异常必须显眼：整屏换告警，反显强调，
             *   绝不能让操作员把旧数据当新数据看。 */
            oled_clearbuffer();
            oled_showstringcenter(0u, "sensor offline", 0u);
            oled_showstringcenter(16u, "check wiring", 0u);
            oled_showstringcenter(32u, "alarm", 1u);
            (void)oled_refresh();
            vtaskdelay(pdms_to_ticks(500));
            continue;
        }

        if (oled_frame_flush(&e) == 0u) {
            s_oled_refresh_ok++;
        } else {
            /* 降级：写不进去时放慢到 2 秒一次，别让重试+超时把系统拖死 */
            s_oled_refresh_bad++;
            vtaskdelay(pdms_to_ticks(2000));
        }
        vtaskdelay(pdms_to_ticks(20));
    }
}

/* ---- 采集任务：只管采数据、塞队列，完全不碰 oled ---- */
static void vtaskenv(void *pv)
{
    sysenv_t e;

    (void)pv;
    for (;;) {
        e.temp_c    = 25.3f;
        e.humi_rh   = 61.8f;
        e.press_hpa = 1013.2f;
        e.light_lx  = 420u;
        e.mpu_ax    = 12;
        e.online    = 1u;
        (void)xqueuesend(s_env_q, &e, 0);
        vtaskdelay(pdms_to_ticks(100));
    }
}

/* ---- 任务创建：显示任务优先级低于采集 ---- */
void app_oled_start(void)
{
    s_env_q = xqueuecreate(4u, sizeof(sysenv_t));
    if (s_env_q == null) return;

    (void)xtaskcreate(vtaskoled, "oled", 512u, null, 2u, null);  /* 慢活，优先级低 */
    (void)xtaskcreate(vtaskenv,  "env",  256u, null, 3u, null);  /* 采集优先 */
}

/* ---- 板1 对照：把 oled_setup 里那几行换成 ----
 * if (sys_oled_init(sys_i2c_1, sys_oled_i2c_addr) != 0u) { ... }
 * 其余任务结构、队列、限速、降级逻辑完全一样。
 */ 上电后屏上先出现自检画面（bit selfcheck / pass）停 1 秒，然后开始以 5hz 刷新环境数据；把传感器拔掉（或把 e.online 置 0），屏上立刻变成 sensor offline / alarm 的反显告警画面。
三个可观测点：① s_oled_refresh_ok 单调增长、s_oled_refresh_bad 不涨；② 采集任务的工作没有被刷屏拖慢（采集周期稳定在 100ms，不因为刷屏抖到 130ms）；③ 屏上数值和串口日志里的数值一致且是同一时刻的（说明抽干队列只留最新这一招起作用了）。 本项目的现状要认清：板2 的 oled_init 只在 oled.c:101 定义、板1 的 sys_oled_init 只在 sys_oled.c:259 定义，两板 main.c 都没有接。所以第一步是把它 include 进工程并加入构建，别以为「驱动写好了就代表跑起来了」。
别让显示任务自己去读传感器。刷屏持锁 20ms，传感器读取被它挡住会让采集周期抖动；dht11 这类微秒级时序的器件更是直接读失败。一律走队列。
队列不要按 fifo 消费，要「抽干只留最新」，否则屏上永远显示几秒前的数据，这个 bug 的迷惑性在于「数据是对的，只是旧的」。
显示任务优先级不要给高。刷屏是慢活，优先级给高了会把控制回路挤掉，现象是「一开屏电机就抖」。
栈要给足（512 字起）：snprintf 带浮点格式化的调用链吃栈，给少了是偶发 hardfault，最难查。
屏故障要能降级而不是死循环重试：oled_refresh 失败时重试 3 次 + 等 i2c 超时，最坏数百毫秒；不给降级的话，屏一坏整个系统的实时性就没了。
异常态必须换画面。继续显示旧值等于误导操作员，这是显示系统设计上的硬要求，不是可选项。 ① freertos 任务 · ⑱ spi flash 断网缓存日志 · ⑲ lora e22 点对点 · ㉒ 自定义帧协议 · ⑧ i2c 总线 · 板2 oled.c / oled.h · 板1 sys_oled.c / sys_oled.h 性能优化：脏页刷新、400khz、以及该不该换 spi 最后一步解决「屏能跑了，但跑得不够快/不够省」的问题。先把账算清楚，才知道该优化哪里。

当前的开销账本（板2）： 整帧刷新 = 40 次 i2c 事务、1024 字节数据、约 23~25ms，而且整段持锁，这 23ms 里总线上其他从机全都得等。如果显示任务以 5hz 刷，那就是每秒 125ms 的总线被独占（12.5%）；如果脑子一热做到 50hz，就是 1.25 秒/秒，总线直接被屏吃光，mpu6050 读一次要排队 20ms 以上，姿态控制必然崩。优化的目标并非「让屏更快」，而是让同样信息量占用更少的总线时间。

优化一：只刷变化的页（脏页刷新），收益最大。 一页 = 竖直 8 像素。本项目一行 8×16 文字正好占 2 页，所以「哪几行变了」直接对应「哪几页脏了」。环境监测这类界面，通常只有 1~2 行数值在变，也就是 2~4 页；把整帧 8 页换成 3 页，刷屏时间从 23ms 直接降到 8~9ms 量级（板2 约 3 页 × 5 次事务 = 15 次事务）。要落地它，需要仿照 oled_refresh 的逐页写法给 oled.c 加一个 `oled_refreshpage(page)`，换算法不换硬件，改动很小，收益立竿见影。

判断「脏」的办法就是成品代码里那套：每一次刷新前，先把新的一行文本和上一轮的文本快照（s_line_last）逐行比较，不一样的行才重画、才标记对应的页。

优化二：把总线提到 400khz。 本项目两板初始化时都已经用 400khz 了（板1 内部 sys_i2c_init(bus, 400000)，板2 由调用方 sys_i2c_init(sys_i2c_1, 400000)）。从 100khz 提到 400khz 是 4 倍带宽，但要两条：① 总线上其他从机必须也支持（24c02 支持 400khz，mpu6050 支持到 400khz）；② 400khz 对上升沿更敏感，上拉不足或走线过长时会开始出错，现象是「原来 100khz 好好的，改成 400khz 就偶尔花屏」。所以提速前先确认上拉和走线。

优化三：降通信量的另一条路，只传变化区域。 如果屏的大部分是静态框线，可以只在初始化时画一次框，之后每次只重画数值区域。这跟「脏页」是同一思路的两种粒度（页粒度 vs 区域粒度），但要 ssd1306 的页模式限制：一笔数据事务不能跨页，所以区域刷新仍要按页拆。

优化四：换个接口，spi 版 ssd1306。 同样的屏有 spi 版本。spi 没有地址寻址、没有应答、没有仲裁，时钟可以到 10mhz 以上，把 1024 字节推出去只要约 1ms，比 i2c 快 20 倍以上；而且它独占总线，不会和 24c02/mpu6050 抢。代价是占 4~5 根线（sclk/mosi/cs/dc/res）、不能再和其他 i2c 器件共享排针，而且要spi 版 ssd1306 没有「控制字节」这个概念，改成用 dc 引脚区分命令/数据，驱动要重写低层（oled_wr 那一层）。如果屏刷新成了系统瓶颈、或者 i2c 总线太挤，换 spi 版是最彻底的解法。

优化五：别刷那么勤。 人眼对 5hz 的数值刷新完全不敏感（尤其是数字只在变化时才需要看到），把频率从 20hz 降到 5hz 直接省 75% 的总线时间，代价为零。这是性价比最高的一招，很多人却忽略了。 ① 先量基线：在刷新前后读 dwt 或 tick，打印一次全屏刷新的实际耗时，确认是不是 23~25ms。
② 统计页面变化率：给每个页加 dirty 标记，打印每轮真正变了几页。
③ 实现脏页刷新：仿照 oled_refresh 逐页写，给 oled.c 加 oled_refreshpage(page)，只刷脏页。
④ 再量一次耗时，对比基线（预期 3 页时 8~9ms）。
⑤ 检查上拉与走线后，确认 400khz 稳定（连续刷新 10 分钟不出错）。
⑥ 如果仍不够快、且总线太挤，评估换 spi 版 ssd1306（要重写低层 + 改接 4~5 根线）。 /* ---- 脏页刷新的落地骨架 ----
 * ① 每轮先把新文本格式化成 4 行，和上一次的快照逐行比较；
 * ② 变了的那一行 → 标记它覆盖的两页为 dirty（一行 8×16 文字 = 2 页）；
 * ③ 只把 dirty 的页推上屏。
 */

/* 行 → 页的映射：一行 8×16 文字占竖直 16 像素 = 2 页 */
#define line_to_page(line)   ((uint8_t)((line) * 2u))

static void oled_mark_dirty(const char line_new[4][24], uint8_t dirty[8])
{
    uint8_t i;

    for (i = 0u; i < 4u; i++) {
        if (strcmp(line_new[i], s_line_last[i]) != 0) {
            uint8_t p = line_to_page(i);
            dirty[p]     = 1u;      /* 该行上半 */
            dirty[p + 1] = 1u;      /* 该行下半 */
            strncpy(s_line_last[i], line_new[i], sizeof(s_line_last[i]) - 1u);
            s_line_last[i][sizeof(s_line_last[i]) - 1u] = 0;
        }
    }
}

/* 需要的驱动增强：仿照 oled_refresh 的逐页体，只写一页。
 * 本项目 oled.c 目前只提供整帧 oled_refresh()，所以这一步是
 * 「给驱动加一个函数」，不是改硬件。加完立刻有 8~9ms 量级的效果。 */

/* ---- 参数速查：本项目两板的实际取值 ---- */
/*   oled_width      128        屏幕宽（列）
 *   oled_height     64         屏幕高（行）
 *   oled_page_cnt   8          页数 = 64/8
 *   oled_chunk      32         一笔数据事务最大字节数（一页分 4 块）
 *   oled_retry      3          每笔事务失败重试次数
 *   oled_addr       0x3c       7 位地址（模块背面标 0x78 是 8 位）
 *   oled_i2c_id     sys_i2c_1  i2c1 = pb8(scl)/pb9(sda)
 *   sys_i2c_timeout 2000000    等标志位的最大循环次数（防死等）
 *   刷新耗时        约 23~25ms 40 次事务 / 1024 字节 @400khz
 */

/* ---- spi 版 ssd1306 的差异（要换接口时看这一条） ----
 *   i2c 版：每笔事务首字节是控制字节 0x00(命令) / 0x40(数据)，共用总线要加锁
 *   spi 版：没有控制字节，改用一根 dc 引脚区分命令/数据，另有 cs 片选
 *           （有的还有 res 复位脚）；独占总线、无需互斥、时钟可上 10mhz+
 *   驱动改动集中在低层 oled_wr 那一层，上层绘图/文字代码可以原样复用。
 */ 基线耗时打印出来应当是 23~25ms（400khz、无重试）。实现脏页刷新后，静态界面（只有 1 行数值在变）每轮耗时应当降到 8~9ms 量级，且 s_oled_refresh_ok 持续增长无失败。
再验证省下的时间真的还给了总线：刷屏期间读一次 mpu6050，优化前耗时在 20ms 量级，优化后应当明显缩短。
如果决定不换硬件，把刷新频率从 20hz 降到 5hz，用同样的方法测一次，也应当看到总线占用时间降到 1/4。 脏页刷新的前提是干净的显存快照。如果程序在别处也会改显存（例如另一个任务画波形），那 s_line_last 这套比较就失效了，要么所有写显存的操作都走同一个地方，要么用一个统一的「脏区域」标记机制。
400khz 不是无条件的。「原来 100khz 好好的，改 400khz 就偶尔花屏」是上拉不足/走线过长的经典症状，不是代码问题，先查上拉电阻和线长，再查代码。
页模式下一笔数据事务不能跨页（ssd1306 写到页尾会回到本页开头，而不是进下一页），所以「只刷某个区域」也仍然要按页边界拆开。板1 用的是水平寻址模式，一次 1024 字节可以自动跨页，两板的优化写法不能照搬。
换 spi 版不是「改个宏」：控制字节没了、要加 dc 引脚、上层要处理 cs，低层 oled_wr 必须重写。但上层（drawpoint / showchar / 绘图）可以原样复用，分层做得好，换接口的代价就只在最下面一层。
优化优先级建议：先降频率（零成本）→ 再脏页刷新（小改动、收益大）→ 最后才考虑换硬件。若直接换 spi 版，往往是在解决一个「刷太勤」造成的伪瓶颈。
别为了刷得快就去掉整帧锁。去掉锁换来的是撕裂画面和偶发数据错，那不是优化，是引入 bug。 ㉓ 本卡的第 5 步 · ㉓ 本卡的第 8 步 · ㉓ 本卡的第 9 步 · ⑧ i2c 总线 · ⑱ spi flash 断网缓存日志 · 板2 oled_refresh / oled_chunk / oled_retry / oled_page_cnt

