/* ============================================================
 *  ㉔ DHT11 单总线温湿度，完整成品代码
 *  平台：STM32F407 · 168MHz · 数据脚 PG9（板上带上拉）
 *  说明：按板2 dht11.c 的思路写（整数 API + 间隔拦截 + 重试），
 *        板1 的对应封装是 sys_dht11.c 的 SYS_DHT11_* 一套。
 * ============================================================ */
#include "stm32f4xx.h"
#include "delay.h"
#include "gpio_core.h"

#define DQ_PORT          GPIOG
#define DQ_PIN           GPIO_Pin_9
#define START_LOW_MS     20U        /* 手册 ≥18ms                        */
#define WAIT_TIMEOUT_US  100U       /* 单段等待上限，手册最长 80us       */
#define BIT_HIGH_US      45U        /* 位1≈70us / 位0≈26us，取中间       */
#define MIN_INTERVAL_MS  1100U      /* 采样率只有 1Hz                    */
#define RETRY_N          3U

static uint8_t  g_raw[5];
static uint32_t g_last_us;
static uint8_t  g_never = 1U;

/* 微秒时间戳：板1 的 delay.h 没有 DWT_GetUs()，直接拿 CYCCNT 换算 */
static uint32_t now_us(void)
{
    return DWT->CYCCNT / (SystemCoreClock / 1000000U);
}

static uint32_t wait_level(uint8_t level, uint32_t timeout_us)
{
    uint32_t t0  = DWT->CYCCNT;
    uint32_t lim = timeout_us * (SystemCoreClock / 1000000U);

    while (GPIO_InRead(DQ_PORT, DQ_PIN) != level)
    {
        if ((DWT->CYCCNT - t0) > lim) { return 0xFFFFFFFFUL; }  /* 超时 */
    }
    return (DWT->CYCCNT - t0);
}

/* 1 = 还没到采样间隔（这一帧不要读，DHT11 最快 1Hz） */
static uint8_t too_soon(void)
{
    if (g_never != 0U) { return 0U; }
    return ((now_us() - g_last_us) < (MIN_INTERVAL_MS * 1000U)) ? 1U : 0U;
}

/* 0 成功 / 1 无应答 / 2 校验和错 / 3 间隔不足 */
static uint8_t read_frame(void)
{
    uint8_t  i, d[5] = {0, 0, 0, 0, 0};
    uint32_t irq, high, thresh;

    delay_us(1);                    /* 确保 DWT 计时已使能              */

    /* ① 起始信号：拉低 20ms 再释放 */
    GPIO_OutInitOD(DQ_PORT, DQ_PIN);
    GPIO_OutWrite(DQ_PORT, DQ_PIN, 0U);
    delay_ms(START_LOW_MS);
    GPIO_OutWrite(DQ_PORT, DQ_PIN, 1U);

    /* ② 关中断窗口开始 */
    irq = __get_PRIMASK();
    __disable_irq();
    GPIO_InInit(DQ_PORT, DQ_PIN, GPIO_PuPd_UP);
    thresh = (SystemCoreClock / 1000000U) * BIT_HIGH_US;

    /* ③ 三次等待：应答低 → 应答高 → 应答高结束（进入 bit0） */
    if (wait_level(0U, WAIT_TIMEOUT_US) == 0xFFFFFFFFUL ||
        wait_level(1U, WAIT_TIMEOUT_US) == 0xFFFFFFFFUL ||
        wait_level(0U, WAIT_TIMEOUT_US) == 0xFFFFFFFFUL)
    {
        __set_PRIMASK(irq);
        GPIO_InInit(DQ_PORT, DQ_PIN, GPIO_PuPd_UP);
        return 1U;
    }

    /* ④ 40 位，高位在前 */
    for (i = 0U; i < 40U; i++)
    {
        if (wait_level(1U, WAIT_TIMEOUT_US) == 0xFFFFFFFFUL) { break; }
        high = wait_level(0U, WAIT_TIMEOUT_US);
        d[i >> 3] = (uint8_t)(d[i >> 3] << 1);
        if (high > thresh) { d[i >> 3] |= 0x01U; }
    }

    __set_PRIMASK(irq);
    GPIO_InInit(DQ_PORT, DQ_PIN, GPIO_PuPd_UP);
    for (i = 0U; i < 5U; i++) { g_raw[i] = d[i]; }

    /* ⑤ 校验和 = 前 4 字节之和的低 8 位 */
    if ((uint8_t)(d[0] + d[1] + d[2] + d[3]) != d[4]) { return 2U; }

    g_last_us = now_us();
    g_never   = 0U;
    return 0U;
}

/* 对外：整数温湿度；返回 0 成功 / 1 无应答 / 2 校验错 / 3 间隔不足 */
int DHT11_Get(uint8_t *temp_c, uint8_t *humi_pct)
{
    uint8_t k, r = 1U;

    if (temp_c == 0 || humi_pct == 0) { return 4; }

    for (k = 0U; k < RETRY_N; k++)
    {
        r = read_frame();
        if (r == 0U) { break; }
        if (r == 1U) { return 1; }   /* 无应答：重试也没有意义           */
        if (r == 3U) { return 3; }   /* 间隔不足：别拿旧值              */
        delay_ms(50);                /* 只有校验失败才退避重试           */
    }
    if (r != 0U) { return (int)r; }

    *humi_pct = g_raw[0];            /* 小数位恒为 0，取整数即可         */
    *temp_c   = g_raw[2];
    return 0;
}

void DHT11_DumpRaw(void)
{
    printf("DHT11 raw: %02X %02X %02X %02X %02X\r\n",
           g_raw[0], g_raw[1], g_raw[2], g_raw[3], g_raw[4]);
}

