/* ============================================================
 *  ㉕ 引导 10 步的成品：一条 I2C1 总线 + 参数掉电保存
 *  平台：STM32F407 · 板2（数据通信端）
 *  总线：I2C1 SCL = PB8 / SDA = PB9（板上 4.7k 上拉，100kHz）
 *  器件：AT24C02(0x50) · MPU6050(0x68) · 外接 OLED(0x3C) / AHT10(0x38)
 * ============================================================ */
#include "stm32f4xx.h"
#include "sys_i2c.h"
#include "at24c02.h"

#include <string.h>

/* ---------------- 地址规划（写进自己的笔记，别散落在代码里） ------------
 *  0x00 ~ 0x03   MAGIC 区（AT24C02_ADDR_MAGIC，值 0xA5）
 *  0x10 ~ 0x17   参数头：MAGIC4 + 版本1 + 长度1 + CRC16(2)
 *  0x18 ~ 0x23   参数体 Param_t（12 字节）
 *  0x40          A/B 轮换的“当前有效份”标志（0xA0 = A 有效 / 0xB0 = B 有效）
 *  0x80 ~ 0xEF   校准数据区
 * ============================================================ */
#define P25_HDR_A     0x10U
#define P25_BODY_A    0x18U
#define P25_HDR_B     0x30U
#define P25_BODY_B    0x38U
#define P25_AB_FLAG   0x40U
#define P25_FLAG_A    0xA0U
#define P25_FLAG_B    0xB0U

typedef struct {
    uint16_t kp_x100;
    uint16_t ki_x100;
    uint16_t kd_x100;
    uint16_t temp_alarm;
    uint8_t  report_s;
    uint8_t  reserved[3];
} Param_t;

static Param_t s_param;
static uint8_t s_slot;          /* 0 = 当前用 A 份，1 = 当前用 B 份 */
/* 别在真代码里用变长数组拼 CRC 输入：MISRA 不喜欢，栈也不可控 */
static uint8_t s_hdr_tmp[8];

static void param_defaults(Param_t *p)
{
    p->kp_x100 = 125U;
    p->ki_x100 = 30U;
    p->kd_x100 = 5U;
    p->temp_alarm = 600U;
    p->report_s = 5U;
    p->reserved[0] = 0U;
    p->reserved[1] = 0U;
    p->reserved[2] = 0U;
}

/* CRC16-MODBUS 放在数据后面：把 6 字节头和 12 字节体一起算进去。
 * 这就是“CRC 覆盖范围包含自身时整段再算一遍为 0”那个性质的用法。 */
static uint16_t param_crc(const uint8_t *h, const uint8_t *b)
{
    uint16_t crc = 0xFFFFU;
    uint16_t k;
    uint8_t  bit;

    for (k = 0U; k < 6U; k++) {
        crc ^= (uint16_t)h[k];
        for (bit = 0U; bit < 8U; bit++) {
            crc = ((crc & 1U) != 0U) ? (uint16_t)((crc >> 1) ^ 0xA001U)
                                     : (uint16_t)(crc >> 1);
        }
    }
    for (k = 0U; k < (uint16_t)sizeof(Param_t); k++) {
        crc ^= (uint16_t)b[k];
        for (bit = 0U; bit < 8U; bit++) {
            crc = ((crc & 1U) != 0U) ? (uint16_t)((crc >> 1) ^ 0xA001U)
                                     : (uint16_t)(crc >> 1);
        }
    }
    return crc;
}

/* ---------------- 写一份：头 8 字节一页 + 体 12 字节两页 ---------------- */
static uint8_t param_write_slot(uint8_t hdr_addr, uint8_t body_addr, const Param_t *p)
{
    uint8_t  hdr[8];
    uint8_t  body[sizeof(Param_t)];
    uint16_t crc;

    hdr[0] = 0x50U; hdr[1] = 0x32U; hdr[2] = 0x35U; hdr[3] = 0x41U;  /* "P25A" */
    hdr[4] = 1U;                                /* 版本 */
    hdr[5] = (uint8_t)sizeof(Param_t);          /* 长度 */
    memcpy(body, p, sizeof(Param_t));
    crc = param_crc(hdr, body);
    hdr[6] = (uint8_t)(crc & 0xFFU);            /* 低字节在前 */
    hdr[7] = (uint8_t)(crc >> 8);

    /* 8 + 12 = 20 字节，但绝不能一次全写：0x10 起 8 字节正好第一页，
     *   0x18 起 12 字节会跨页（0x18 页内偏移 0，8 字节后到 0x20 是
     *   下一页，还剩 4 字节），必须交给 AT24C02_WriteBytes 自动分片。 */
    if (AT24C02_WriteBytes(hdr_addr, hdr, 8U) != 0U)  return 1U;
    if (AT24C02_WriteBytes(body_addr, body, (uint16_t)sizeof(Param_t)) != 0U) return 1U;
    return 0U;
}

/* ---------------- 读一份：MAGIC + 版本 + 长度 + CRC 四关 ---------------- */
static uint8_t param_read_slot(uint8_t hdr_addr, uint8_t body_addr, Param_t *out)
{
    uint8_t  hdr[8];
    uint8_t  body[sizeof(Param_t)];
    uint16_t crc_now, crc_stored;

    if (AT24C02_ReadBytes(hdr_addr, hdr, 8U) != 0U) return 0U;
    if ((hdr[0] != 0x50U) || (hdr[1] != 0x32U) ||
        (hdr[2] != 0x35U) || (hdr[3] != 0x41U)) return 0U;
    if ((hdr[4] != 1U) || (hdr[5] != (uint8_t)sizeof(Param_t))) return 0U;
    if (AT24C02_ReadBytes(body_addr, body, (uint16_t)sizeof(Param_t)) != 0U) return 0U;

    crc_stored = (uint16_t)(((uint16_t)hdr[7] << 8) | (uint16_t)hdr[6]);
    crc_now    = param_crc(hdr, body);
    if (crc_now != crc_stored) return 0U;

    memcpy(out, body, sizeof(Param_t));
    return 1U;
}

/* ---------------- 保存：先写另一份，再原子地改标志 ---------------- */
uint8_t param_save(const Param_t *p)
{
    uint8_t next = (uint8_t)(s_slot ^ 1U);          /* 永远写“非当前”的那一份 */
    uint8_t flag;

    /* 外层锁：这一整段是“多笔连续事务”，中途被别的任务插进来就毁了。
     *   sys_i2c 的每个公共入口内部也都加锁，本项目是递归锁，嵌套安全。 */
    SYS_I2C_Lock(SYS_I2C_1);

    if (next == 0U) {
        if (param_write_slot(P25_HDR_A, P25_BODY_A, p) != 0U) {
            SYS_I2C_Unlock(SYS_I2C_1);
            return 1U;
        }
    } else {
        if (param_write_slot(P25_HDR_B, P25_BODY_B, p) != 0U) {
            SYS_I2C_Unlock(SYS_I2C_1);
            return 1U;
        }
    }

    /* 关键顺序：先把数据写完并确认，再改标志。
     *   如果先改标志再写数据，掉电就会得到“标志指向一份没写完的数据”。
     *   反之，最坏情况只是“标志仍指向旧副本”，旧副本完整，能正常启动。 */
    flag = (next == 0U) ? P25_FLAG_A : P25_FLAG_B;
    if (AT24C02_WriteByte(P25_AB_FLAG, flag) != 0U) {
        SYS_I2C_Unlock(SYS_I2C_1);
        return 2U;
    }

    SYS_I2C_Unlock(SYS_I2C_1);
    s_slot = next;
    return 0U;
}

/* ---------------- 加载：标志优先，标志不可信就两份都试 ---------------- */
uint8_t param_load(void)
{
    uint8_t flag = 0U;
    Param_t tmp;

    /* 标志本身也可能坏（空片 0xFF / 写一半），所以它只是“优先提示”，
     *   绝不能“标志说用 A 就无脑信 A”。真正的判据永远是那一份自己的 CRC。 */
    if (AT24C02_ReadByte(P25_AB_FLAG, &flag) == 0U) {
        if (flag == P25_FLAG_A) {
            if (param_read_slot(P25_HDR_A, P25_BODY_A, &s_param) != 0U) { s_slot = 0U; return 0U; }
        } else if (flag == P25_FLAG_B) {
            if (param_read_slot(P25_HDR_B, P25_BODY_B, &s_param) != 0U) { s_slot = 1U; return 0U; }
        }
    }

    /* 标志无效，或标志指向的那份 CRC 没过：两份都试一遍，谁过用谁。
     * 这就是 A/B 轮换的全部价值，掉电最多只丢最后一次改动。 */
    if (param_read_slot(P25_HDR_A, P25_BODY_A, &tmp) != 0U) {
        memcpy(&s_param, &tmp, sizeof(Param_t));
        s_slot = 0U;
        return 0U;
    }
    if (param_read_slot(P25_HDR_B, P25_BODY_B, &tmp) != 0U) {
        memcpy(&s_param, &tmp, sizeof(Param_t));
        s_slot = 1U;
        return 0U;
    }
    return 1U;      /* 两份都不可信：调用方接手写默认值 */
}

/* ---------------- 开机自检：扫描 + 加载 ---------------- */
uint8_t i2c_boot_selfcheck(void)
{
    uint8_t found[16];
    uint8_t n, i;

    SYS_I2C_Init(SYS_I2C_1, 100000UL);
    n = SYS_I2C_Scan(SYS_I2C_1, found, 16U);
    printf("I2C1 应答 %u 个：", (unsigned)n);
    for (i = 0U; i < n; i++) printf("0x%02X ", (unsigned)found[i]);
    printf("\r\n");

    if (AT24C02_Init(0U) != 0U) return 1U;          /* 0x50 没应答 */

    /* 用驱动自己的魔数接口判“空片”，新语义：1 = 魔数在 = 存过。
     * 旧名 AT24C02_IsBlank 的返回值含义与参数名相反，已废弃改名。 */
    if (AT24C02_IsMagicSet(AT24C02_ADDR_MAGIC, AT24C02_MAGIC_VALUE) == 0U) {
        param_defaults(&s_param);
        s_slot = 1U;                                 /* 让第一次保存去写 A 份 */
        (void)param_save(&s_param);
        (void)AT24C02_WriteByte(AT24C02_ADDR_MAGIC, AT24C02_MAGIC_VALUE);
        printf("空片：已写入默认参数并打上魔数标记\r\n");
        return 0U;
    }

    if (param_load() != 0U) {
        param_defaults(&s_param);
        (void)param_save(&s_param);
        printf("两份参数都不可信：回落默认值并重写\r\n");
        return 2U;
    }
    printf("参数加载成功：Kp=%u.%02u 阈值=%u.%u 上报=%us\r\n",
           (unsigned)(s_param.kp_x100 / 100U), (unsigned)(s_param.kp_x100 % 100U),
           (unsigned)(s_param.temp_alarm / 10U), (unsigned)(s_param.temp_alarm % 10U),
           (unsigned)s_param.report_s);
    return 0U;
}

f:
/* 扫描 + 点名：I2C 排障的第一把钥匙 */
void bus_scan_report(void)
{
