/* 单寄存器读写 + 错误码分流 */
void reg_rw_demo(void)
{
    uint8_t who = 0U;
    uint8_t back = 0U;
    int     err;

    /* ① 读 WHO_AM_I（只读寄存器，0x75），期望 0x68 */
    err = SYS_I2C_ReadByte(SYS_I2C_1, SYS_I2C_ADDR_MPU6050, 0x75U, &who);
    if (err != SYS_I2C_OK) {
        printf("读 WHO_AM_I 失败：%s\r\n", SYS_I2C_ErrStr(err));
        return;
    }
    printf("WHO_AM_I = 0x%02X（应 0x68）\r\n", (unsigned)who);

    /* ② 写 PWR_MGMT_1（0x6B）解除休眠，再读回来比对 */
    err = SYS_I2C_WriteByte(SYS_I2C_1, SYS_I2C_ADDR_MPU6050, 0x6BU, 0x00U);
    if (err != SYS_I2C_OK) {
        printf("写 PWR_MGMT_1 失败：%s\r\n", SYS_I2C_ErrStr(err));
        return;
    }
    err = SYS_I2C_ReadByte(SYS_I2C_1, SYS_I2C_ADDR_MPU6050, 0x6BU, &back);
    if ((err != SYS_I2C_OK) || (back != 0x00U)) {
        printf("写回不一致：err=%d back=0x%02X\r\n", err, (unsigned)back);
    }
}

/* 只发命令 + 不发寄存器直接读：BH1750 光照传感器 */
#define BH1750_ADDR      0x23U      /* ADDR 接 GND；接 VCC 变 0x5C */
#define BH1750_POWER_ON  0x01U
#define BH1750_CONT_H    0x10U      /* 连续 H 分辨率，1lx 精度 */

int bh1750_read_lux(float *lux)
{
    uint8_t raw[2];
    int     err;
    uint16_t raw16;

    /* ① 只发命令：必须用 WriteCmd，不能用 WriteBytes(..., NULL, 0) */
    err = SYS_I2C_WriteCmd(SYS_I2C_1, BH1750_ADDR, BH1750_POWER_ON);
    if (err != SYS_I2C_OK) return err;

    err = SYS_I2C_WriteCmd(SYS_I2C_1, BH1750_ADDR, BH1750_CONT_H);
    if (err != SYS_I2C_OK) return err;

    /* ② 连续 H 分辨率模式一次测量最长 180ms，等够了再读 */
    delay_ms(180);

    /* ③ 不发寄存器号直接读 2 字节（高字节在前） */
    err = SYS_I2C_ReadRaw(SYS_I2C_1, BH1750_ADDR, raw, 2U);
    if (err != SYS_I2C_OK) return err;

    raw16 = (uint16_t)(((uint16_t)raw[0] << 8) | (uint16_t)raw[1]);
    *lux  = (float)raw16 / 1.2f;    /* 手册给的换算关系 */
    return SYS_I2C_OK;
}

/* 反面教材（不要这么写）：
 *   SYS_I2C_WriteBytes(SYS_I2C_1, 0x23, 0, NULL, 0);
 *   源码判 buf == 0 || len == 0 → 直接返回 SYS_I2C_ERR_PARAM(-1)，
 *   字节一个都没发出去，却很容易被当成“器件坏了”。 */

/* 地址宽度对照：选错 API 的后果 */
/*  24C02  256 字节   地址 8 位   → AT24C02_WriteBytes / SYS_I2C_WriteByte
 *  24C04  512 字节   地址 8 位 + 页选择位（复用器件地址低位）
 *  24C08  1K 字节    同上，A2/A1 被拿去做页选择
 *  24C16  2K 字节    同上，A2/A1/A0 全被拿走
 *  24C32  4K 字节    地址 16 位   → SYS_I2C_WriteReg16 / ReadReg16
 *  24C64  8K 字节    地址 16 位   → 同上
 */

/* 16 位地址器件的读写写法（以 24C64 为例，本项目 24C02 用不到） */
int eeprom64_write(uint8_t addr7, uint16_t mem_addr,
                   const uint8_t *buf, uint16_t len)
{
    /* reg 是 uint16_t：库内部按“高字节在前、低字节在后”发两个字节 */
    return SYS_I2C_WriteReg16(SYS_I2C_1, addr7, mem_addr, buf, len);
}

int eeprom64_read(uint8_t addr7, uint16_t mem_addr,
                  uint8_t *buf, uint16_t len)
{
    return SYS_I2C_ReadReg16(SYS_I2C_1, addr7, mem_addr, buf, len);
}

/* 24C02 用的是 8 位地址，别拿 Reg16 去套：
 *   24C02 的“寄存器号”就是它内部的字节地址（0x00~0xFF），
 *   多发的那个高字节会被它当数据吃掉。
 */

/* 写周期的两种等法：驱动用的是右边那种（ACK 轮询） */

/* ① 教科书做法：死等一个写周期 */
static void wait_by_delay(void)
{
    delay_ms(AT24C02_WRITE_MS);        /* AT24C02_WRITE_MS = 5U */
}

/* ② 本项目 at24c02.c 的做法：ACK 轮询，写到哪算哪 */
static void at24c02_wait_ready(void)
{
    uint32_t guard = 0;

    /* 有 ACK 就说明内部写完了，通常 2~3ms 就能返回 */
    while (guard++ < 200U) {
        if (SYS_I2C_IsDeviceReady(AT24C02_I2C_ID, AT24C02_ADDR) == SYS_I2C_OK) {
            return;
        }
    }
    /* 兜底：芯片坏了永远不应答时，也不能死在这里 */
    delay_ms(AT24C02_WRITE_MS);
}

/* 容量与页的账：256 字节 = 32 页 */
/*   AT24C02_TOTAL_SIZE  256U
 *   AT24C02_PAGE_SIZE     8U
 *   AT24C02_WRITE_MS      5U
 *   整片写一遍 ≈ 32 × 5ms = 160ms（头文件说 Erase 约 0.2 秒）
 */

/* 页写边界的账，以及驱动替挡下的两件事 */

/* ① 边界公式：本次最多能写多少字节 */
#define PAGE_LEFT(addr)  (8U - ((addr) & 0x07U))

/*   addr = 0x10 → 0x10 & 7 = 0 → 可写 8
 *   addr = 0x15 → 0x15 & 7 = 5 → 可写 3（0x15,0x16,0x17）
 *   addr = 0xFA → 0xFA & 7 = 2 → 可写 6（0xFA..0xFF）
 *   再往后就回卷到 0x00，这正是要拦住的越界
 */

/* ② 驱动内部的分片逻辑（at24c02.c 的实际做法，读它、信它） */
uint8_t AT24C02_WriteBytes(uint8_t addr, const uint8_t *buf, uint16_t len)
{
    uint16_t done = 0;

    if (buf == 0 || len == 0U) return 1U;

    /* 越界硬拦截：不依赖“芯片会绕回”，而是显式失败 */
    if ((uint16_t)addr + len > (uint16_t)AT24C02_TOTAL_SIZE) return 1U;

    while (done < len) {
        /* 本次能写多少：不能跨页（页内地址低 3 位必须同页） */
        uint8_t  in_page = (uint8_t)(AT24C02_PAGE_SIZE -
                                     ((addr + done) & (AT24C02_PAGE_SIZE - 1U)));
        uint16_t n       = (uint16_t)(len - done);

        if (n > (uint16_t)in_page) n = (uint16_t)in_page;

        if (SYS_I2C_WriteBytes(AT24C02_I2C_ID, AT24C02_ADDR,
                               (uint8_t)(addr + done), &buf[done], n) != SYS_I2C_OK) {
            return 1U;
        }
        at24c02_wait_ready();       /* 每片写完都要等一个写周期 */
        done = (uint16_t)(done + n);
    }
    return 0U;
}

/* ③ 参数区按页对齐存放，连“拆”都不需要发生，逻辑最干净：
 *   0x10  头 8 字节  → 正好一页
 *   0x18  体 12 字节 → 0x18 起 8 字节一页 + 0x20 起 4 字节，两页
 *   0x30  第二份头、0x38 第二份体（A/B 轮换用）
 */

/* 参数结构体与参数保存的完整链路（节选，详见 e 字段成品代码） */
typedef struct {
    uint16_t kp_x100;      /* PID Kp ×100：1.25 → 125 */
    uint16_t ki_x100;
    uint16_t kd_x100;
    uint16_t temp_alarm;   /* 报警阈值 ×10 摄氏度 */
    uint8_t  report_s;     /* 上报周期（秒） */
    uint8_t  reserved[3];  /* 补齐到 12 字节 */
} Param_t;

#define P25_HDR_A    0x10U
#define P25_BODY_A   0x18U
#define P25_HDR_B    0x30U
#define P25_BODY_B   0x38U
#define P25_AB_FLAG  0x40U
#define P25_FLAG_A   0xA0U
#define P25_FLAG_B   0xB0U

/* 保存：写非当前份 → 成功后再改标志（顺序不能换） */
uint8_t param_save(const Param_t *p)
{
    uint8_t next = (uint8_t)(s_slot ^ 1U);
    uint8_t flag = (next == 0U) ? P25_FLAG_A : P25_FLAG_B;

    SYS_I2C_Lock(SYS_I2C_1);        /* 多笔连续操作，整体持锁 */

    if (next == 0U) {
        if (param_write_slot(P25_HDR_A, P25_BODY_A, p) != 0U) {
            SYS_I2C_Unlock(SYS_I2C_1);
            return 1U;
        }
    } else {
        if (param_write_slot(P25_HDR_B, P25_BODY_B, p) != 0U) {
            SYS_I2C_Unlock(SYS_I2C_1);
            return 1U;
        }
    }

    /* 关键时刻：先确认数据写完，再用【一次原子写】更新标志 */
    if (AT24C02_WriteByte(P25_AB_FLAG, flag) != 0U) {
        SYS_I2C_Unlock(SYS_I2C_1);
        return 2U;
    }

    SYS_I2C_Unlock(SYS_I2C_1);
    s_slot = next;
    return 0U;
}

/* 加载：标志只是提示，真正的判据是那一份自己的 CRC */
uint8_t param_load(void)
{
    uint8_t flag = 0U;

    if (AT24C02_ReadByte(P25_AB_FLAG, &flag) == 0U) {
        if (flag == P25_FLAG_A) {
            if (param_read_slot(P25_HDR_A, P25_BODY_A, &s_param) != 0U) {
                s_slot = 0U; return 0U;
            }
        } else if (flag == P25_FLAG_B) {
            if (param_read_slot(P25_HDR_B, P25_BODY_B, &s_param) != 0U) {
                s_slot = 1U; return 0U;
            }
        }
    }
    /* 标志无效或那份 CRC 不过：两份都试，谁过用谁 */
    if (param_read_slot(P25_HDR_A, P25_BODY_A, &s_param) != 0U) { s_slot = 0U; return 0U; }
    if (param_read_slot(P25_HDR_B, P25_BODY_B, &s_param) != 0U) { s_slot = 1U; return 0U; }
    return 1U;      /* 两份都不可信 */
}

/* 多任务安全的写参数：整体持锁 + 出错用 BusReset 自救 */
uint8_t param_commit_safe(const Param_t *p)
{
    uint8_t r;

    /* 整段“多笔连续事务”必须在同一把锁里完成。
     *   sys_i2c 的每个公共入口内部也会加锁，本项目是递归锁，
     *   同任务重复 Lock 只是计数 +1，不会自锁死。 */
    SYS_I2C_Lock(SYS_I2C_1);
    r = param_save(p);
    SYS_I2C_Unlock(SYS_I2C_1);

    if (r == 0U) return 0U;

    /* 失败了一次：救总线，再整体重试一次 */
    SYS_I2C_BusReset(SYS_I2C_1);        /* 9 个时钟 + STOP + 重新初始化 */

    SYS_I2C_Lock(SYS_I2C_1);
    r = param_save(p);
    SYS_I2C_Unlock(SYS_I2C_1);
    return r;
}

/* 中断里绝对不要这么写：
 *   void EXTI0_IRQHandler(void)
 *   {
 *       AT24C02_WriteByte(0x10, 1U);   // 错。SYS_I2C_Lock 在 ISR 里
 *                                       // 被 __get_IPS R() 判断后直接跳过，
 *                                       // 这一次写没有任何互斥保护
 *   }
 *   同时它还要等 5ms 写周期，把中断拖成几十毫秒。
 *
 *   正确做法：中断里只投递消息，由任务去写：
 *   void EXTI0_IRQHandler(void)
 *   {
 *       BaseType_t woken = pdFALSE;
 *       xQueueSendFromISR(g_i2c_q, &msg, &woken);
 *       portYIELD_FROM_ISR(woken);
 *   }
 */

/* 出错自查表（打印出来贴在工位上）：
 *   -2 ERR_START   起始条件失败  → 上拉缺失 / 总线忙 / 引脚配置错
 *   -3 ERR_ADDR    器件无应答    → 地址错(7位/8位) / 没供电 / 写周期内重发
 *   -4 ERR_DATA    数据阶段 NACK → 寄存器号不对 / 器件类型不匹配
 *   -5 ERR_TIMEOUT 等标志超时    → 总线被从机拉死 → BusReset 后重试
 *   -6 ERR_BUS     总线错误      → 时序被干扰 → 降速 / 缩短走线
 *   -1 ERR_PARAM   参数非法      → 指针为空 / len 为 0 / id 越界
 */

