/* ============================================================
 *  ㉗ 滤波 + 卡尔曼 + PID 闭环，按引导 10 步搭出来的成品
 *  链路：ADC 采样 -> 限幅挡野值 -> 一阶低通降噪 -> 卡尔曼估计 -> PID -> PWM
 *  平台：STM32F407 · sys_filter.h / kalman.h / pid.h / sys_adc.h / sys_tim.h
 * ============================================================ */
#include "stm32f4xx.h"
#include "sys_filter.h"
#include "kalman.h"
#include "pid.h"
#include "sys_adc.h"
#include "sys_tim.h"
#include "sys_tick.h"
#include <stdio.h>

/* ---- 采样与执行器：量纲集中在这里 ---- */
#define LOOP_ADC        ADC1
#define LOOP_ADC_CH     5U
#define LOOP_PWM_TIM    SYS_TIM_1
#define LOOP_PWM_CH     1U
#define LOOP_PERIOD_MS  10U

#define RAW_STEP_MAX    200U
#define LPF_FC_HZ       20.0f
#define LPF_FS_HZ       1000.0f

/* ---- 三个对象一律 static：递推滤波器必须有记忆 ---- */
static FilterLpf_t s_lpf;
static Kalman_t    s_kf;
static Pid_t       s_pid;
static uint16_t    s_prev_raw;
static uint32_t    s_bad_cnt;

/* ---- PID 浮点输出 -> PWM 千分比（0~1000）并钳位 ---- */
static uint16_t out_to_permille(float out)
{
    float v = out;
    if (v < 0.0f)    { v = 0.0f; }
    if (v > 1000.0f) { v = 1000.0f; }
    return (uint16_t)(v + 0.5f);
}

/* ---- 初始化：先对象、再限幅 ---- */
void loop_init(float target)
{
    FILTER_LpfInit(&s_lpf, LPF_FC_HZ, LPF_FS_HZ);

    (void)KALMAN_AutoTune(&s_kf, 1.0f, 8.0f);   /* 1 个单位要跟上，8 个单位要滤掉 */
    KALMAN_Reset(&s_kf, target);

    PID_Init(&s_pid, 20.0f, 5.0f, 0.5f);
    PID_SetOutputLimit(&s_pid, 0.0f, 1000.0f);       /* 必须设 */
    PID_SetIntegralLimit(&s_pid, -500.0f, 500.0f);
    PID_SetDerivOnMeasurement(&s_pid, 1U);
    PID_SetSeparateThreshold(&s_pid, 200.0f);
}

/* ---- 跑一拍：采样 -> 限幅 -> 低通 -> 卡尔曼 -> PID -> PWM ---- */
void loop_step(float target, float dt)
{
    uint16_t raw;
    float    z, y, out;

    raw = SYS_ADC_Read(LOOP_ADC, LOOP_ADC_CH);

    raw = FILTER_Limit(s_prev_raw, raw, RAW_STEP_MAX);
    s_prev_raw = raw;

    z = (float)raw;
    if (z != z) { s_bad_cnt++; return; }
    y = FILTER_LpfUpdate(&s_lpf, z);

    y = KALMAN_Update(&s_kf, y);

    out = PID_Update(&s_pid, target, y, dt);
    SYS_TIM_PwmSetDuty(LOOP_PWM_TIM, LOOP_PWM_CH, out_to_permille(out));
}

/* ---- 固定周期主循环：dt 稳定，Ki/Kd 才有意义 ---- */
void loop_task(float target)
{
    uint32_t last = 0U;

    loop_init(target);

    for (;;)
    {
        uint32_t t0 = SYS_TICK_GetTick();
        if (SYS_TICK_Every(&last, LOOP_PERIOD_MS) != 0U)
        {
            float dt = (float)SYS_TICK_Elapsed(t0) / 1000.0f;
            loop_step(target, (dt > 0.0f) ? dt : 0.01f);
        }
    }
}

/* ---- 排错：一眼看出是谁在捣乱 ---- */
void loop_dump(void)
{
    float p, i, d;
    PID_GetTerms(&s_pid, &p, &i, &d);
    printf("K=%.3f resid=%.2f P=%.2f I=%.2f D=%.2f bad=%lu\r\n",
           KALMAN_GetGain(&s_kf), KALMAN_GetResid(&s_kf),
           p, i, d, (unsigned long)s_bad_cnt);
}

