/* 第 2 步：先把裸值打出来看。这一段的输出就是后面所有调参的基准。 */
#include "sys_adc.h"
#include <stdio.h>

#define RAW_ADC     ADC1
#define RAW_CH      5U

void adc_probe(void)
{
    uint16_t i, raw;

    SYS_ADC_Init(RAW_ADC, RAW_CH);

    for (i = 0U; i < 50U; i++)
    {
        raw = SYS_ADC_Read(RAW_ADC, RAW_CH);   /* 两个参数：adc, channel */

        if (SYS_ADC_ReadOK(raw) == 0U)         /* 值本身是否可疑 */
        {
            printf("raw = %u   (无效)\r\n", (unsigned)raw);
        }
        else
        {
            printf("raw = %u   = %lu mV\r\n", (unsigned)raw,
                   (unsigned long)SYS_ADC_ReadMilliVolt(RAW_ADC, RAW_CH));
        }
        SYS_TICK_Delay_ms(10U);
    }
}

/* 第一关：限幅。max_step 按“物理上不可能变化这么快”来定。 */
#include "sys_filter.h"

#define RAW_STEP_MAX   200U   /* 正常抖动约 20~40 时，取 200 已经很宽松 */

static uint16_t s_prev_raw;
static uint32_t s_limit_hit;   /* 拦截次数：调参和排错都要看 */

static uint16_t guard(uint16_t now)
{
    uint16_t v = FILTER_Limit(s_prev_raw, now, RAW_STEP_MAX);

    if (v != now) { s_limit_hit++; }   /* 说明这次被判成野值了 */
    s_prev_raw = v;
    return v;
}

/* 第二关：一阶低通。α 让库按截止频率算，别自己写 2*pi*fc/fs。 */
#include "sys_filter.h"
#include <stdio.h>

static FilterLpf_t s_lpf;
static uint32_t    s_bad_cnt;     /* 坏值计数：滤波器不替我们数 */

static float denoise(float z)
{
    if (z != z) { s_bad_cnt++; return 0.0f; }   /* z != z 是抓 NaN 最快的写法 */

    return FILTER_LpfUpdate(&s_lpf, z);
}

void lpf_demo(void)
{
    FILTER_LpfInit(&s_lpf, 20.0f, 1000.0f);     /* 20Hz 截止、1kHz 采样 */

    printf("alpha = %.4f\r\n", (double)s_lpf.alpha);
    /* 精确式应打印 0.1179 附近（fc=20, fs=1000），近似式会算出 0.1257 */
}

/* 第三关：卡尔曼。按“手感”调，不用算协方差。 */
#include "kalman.h"

static Kalman_t s_kf;

void kalman_setup(float first)
{
    /* 1 个单位的变化要跟得上，8 个单位的乱跳要滤掉 */
    if (KALMAN_AutoTune(&s_kf, 1.0f, 8.0f) != KALMAN_OK)
    {
        return;   /* 参数非法（含 NaN）会返回 KALMAN_ERR_PARAM */
    }

    KALMAN_Reset(&s_kf, first);   /* x0 传 NaN/Inf 时按 0 处理 */
}

float kalman_step(float z)
{
    return KALMAN_Update(&s_kf, z);   /* 第一次调用直接把 z 当初始估计 */
}

/* 调参仪表盘：把卡尔曼的内部量打出来，比看输出曲线快得多。 */
#include "kalman.h"
#include <stdio.h>

static Kalman_t s_kf;

void kalman_dashboard(float z)
{
    float y = KALMAN_Update(&s_kf, z);
    float k = KALMAN_GetGain(&s_kf);

    printf("z=%.1f y=%.1f K=%.3f resid=%.2f\r\n",
           (double)z, (double)y, (double)k, (double)KALMAN_GetResid(&s_kf));

    /*
     * 典型判读：
     *   K 长期 0.03  -> 太平滑，跳变跟不上 -> KALMAN_SetQR(&kf, 0.05f, 4.0f)
     *   K 长期 0.60  -> 等于没滤           -> KALMAN_SetQR(&kf, 0.01f, 16.0f)
     *   平稳 0.1 / 跳变 0.8  -> 已经调好，别再动
     */
}

/* 第四关：PID 初始化 + 量纲换算。限幅必须在 Init 之后马上设。 */
#include "pid.h"
#include "sys_tim.h"

#define PWM_TIM   SYS_TIM_1
#define PWM_CH    1U

static Pid_t s_pid;

static uint16_t out_to_permille(float out)
{
    float v = out;

    if (v < 0.0f)    { v = 0.0f; }        /* 单向执行器：负输出没有意义 */
    if (v > 1000.0f) { v = 1000.0f; }

    return (uint16_t)(v + 0.5f);          /* 四舍五入，不要直接截断 */
}

void pid_setup(void)
{
    PID_Init(&s_pid, 20.0f, 5.0f, 0.5f);

    /* 上电第一件事：告诉 PID 执行器的真实量纲 */
    PID_SetOutputLimit(&s_pid, 0.0f, 1000.0f);

    PID_SetMode(&s_pid, PID_MODE_POSITION);   /* 位置式：输出就是绝对占空比 */
}

void pid_run(float target, float measure, float dt)
{
    float out = PID_Update(&s_pid, target, measure, dt);

    SYS_TIM_PwmSetDuty(PWM_TIM, PWM_CH, out_to_permille(out));
}

/* 抗积分饱和：限幅 + 分离 + 微分先行，三个一起上。 */
#include "pid.h"
#include <stdio.h>

static Pid_t s_pid;

void pid_anti_windup(void)
{
    /* ① 积分限幅：取输出限幅的 50%~100% */
    PID_SetIntegralLimit(&s_pid, -500.0f, 500.0f);

    /* ② 积分分离：误差还很大时先不积分，专治起步超调 */
    PID_SetSeparateThreshold(&s_pid, 200.0f);   /* 0 表示关闭该功能 */

    /* ③ 微分先行：设定值突变不产生微分尖峰 */
    PID_SetDerivOnMeasurement(&s_pid, 1U);
}

void pid_watch(void)
{
    float p, i, d;

    PID_GetTerms(&s_pid, &p, &i, &d);

    /* 稳态时：P 接近 0、I 是一个不动的常数、D 接近 0。
     *   I 一直在涨           -> 积分饱和（查上面三条有没有设上）
     *   D 一直在正负乱跳     -> 传感器噪声没滤干净，先回去加滤波
     *   P 一直很大且反号振荡 -> Kp 太大
     */
    printf("P=%.2f I=%.2f D=%.2f\r\n", (double)p, (double)i, (double)d);
}

/* 固定周期 + 真实 dt + 接进 FreeRTOS 任务。 */
#include "pid.h"
#include "sys_tick.h"
#include "FreeRTOS.h"
#include "task.h"

#define LOOP_PERIOD_MS  10U

void loop_task(void *arg)
{
    TickType_t last = xTaskGetTickCount();

    (void)arg;

    for (;;)
    {
        uint32_t t0 = SYS_TICK_GetTick();
        float    dt;

        /* ① 用 RTOS 的周期延时保证 10ms 一次，从根上消灭 dt 抖动 */
        vTaskDelayUntil(&last, pdMS_TO_TICKS(LOOP_PERIOD_MS));

        /* ② 把真实经过的时间算出来（正常情况下就是 0.010） */
        dt = (float)SYS_TICK_Elapsed(t0) / 1000.0f;
        if ((dt <= 0.0f) || (dt > 0.1f)) { dt = 0.01f; }   /* 明显异常就用标称值 */

        loop_step(target_value(), dt);
    }
}

/* 全链路 + 可观测性：出问题时先看这一行输出。 */
#include "sys_filter.h"
#include "kalman.h"
#include "pid.h"
#include "hcsr04.h"
#include "sys_adc.h"
#include <stdio.h>

void loop_dump(void)
{
    float p, i, d;

    PID_GetTerms(&s_pid, &p, &i, &d);

    printf("K=%.3f resid=%.2f | P=%.2f I=%.2f D=%.2f | bad=%lu\r\n",
           (double)KALMAN_GetGain(&s_kf), (double)KALMAN_GetResid(&s_kf),
           (double)p, (double)i, (double)d, (unsigned long)s_bad_cnt);
}

/* 超声波当输入源时的典型处理：先中值再限幅，两种错误分别处理 */
float distance_step(float target)
{
    uint16_t cm = 0U;
    uint8_t  rc = HCSR04_ReadCmMedian(&cm, 5U);

    if (rc == HCSR04_ERR_NO_ECHO) { return KALMAN_GetValue(&s_kf); }  /* 没回波：沿用上次 */
    if (rc == HCSR04_ERR_RANGE)   { return KALMAN_GetValue(&s_kf); }  /* 超量程：同上 */
    if (rc != HCSR04_OK)          { return KALMAN_GetValue(&s_kf); }

    return KALMAN_Update(&s_kf, (float)cm);
}

