/* ============================================================
 *  板2：DS18B20 单总线温度最小可用 *   按「㉙ DS18B20 引导」5 步搭出来的成品
 *  平台：STM32F407ZGT6 · FWLIB · ds18b20.h
 *  接线：DQ = PG9，4.7kΩ 上拉到 3.3V；总线可挂多颗（本项目只挂一颗）
 * ============================================================ */
#include "stm32f4xx.h"
#include "sys_clock.h"
#include "sys_tick.h"
#include "sys_usart.h"
#include "ds18b20.h"

/* 12 位分辨率：1 LSB = 0.0625℃ = 1/16℃，×100/16 就是百分之一度 */
static int32_t ds18b20_raw_to_c100(int16_t raw)
{
    return ((int32_t)raw * 100) / 16;
}

static uint8_t ds18b20_read_c100(int32_t *out_c100)
{
    int16_t raw = 0;

    if (DS18B20_IsPresent() == 0U)    { return 0U; }   /* 线掉了或没插器件 */
    if (DS18B20_StartConvert() == 0U) { return 0U; }   /* 只发命令，数据还没好 */

    SYS_TICK_Delay_ms(900);                            /* 12 位要 800ms，留 100ms 余量 */

    if (DS18B20_ReadTempRaw(&raw) == 0U) { return 0U; }

    *out_c100 = ds18b20_raw_to_c100(raw);
    return 1U;
}

int main(void)
{
    int32_t c100 = 0;

    SYS_CLK_ToHighSpeed();
    SYS_TICK_Init();
    SYS_USART_Init(SYS_USART_1, 115200U);
    DS18B20_Init();

    while (1)
    {
        if (ds18b20_read_c100(&c100) != 0U)
        {
            SYS_USART_Printf(SYS_USART_1, "T = %ld.%02ld C\r\n",
                             (long)(c100 / 100), (long)(c100 >= 0 ? c100 % 100 : (-c100) % 100));
        }
        else
        {
            SYS_USART_SendLine(SYS_USART_1, "DS18B20 read fail");
        }
        SYS_TICK_Delay_ms(1000);
    }
}

