/* ============================================================
 *  ota.h —— 升级宏与结构体（App 与 Bootloader 共用同一份，别各写一套）
 * ============================================================ */
#define OTA_APP_ADDR      0x08004000UL      /* App 运行区基址（IROM1 也改这里） */
#define OTA_BACKUP_ADDR   0x08010000UL      /* 下载区基址（板1 64KB / 板2 192KB） */
#define OTA_APP_MAX       0x0000C000UL      /* 运行区容量 48KB，固件不许超过 */
#define OTA_MAGIC         0x4F544131UL      /* 'OTA1'：固件头魔数 */
#define OTA_FLAG_PENDING  0xA5A50001UL      /* 待安装（写进 RTC_BKP_DR1） */
#define OTA_FLAG_DONE     0xA5A50002UL      /* 已安装 */
#define OTA_CHUNK_MAX     128U              /* 一个数据块的字节数（4 字节对齐） */

/* 升级命令：新开三条，和现有 20 字节帧的 CMD 段并存，用前同步写进协议文档 */
#define OTA_CMD_START     0x30U             /* 上位机 → 设备：总长度 + CRC，请开始 */
#define OTA_CMD_DATA      0x31U             /* 上位机 → 设备：偏移 + 数据块 */
#define OTA_CMD_FINISH    0x32U             /* 上位机 → 设备：发完了，请校验 */

typedef struct
{
    uint32_t magic;
    uint32_t version;
    uint32_t size;              /* 固件字节数，不含头 */
    uint32_t crc32;             /* 对固件体算的 CRC（ST 硬件 CRC，按字） */
    uint32_t reserved[4];       /* 补齐到 32 字节 */
} OtaHdr_t;

typedef struct
{
    uint32_t off;               /* 写进下载区的字节偏移 */
    uint16_t len;               /* 本块有效字节数（≤ OTA_CHUNK_MAX，4 字节对齐） */
    uint8_t  data[OTA_CHUNK_MAX];
} OtaChunk_t;

uint8_t ota_write_chunk(uint32_t off, const uint8_t *p, uint32_t len);
uint8_t ota_verify(const OtaHdr_t *h);

/* ============================================================
 *  App 侧：升级任务（通信任务只把块塞进队列，Flash 操作全在这里做）
 *  为什么单独一个任务：擦写内部 Flash 时 CPU 取指被暂挂，写一块要毫秒级、
 *  擦一扇区到秒级，放在通信任务里会直接把 LoRa / MQTT 的收包节奏拖垮。
 * ============================================================ */
static QueueHandle_t s_q_ota = NULL;

static void OtaTask(void *arg)
{
    OtaChunk_t c;
    (void)arg;

    for (;;)
    {
        if (xQueueReceive(s_q_ota, &c, portMAX_DELAY) != pdTRUE)
        {
            continue;
        }

        if (ota_write_chunk(c.off, c.data, c.len) != 0U)
        {
            /* 写失败：不置标志，让上位机从这一块重发（偏移由上位机维护） */
            SYS_USART_SendLine(SYS_USART_1, "[OTA] write chunk FAILED, ask resend");
            continue;
        }

        /* 最后一块到达后由 OTA_CMD_FINISH 触发校验；这里只在收到收尾命令时校验 */
        if (c.off == 0xFFFFFFFFUL)
        {
            const OtaHdr_t *h = (const OtaHdr_t *)OTA_BACKUP_ADDR;

            if (ota_verify(h) != 0U)
            {
                SYS_USART_SendLine(SYS_USART_1, "[OTA] verify FAILED, ask resend");
                continue;                    /* 校验不过：旧程序继续跑，不砖 */
            }

            PWR_BackupAccessCmd(ENABLE);
            RTC_WriteBackupRegister(RTC_BKP_DR1, OTA_FLAG_PENDING);
            SYS_USART_SendLine(SYS_USART_1, "[OTA] download complete, reboot to install");
            vTaskDelay(pdMS_TO_TICKS(50));   /* 等串口把这句话发完再复位 */
            NVIC_SystemReset();              /* 剩下的交给 Bootloader */
        }
    }
}

/* 通信任务解析出 0x30 / 0x31 / 0x32 之后，只往队列里塞，不碰 Flash */
static void ota_on_frame(const uint8_t *frame)
{
    OtaChunk_t c;

    if (frame[2] == OTA_CMD_START)
    {
        /* 只是通告“要开始了”；擦除交给第一块数据（off == 0 时自动擦） */
        return;
    }

    if (frame[2] != OTA_CMD_DATA)
    {
        if (frame[2] == OTA_CMD_FINISH)
        {
            c.off = 0xFFFFFFFFUL;            /* 约定：这个偏移表示“收尾，去校验” */
            c.len = 0U;
            xQueueSend(s_q_ota, &c, 0);
        }
        return;
    }

    c.off = ((uint32_t)frame[3] << 24) | ((uint32_t)frame[4] << 16)
          | ((uint32_t)frame[5] << 8)  |  (uint32_t)frame[6];
    c.len = (uint16_t)frame[7];
    if (c.len == 0U || c.len > OTA_CHUNK_MAX || (c.len & 0x3U) != 0U)
    {
        return;                              /* 长度不合法：直接丢，等上位机重传 */
    }
    memcpy(c.data, frame + 8, c.len);
    xQueueSend(s_q_ota, &c, 0);              /* 队列满就丢，由上位机重传 */
}

int main(void)
{
    /* 升级任务优先级给低一点（2）：它一擦 Flash 就长时间占着 CPU */
    s_q_ota = xQueueCreate(4, sizeof(OtaChunk_t));
    xTaskCreate(OtaTask, "Ota", 256, NULL, 2, NULL);

    /* 通信任务：收到帧先 SYS_FRAME_Verify，再按 CMD 分发；0x30~0x32 走 ota_on_frame */
    xTaskCreate(CommTask, "Comm", 192, NULL, 4, NULL);
    vTaskStartScheduler();
    for (;;) { }
}

