/* system_stm32f4xx.c 里那一行（两个工程都要改）： */
#define VECT_TAB_OFFSET  0x0040000U   /* 原为 0x00！App 基址 0x08004000 */
/* 不想改这一行，也可以在 App 的 main() 最开头补：
 *   SCB->VTOR = 0x08004000UL;
 * 但两者只能留一个，别两边都写。 */

/* ota.h 关键片段 */
#define OTA_CHUNK_MAX     128U      /* 一块 128 字节，LoRa 通道够用 */
#define OTA_CMD_START     0x30U     /* 上位机 → 设备：总长 + CRC */
#define OTA_CMD_DATA      0x31U     /* 上位机 → 设备：偏移 + 数据 */
#define OTA_CMD_FINISH    0x32U     /* 上位机 → 设备：收完了 */

typedef struct
{
    uint32_t magic;
    uint32_t version;
    uint32_t size;
    uint32_t crc32;
    uint32_t reserved[4];
} OtaHdr_t;

uint8_t ota_write_chunk(uint32_t off, const uint8_t *p, uint32_t len)
{
    if ((off & 0x3U) != 0U || (len & 0x3U) != 0U) { return 1U; }
    if (off == 0U && SYS_FLASH_EraseSector(OTA_BACKUP_ADDR) != SYS_FLASH_OK) { return 2U; }
    return (SYS_FLASH_Write(OTA_BACKUP_ADDR + off, p, len) == SYS_FLASH_OK) ? 0U : 3U;
}

/* 通信任务里只入队，不做 Flash 操作：队列满就丢，交给重传 */
if (xQueueSend(s_q_ota, &c, 0) != pdTRUE)
{
    /* 队列满：本块丢弃，上位机会重发 */
}
/* 不要把 xQueueSend 的等待设成 portMAX_DELAY：
 * 那会把 LoRa / MQTT 的收包任务一起拖住。 */

CRC_ResetDR();                                 /* 必须先复位，否则接着上次的结果算 */
uint32_t crc = CRC_CalcBlockCRC((uint32_t *)(OTA_BACKUP_ADDR + 32U), hdr.size / 4U);
if (hdr.magic != OTA_MAGIC || hdr.size == 0U || hdr.size > OTA_APP_MAX
    || (hdr.size & 0x3U) != 0U || crc != hdr.crc32)
{
    return 1U;                                 /* 校验不过：不许安装 */
}

PWR_BackupAccessCmd(ENABLE);
RTC_WriteBackupRegister(RTC_BKP_DR1, 0xA5A50001UL);   /* 待安装 */
SYS_USART_SendLine(SYS_USART_1, "[OTA] download complete, reboot to install");
vTaskDelay(pdMS_TO_TICKS(50));                       /* 等串口发完 */
NVIC_SystemReset();                                  /* 软复位，交给 Bootloader */

if (RTC_ReadBackupRegister(RTC_BKP_DR1) == OTA_FLAG_PENDING)
{
    if (ota_verify(hdr) == 0U && ota_install(hdr) == 0U)
    {
        RTC_WriteBackupRegister(RTC_BKP_DR1, OTA_FLAG_DONE);  /* 装完才清标志 */
    }
    /* 失败：标志保持“待安装”，下次上电再试；旧程序仍在运行区 */
}
ota_jump(OTA_APP_ADDR);

uint32_t sp = *(volatile uint32_t *)OTA_APP_ADDR;
uint32_t pc = *(volatile uint32_t *)(OTA_APP_ADDR + 4U);
__disable_irq();
SysTick->CTRL = 0U;
for (int i = 0; i < 8; i++) { NVIC->ICER[i] = 0xFFFFFFFFUL; NVIC->ICPR[i] = 0xFFFFFFFFUL; }
SCB->VTOR = OTA_APP_ADDR;
__set_MSP(sp);
((void (*)(void))pc)();

