#define ota_app_max       0x0000c000ul   /* 48kb */
#define ota_magic         0x4f544131ul   /* 'ota1' */ 把四段地址按顺序写成一列，相邻两段必须首尾相接：0x08000000+16k=0x08004000，0x08004000+48k=0x08010000，下载区之后是预留区，最后是参数区。
参数区必须是 sys_flash.h 里现有的 sys_flash_param_addr（板1 0x08070000 / 板2 0x080e0000），不要另选地址。 48kb 的运行区对本仓库现在的代码（板1 约 30kb、板2 约 43kb）够用但不宽裕：加功能前先看 keil 的 program size 或 .map，超过 48kb 就要把运行区放大，同时下载区也要跟着够大。
如果选了和参数区同一个扇区，第一次保存参数就会把运行区擦掉。 sys_flash_erasesector flash_erasesector flash_sector_11 flash_sector_7 sys_flash_param_addr 把 app 从 0x08000000 挪到 0x08004000 bootloader 要占住 0x08000000，app 就必须搬家。搬家要改两个地方，只改一个的后果是“烧进去能跑、一进中断就跑飞”，很难查。 ① keil：target → irom1 起始地址改成 0x08004000（长度按 0x8000 或 0xc000 填）；② 打开 rte/device/…/system_stm32f4xx.c，把 vect_tab_offset 从 0x00 改成 0x4000；③ 先只烧 app（不烧 bootloader）到 0x08004000，验证串口、定时器、中断都正常；④ 确认没问题再写 bootloader。 /* system_stm32f4xx.c 里那一行（两个工程都要改）： */
#define vect_tab_offset  0x0040000u   /* 原为 0x00！app 基址 0x08004000 */
/* 不想改这一行，也可以在 app 的 main() 最开头补：
 *   scb->vtor = 0x08004000ul;
 * 但两者只能留一个，别两边都写。 */ 把 app 单独烧到 0x08004000：串口有打印、定时器中断能进（led 心跳在闪）、按键外部中断能进。
三项都通过，说明 irom1 与 vect_tab_offset 都对了。 只改 irom1 不改 vect_tab_offset：systick 还能跑（它是内核异常，向量表在 systeminit 之后才用），但一进 usart/exti 中断就跳到 0x08000000 的旧向量表 → hardfault 或跑到 bootloader 的死循环里。
两个工程（板1、板2）的 system_stm32f4xx.c 是各自独立的，改一个不要忘了另一个。 nvic_setvectortable scb_vtor systeminit vect_tab_offset 新开 ota.h：宏、固件头、数据块、命令号 把升级相关的东西集中到一个头文件，app 与 bootloader 共用：地址宏、固件头结构体、数据块、以及三条新命令号。这样两边不会有“同一件事写两份、改一处忘一处”的问题（本仓库踩过这个坑，所以这次直接把共用项抽出来）。 ① 建 ota.h，写四个地址宏 + ota_magic + 两个标志值；② 定义固件头 otahdr_t（32 字节：magic / version / size / crc32 / 保留）；③ 定义升级命令 ota_cmd_start / data / finish；④ 把三条命令号写进协议文档，和现有 cmd 列表一起维护。 /* ota.h 关键片段 */
#define ota_chunk_max     128u      /* 一块 128 字节，lora 通道够用 */
#define ota_cmd_start     0x30u     /* 上位机 → 设备：总长 + crc */
#define ota_cmd_data      0x31u     /* 上位机 → 设备：偏移 + 数据 */
#define ota_cmd_finish    0x32u     /* 上位机 → 设备：收完了 */

typedef struct
{
    uint32_t magic;
    uint32_t version;
    uint32_t size;
    uint32_t crc32;
    uint32_t reserved[4];
} otahdr_t; ota.h 能被 app 与 bootloader 两个工程同时 include 且不报错；固件头 sizeof(otahdr_t) 打印出来必须是 32。
“32”这个数字很重要：下载区最前面 32 字节是头，固件体从第 33 字节开始。 结构体不要用位域或 uint8_t 拼：编译器的对齐规则不同，两端的 32 字节内容就会错位，crc 永远对不上。
命令号别和现有 cmd 撞：本仓库业务帧用的是 0x01~0x17，从 0x30 起新开一段，留出中间给以后的功能。 sys_frame_verify otahdr_t 收固件：分块写进下载区（第一块先擦） 下载区是一段从来没被写过的 flash：f4 只能把 1 写成 0，所以写入前必须整段擦成 0xff。擦除按扇区做，sys_flash_erasesector 会自动由地址定位扇区号，不用自己算。 ① 收到 ota_cmd_start 时先擦下载区；② 每收到一块数据，按偏移写进去，绝对地址 = ota_backup_addr + off；③ 写入长度必须是 4 的整数倍（不足的块由上位机补齐）；④ 每次都检查返回值，失败就回报“这一块请重发”。 uint8_t ota_write_chunk(uint32_t off, const uint8_t *p, uint32_t len)
{
    if ((off & 0x3u) != 0u || (len & 0x3u) != 0u) { return 1u; }
    if (off == 0u && sys_flash_erasesector(ota_backup_addr) != sys_flash_ok) { return 2u; }
    return (sys_flash_write(ota_backup_addr + off, p, len) == sys_flash_ok) ? 0u : 3u;
} 串口/上位机发 3 块，设备端回 3 条成功；用调试器看 0x08010000 开始的内存，前 32 字节是固件头（前 4 个字节是 41 31 54 4f，即 'ota1' 的小端）。
再故意发一块越界的（off 超过 ota_app_max），应该返回失败而不是写坏。 第一次写之前忘了擦：写进去的值和 0xff 做与运算后不等于期望值，但 flash_programword 仍可能返回成功——所以“写前必擦”是硬规矩。
擦的是下载区，别把 0x08000000（bootloader）或参数区地址传进来：sys_flash_erasesector 是整扇区擦，传错地址等于把自己擦掉。 sys_flash_erasesector sys_flash_write sys_flash_read flash_programword 丢包与断点续传：偏移由发送方维护 无线链路会丢块（lora 尤其），所以必须能重传；但设备端不需要记住“收到哪了”，让上位机/云端维护偏移，重发时带着同一个偏移重发即可。这样断电重启也能续：上位机重发全部，或者从它自己记的偏移继续。 ① 约定数据块格式：偏移 4 字节（大端）+ 长度 1 字节 + 数据；② 设备端写失败就回报失败，不发“进度”；③ 上位机每发 n 块等一次回应（或定时重发同一块）；④ 队列满就丢块，靠上位机重传来兜底（不要阻塞通信任务）。 /* 通信任务里只入队，不做 flash 操作：队列满就丢，交给重传 */
if (xqueuesend(s_q_ota, &c, 0) != pdtrue)
{
    /* 队列满：本块丢弃，上位机会重发 */
}
/* 不要把 xqueuesend 的等待设成 portmax_delay：
 * 那会把 lora / mqtt 的收包任务一起拖住。 */ 故意在发送中途拔掉天线或断开 wifi，再恢复：上位机重发后设备仍能收全，最后校验通过。
全程设备端不能出现“卡住不动、串口不响应”的现象。 设备端如果自己记偏移，一旦设备断电重启，上位机不知道设备记得多少，只能全部重发；所以让发送方维护偏移是最省事、也最适合现场的做法。
不要在设备端用“累计字节数”判断进度：丢一块之后累计值就永远对不上，后面全部错位——所以偏移必须由发送方算好再发。 xqueuesend xqueuecreate 校验：魔数 + 长度 + crc（长度参数是字数！） 校验是“不砖”的唯一防线。三个检查缺一不可：magic 判“下载区里到底是不是固件”，size 判“会不会写爆运行区”，crc32 判“内容有没有坏”。这一步通过之前，任何擦除都不许发生。 ① 先查 magic、size 范围、size 是否 4 的倍数；② crc_resetdr() 复位，再对固件体（跳过 32 字节头）算 crc_calcblockcrc；③ 和头里的 crc32 比；④ 记录 version，复位后 app 打印出来便于确认升到了哪一版。 crc_resetdr();                                 /* 必须先复位，否则接着上次的结果算 */
uint32_t crc = crc_calcblockcrc((uint32_t *)(ota_backup_addr + 32u), hdr.size / 4u);
if (hdr.magic != ota_magic || hdr.size == 0u || hdr.size > ota_app_max
    || (hdr.size & 0x3u) != 0u || crc != hdr.crc32)
{
    return 1u;                                 /* 校验不过：不许安装 */
} 把固件中间改一个字节再走一遍：必须看到 verify failed，而且设备串口仍能应答（说明还在跑旧程序）。
再把它改回来重走：应该通过。 最容易错的是长度参数：crc_calcblockcrc 的第二个参数是【字数】（字节数 ÷ 4），不是字节数；写成字节数会算到内存越界，结果当然对不上。
第二容易错的是算法不一致：st 的 crc 单元多项式 0x4c11db7、没有输入/输出反转，结果和电脑上 zlib 的 crc32 完全不同——上位机要校验就得照 st 的算法实现一遍，或者两边都改用软件 crc32。 crc_resetdr crc_calcblockcrc 置“待安装”标志、应答、软复位 校验通过后不要就地安装：app 自己正跑在运行区里，擦运行区就是擦掉自己正在执行的代码，必死。正确做法是写一个“待安装”标志，然后复位，让 bootloader 去干这件事。 ① 打开备份域访问，把标志写进 rtc_bkp_dr1（掉电保持、写入快，不用擦扇区）；② 给上位机回一条“下载完成”，等串口把它发完；③ 调用 nvic_systemreset() 复位。注意 rtc_bkp_dr0 已被“已初始化 0x5a5a”占用，不要混用。 pwr_backupaccesscmd(enable);
rtc_writebackupregister(rtc_bkp_dr1, 0xa5a50001ul);   /* 待安装 */
sys_usart_sendline(sys_usart_1, "[ota] download complete, reboot to install");
vtaskdelay(pdms_to_ticks(50));                       /* 等串口发完 */
nvic_systemreset();                                  /* 软复位，交给 bootloader */ 执行后串口先打出 download complete, reboot to install，然后板子复位重新上电（能看到上电横幅）。
复位后用调试器读 rtc_bkp_dr1，值必须是 0xa5a50001。 复位前不 delay 直接 nvic_systemreset()：串口那句话可能只发出去一半，上位机显示的是乱码或超时，误判成升级失败。
用 systemreset 而不是直接跳转：复位能让外设、时钟、nvic 全部回到干净状态，比手工清理可靠得多。 pwr_backupaccesscmd rtc_writebackupregister rtc_readbackupregister nvic_systemreset 写 bootloader：读标志 → 再校验一次 → 搬运 bootloader 只做四件事，多一行代码都别加。它必须“不信任上一次运行的结果”：不管标志是什么，装之前都自己再校验一遍，避免“上位机报的通过”和“实际内存里的内容”不一致。 ① 复位后先初始化串口（方便看日志）；② 读 rtc_bkp_dr1：不是“待安装”就直接跳到 app；③ 是“待安装”，就重新校验固件头与 crc；④ 通过才擦运行区、从下载区分块复制过去，复制完回读比对；⑤ 全部成功后才把标志改成“已安装”。 if (rtc_readbackupregister(rtc_bkp_dr1) == ota_flag_pending)
{
    if (ota_verify(hdr) == 0u && ota_install(hdr) == 0u)
    {
        rtc_writebackupregister(rtc_bkp_dr1, ota_flag_done);  /* 装完才清标志 */
    }
    /* 失败：标志保持“待安装”，下次上电再试；旧程序仍在运行区 */
}
ota_jump(ota_app_addr); 正常升级：串口先打 pending fw found / crc ok / installing / install done，然后 app 起来（能打印出新版本号）。
把下载区故意改坏一个字节：应该只打 verify failed，设备仍然跑旧程序——这就是回滚生效。 清标志的位置最关键：必须放在“搬运完成并回读比对通过”之后。放在擦除之前，一旦搬一半断电，标志已清，设备就真的砖了。
不要把 bootloader 写大：sector 0 只有 16kb，里面只放升级逻辑和串口打印，别把业务驱动链进来。 flash_unlock flash_erasesector flash_programword flash_waitforlastoperation flash_clearflag crc_calcblockcrc 跳转：六步顺序，一步都不能换 跳转顺序是“错一步就崩”的那种：关中断 → 关节拍 → 清 icer/icpr → 设 vtor → 设 msp → 跳 pc。其中 vtor 最容易被漏，漏了的表现是“程序跑起来但一进中断就死”。 ① __disable_irq()；② systick->ctrl = 0；③ 循环写 nvic->icer/icpr 全 1（清掉所有外设中断与挂起）；④ scb->vtor = ota_app_addr；⑤ __set_msp(*(uint32_t*)app)，把栈指针换成 app 的；⑥ 跳到 app+4 处的地址。 uint32_t sp = *(volatile uint32_t *)ota_app_addr;
uint32_t pc = *(volatile uint32_t *)(ota_app_addr + 4u);
__disable_irq();
systick->ctrl = 0u;
for (int i = 0; i < 8; i++) { nvic->icer[i] = 0xfffffffful; nvic->icpr[i] = 0xfffffffful; }
scb->vtor = ota_app_addr;
__set_msp(sp);
((void (*)(void))pc)(); 跳过去之后 app 的串口横幅要正常打出来（说明栈指针和 pc 都对），随便触发一次按键中断（说明 vtor 对了）。
如果卡在 hardfault 或什么都不打印，优先怀疑顺序和 vtor。 先跳再改 vtor 是最典型的错：跳过去的瞬间如果来了中断（systick 就在跑），cpu 按旧向量表取地址，直接 hardfault。
不关中断就换栈指针，也会在中断返回时用到旧栈，表现同样是 hardfault。 scb_vtor nvic_setvectortable nvic_systemreset 上板验证：按断电时刻三个点逐条核对 升级代码写完之后，真正要验证的不是“能升级”，而是“任何时候断电都不砖”。按三个断电点各做一次，全部通过才敢用在现场设备上。 ① 写下载区途中断电：上电应照跑旧程序（标志还是“无”）；② 已置标志、还没复位就断电：上电 bootloader 重新校验，校验不过就不装；③ 搬运行区途中断电：上电重新搬一遍，最终仍能起来。
再加一条：搬运耗时必须小于看门狗超时，否则搬一半被复位，就会永远装不完。 /* 三个断电点 + 看门狗，做成一张上板验证清单：
 *  ① 写下载区途中拔电 → 上电跑旧程序（版本号不变）
 *  ② 置标志后拔电     → 上电走一遍校验，不通过就跳过安装
 *  ③ 搬运途中拔电     → 上电重装，最终跑新程序
 *  ④ 把 iwdg 超时调到 2.5s 后重复 ③ → 必须仍然能装完
 *     （装不完说明搬运耗时 > 狗超时，要放宽 iwdg 或缩小运行区）
 */ 四项全部通过：每一次恢复供电后设备都能正常起来（要么旧版本、要么新版本），串口有明确日志，没有一次需要重新烧写。
做过这一轮，才能说“升级不会变砖”。 在片内 flash 擦写时 cpu 取指被硬件暂挂，擦一个 128kb 扇区可能到秒级，而 iwdg 可能 2.5 秒就复位——所以第 ④ 项必须真做实机，不能只在纸上算。
bootloader 里没有 rtos，喂狗任务不存在，所以更要靠“搬运耗时 < 狗超时”来保证。 iwdg_setreload iwdg_reloadcounter sys_wdg_init nvic_systemreset

