// ① 发 2 字节命令：首字节当 reg 传，第二字节放 buf 里
uint8_t lo = 0x00;
SYS_I2C_WriteBytes(SYS_I2C_1, 0x44, 0x24, &lo, 1);   // 线上实际发出 0x24 0x00
vTaskDelay(pdMS_TO_TICKS(15));                        // 等转换（手册 max 15 ms）

// ② 读 6 字节：SHT30 没有寄存器号概念，用 ReadRaw（不是 ReadBytes）
uint8_t d[6];
SYS_I2C_ReadRaw(SYS_I2C_1, 0x44, d, 6);

// ③ 换算（数据手册原文）
uint16_t tRaw = ((uint16_t)d[0] << 8) | d[1];          // 温度原始值（大端）
uint16_t hRaw = ((uint16_t)d[3] << 8) | d[4];          // 湿度原始值（大端）
float temp = -45.0f + 175.0f * tRaw / 65535.0f;        // 摄氏度
float humi = 100.0f * hRaw / 65535.0f;                 // 相对湿度 %RH

// ④ 本项目协议要求 ×100 后的整数
int16_t  temp100 = (int16_t)(temp * 100);              // 25.30 ℃ → 2530
uint16_t humi100 = (uint16_t)(humi * 100);             // 48.55 %  → 4855
// 若发的是 0x2C06（带拉伸）：芯片会把 SCL 拉低直到出数，主机不用再延时；板1 超时较短，见命令表说明
// ⑤ CRC-8 校验（poly 0x31、init 0xFF、不反转、不异或）：crc ^= 字节后 8 次「左移一位，最高位为 1 则异或 0x31」；自检 CRC(0xBEEF) = 0x92

all._hay:
sht30 温湿度传感器 sensirion 温湿度传感器，直接输出数字温度与湿度，无需 adc 采样、线性拟合与标定。温度精度 ±0.3 ℃（典型），湿度 ±3 %rh（±2 %rh 是 sht31 的指标），分辨率 0.015 ℃ / 湿度 0.01 %rh。本项目协议按 ×100 传输，即 0.01 分辨率，÷10 会浪费芯片本身的分辨能力。单次测量最长 15 ms（高重复性档）。dht11 为 ±2 ℃、整数输出、单总线时序敏感，本器件精度高一个量级，走标准 i2c，同一条总线可挂多颗。 sht30 sht30 温湿度 温度 湿度 传感器 环境 数据手册 寄存器 0x44 i2c 换算 读取 crc 传感器 1) 第 3、6 字节是 crc 校验字节，不是数据；不能把 6 字节当作 3 个 16 位数。crc-8 参数（手册表19）：多项式 0x31（x8+x5+x4+1）、初值 0xff、输入/输出不反转、结果不与 0xff 异或；自检向量 crc(0xbeef) = 0x92。
2) 命令字先高字节后低字节（0x24 在前），与多数芯片相反；发 2 字节命令要用 writebytes 把首字节当 reg 传。
3) 地址 0x44 是 7 位地址，sys_i2c.h 的 addr7 参数一律传 0x44（底层自己左移，不要自己写 0x88）。
4) 15 ms 等待在 rtos 任务里用 vtaskdelay 让出 cpu，不要在 sensortask 内空转。
5) 本器件与 bmp280/bh1750/ccs811 共用 i2c1，读写前后须 sys_i2c_lock / sys_i2c_unlock。
6) 本项目尚未写 sht30 专用驱动（fwlib 里只有 sys_bmp280 / sys_bh1750 / sys_ccs811 / sys_dht11），上面这段就是可直接搬的读法；若与 aht10（0x38）互换，注意命令字完全不同。 // ① 发 2 字节命令：首字节当 reg 传，第二字节放 buf 里
uint8_t lo = 0x00;
sys_i2c_writebytes(sys_i2c_1, 0x44, 0x24, &lo, 1);   // 线上实际发出 0x24 0x00
