float lux;
if (SYS_BH1750_ReadLux(SYS_I2C_1, &lux) == 0) {
    /* lux 已是照度值；过饱和（原始值 0xFFFF）时驱动返回 SYS_BH1750_ERR_SATURATED */
}

// ② 手动读（搞清时序用）：命令式器件，写命令用 WriteCmd，读数据用 ReadRaw
