// ① 推荐用本项目驱动（FWLIB\src\sys_ccs811.c）
//    驱动内部顺序：等 20ms → 读 0x20 自检 → 0xFF 软复位 → 等 20ms
//    → 轮询 0x00 等 APP_VALID(bit4) → 0xF4 只发命令(APP_START) → 写 0x01 设模式
if (SYS_CCS811_Init(SYS_I2C_1) != 0) { /* 见 SYS_CCS811_ERR_HW_ID / ERR_APP_INVALID / ERR_DEV_ERROR */ }
SYS_CCS811_Data_t d;
if (SYS_CCS811_DataReady(SYS_I2C_1) && SYS_CCS811_Read(SYS_I2C_1, &d) == 0 && d.valid) {   // 先判就绪（STATUS 0x08）再读
    /* d.eco2_ppm / d.tvoc_ppb；d.status、d.error_id 排错用 */
}
SYS_CCS811_SetEnvData(SYS_I2C_1, temp_c, humi_rh);   // 用 SHT30 读数喂进去，提高 TVOC 精度

// ② 手动初始化时两条命令要分清：
//    只发一个字节的命令（APP_START）用 WriteCmd
SYS_I2C_WriteCmd(SYS_I2C_1, 0x5A, 0xF4);
//    写带数据的寄存器用 WriteByte
SYS_I2C_WriteByte(SYS_I2C_1, 0x5A, 0x01, 0x10);      // MEAS_MODE = 恒供电，每秒测一次

// ③ 每 1 s 读结果（8 字节）
uint8_t r[8];
SYS_I2C_ReadBytes(SYS_I2C_1, 0x5A, 0x02, r, 8);
uint16_t eco2 = ((uint16_t)r[0] << 8) | r[1];        // ppm，大端
uint16_t tvoc = ((uint16_t)r[2] << 8) | r[3];        // ppb，大端
// 协议要求：TVOC 原值（ppb）直接填；eCO2 只在界面上显示，不进环境帧

all._hay:
ccs811 空气质量传感器（tvoc / eco₂） ams 金属氧化物气体传感器，算法在芯片内部执行，主机读 alg_result_data 即可获得 tvoc（ppb）与等效 co₂（ppm）。无需标定曲线。芯片按设定周期自主测量，主机读一次结果寄存器（8 字节，前 4 字节为 eco₂/tvoc），耗时以实测为准，厂商手册未给该数字。
测量对象为总挥发性有机物（新家具、溶剂、酒精、人体代谢物均会使其升高），对应项目中的空气洁净度。
wake 脚未拉低时芯片不响应 i2c，地址扫描也扫不到，易误判为模块损坏。 ccs811 ccs811 tvoc eco2 二氧化碳 空气质量 空气洁净度 有害气体 挥发性有机物 传感器 数据手册 寄存器 0x5a wake 老化 基线 meas_mode 传感器 1) wake 脚不拉低时 ccs811 不响应 i2c，地址扫描也扫不到。先拉低 wake 再读 hw_id(0x20)，读到 0x81 为正常。
2) 必须发 app_start(0xf4)，否则芯片停在引导模式，读 alg_result_data 返回全 0 或报错；它是「只发寄存器号」的命令，要用 writecmd 而不是 writebyte。
3) 新模块需连续老化（burn-in）48 小时后读数才稳定，使用前应提前通电。
4) 基线（0x11）只在器件稳定后读才有意义：写回可少等一段稳定时间，但不能替代老化，且必须「同一器件 + 同一驱动模式」；运行不足 24 h 就写回，器件会把污染物浓度算得偏高（驱动 sys_ccs811_setbaseline / getbaseline）。
5) 模式选恒供电 0x10（每秒一次）时 cpu 占用最低（一次读回 8 字节，前 4 字节是 eco₂/tvoc）；0x00 是空闲，会一直读出旧值。
6) error_id 是排错第一现场：0x10 加热器故障、0x20 加热电压错误多为供电不足或焊接不良。 // ① 推荐用本项目驱动（fwlib\src\sys_ccs811.c）
//    驱动内部顺序：等 20ms → 读 0x20 自检 → 0xff 软复位 → 等 20ms
//    → 轮询 0x00 等 app_valid(bit4) → 0xf4 只发命令(app_start) → 写 0x01 设模式
if (sys_ccs811_init(sys_i2c_1) != 0) { /* 见 sys_ccs811_err_hw_id / err_app_invalid / err_dev_error */ }
sys_ccs811_data_t d;
if (sys_ccs811_dataready(sys_i2c_1) && sys_ccs811_read(sys_i2c_1, &d) == 0 && d.valid) {   // 先判就绪（status 0x08）再读
    /* d.eco2_ppm / d.tvoc_ppb；d.status、d.error_id 排错用 */
}
sys_ccs811_setenvdata(sys_i2c_1, temp_c, humi_rh);   // 用 sht30 读数喂进去，提高 tvoc 精度

// ② 手动初始化时两条命令要分清：
//    只发一个字节的命令（app_start）用 writecmd
sys_i2c_writecmd(sys_i2c_1, 0x5a, 0xf4);
//    写带数据的寄存器用 writebyte
sys_i2c_writebyte(sys_i2c_1, 0x5a, 0x01, 0x10);      // meas_mode = 恒供电，每秒测一次

// ③ 每 1 s 读结果（8 字节）
uint8_t r[8];
sys_i2c_readbytes(sys_i2c_1, 0x5a, 0x02, r, 8);
uint16_t eco2 = ((uint16_t)r[0] << 8) | r[1];        // ppm，大端
uint16_t tvoc = ((uint16_t)r[2] << 8) | r[3];        // ppb，大端
// 协议要求：tvoc 原值（ppb）直接填；eco2 只在界面上显示，不进环境帧    hw_id 0x20 读 1 字节 型号校验：须为 0x81，否则停止后续初始化 hw_version 0x21 读 1 字节 硬件版本号，如 0x10 / 0x11 / 0x12 fw_boot_version 0x23 读 2 字节 固件引导版本（大端） fw_app_version 0x24 读 2 字节 固件应用版本（大端） status 0x00 读 1 字节 bit4 = app_valid（应用固件已加载）、bit3 = data_ready（新数据就绪）、bit0 = error app_start 0xf4 写 — 从引导模式切到应用模式，只发寄存器号不带数据（用 sys_i2c_writecmd） meas_mode 0x01 读/写 1 字节 bit6~4 驱动模式：0x00 空闲 / 0x10 恒供电每秒 / 0x20 脉冲 10 s / 0x30 低功耗脉冲 60 s / 0x40 低功耗 250 ms。bit3 = interrupt（有新样本就拉 nint）、bit2 = thresh（只在越过阈值时才拉 nint） alg_result_data 0x02 读 8 字节 eco₂ 2 字节(大端, ppm) + tvoc 2 字节(大端, ppb) + 状态 1 字节 + 错误 id 1 字节 + 原始 adc 2 字节 env_data 0x05 写 4 字节 外部温湿度输入（提高精度用）：湿度 2 字节 + 温度 2 字节，各按「值 × 512」编码后再取整 baseline 0x11 读/写 2 字节 基线值。写回可省去重新稳定的时间，但不能替代老化：须同一器件、同一驱动模式、且在洁净空气中稳定运行后写回才有意义；早期（运行 ≤500 h）每 24~48 h 重存一次、之后每 5~7 天；只能在驱动模式 ≠ 空闲（0x00）时写 sw_reset 0xff 写 4 字节 软复位（固定序列 0x11 0xe5 0x72 0x8a） error_id 0xe0 读 1 字节 只读寄存器：读它即清错误标志（sw_reset / 上电复位 / nreset 也会清）；读回错误码：0x01 写非法寄存器 / 0x02 读非法寄存器 / 0x04 无效测量模式 / 0x08 传感器电阻超量程 / 0x10 加热器故障 / 0x20 加热电压错误 寄存器 地址 读/写 内容与用途

