sys_adc_init(sys_adc_light_adc, sys_adc_light_ch);        // adc3 + adc_channel_5（pf7）
uint16_t raw = sys_adc_readavg(sys_adc_light_adc, sys_adc_light_ch, sys_adc_avg_times);
uint32_t mv  = sys_adc_tomillivolt(raw);                  // 3300 mv 参考

// ② 反推光敏电阻阻值（分压公式），再按标定表换算亮度
//    假设：3.3v — r_photo — 节点(adc) — r_fixed(10k) — gnd
//    vout = 3.3 * r_fixed / (r_photo + r_fixed)
//    → r_photo = r_fixed * (3.3 - vout) / vout
float vout = mv / 1000.0f;
float r_photo = 10.0f * (3.3f - vout) / vout;             // 单位 kω

