#define FILT_N 8

typedef struct {
    int32_t buf[FILT_N];
    int32_t sum;
    uint8_t idx;
    uint8_t cnt;
} Filt_t;

static int32_t filt_push(Filt_t *f, int32_t v)
{
    if (f->cnt < FILT_N) {
        f->cnt++;
    } else {
        f->sum -= f->buf[f->idx];      /* 挤掉最老的 */
    }
    f->buf[f->idx] = v;
    f->sum += v;
    f->idx = (uint8_t)((f->idx + 1U) % FILT_N);
    return f->sum / (int32_t)f->cnt;
}

static int32_t med3(int32_t a, int32_t b, int32_t c)
{
    if (a > b) { int32_t t = a; a = b; b = t; }
    if (b > c) { int32_t t = b; b = c; c = t; }
    if (a > b) { int32_t t = a; a = b; b = t; }
    return b;                              /* 中值 */
}

#define TEMP_JUMP_X100   300    /* 单次允许最大跳变 3.00 ℃ */
#define PRESS_JUMP_X10    50    /* 单次允许最大跳变 5.0 hPa */

static uint8_t is_outlier(int32_t now, int32_t last, int32_t jump_lim)
{
    int32_t d = now - last;
    if (d < 0) d = -d;
    return (d > jump_lim) ? 1U : 0U;
}

static uint16_t s_reject_t, s_reject_p;

if (is_outlier(t_raw, s_t_last, TEMP_JUMP_X100)) {
    s_reject_t++;                          /* 丢弃，不改 s_t_last */
    SYS_USART_Printf(SYS_USART_1, "temp outlier %d, reject=%u\r\n",
                     t_raw, (unsigned)s_reject_t);
} else {
    s_t_last = t_raw;
}

#define T_LIMIT_X100   3000    /* 30.00 ℃ 触发 */
#define T_HYST_X100     100    /* 回差 1.00 ℃ */

static uint8_t s_alarm_t;

static uint8_t alarm_step(uint8_t cur, int32_t v, int32_t limit, int32_t hyst)
{
    if (cur == 0U) {
        if (v > limit) return 1U;          /* 超上限才置 */
    } else {
        if (v < (limit - hyst)) return 0U; /* 回到回差以下才清 */
    }
    return cur;                            /* 中间带保持 */
}

s_alarm_t = alarm_step(s_alarm_t, s_t_last, T_LIMIT_X100, T_HYST_X100);
SYS_USART_Printf(SYS_USART_1, "T=%d.%02d alarm=%u\r\n",
                 s_t_last / 100, s_t_last % 100, (unsigned)s_alarm_t);

#define AL_TEMP   (1U << 0)
#define AL_HUMI   (1U << 1)
#define AL_PRESS  (1U << 2)
#define AL_LIGHT  (1U << 3)
#define AL_TVOC   (1U << 4)
#define AL_MQ135  (1U << 5)

