if (alarm != 0U) {
    SYS_FRAME_SendShort(SYS_USART_1, 0x02U);   /* 示例：CMD=0x02 表示“有告警” */
}

static QueueHandle_t s_q_sensor;    /* 采集 → 处理 */
static QueueHandle_t s_q_result;    /* 处理 → 组帧（结构体，按值拷贝） */

void vTaskProcess(void *pv)
{
    SensorMsg_t m;
    ProcResult_t r;

    (void)pv;
    for (;;) {
        if (xQueueReceive(s_q_sensor, &m, portMAX_DELAY) == pdPASS) {
