            r.alarm = process_one(&m, &r);          /* 滤波+野值+换算+阈值 */
            r.tick  = SYS_TICK_GetTick();

            SYS_USART_Printf(SYS_USART_1, "[处理] valid=0x%02X alarm=0x%02X T=%d.%02d\r\n",
