🧭 板1 · 阶段 5｜数据处理与阈值：从原始值到能报警的干净数 把采集来的原始值做滤波、去野值、判阈值、打包告警位，并把量纲换算成整数（温度湿度 ×100、气压 ×10）。 板1 数据处理 滑动平均 中值滤波 野值剔除 阈值 回差 迟滞 告警位 打包 量纲 倍率 ×100 ×10 定点 板1 项目引导   本阶段的产物：一个纯计算的“处理任务”——输入是阶段 4 的 sensormsg_t，输出是 6 个定点整数 + 1 个告警位字节。它必须做到：不阻塞、不访问硬件、读不到的数不进结果；超限置位、回到阈值以下（带回差）才清位，避免在阈值上下抖动时告警疯狂翻转。做完这一阶段，你可以在不动任何硬件的情况下，用“注入一个假值”把告警路径完整走一遍。 滤波：滑动平均 + 中值，抑制单点跳变 传感器偶发跳变（dht11 位相位偏一下、adc 被电机干扰）如果直接进帧，上位机曲线上就是一根根毛刺，阈值判据会被噪声反复触发。 为每一路准备一个小窗口。滑动平均用环形缓冲、窗口 8，算总和而不是每次重算（`sum -= old; sum += new;`）；中值用于抗单点野值，窗口取 3 就够：三个值排序取中间那个，把一次跳变直接吃掉。滤波只对**成功读到**的样本做，失败轮次不要塞 0 进窗口（会把平均值拉低）。 #define filt_n 8

typedef struct {
    int32_t buf[filt_n];
    int32_t sum;
    uint8_t idx;
    uint8_t cnt;
} filt_t;

static int32_t filt_push(filt_t *f, int32_t v)
{
    if (f->cnt < filt_n) {
        f->cnt++;
    } else {
        f->sum -= f->buf[f->idx];      /* 挤掉最老的 */
    }
    f->buf[f->idx] = v;
    f->sum += v;
    f->idx = (uint8_t)((f->idx + 1u) % filt_n);
    return f->sum / (int32_t)f->cnt;
}

static int32_t med3(int32_t a, int32_t b, int32_t c)
{
    if (a > b) { int32_t t = a; a = b; b = t; }
    if (b > c) { int32_t t = b; b = c; c = t; }
    if (a > b) { int32_t t = a; a = b; b = t; }
    return b;                              /* 中值 */
} 串口同时打印“原始值 / 平均后 / 中值后”三列：正常时三者接近；用手指快速弹一下 dht11 或让光敏闪一下手电，原始值出现一根大毛刺，中值列基本不动、平均列只轻微抬一下。 两个坑：① 窗口越大越平滑，但对真实突变的响应越慢——测烟雾/气体这类要抓快速上升的量，窗口别超过 8；② `sum` 用 int32 累加定点值（最大 10132×8），别用 int16，会溢出。 sys_tick_gettick / xqueuereceive / xqueuesend 野值剔除：和中值/上次值比，太离谱就丢 光有平均挡不住连续几拍的野值（比如 dht11 连续两次位相位错），中值窗口 3 也吃不掉；这类值必须按“物理上不可能”直接判死。 两条判据二选一或同时用：① 与同一路最近一次**已接受**值的差超过变化率上限（如气压 1 秒内变化超过 5 hpa、温度超过 3℃/次）即判野值；② 与中值之差超过容忍带即判野值。判野值后**不更新滤波器、也不更新上一次接受值**，并给该路计一个 `reject_cnt` 计数。野值不算“读失败”，所以 `valid` 位保持，但值沿用滤波结果（或本轮标无效，按你的验收口径定，定完就别改）。 #define temp_jump_x100   300    /* 单次允许最大跳变 3.00 ℃ */
#define press_jump_x10    50    /* 单次允许最大跳变 5.0 hpa */

static uint8_t is_outlier(int32_t now, int32_t last, int32_t jump_lim)
{
    int32_t d = now - last;
    if (d < 0) d = -d;
    return (d > jump_lim) ? 1u : 0u;
}

static uint16_t s_reject_t, s_reject_p;

if (is_outlier(t_raw, s_t_last, temp_jump_x100)) {
    s_reject_t++;                          /* 丢弃，不改 s_t_last */
    sys_usart_printf(sys_usart_1, "temp outlier %d, reject=%u\r\n",
                     t_raw, (unsigned)s_reject_t);
} else {
    s_t_last = t_raw;
} 串口打印 `reject` 计数：正常运行时它长时间为 0；用打火机/电烙铁靠近温度探头再迅速移开，或在 dht11 中途拔线再插，`reject` 计数增加而曲线不断点。 最大的坑是**用野值去更新上一次接受值**：一旦把野值当成基准，后面所有正常值都会相对它判成野值，曲线会永久跑偏。另一坑是变化率限值定太严：真正的开窗通风会让温度 1 分钟内变化几度，限值按“单次采样间隔”算，不要按分钟算。 sys_usart_printf / sys_tick_gettick 量纲与倍率：温度湿度 ×100、气压 ×10 协议里全是整数（线上不传 float：结构体对齐与字节序随编译器变），换算错一次，上位机看到的数就整体差 10 倍或 100 倍，而且看起来“还挺像”。 统一在**处理任务里**换算，采集任务只给物理量（float 或原始 adc）。规则：温度 `int16_t  temp_x100  = (int16_t)(t_c * 100.0f);`（可为负，-5.00℃ → -500，补码 0xfe0c）；湿度 `int16_t humi_x100 = (int16_t)(h_rh * 100.0f);`；气压 `int16_t press_x10 = (int16_t)(p_hpa * 10.0f);`（**必须 ×10**：1013.25×100 = 101325 超出 uint16 上限 65535，×10 得 10132 正好）。光照/tvoc/mq-135 是 uint16 原值，不乘。 /* 物理量 → 线上定点整数 */
int16_t  temp_x100  = (int16_t)(25.60f * 100.0f);    /* 2560  */
int16_t  humi_x100  = (int16_t)(60.30f * 100.0f);    /* 6030  */
int16_t  press_x10  = (int16_t)(1013.25f * 10.0f);   /* 10132 */

/* 反算回物理量（串口/oled 自检时用） */
sys_usart_printf(sys_usart_1, "t=%d.%02d c  h=%d.%02d %%rh  p=%d.%01d hpa\r\n",
                 temp_x100 / 100,  temp_x100 % 100,
                 humi_x100 / 100,  humi_x100 % 100,
                 press_x10 / 10,   press_x10 % 10);

/* 负数取余要小心：-500 % 100 = 0，-560 % 100 = -60 */
sys_usart_printf(sys_usart_1, "neg case: t=%d.%02d\r\n",
                 (int)(-560 / 100), (int)((-560 % 100 < 0) ? -(-560 % 100) : (-560 % 100))); 拿已知值验证：串口打印 `t=25.60`、`h=60.30`、`p=1013.2`（用计算器核对换算）；把温度故意取负值 -5.00，打印仍为 `-5.00` 而不是 `650.36` 或 `-5.-0`。 三个真坑：① 气压用 ×100 会溢出：1013.25×100 = 101325 > 65535，压成 uint16 后显示成 101.3 hpa 这种“永远偏低”的怪值；② 负数取模在 c 里是截断向零，`-560 % 100 = -60`，直接拼字符串会打出 `-5.-60`，显示前要取绝对值；③ 不要在串口打印之前就把定点值转回 float 打印（`printf` 的 `%f` 在部分工程不开 microlib 时也不可用，用整数打印最稳）。 sys_frame_buildenv / sys_frame_unpackenv / sys_usart_printf 阈值判定 + 回差（迟滞），让告警不抖 用单一阈值判超限，值在阈值附近抖一下（比如温度 29.98/30.02）就会让告警位每秒翻转几十次：上位机报警刷屏、蜂鸣器吱吱乱叫。 每个量配两个数：`limit`（触发上限）与 `hyst`（回差，如 1℃）。状态机：未报警时只在 `value > limit` 时置报警；已报警时只在 `value < limit - hyst` 时清报警。中间这段（limit-hyst ~ limit）保持原状态不变。状态保存成全局/静态变量，跨轮次保持。 #define t_limit_x100   3000    /* 30.00 ℃ 触发 */
#define t_hyst_x100     100    /* 回差 1.00 ℃ */

static uint8_t s_alarm_t;

static uint8_t alarm_step(uint8_t cur, int32_t v, int32_t limit, int32_t hyst)
{
    if (cur == 0u) {
        if (v > limit) return 1u;          /* 超上限才置 */
    } else {
        if (v < (limit - hyst)) return 0u; /* 回到回差以下才清 */
    }
    return cur;                            /* 中间带保持 */
