if (s_alarm_h) alarm |= al_humi;
if (s_alarm_p) alarm |= al_press;
if (s_alarm_l) alarm |= al_light;
if (s_alarm_v) alarm |= al_tvoc;
if (s_alarm_m) alarm |= al_mq135;

