#include "sys_frame.h"

/* 协议速查（对照 sys_frame.h 的宏，不要凭记忆写） */
/*  [0][1]  = 0xAA 0x55                    帧头 */
/*  [2]     = SYS_FRAME_CMD_ENV      0x01  命令 */
/*  [3]     = SYS_FRAME_ENV_LEN      0x0C  数据段 12 字节 */
/*  [4..5]  = TEMP  int16  0.01 ℃          段内 0  */
/*  [6..7]  = HUMI  int16  0.01 %RH        段内 2  */
/*  [8..9]  = PRESS int16  0.1 hPa         段内 4  */
/*  [10..11]= LIGHT uint16 lx              段内 6  */
/*  [12..13]= TVOC  uint16 ppb             段内 8  */
/*  [14..15]= MQ135 uint16 原始 ADC        段内 10 */
/*  [16][17]= CRC16-MODBUS 低字节在前 */
/*  [18][19]= 0x55 0xAA                    帧尾 */

uint8_t  f[32];
uint16_t n;

n = SYS_FRAME_BuildEnv(f, sizeof(f), 2560, 6030, 10132, 320, 15, 812);
SYS_USART_Printf(SYS_USART_1, "frame n=%u\r\n", (unsigned)n);
for (i = 0; i < n; i++) {
    SYS_USART_Printf(SYS_USART_1, "%02X ", (unsigned)f[i]);
}
SYS_USART_SendLine(SYS_USART_1, "");

#include "sys_modbus.h"

static void put_be16(uint8_t *p, uint16_t v)
{
    p[0] = (uint8_t)(v >> 8);        /* 大端：高字节在前 */
    p[1] = (uint8_t)(v & 0xFFU);
}

uint8_t  f[20];
uint16_t crc;

memset(f, 0, sizeof(f));
f[0] = 0xAAU;  f[1] = 0x55U;
f[2] = SYS_FRAME_CMD_ENV;
f[3] = SYS_FRAME_ENV_LEN;
put_be16(&f[4],  (uint16_t)temp_x100);     /* int16 补码按位写即可 */
put_be16(&f[6],  (uint16_t)humi_x100);
put_be16(&f[8],  (uint16_t)press_x10);
put_be16(&f[10], light_lx);
put_be16(&f[12], tvoc_ppb);
put_be16(&f[14], mq135_raw);

crc = SYS_MODBUS_Crc16(&f[2], 14U);        /* 范围：CMD+LEN+数据段 */
f[16] = (uint8_t)(crc & 0xFFU);            /* 低字节在前 */
f[17] = (uint8_t)(crc >> 8);
f[18] = 0x55U;  f[19] = 0xAAU;

uint8_t r;

if (SYS_FRAME_Verify(f, n) == SYS_FRAME_OK) {
    SYS_USART_SendLine(SYS_USART_1, "frame verify OK");
} else {
    r = SYS_FRAME_Verify(f, n);
    SYS_USART_Printf(SYS_USART_1, "frame verify FAIL rc=%u\r\n", (unsigned)r);
}

/* 也可用“整段 CRC = 0”当第二重判据：覆盖 CMD..CRC 自己再算一遍应为 0 */
if (SYS_MODBUS_Crc16(&f[2], 16U) == 0U) {
    SYS_USART_SendLine(SYS_USART_1, "crc check OK");
}

void vTaskComm(void *pv)
{
    ProcResult_t r;
    uint8_t  f[32];
    uint16_t n;

    (void)pv;
    for (;;) {
        if (xQueueReceive(s_q_result, &r, portMAX_DELAY) == pdPASS) {
            n = SYS_FRAME_BuildEnv(f, sizeof(f), r.temp_x100, r.humi_x100,
                                   r.press_x10, r.light_lx, r.tvoc_ppb, r.mq135_raw);
            if ((n == 20U) && (SYS_FRAME_Verify(f, n) == SYS_FRAME_OK)) {
                /* 下一阶段在这里发出去 */
                SYS_USART_Printf(SYS_USART_1, "[组帧] 20B ok, tick=%u\r\n",
                                 (unsigned)SYS_TICK_GetTick());
            } else {
                SYS_USART_Printf(SYS_USART_1, "[组帧] 失败 n=%u\r\n", (unsigned)n);
            }
            SYS_WDG_Heartbeat(2U);
        }
    }
}

