#define SEND_PERIOD_MS   2000U

void vTaskComm(void *pv)
{
    ProcResult_t r;
    uint8_t  f[32];
    uint16_t n;

    (void)pv;
    for (;;) {
        if (xQueueReceive(s_q_result, &r, portMAX_DELAY) == pdPASS) {
