xTaskCreate(vTaskLoraRx,  "LoraRx",  512, NULL, 3, NULL);
xTaskCreate(vTaskForward, "Forward", 512, NULL, 4, NULL);
xTaskCreate(vTaskCmdRx,   "CmdRx",   512, NULL, 3, NULL);
xTaskCreate(vTaskReplay,  "Replay",  256, NULL, 3, NULL);
xTaskCreate(vTaskMonitor, "Monitor", 256, NULL, 5, NULL);

static void vTaskReplay(void *pv) {
    const TickType_t period = pdMS_TO_TICKS(50);
    TickType_t last = xTaskGetTickCount();
    for (;;) {
        replay_step();          /* 没在补传时立刻返回 */
        vTaskDelayUntil(&last, period);
    }
}

static SemaphoreHandle_t s_qt_tx_mtx = NULL;

static void qt_send_frame(uint8_t cmd, const uint8_t *payload, uint16_t len)
{
    if (xSemaphoreTake(s_qt_tx_mtx, pdMS_TO_TICKS(50)) != pdPASS) {
        s_drop++;                 /* 拿不到锁就丢这一帧，绝不无超时死等 */
        return;
    }
    SYS_FRAME_Send(SYS_USART_2, cmd, payload, len);
    xSemaphoreGive(s_qt_tx_mtx);
}

#define APP_WDG_TIMEOUT_MS   4000U

/* 每个任务循环里各自调一次：SYS_WDG_Heartbeat(0U) / (1U) / (2U) ... */

static void vTaskMonitor(void *pv) {
    SYS_WDG_Init(APP_WDG_TIMEOUT_MS);
    for (;;) {
        if (SYS_WDG_HeartbeatAll() != 0U) {   /* 全部任务都报到 */
