        SYS_USART_Printf(SYS_USART_1, "pending=0x%X heap=%u\r\n",
                        (unsigned)SYS_WDG_HeartbeatPending(),
                        (unsigned)xPortGetFreeHeapSize());
        vTaskDelay(pdMS_TO_TICKS(1000));
    }
}

