#define configtick_rate_hz      ((ticktype_t)1000)
#define configmax_priorities    8
#define configtotal_heap_size   ((size_t)(30 * 1024))
#define configsupport_static_allocation  0
#define configcheck_for_stack_overflow   2 你能在 freertosconfig.h 里指出这 5 行的位置，并算出 5 个任务的栈合计约 9kb（512×4 字 + 256×2 字 ≈ 8.5kb），30kb 堆有余量。 configtotal_heap_size 是「全部动态分配加起来」的上限，不是每个任务的；configcheck_for_stack_overflow 开着时栈溢出会走 configassert，别把它关掉来「解决」问题；堆不足时 vtaskstartscheduler 直接返回，你写在它后面的死循环会跑起来，看起来像「程序在跑但什么都没做」。 configtotal_heap_size / configtick_rate_hz / configmax_priorities / configsupport_static_allocation / xportgetfreeheapsize / configcheck_for_stack_overflow 周期节拍：vtaskdelay 与 pdms_to_ticks rtos 下延时写错，轻则补传节奏抖，重则整个任务被自己的等待锁住。 收帧任务用短周期轮询（vtaskdelay(pdms_to_ticks(10))）；补传用 vtaskdelay(pdms_to_ticks(50)) 约 20 帧/秒；需要严格周期（监控 1s 心跳）改用 vtaskdelayuntil()，以当前 tick 为基准累加。 static void vtaskreplay(void *pv) {
    const ticktype_t period = pdms_to_ticks(50);
    ticktype_t last = xtaskgettickcount();
    for (;;) {
        replay_step();          /* 没在补传时立刻返回 */
        vtaskdelayuntil(&last, period);
    }
} 任务里用 xtaskgettickcount() 打时间戳，连续两次补传间隔稳定在 50ms±1 tick。 任务里不要用 sys_tick_delay_ms(50) 这类忙等；毫秒换算一律走 pdms_to_ticks，直接写 50 会被当成 50 个 tick（本板 tick=1ms 时凑巧一样，改节拍就错）；微秒级延时用 delay_us()，但必须先初始化 dwt。 vtaskdelay / vtaskdelayuntil / pdms_to_ticks / xtaskgettickcount / delay_us / delay_dwt_init 队列满了、串口在抢：超时与互斥量 真实系统一定会遇到消费者变慢，没有超时策略就会死等或者悄悄丢数据；两个任务同时写 usart2 会把帧写花。 发送侧统一用带超时的 xqueuesend(q, &m, pdms_to_ticks(5))，返回非 pdpass 就累加丢帧计数；usart2 是转发任务与补传任务共用的，用一把 xsemaphorecreatemutex() 建互斥量，写之前 xsemaphoretake、写完 xsemaphoregive，保证一帧 20 字节不会被另一条帧插进中间。 static semaphorehandle_t s_qt_tx_mtx = null;

