                (unsigned)id, (unsigned)r);

/* 一条记录 = 12 字节头 + 20 字节载荷 = 32 字节 */
/* [0..4)  seq  自增序号，0xFFFFFFFF 表示空槽 */
/* [4..8)  ts   时间戳（本工程用 RTC 秒） */
/* [8..10) len  本载荷实际字节数 */
/* [10..12) CRC16 低字节在前 */
/* [12..32) 载荷：整帧 20 字节环境帧 */

if (W25QXX_LogInit() != W25QXX_LOG_OK) {
    SYS_USART_SendLine(SYS_USART_1, "log init failed (先 W25QXX_Init)\r\n");
}

if (W25QXX_LogWrite(ts, frame20, 20U) == W25QXX_LOG_OK) {
    s_cache_ok++;
} else {
    s_cache_fail++;
}

SysRtc_t now;
SYS_RTC_GetTime(&now);
uint32_t ts = SYS_RTC_GetUnix();

if (W25QXX_LogWrite(ts, frame20, 20U) == W25QXX_LOG_OK) { /* 缓存成功 */ }

/* 补传时拼 0x15 历史帧：4 字节大端时间戳 + 20 字节原帧 */
hist[SYS_FRAME_HISTORY_TS_OFF + 0] = (uint8_t)(ts >> 24);
hist[SYS_FRAME_HISTORY_TS_OFF + 1] = (uint8_t)(ts >> 16);
hist[SYS_FRAME_HISTORY_TS_OFF + 2] = (uint8_t)(ts >> 8);
hist[SYS_FRAME_HISTORY_TS_OFF + 3] = (uint8_t)(ts);

uint16_t count, cap, head;
uint32_t ts; uint8_t buf[W25QXX_LOG_PAYLOAD]; uint16_t n;

W25QXX_LogStat(&count, &cap, &head);
SYS_USART_Printf(SYS_USART_1, "log %u/%u head=%u lost=%u\r\n",
                (unsigned)count, (unsigned)cap, (unsigned)head,
                (unsigned)W25QXX_LogLost());

if (W25QXX_LogTail(&ts, buf, &n) == W25QXX_LOG_OK) {
    SYS_USART_Printf(SYS_USART_1, "tail ts=%u len=%u\r\n", (unsigned)ts, (unsigned)n);
}

/* 0x13 清缓存命令的处理：擦除期间必须先关写入 */
s_cache_on = 0U;
if (W25QXX_LogClear() == W25QXX_LOG_OK) {
    SYS_USART_SendLine(SYS_USART_1, "log cleared\r\n");
}
s_cache_on = 1U;

#define REPLAY_PERIOD_MS   50U

/* 收到 0x16(1)：把此刻的条数冻结成 total，从头开始，并关掉写入 */
s_replay_i     = 0U;
s_replay_total = W25QXX_LogCount();
s_replay_sent  = 0U;
s_cache_on     = 0U;
s_replay_st    = SYS_FRAME_REPLAY_ST_REPLAYING;

/* 每 50ms 一步：读一条 -> 组 0x15 -> 经互斥量发到 USART2 */
if (s_replay_st == SYS_FRAME_REPLAY_ST_REPLAYING) {
    uint32_t ts; uint8_t buf[W25QXX_LOG_PAYLOAD]; uint16_t n;
    if (W25QXX_LogRead(s_replay_i, &ts, buf, &n) == W25QXX_LOG_OK) {
        uint8_t hist[SYS_FRAME_HISTORY_LEN];
        /* [0..4) 大端 ts，[4..24) 原帧 */
        qt_send_frame((uint8_t)SYS_FRAME_CMD_HISTORY, hist,
                      (uint16_t)SYS_FRAME_HISTORY_LEN);
        s_replay_i++;
        s_replay_sent++;
    } else {
        s_replay_bad++;          /* 坏记录：跳过并计数，不要当读到头 */
        s_replay_i++;
    }
    if (s_replay_i >= s_replay_total) {
        s_replay_st = SYS_FRAME_REPLAY_ST_DONE;
        s_cache_on  = 1U;        /* 补传结束，恢复写入 */
    }
}

