namespace FrameProto {
const quint8  HEAD_HI = 0xAAU, HEAD_LO = 0x55U;
const quint8  TAIL_HI = 0x55U, TAIL_LO = 0xAAU;
const int     OVERHEAD = 8;          /* 头 2 + CMD 1 + LEN 1 + CRC 2 + 尾 2 */
const quint8  CMD_ENV = 0x01U;
const quint8  ENV_LEN = 0x0CU;
