quint16 FrameProto::crc16Modbus(const quint8 *buf, int len)
{
    quint16 crc = 0xFFFFU;
    for (int i = 0; i < len; ++i) {
        crc ^= quint16(buf[i]);
        for (int bit = 0; bit < 8; ++bit) {
            if (crc & 0x0001U)
                crc = quint16((crc >> 1) ^ 0xA001U);
            else
                crc >>= 1;
        }
    }
    return crc;
}

